window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ISA"]={"book":"ISA","editions":{"fin-biblia1776":[[1,1,"Jesaian, Amotsin pojan näky, jonka hän näki Juudasta ja Jerusalemista, Ussian, Jotamin, Ahaksen ja Jehiskian, Juudan kuningasten aikana.","Jesaian, Amotsin pojan näky, jonka hän näki Juudasta ja Jerusalemista, Ussian, Jotamin, Ahaksen ja Jehiskian, Juudan kuningasten aikana."],[1,2,"Kuulkaat taivaat, ja maa ota korviis, sillä Herra puhuu: minä olen lapsia kasvattanut ja korottanut, ja he ovat minusta luopuneet.","Kuulkaat taivaat, ja maa ota korviis, sillä Herra puhuu: minä olen lapsia kasvattanut ja korottanut, ja he ovat minusta luopuneet."],[1,3,"Härkä tuntee omistajansa ja aasi isäntänsä seimen; mutta Israel ei tunne, ja minun kansani ei ymmärrä.","Härkä tuntee omistajansa ja aasi isäntänsä seimen; mutta Israel ei tunne, ja minun kansani ei ymmärrä."],[1,4,"Voi syntistä kansaa, kansaa suuresta pahasta teosta, pahanilkistä siementä, vahingollisia lapsia, jotka Herran hylkäsivät ja Israelin Pyhää pilkkasivat, he poikkesivat takaperin.","Voi syntistä kansaa, kansaa suuresta pahasta teosta, pahanilkistä siementä, vahingollisia lapsia, jotka Herran hylkäsivät ja Israelin Pyhää pilkkasivat, he poikkesivat takaperin."],[1,5,"Mitä varten teitä enempi lyödään, koska te aina harhailette? Koko pää on sairas, ja koko sydän on väsynyt.","Mitä varten teitä enempi lyödään, koska te aina harhailette? Koko pää on sairas, ja koko sydän on väsynyt."],[1,6,"Hamasta kantapäästä niin kiireeseen asti ei hänessä ole tervettä; vaan haavat, sinimarjat ja veripahat, jotka ei ole puserretut, eikä sidotut, taikka öljyllä sivellyt.","Hamasta kantapäästä niin kiireeseen asti ei hänessä ole tervettä; vaan haavat, sinimarjat ja veripahat, jotka ei ole puserretut, eikä sidotut, taikka öljyllä sivellyt."],[1,7,"Teidän maanne on autiona, teidän kaupunkinne ovat tulella poltetut; muukalaiset syövät peltonne silmäin edessä; ja on autio, niinkuin se, joka muukalaisilta raadeltu on.","Teidän maanne on autiona, teidän kaupunkinne ovat tulella poltetut; muukalaiset syövät peltonne silmäin edessä; ja on autio, niinkuin se, joka muukalaisilta raadeltu on."],[1,8,"Mutta mitä vielä Zionin tyttärestä jäänyt on, se on niinkuin maja viinamäessä, ja niinkuin hakomaja yrttitarhassa, niinkuin hävitetty kaupunki.","Mutta mitä vielä Zionin tyttärestä jäänyt on, se on niinkuin maja viinamäessä, ja niinkuin hakomaja yrttitarhassa, niinkuin hävitetty kaupunki."],[1,9,"Ellei Herra Zebaot meille jotakin vähää jättäisi, niin me olisimme kuin Sodoma, ja olisimme Gomorran kaltaiset.","Ellei Herra Zebaot meille jotakin vähää jättäisi, niin me olisimme kuin Sodoma, ja olisimme Gomorran kaltaiset."],[1,10,"Te Sodoman päämiehet, kuulkaat Herran sanaa: ottakaat korviinne meidän Jumalamme laki, sinä Gomorran kansa.","Te Sodoman päämiehet, kuulkaat Herran sanaa: ottakaat korviinne meidän Jumalamme laki, sinä Gomorran kansa."],[1,11,"Mitä minulle on teidän uhrienne paljoudesta? sanoo Herra: minä olen oinasten polttouhrista ja syöttiläin rasvasta ravittu, ja en tottele vasikkain, lammasten ja kauristen verta.","Mitä minulle on teidän uhrienne paljoudesta? sanoo Herra: minä olen oinasten polttouhrista ja syöttiläin rasvasta ravittu, ja en tottele vasikkain, lammasten ja kauristen verta."],[1,12,"Kuin te tulette ja ilmestytte minun kasvoini eteen, kuka senkaltaisia vaatii teidän käsistänne, että te vaeltaisitte minun esihuoneessani?","Kuin te tulette ja ilmestytte minun kasvoini eteen, kuka senkaltaisia vaatii teidän käsistänne, että te vaeltaisitte minun esihuoneessani?"],[1,13,"Älkäät silleen turhaa ruokauhrianne tuoko edes, se suitsutus on minulle kauhistus: uudella kuulla ja sabbatina, kuin kokous kuulutetaan, en minä voi kärsiä vääryyttä ja juhlapäivää yhdessä.","Älkäät silleen turhaa ruokauhrianne tuoko edes, se suitsutus on minulle kauhistus: uudella kuulla ja sabbatina, kuin kokous kuulutetaan, en minä voi kärsiä vääryyttä ja juhlapäivää yhdessä."],[1,14,"Minun sieluni vihaa uusia kuitanne ja juhlapäiviänne, minä olen niistä suuttunut; minä väsyn niitä kärseissäni.","Minun sieluni vihaa uusia kuitanne ja juhlapäiviänne, minä olen niistä suuttunut; minä väsyn niitä kärseissäni."],[1,15,"Ja kuin te parhaallansa käsiänne nostatte, niin minä kuitenkin käännän silmäni teistä pois; ja vaikka te paljon rukoilisitte, en minä kuitenkaan teitä kuule; teidän kätenne ovat verenvikoja täynnä.","Ja kuin te parhaallansa käsiänne nostatte, niin minä kuitenkin käännän silmäni teistä pois; ja vaikka te paljon rukoilisitte, en minä kuitenkaan teitä kuule; teidän kätenne ovat verenvikoja täynnä."],[1,16,"Peskäät teitänne, puhdistakaat teitänne, pankaat paha menonne pois minun silmäini edestä, lakatkaat pahaa tekemästä.","Peskäät teitänne, puhdistakaat teitänne, pankaat paha menonne pois minun silmäini edestä, lakatkaat pahaa tekemästä."],[1,17,"Oppikaat tekemään hyvää, ja etsikäät oikeutta, auttakaat alaspainettua, saattakat orvoille oikeus, ja auttakaat lesken asiaa.","Oppikaat tekemään hyvää, ja etsikäät oikeutta, auttakaat alaspainettua, saattakat orvoille oikeus, ja auttakaat lesken asiaa."],[1,18,"Ja sitte tulkaat, ja katsokaamme, kummalla oikeus on, sanoo Herra. Jos teidän syntinne veriruskiat olisivat, niin heidän pitää lumivalkiaksi tuleman; ja vaikka he olisivat niinkuin ruusunkarvaiset, pitää heidän kuitenkin niinkuin villa tuleman.","Ja sitte tulkaat, ja katsokaamme, kummalla oikeus on, sanoo Herra. Jos teidän syntinne veriruskiat olisivat, niin heidän pitää lumivalkiaksi tuleman; ja vaikka he olisivat niinkuin ruusunkarvaiset, pitää heidän kuitenkin niinkuin villa tuleman."],[1,19,"Jos te tahtoisitte ja (minua) kuulisitte, niin te maan hyvyyden nautita saisitte.","Jos te tahtoisitte ja (minua) kuulisitte, niin te maan hyvyyden nautita saisitte."],[1,20,"Mutta jos te estelette teitänne ja olette kovakorvaiset, niin miekan pitää teitä syömän; sillä Herran suu puhuu sen.","Mutta jos te estelette teitänne ja olette kovakorvaiset, niin miekan pitää teitä syömän; sillä Herran suu puhuu sen."],[1,21,"Kuinka se tapahtuu, että hurskas kaupunki on portoksi tullut? Hän oli täynnä oikeutta, vanhurskaus asui hänessä; mutta nyt murhaajat.","Kuinka se tapahtuu, että hurskas kaupunki on portoksi tullut? Hän oli täynnä oikeutta, vanhurskaus asui hänessä; mutta nyt murhaajat."],[1,22,"Sinun hopias on karreksi tullut, sinun juomas on vedellä sekoitettu.","Sinun hopias on karreksi tullut, sinun juomas on vedellä sekoitettu."],[1,23,"Sinun päämiehes ovat vilpistelleet ja varasten kumppanit; kaikki he mielellänsä lahjoja ottavat, ja pyytävät antimia. Ei he orvoille oikeutta tee, ja leskein asia ei tule heidän eteensä.","Sinun päämiehes ovat vilpistelleet ja varasten kumppanit; kaikki he mielellänsä lahjoja ottavat, ja pyytävät antimia. Ei he orvoille oikeutta tee, ja leskein asia ei tule heidän eteensä."],[1,24,"Sentähden sanoo Herra, Herra Zebaot, väkevä Israelissa: voi! minä tahdon itseni lohduttaa vihollisistani, ja vihamiehissäni vihani sammuttaa;","Sentähden sanoo Herra, Herra Zebaot, väkevä Israelissa: voi! minä tahdon itseni lohduttaa vihollisistani, ja vihamiehissäni vihani sammuttaa;"],[1,25,"Ja käännän käteni sinua vastaan, ja sinun kartes puhtaammaksi selitän, ja vien pois kaiken sinun tinas.","Ja käännän käteni sinua vastaan, ja sinun kartes puhtaammaksi selitän, ja vien pois kaiken sinun tinas."],[1,26,"Ja saatan sinun tuomaris entisellensä, ja neuvonantajas niinkuin alustakin: sitte sinä kutsutaan vanhurskaaksi ja uskolliseksi kaupungiksi.","Ja saatan sinun tuomaris entisellensä, ja neuvonantajas niinkuin alustakin: sitte sinä kutsutaan vanhurskaaksi ja uskolliseksi kaupungiksi."],[1,27,"Zion lunastetaan oikeudella, ja sen kääntyväiset vanhurskaudella,","Zion lunastetaan oikeudella, ja sen kääntyväiset vanhurskaudella,"],[1,28,"Että ylitsekäymärit ja syntiset ynnä särjetään, ja jotka Herran hylkäävät, hukutetaan.","Että ylitsekäymärit ja syntiset ynnä särjetään, ja jotka Herran hylkäävät, hukutetaan."],[1,29,"Sillä heidän täytyy häpiään tulla tammien tähden, joita he himoitsevat, ja häväistyksi tuleman yrttitarhain tähden, jotka he valitsivat.","Sillä heidän täytyy häpiään tulla tammien tähden, joita he himoitsevat, ja häväistyksi tuleman yrttitarhain tähden, jotka he valitsivat."],[1,30,"Ja te tulette niinkuin joku tammi surkastuneilla lehdillä, ja niinkuin joku vedetöin yrttitarha.","Ja te tulette niinkuin joku tammi surkastuneilla lehdillä, ja niinkuin joku vedetöin yrttitarha."],[1,31,"Ja väkevä tulee niinkuin rohdin, ja hänen tekonsa niinkuin kipinä. Ja he sytytetään ynnä molemmat, jota ei kenkään sammuta.","Ja väkevä tulee niinkuin rohdin, ja hänen tekonsa niinkuin kipinä. Ja he sytytetään ynnä molemmat, jota ei kenkään sammuta."],[2,1,"Tämä on se, minkä Jesaia Amotsin poika näki Juudasta ja Jerusalemista.","Tämä on se, minkä Jesaia Amotsin poika näki Juudasta ja Jerusalemista."],[2,2,"Viimeisenä aikana pitää sen vuoren, jolla Herran huone on, vahvan oleman, korkiampi kuin kaikki vuoret, ja korotettaman kukkulain ylitse; ja kaikki pakanat pitää sinne juokseman.","Viimeisenä aikana pitää sen vuoren, jolla Herran huone on, vahvan oleman, korkiampi kuin kaikki vuoret, ja korotettaman kukkulain ylitse; ja kaikki pakanat pitää sinne juokseman."],[2,3,"Ja paljo kansaa pitää sinne menemän, ja sanoman: tulkaat, astukaamme ylös Herran vuorelle, Jakobin Jumalan huoneeseen, että hän opettais meille teitänsä, ja me vaeltaisimme hänen poluillansa; sillä Zionista on laki tuleva, ja Herran sana Jerusalemista.","Ja paljo kansaa pitää sinne menemän, ja sanoman: tulkaat, astukaamme ylös Herran vuorelle, Jakobin Jumalan huoneeseen, että hän opettais meille teitänsä, ja me vaeltaisimme hänen poluillansa; sillä Zionista on laki tuleva, ja Herran sana Jerusalemista."],[2,4,"Ja hän tuomitsee pakanain seassa, ja rankaisee monta kansaa. Silloin heidän pitää miekkansa vannaksi tekemän, ja keihäänsä vikahteeksi; sillä ei yhdenkään kansan pidä toista kansaa vastaan miekkaa nostaman, eikä silleen tottuman sotimaan.","Ja hän tuomitsee pakanain seassa, ja rankaisee monta kansaa. Silloin heidän pitää miekkansa vannaksi tekemän, ja keihäänsä vikahteeksi; sillä ei yhdenkään kansan pidä toista kansaa vastaan miekkaa nostaman, eikä silleen tottuman sotimaan."],[2,5,"Tulkaat, te Jakobin huoneesta, vaeltakaamme Herran valkeudessa.","Tulkaat, te Jakobin huoneesta, vaeltakaamme Herran valkeudessa."],[2,6,"Mutta sinä olet sinun kansas Jakobin huoneen hyljännyt; sillä he rikkovat enemmän kuin itäläiset, ja ovat päiväin valitsiat, niinkuin Philistealaiset, ja sallivat muukalaiset lapset moneksi tulla.","Mutta sinä olet sinun kansas Jakobin huoneen hyljännyt; sillä he rikkovat enemmän kuin itäläiset, ja ovat päiväin valitsiat, niinkuin Philistealaiset, ja sallivat muukalaiset lapset moneksi tulla."],[2,7,"Heidän maansa on täynnä hopiaa ja kultaa, ja heidän rikkaudellansa ei ole loppua; heidän maansa on täynnä hevosia, ja heidän rattaillansa ei ole loppua.","Heidän maansa on täynnä hopiaa ja kultaa, ja heidän rikkaudellansa ei ole loppua; heidän maansa on täynnä hevosia, ja heidän rattaillansa ei ole loppua."],[2,8,"Heidän maansa on myös täynnä epäjumalia; he kumartavat käsialaansa, jotka heidän sormensa tehneet ovat.","Heidän maansa on myös täynnä epäjumalia; he kumartavat käsialaansa, jotka heidän sormensa tehneet ovat."],[2,9,"Siellä yhteinen kansa kumartelee, siellä sankarit heitänsä nöyryyttävät, joka et heille anna anteeksi.","Siellä yhteinen kansa kumartelee, siellä sankarit heitänsä nöyryyttävät, joka et heille anna anteeksi."],[2,10,"Mene kallioon, ja kätke sinuas maahan, Herran pelvon edestä, ja hänen kunniallisen majesteettinsa edestä.","Mene kallioon, ja kätke sinuas maahan, Herran pelvon edestä, ja hänen kunniallisen majesteettinsa edestä."],[2,11,"Sillä kaikki korkiat silmät alennetaan, ja jotka jaloimmat kansoissa ovat, täytyy itsensä notkistaa; sillä Herra on yksinänsä sinä aikana korkein.","Sillä kaikki korkiat silmät alennetaan, ja jotka jaloimmat kansoissa ovat, täytyy itsensä notkistaa; sillä Herra on yksinänsä sinä aikana korkein."],[2,12,"Sillä Herran Zebaotin päivä käy kaiken koreuden ja korkeuden ylitse, ja kaikkein paisuneiden ylitse, että ne alennettaisiin,","Sillä Herran Zebaotin päivä käy kaiken koreuden ja korkeuden ylitse, ja kaikkein paisuneiden ylitse, että ne alennettaisiin,"],[2,13,"Ja kaikkein korkiain ja korotettuin sedrein ylitse Libanonissa, ja kaikkein tammein ylitse Basanissa;","Ja kaikkein korkiain ja korotettuin sedrein ylitse Libanonissa, ja kaikkein tammein ylitse Basanissa;"],[2,14,"Niin myös kaikkein korkiain vuorten ylitse, ja kaikkein korotettuin kukkulain ylitse,","Niin myös kaikkein korkiain vuorten ylitse, ja kaikkein korotettuin kukkulain ylitse,"],[2,15,"Ja jokaisen korkian tornin ylitse, ja kaikkein vahvain muurein ylitse;","Ja jokaisen korkian tornin ylitse, ja kaikkein vahvain muurein ylitse;"],[2,16,"Niin myös kaikkein haahtein ylitse meressä, ja kaiken kauniin käsialan ylitse;","Niin myös kaikkein haahtein ylitse meressä, ja kaiken kauniin käsialan ylitse;"],[2,17,"Että kaikki ihmisten korkeus pitää notkistaman hänensä, ja nöyryyttämän itsensä, mitä ihmisessä korkiaa on; ja Herra yksin on silloin korkia oleva.","Että kaikki ihmisten korkeus pitää notkistaman hänensä, ja nöyryyttämän itsensä, mitä ihmisessä korkiaa on; ja Herra yksin on silloin korkia oleva."],[2,18,"Ja epäjumalain pitää ratki hukkuman.","Ja epäjumalain pitää ratki hukkuman."],[2,19,"Silloin mennään vuorten rotkoihin ja maan kuoppiin, Herran pelvon tähden, ja hänen kunniallisen majesteettinsa tähden, kuin hän nousee maata peljättämään.","Silloin mennään vuorten rotkoihin ja maan kuoppiin, Herran pelvon tähden, ja hänen kunniallisen majesteettinsa tähden, kuin hän nousee maata peljättämään."],[2,20,"Silloin pitää jokaisen hopiaiset ja kultaiset epäjumalansa heittämän pois, jotka hän on teettänyt kumartaaksensa, myyräin ja yökköin kuvat,","Silloin pitää jokaisen hopiaiset ja kultaiset epäjumalansa heittämän pois, jotka hän on teettänyt kumartaaksensa, myyräin ja yökköin kuvat,"],[2,21,"Että he menevät kivien rakoihin ja vuorten rotkoihin, Herran pelvon tähden, ja hänen kunniallisen majesteettinsa tähden, kuin hän nousee maata peljättämään.","Että he menevät kivien rakoihin ja vuorten rotkoihin, Herran pelvon tähden, ja hänen kunniallisen majesteettinsa tähden, kuin hän nousee maata peljättämään."],[2,22,"Niin lakatkaat siis ihmisestä, jonka sieramissa henki on; sillä ette tiedä, missä arviossa hän on.","Niin lakatkaat siis ihmisestä, jonka sieramissa henki on; sillä ette tiedä, missä arviossa hän on."],[3,1,"Sillä katso, Herra, Herra Zebaot ottaa pois Jerusalemista ja Juudasta kaikkinaisen varan, kaiken leivän varan, ja kaiken veden varan;","Sillä katso, Herra, Herra Zebaot ottaa pois Jerusalemista ja Juudasta kaikkinaisen varan, kaiken leivän varan, ja kaiken veden varan;"],[3,2,"Väkevät sotamiehet, tuomarit, prophetat, tietäjät ja vanhimmat;","Väkevät sotamiehet, tuomarit, prophetat, tietäjät ja vanhimmat;"],[3,3,"Viidenkymmenen päämiehet, ja kunnialliset miehet, neuvonantajat, ja taitavat virkamiehet, ja toimella puhuvaiset miehet.","Viidenkymmenen päämiehet, ja kunnialliset miehet, neuvonantajat, ja taitavat virkamiehet, ja toimella puhuvaiset miehet."],[3,4,"Ja tahtoo heille antaa nuorukaiset pääruhtinaiksi, ja lapset heitä hallitsemaan.","Ja tahtoo heille antaa nuorukaiset pääruhtinaiksi, ja lapset heitä hallitsemaan."],[3,5,"Ja kansan pitää ryöstämän toinen toistansa, ja jokaisen lähimmäistänsä; ja nuoremman pitää ylpiä oleman vanhaa vastaan, ja ylönkatsotun kunniallista vastaan.","Ja kansan pitää ryöstämän toinen toistansa, ja jokaisen lähimmäistänsä; ja nuoremman pitää ylpiä oleman vanhaa vastaan, ja ylönkatsotun kunniallista vastaan."],[3,6,"Silloin tarttuu veli veljeensä isänsä huoneesta: sinulla on vaatteet, ole meidän hallitsiamme, auta sinä tätä lankeemusta.","Silloin tarttuu veli veljeensä isänsä huoneesta: sinulla on vaatteet, ole meidän hallitsiamme, auta sinä tätä lankeemusta."],[3,7,"Mutta silloin hän vannoo ja sanoo: en minä taida parantaa, ei kotonani ole leipää eikä vaatteita: älkäät minun panko kansan hallitsiaksi.","Mutta silloin hän vannoo ja sanoo: en minä taida parantaa, ei kotonani ole leipää eikä vaatteita: älkäät minun panko kansan hallitsiaksi."],[3,8,"Sillä Jerusalem kaatuu, ja Juuda käy ylösalaisin; että heidän kielensä ja tekonsa on Herraa vastaan, niin että he hänen majesteettinsa silmiä vastoin sotivat.","Sillä Jerusalem kaatuu, ja Juuda käy ylösalaisin; että heidän kielensä ja tekonsa on Herraa vastaan, niin että he hänen majesteettinsa silmiä vastoin sotivat."],[3,9,"Heidän kasvoinsa hahmo todistaa heitä vastaan: ja he kerskaavat rikoksistansa, niinkuin Sodoma, ja ei salaa niitä. Voi heidän sielujansa! sillä he itse saattavat päällensä onnettomuuden.","Heidän kasvoinsa hahmo todistaa heitä vastaan: ja he kerskaavat rikoksistansa, niinkuin Sodoma, ja ei salaa niitä. Voi heidän sielujansa! sillä he itse saattavat päällensä onnettomuuden."],[3,10,"Sanokaat vanhurskaalle, että hänen käy hyvin; sillä hän saa syödä töidensä hedelmän.","Sanokaat vanhurskaalle, että hänen käy hyvin; sillä hän saa syödä töidensä hedelmän."],[3,11,"Mutta voi jumalattomia; sillä he ovat pahat, ja heille maksetaan niinkuin he ansaitsevat.","Mutta voi jumalattomia; sillä he ovat pahat, ja heille maksetaan niinkuin he ansaitsevat."],[3,12,"Lapset ovat minun kansani vaivaajat, ja vaimot vallitsevat heitä. Minun kansani, sinun lohduttajas häiritsevät sinun, ja turmelevat tien, jota sinun käymän pitäis.","Lapset ovat minun kansani vaivaajat, ja vaimot vallitsevat heitä. Minun kansani, sinun lohduttajas häiritsevät sinun, ja turmelevat tien, jota sinun käymän pitäis."],[3,13,"Mutta Herra seisoo siellä oikeudella, ja on seisahtanut tuomitsemaan kansoja.","Mutta Herra seisoo siellä oikeudella, ja on seisahtanut tuomitsemaan kansoja."],[3,14,"Herra tulee tuomiolle kansansa vanhimpain kanssa ja pääruhtinasten kanssa; sillä te olette turmelleet viinamäen, ja köyhäin ryöstö on teidän huoneessanne.","Herra tulee tuomiolle kansansa vanhimpain kanssa ja pääruhtinasten kanssa; sillä te olette turmelleet viinamäen, ja köyhäin ryöstö on teidän huoneessanne."],[3,15,"Miksi tallaatte kansaani, ja runtelette köyhää? sanoo Herra, Herra Zebaot.","Miksi tallaatte kansaani, ja runtelette köyhää? sanoo Herra, Herra Zebaot."],[3,16,"Ja Herra sanoo: että Zionin tyttäret ovat ylpiät, ja käyvät kenossa kauloin, kiilusilminä, kävelevät ja koriasti astelevat, niinkuin jalat sidotut olisivat;","Ja Herra sanoo: että Zionin tyttäret ovat ylpiät, ja käyvät kenossa kauloin, kiilusilminä, kävelevät ja koriasti astelevat, niinkuin jalat sidotut olisivat;"],[3,17,"On siis Herra tekevä Zionin tytärten päät rupisiksi, ja Herra on paljastava heidän häpiänsä.","On siis Herra tekevä Zionin tytärten päät rupisiksi, ja Herra on paljastava heidän häpiänsä."],[3,18,"Silloin on Herra ottava kenkäin kaunistuksen pois, ja koriasti kudotut rihmat ja soljet,","Silloin on Herra ottava kenkäin kaunistuksen pois, ja koriasti kudotut rihmat ja soljet,"],[3,19,"Käädyt, ja rannerenkaat ja seppelit,","Käädyt, ja rannerenkaat ja seppelit,"],[3,20,"Kalliit pääliinat, ja polukset, ja päärihmat, ja lemausastiat, ja korvarenkaat,","Kalliit pääliinat, ja polukset, ja päärihmat, ja lemausastiat, ja korvarenkaat,"],[3,21,"Sormukset ja otsalehdet,","Sormukset ja otsalehdet,"],[3,22,"Juhlavaatteet, ja kaaput, ja timpit, ja kukkarot,","Juhlavaatteet, ja kaaput, ja timpit, ja kukkarot,"],[3,23,"Peilit ja pienet liinavaatteet, ja lakit ja suvihameet.","Peilit ja pienet liinavaatteet, ja lakit ja suvihameet."],[3,24,"Ja pitää häijy löyhkä hyvän hajun edestä oleman, ja nuora vyön edestä, ja paljas pää kaharain hiusten edestä, ja ahdas säkki avaran hameen edestä. Nämät kaikki sinun kauneutes siaan.","Ja pitää häijy löyhkä hyvän hajun edestä oleman, ja nuora vyön edestä, ja paljas pää kaharain hiusten edestä, ja ahdas säkki avaran hameen edestä. Nämät kaikki sinun kauneutes siaan."],[3,25,"Sinun miehes kaatuvat miekan kautta, ja sinun väkeväs sodassa.","Sinun miehes kaatuvat miekan kautta, ja sinun väkeväs sodassa."],[3,26,"Ja heidän porttinsa pitää murehtiman ja valittaman: ja heidän pitää vaikiasti istuman maan päällä.","Ja heidän porttinsa pitää murehtiman ja valittaman: ja heidän pitää vaikiasti istuman maan päällä."],[4,1,"Ja seitsemän vaimoa tarttuvat silloin yhteen mieheen, ja sanovat: me tahdomme itseämme elättää ja vaatettaa; anna meitä ainoastaan sinun nimelläs nimitettää, että häväistyksemme otettaisiin meiltä pois.","Ja seitsemän vaimoa tarttuvat silloin yhteen mieheen, ja sanovat: me tahdomme itseämme elättää ja vaatettaa; anna meitä ainoastaan sinun nimelläs nimitettää, että häväistyksemme otettaisiin meiltä pois."],[4,2,"Sinä päivänä on Herran vesa oleva rakas ja kallis; ja maan hedelmä jalo ja kaunis niiden tykönä, jotka Israelista vapahdetaan.","Sinä päivänä on Herran vesa oleva rakas ja kallis; ja maan hedelmä jalo ja kaunis niiden tykönä, jotka Israelista vapahdetaan."],[4,3,"Ja on tapahtuva, että se joka Zionissa jäljellä on, ja se joka Jerusalemissa jäänyt on, pitää pyhäksi kutsuttaman; jokainen kuin kirjoitettu on eläväin seassa Jerusalemissa.","Ja on tapahtuva, että se joka Zionissa jäljellä on, ja se joka Jerusalemissa jäänyt on, pitää pyhäksi kutsuttaman; jokainen kuin kirjoitettu on eläväin seassa Jerusalemissa."],[4,4,"Silloin Herra pesee Zionin tytärten saastaisuuden, ja viruttaa Jerusalemin verenviat hänestä pois, tuomitsevan ja polttavan hengen kautta.","Silloin Herra pesee Zionin tytärten saastaisuuden, ja viruttaa Jerusalemin verenviat hänestä pois, tuomitsevan ja polttavan hengen kautta."],[4,5,"Ja Herra saattaa kaiken Zionin vuoren asumisen ylitse, ja kussa ikänä se koottu on, päivällä pilven ja savun, ja tulen paisteen yöllä palamaan; sillä suojelus pitää oleman kaiken kunnian ylitse.","Ja Herra saattaa kaiken Zionin vuoren asumisen ylitse, ja kussa ikänä se koottu on, päivällä pilven ja savun, ja tulen paisteen yöllä palamaan; sillä suojelus pitää oleman kaiken kunnian ylitse."],[4,6,"Ja maja pitää oleman päivän varjoksi hellettä vastaan, ja turva ja varjelus rajuilmaa ja sadetta vastaan.","Ja maja pitää oleman päivän varjoksi hellettä vastaan, ja turva ja varjelus rajuilmaa ja sadetta vastaan."],[5,1,"Minä veisaan ystävästä, ystäväni veisun hänen viinamäestänsä. Ystävälläni on viinamäki lihavassa paikassa.","Minä veisaan ystävästä, ystäväni veisun hänen viinamäestänsä. Ystävälläni on viinamäki lihavassa paikassa."],[5,2,"Ja hän aitasi sen ympärinsä, ja perkasi kivet pois, ja istutti parhaat viinapuut, ja rakensi myös siihen tornin, ja pani sinne viinakuurnan, ja odotti sen viinamarjoja kantavan; vaan se kantoi pahoja marjoja.","Ja hän aitasi sen ympärinsä, ja perkasi kivet pois, ja istutti parhaat viinapuut, ja rakensi myös siihen tornin, ja pani sinne viinakuurnan, ja odotti sen viinamarjoja kantavan; vaan se kantoi pahoja marjoja."],[5,3,"Te Jerusalemin asujat ja Juudan miehet, tuomitkaat siis nyt minun ja viinamäkeni välillä.","Te Jerusalemin asujat ja Juudan miehet, tuomitkaat siis nyt minun ja viinamäkeni välillä."],[5,4,"Mitä olis enempi viinamäelleni tekemistä, jota en minä hänessä tehnyt ole? Miksi hän kantoi pahoja marjoja, kuin minä odotin hänen viinamarjoja kantavan?","Mitä olis enempi viinamäelleni tekemistä, jota en minä hänessä tehnyt ole? Miksi hän kantoi pahoja marjoja, kuin minä odotin hänen viinamarjoja kantavan?"],[5,5,"Ja nyt minä tahdon teille ilmoittaa, mitä minä tahdon viinamäelleni tehdä: hänen aitansa pitää otettaman pois, että hänen pitää autiona oleman, ja hänen muurinsa pitää särjettämän, että hän tallattaisiin.","Ja nyt minä tahdon teille ilmoittaa, mitä minä tahdon viinamäelleni tehdä: hänen aitansa pitää otettaman pois, että hänen pitää autiona oleman, ja hänen muurinsa pitää särjettämän, että hän tallattaisiin."],[5,6,"Minä tahdon sen saattaa autioksi, ettei kenkään pidä hänessä leikkaaman eli kaivaman, vaan ohdakkeita ja orjantappuroita pitää hänessä kasvaman: ja tahdon pilviä kieltää satamasta hänen päällensä.","Minä tahdon sen saattaa autioksi, ettei kenkään pidä hänessä leikkaaman eli kaivaman, vaan ohdakkeita ja orjantappuroita pitää hänessä kasvaman: ja tahdon pilviä kieltää satamasta hänen päällensä."],[5,7,"Mutta Herran Zebaotin viinamäki on Israelin huone, ja Juudan miehet hänen suloinen istuttamansa. Hän odottaa oikeutta, ja katso, ei ole muuta kuin väkivaltaa, vanhurskautta, niin on sula valitus.","Mutta Herran Zebaotin viinamäki on Israelin huone, ja Juudan miehet hänen suloinen istuttamansa. Hän odottaa oikeutta, ja katso, ei ole muuta kuin väkivaltaa, vanhurskautta, niin on sula valitus."],[5,8,"Voi niitä, jotka yhden huoneen toisen tykö vetävät, ja yhden pellon toisen tykö saattavat, siihen asti ettei enää siaa ole, asuaksenne yksinänne maan päällä!","Voi niitä, jotka yhden huoneen toisen tykö vetävät, ja yhden pellon toisen tykö saattavat, siihen asti ettei enää siaa ole, asuaksenne yksinänne maan päällä!"],[5,9,"Nämä ovat (sanoo) Herra Zebaot minun korvilleni tulleet: mitämaks, ellei ne monet huoneet tule kylmille, ja ne suuret ja kauniit jää ilman asujia;","Nämä ovat (sanoo) Herra Zebaot minun korvilleni tulleet: mitämaks, ellei ne monet huoneet tule kylmille, ja ne suuret ja kauniit jää ilman asujia;"],[5,10,"Sillä kymmenen viinamäen sarkaa pitää vaivoin yhden batin antaman; ja gomer siemeniä tekee ainoastaan ephan.","Sillä kymmenen viinamäen sarkaa pitää vaivoin yhden batin antaman; ja gomer siemeniä tekee ainoastaan ephan."],[5,11,"Voi niitä, jotka varhain huomeneltain ylhäällä ovat, juopumusta noutelemaan, ja istuvat hamaan yöhön asti, että he viinasta palavaksi tulisivat!","Voi niitä, jotka varhain huomeneltain ylhäällä ovat, juopumusta noutelemaan, ja istuvat hamaan yöhön asti, että he viinasta palavaksi tulisivat!"],[5,12,"Joilla ovat kanteleet, harput, rummut, huilut, ja viinaa heidän pidoissansa; ja ei katso Herran tekoa, eikä tottele hänen käsialaansa.","Joilla ovat kanteleet, harput, rummut, huilut, ja viinaa heidän pidoissansa; ja ei katso Herran tekoa, eikä tottele hänen käsialaansa."],[5,13,"Sentähden pitää minun kansani vietämän vankeuteen, ettei heillä ole ymmärrystä; ja hänen kunniallistensa täytyy nälkää kärsiä, ja heidän yhteinen kansansa kuivua janoon.","Sentähden pitää minun kansani vietämän vankeuteen, ettei heillä ole ymmärrystä; ja hänen kunniallistensa täytyy nälkää kärsiä, ja heidän yhteinen kansansa kuivua janoon."],[5,14,"Sitä varten on helvetti sielunsa lavialta avannut, ja hänen kitansa on ammollansa ilman määrää, mennä sinne alas sekä heidän kunniallisensa että yhteisen kansansa, sekä heidän rikkaansa että riemullisensa;","Sitä varten on helvetti sielunsa lavialta avannut, ja hänen kitansa on ammollansa ilman määrää, mennä sinne alas sekä heidän kunniallisensa että yhteisen kansansa, sekä heidän rikkaansa että riemullisensa;"],[5,15,"Että jokainen itsensä notkistais ja kukin nöyryytettäisiin; ja koreiden silmät myös nöyryytetyksi tulisivat.","Että jokainen itsensä notkistais ja kukin nöyryytettäisiin; ja koreiden silmät myös nöyryytetyksi tulisivat."],[5,16,"Mutta Herra Zebaot pitää tuomiossa ylistettämän, ja pyhä Jumala pitää vanhurskaudessa pyhitettävän.","Mutta Herra Zebaot pitää tuomiossa ylistettämän, ja pyhä Jumala pitää vanhurskaudessa pyhitettävän."],[5,17,"Silloin pitää lampaat tavallansa kaittaman, ja muukalaiset pitää itsensä elättämän lihavain aukiudessa.","Silloin pitää lampaat tavallansa kaittaman, ja muukalaiset pitää itsensä elättämän lihavain aukiudessa."],[5,18,"Voi niitä, jotka itsensä sitovat valheen nuoralla yhteen vääryyttä tekemään, ja niinkuin ratasten köydellä syntiä tekemään!","Voi niitä, jotka itsensä sitovat valheen nuoralla yhteen vääryyttä tekemään, ja niinkuin ratasten köydellä syntiä tekemään!"],[5,19,"Ja sanovat: anna hänen tekonsa rientää ja pian tulla, sitä nähdäksemme: lähestyköön ja tulkoon Israelin pyhän aivoitus, että me sen tietäisimme.","Ja sanovat: anna hänen tekonsa rientää ja pian tulla, sitä nähdäksemme: lähestyköön ja tulkoon Israelin pyhän aivoitus, että me sen tietäisimme."],[5,20,"Voi niitä, jotka pahan hyväksi ja hyvän pahaksi sanovat; jotka pimeydestä valkeuden, ja valkeudesta pimeyden tekevät, jotka karvaasta makian, ja makiasta karvaan tekevät.","Voi niitä, jotka pahan hyväksi ja hyvän pahaksi sanovat; jotka pimeydestä valkeuden, ja valkeudesta pimeyden tekevät, jotka karvaasta makian, ja makiasta karvaan tekevät."],[5,21,"Voi niitä, jotka viisaat olevinansa ovat, ja itsensä toimellisina pitävät!","Voi niitä, jotka viisaat olevinansa ovat, ja itsensä toimellisina pitävät!"],[5,22,"Voi niitä, jotka jalot ovat viinaa juomaan, ja juomassa kilvoittelevat!","Voi niitä, jotka jalot ovat viinaa juomaan, ja juomassa kilvoittelevat!"],[5,23,"Jotka jumalattoman lahjain tähden vanhurskauttavat, ja kääntävät vanhurskasten oikeuden pois heiltä:","Jotka jumalattoman lahjain tähden vanhurskauttavat, ja kääntävät vanhurskasten oikeuden pois heiltä:"],[5,24,"Sentähden niinkuin tulen hehku korren kuluttaa, ja liekki sivaltaa akanat pois: aivan niin pitää heidän juurensa mätänemän, ja heidän vesansa hajooman pois niinkuin tomu; sillä he katsovat Herran Zebaotin lain ylön, ja pilkkaavat Israelin pyhän sanat.","Sentähden niinkuin tulen hehku korren kuluttaa, ja liekki sivaltaa akanat pois: aivan niin pitää heidän juurensa mätänemän, ja heidän vesansa hajooman pois niinkuin tomu; sillä he katsovat Herran Zebaotin lain ylön, ja pilkkaavat Israelin pyhän sanat."],[5,25,"Sentähden Herran viha julmistuu kansansa päälle, ja hän ojentaa kätensä heidän päällensä, ja lyö heitä, niin että vuoret vapisevat ja heidän ruumiinsa on niinkuin loka kadulla. Ja kaikissa näissä ei hänen vihansa lakkaa, vaan hänen kätensä on vielä ojennettu.","Sentähden Herran viha julmistuu kansansa päälle, ja hän ojentaa kätensä heidän päällensä, ja lyö heitä, niin että vuoret vapisevat ja heidän ruumiinsa on niinkuin loka kadulla. Ja kaikissa näissä ei hänen vihansa lakkaa, vaan hänen kätensä on vielä ojennettu."],[5,26,"Sillä hän nostaa lipun ylös kaukana pakanain seassa, ja viheltää niille maan ääristä: ja katso, he tulevat äkisti ja nopiasti.","Sillä hän nostaa lipun ylös kaukana pakanain seassa, ja viheltää niille maan ääristä: ja katso, he tulevat äkisti ja nopiasti."],[5,27,"Ei ole kenkään heistä väsynyt eli heikko, eikä kenkään torku eli makaa; ei myös päästä kenkään vyötä lanteestansa, eikä kenenkään kengänrihmoja rikota.","Ei ole kenkään heistä väsynyt eli heikko, eikä kenkään torku eli makaa; ei myös päästä kenkään vyötä lanteestansa, eikä kenenkään kengänrihmoja rikota."],[5,28,"Sillä heidän nuolensa ovat terävät, ja kaikki heidän joutsensa jännitetyt; heidän orittensa kaviot ovat niinkuin limsiä, ja heidän ratastensa pyörät niinkuin tuulispää.","Sillä heidän nuolensa ovat terävät, ja kaikki heidän joutsensa jännitetyt; heidän orittensa kaviot ovat niinkuin limsiä, ja heidän ratastensa pyörät niinkuin tuulispää."],[5,29,"He kiljuvat niinkuin jalopeurat, ja kiljuvat niinkuin nuoret jalopeurat. He kilistelevät ja tempaavat saaliin, ja omistavat sen, ettei kenkään sitä saa jälleen.","He kiljuvat niinkuin jalopeurat, ja kiljuvat niinkuin nuoret jalopeurat. He kilistelevät ja tempaavat saaliin, ja omistavat sen, ettei kenkään sitä saa jälleen."],[5,30,"Ja silloin pauhataan heidän ylitsensä niinkuin meri pauhaa. Koska silloin katsotaan maan päälle, katso, niin on pimeys ahdistuksesta, ja ei valkeus paista silleen heidän ylitsensä.","Ja silloin pauhataan heidän ylitsensä niinkuin meri pauhaa. Koska silloin katsotaan maan päälle, katso, niin on pimeys ahdistuksesta, ja ei valkeus paista silleen heidän ylitsensä."],[6,1,"Sinä vuonna, jona kuningas Ussia kuoli, näin minä Herran istuvan korkialla ja korotetulla istuimella, ja hänen vaatteensa liepeet täyttivät templin.","Sinä vuonna, jona kuningas Ussia kuoli, näin minä Herran istuvan korkialla ja korotetulla istuimella, ja hänen vaatteensa liepeet täyttivät templin."],[6,2,"Seraphit seisoivat häntä ylempänä, ja kullakin oli kuusi siipeä: kahdella he peittivät kasvonsa, kahdella jalkansa, ja kahdella he lensivät.","Seraphit seisoivat häntä ylempänä, ja kullakin oli kuusi siipeä: kahdella he peittivät kasvonsa, kahdella jalkansa, ja kahdella he lensivät."],[6,3,"Ne huusivat toinen toisellensa ja sanoivat: Pyhä, pyhä, pyhä, Herra Zebaot: kaikki maa on täynnä hänen kunniaansa;","Ne huusivat toinen toisellensa ja sanoivat: Pyhä, pyhä, pyhä, Herra Zebaot: kaikki maa on täynnä hänen kunniaansa;"],[6,4,"Niin että pihtipielet vapisivat heidän huutonsa äänestä, ja huone täytettiin savulla.","Niin että pihtipielet vapisivat heidän huutonsa äänestä, ja huone täytettiin savulla."],[6,5,"Niin minä sanoin: voi minuani! minä hukun, sillä minulla on saastaiset huulet, ja asun sen kansan seassa, jolla on saastaiset huulet; sillä minun silmäni ovat nähneet kuninkaan, Herran Zebaotin.","Niin minä sanoin: voi minuani! minä hukun, sillä minulla on saastaiset huulet, ja asun sen kansan seassa, jolla on saastaiset huulet; sillä minun silmäni ovat nähneet kuninkaan, Herran Zebaotin."],[6,6,"Niin lensi yksi Seraphimeista minun tyköni, jolla oli kädessä tulinen hiili, jonka hän otti hohtimilla alttarilta,","Niin lensi yksi Seraphimeista minun tyköni, jolla oli kädessä tulinen hiili, jonka hän otti hohtimilla alttarilta,"],[6,7,"Ja rupesi minun suuhuni, ja sanoi: katso, tällä olen minä ruvennut huuliis, että sinun pahat tekos otettaisiin sinulta pois, ja sinun rikokses olis sovitettu.","Ja rupesi minun suuhuni, ja sanoi: katso, tällä olen minä ruvennut huuliis, että sinun pahat tekos otettaisiin sinulta pois, ja sinun rikokses olis sovitettu."],[6,8,"Ja minä kuulin Herran äänen, että hän sanoi: kenenkä minä lähetän? kuka tahtoo olla meidän sanansaattajamme? Mutta minä sanoin: tässä minä olen, lähetä minua.","Ja minä kuulin Herran äänen, että hän sanoi: kenenkä minä lähetän? kuka tahtoo olla meidän sanansaattajamme? Mutta minä sanoin: tässä minä olen, lähetä minua."],[6,9,"Ja hän sanoi: mene ja sano tälle kansalle, kuulten kuulkaat, ja älkäät ymmärtäkö, nähden nähkäät, ja älkäät tähtäkö.","Ja hän sanoi: mene ja sano tälle kansalle, kuulten kuulkaat, ja älkäät ymmärtäkö, nähden nähkäät, ja älkäät tähtäkö."],[6,10,"Paaduta tämän kansan sydän, ja anna heidän korvansa paksuksi tulla, ja sokaise heidän silmänsä, ettei he näkisi silmillänsä, eikä kuulisi korvillansa, eli myös ymmärtäisi sydämellänsä, eli kääntäisi itsiänsä ja parannetuksi tulisi.","Paaduta tämän kansan sydän, ja anna heidän korvansa paksuksi tulla, ja sokaise heidän silmänsä, ettei he näkisi silmillänsä, eikä kuulisi korvillansa, eli myös ymmärtäisi sydämellänsä, eli kääntäisi itsiänsä ja parannetuksi tulisi."],[6,11,"Mutta minä sanoin: Herra, kuinka kauvan? Hän sanoi: siihenasti kuin kaupungit tulevat kylmille ja ilman asujia, ja huoneet ilman väetä, ja maa on peräti autiona.","Mutta minä sanoin: Herra, kuinka kauvan? Hän sanoi: siihenasti kuin kaupungit tulevat kylmille ja ilman asujia, ja huoneet ilman väetä, ja maa on peräti autiona."],[6,12,"Sillä Herra ajaa väen kauvas, niin että maa tulee peräti hyljätyksi.","Sillä Herra ajaa väen kauvas, niin että maa tulee peräti hyljätyksi."],[6,13,"Ja ehkä kymmenes osa siihen vielä jää, niin sekin taas hävitetään; kuitenkin niinkuin tammelle ja tuomelle jää kanto, vaikka heidän lehtensä varistetaan, niin pitää myös pyhällä siemenellä kanto oleman.","Ja ehkä kymmenes osa siihen vielä jää, niin sekin taas hävitetään; kuitenkin niinkuin tammelle ja tuomelle jää kanto, vaikka heidän lehtensä varistetaan, niin pitää myös pyhällä siemenellä kanto oleman."],[7,1,"Sitte tapahtui Ahaksen Jotamin pojan, Ussian pojan, Juudan kuninkaan aikana, että Retsin Syrian kuningas, ja Peka Remalian poika, Israelin kuningas, vaelsivat Jerusalemiin, sotimaan sitä vastaan; mutta ei he taitaneet sitä voittaa.","Sitte tapahtui Ahaksen Jotamin pojan, Ussian pojan, Juudan kuninkaan aikana, että Retsin Syrian kuningas, ja Peka Remalian poika, Israelin kuningas, vaelsivat Jerusalemiin, sotimaan sitä vastaan; mutta ei he taitaneet sitä voittaa."],[7,2,"Silloin sanottiin Davidin huoneelle: Syrialaiset luottavat Ephraimiin. Silloin vapisi hänen sydämensä ja hänen kansansa sydän, niinkuin puut vapisevat metsässä tuulesta.","Silloin sanottiin Davidin huoneelle: Syrialaiset luottavat Ephraimiin. Silloin vapisi hänen sydämensä ja hänen kansansa sydän, niinkuin puut vapisevat metsässä tuulesta."],[7,3,"Mutta Herra puhui Jesaialle: mene nyt Ahasta vastaan, sinä ja poikas SearJasub, ylimmäisen vesilammikon kanavan päähän, tiellä vanuttajakedolle.","Mutta Herra puhui Jesaialle: mene nyt Ahasta vastaan, sinä ja poikas SearJasub, ylimmäisen vesilammikon kanavan päähän, tiellä vanuttajakedolle."],[7,4,"Ja sano hänelle: kavahda ja pysy alallas, älä pelkää, älköön myös sydämes vapisko näitä kahta suitsevan kekäleen päätä, Retsinin ja Syrialaisten, ja Remalian pojan vihaa.","Ja sano hänelle: kavahda ja pysy alallas, älä pelkää, älköön myös sydämes vapisko näitä kahta suitsevan kekäleen päätä, Retsinin ja Syrialaisten, ja Remalian pojan vihaa."],[7,5,"Että Syrialaiset ovat pitäneet pahoja juonia sinua vastaan, niin myös Ephraim ja Remalian poika, ja sanovat:","Että Syrialaiset ovat pitäneet pahoja juonia sinua vastaan, niin myös Ephraim ja Remalian poika, ja sanovat:"],[7,6,"Me tahdomme mennä ylös Juudaan, ja herättää häntä, ja jakaa sen keskenämme, ja tehdä siihen Tabealin pojan kuninkaaksi.","Me tahdomme mennä ylös Juudaan, ja herättää häntä, ja jakaa sen keskenämme, ja tehdä siihen Tabealin pojan kuninkaaksi."],[7,7,"Sillä näin sanoo Herra, Herra: ei sen pidä pysymän, eikä näin oleman.","Sillä näin sanoo Herra, Herra: ei sen pidä pysymän, eikä näin oleman."],[7,8,"Vaan niinkuin Damasku on Syrian pää, niin pitää Retsinin oleman Damaskun pään. Ja viiden ajastajan perästä seitsemättäkymmentä, pitää Ephraimin tuleman perikatoon, niin ettei heidän enään pidä kansana oleman.","Vaan niinkuin Damasku on Syrian pää, niin pitää Retsinin oleman Damaskun pään. Ja viiden ajastajan perästä seitsemättäkymmentä, pitää Ephraimin tuleman perikatoon, niin ettei heidän enään pidä kansana oleman."],[7,9,"Ja niinkuin Samaria on Ephraimin pää, niin pitää Remalian poika oleman Samarian pään. Jollette usko, niin ette vahvistu.","Ja niinkuin Samaria on Ephraimin pää, niin pitää Remalian poika oleman Samarian pään. Jollette usko, niin ette vahvistu."],[7,10,"Ja Herra puhui taas Ahakselle ja sanoi:","Ja Herra puhui taas Ahakselle ja sanoi:"],[7,11,"Pyydä sinulles merkkiä Herralta sinun Jumalaltas, taikka alhaalle syvyyteen, eli ylhäälle korkeuteen.","Pyydä sinulles merkkiä Herralta sinun Jumalaltas, taikka alhaalle syvyyteen, eli ylhäälle korkeuteen."],[7,12,"Niin Ahas sanoi: en ano ja en tahdo Herraa kiusata.","Niin Ahas sanoi: en ano ja en tahdo Herraa kiusata."],[7,13,"Niin hän sanoi: kuulkaat siis te Davidin huone: vähäkö se teille on, että te ihmisiä vastoin teette, mutta myös teette minun Jumalaani vastoin?","Niin hän sanoi: kuulkaat siis te Davidin huone: vähäkö se teille on, että te ihmisiä vastoin teette, mutta myös teette minun Jumalaani vastoin?"],[7,14,"Sentähden antaa itse Herra teille merkin: katso, neitsy siittää ja synnyttää pojan, sen nimi pitää kutsuttaman Immanuel.","Sentähden antaa itse Herra teille merkin: katso, neitsy siittää ja synnyttää pojan, sen nimi pitää kutsuttaman Immanuel."],[7,15,"Voita ja hunajaa hän syö, tietääksensä hyljätä pahaa ja valita hyvää.","Voita ja hunajaa hän syö, tietääksensä hyljätä pahaa ja valita hyvää."],[7,16,"Sillä ennenkuin poikainen oppii hylkäämään pahaa ja valitsemaan hyvää, pitää se maa, jotas kauhistut, kahdelta kuninkaalta hyljättämän.","Sillä ennenkuin poikainen oppii hylkäämään pahaa ja valitsemaan hyvää, pitää se maa, jotas kauhistut, kahdelta kuninkaalta hyljättämän."],[7,17,"Mutta Herra antaa sinun, sinun kansas ja isäs huoneen päälle tulla, Assyrian kuninkaan kautta, ne päivät, jotka ei sitte tulleet ole, kuin Ephraim erkani Juudasta.","Mutta Herra antaa sinun, sinun kansas ja isäs huoneen päälle tulla, Assyrian kuninkaan kautta, ne päivät, jotka ei sitte tulleet ole, kuin Ephraim erkani Juudasta."],[7,18,"Ja tapahtuu, että Herra viheltää sinä päivänä kärpäsiä Egyptin virtain äärestä, ja kimalaisia Assurin maalta;","Ja tapahtuu, että Herra viheltää sinä päivänä kärpäsiä Egyptin virtain äärestä, ja kimalaisia Assurin maalta;"],[7,19,"Että he tulevat ja sioittavat kaikki tyynni itsensä hävinneihin laaksoihin, ja kiven rakoihin, ja kaikkiin mättäisiin ja pensaisiin.","Että he tulevat ja sioittavat kaikki tyynni itsensä hävinneihin laaksoihin, ja kiven rakoihin, ja kaikkiin mättäisiin ja pensaisiin."],[7,20,"Silloin Herra ajelee pään ja karvat jaloista, ja ottaa pois parran palkatulla partaveitsellä, niiden kautta, jotka sillä puolella virtaa ovat, Assyrian kuninkaan kautta.","Silloin Herra ajelee pään ja karvat jaloista, ja ottaa pois parran palkatulla partaveitsellä, niiden kautta, jotka sillä puolella virtaa ovat, Assyrian kuninkaan kautta."],[7,21,"Siihen aikaan pitää yhden miehen yhtä lehmää ja kahta lammasta kaitseman,","Siihen aikaan pitää yhden miehen yhtä lehmää ja kahta lammasta kaitseman,"],[7,22,"Ja saaman niin paljon rieskaa, että hän saa syödä voita; sillä se joka jää maahan, saa voita ja hunajaa syödä.","Ja saaman niin paljon rieskaa, että hän saa syödä voita; sillä se joka jää maahan, saa voita ja hunajaa syödä."],[7,23,"Sillä siihen aikaan tapahtuu, että kussa nyt on tuhannen viinapuuta, jotka maksavat tuhannen hopiapenninkiä, siellä pitää orjantappurat ja ohdakkeet oleman.","Sillä siihen aikaan tapahtuu, että kussa nyt on tuhannen viinapuuta, jotka maksavat tuhannen hopiapenninkiä, siellä pitää orjantappurat ja ohdakkeet oleman."],[7,24,"Ja sinne mennään nuolella ja joutsella; sillä koko maassa pitää oleman orjantappurat ja ohdakkeet;","Ja sinne mennään nuolella ja joutsella; sillä koko maassa pitää oleman orjantappurat ja ohdakkeet;"],[7,25,"Niin ettei taideta tulla kaikkiin niihin mäkiin, joita lapiolla kaivetaan, orjantappurain, mätästen ja ohdakkeiden tähden; vaan härjät annetaan siinä käydä, ja lampaat sitä tallata.","Niin ettei taideta tulla kaikkiin niihin mäkiin, joita lapiolla kaivetaan, orjantappurain, mätästen ja ohdakkeiden tähden; vaan härjät annetaan siinä käydä, ja lampaat sitä tallata."],[8,1,"Ja Herra sanoi minulle: ota suuri kirja etees, ja kirjoita siihen ihmisen kirjoituksella: ryöstä nopiasti, riennä saaliille.","Ja Herra sanoi minulle: ota suuri kirja etees, ja kirjoita siihen ihmisen kirjoituksella: ryöstä nopiasti, riennä saaliille."],[8,2,"Ja minä otin tyköni uskolliset todistajat: papin Urijan, ja Sakarian Jeberekjan pojan,","Ja minä otin tyköni uskolliset todistajat: papin Urijan, ja Sakarian Jeberekjan pojan,"],[8,3,"Ja menin prophetissan tykö, se tuli raskaaksi ja synnytti pojan; ja Herra sanoi minulle: nimitä se: ryöstä pian, ja riennä jakoon.","Ja menin prophetissan tykö, se tuli raskaaksi ja synnytti pojan; ja Herra sanoi minulle: nimitä se: ryöstä pian, ja riennä jakoon."],[8,4,"Sillä ennenkuin poikainen taitaa sanoa: isäni, äitini, viedään Damaskun tavarat ja Samarian saalis pois Assyrian kuninkaan edellä.","Sillä ennenkuin poikainen taitaa sanoa: isäni, äitini, viedään Damaskun tavarat ja Samarian saalis pois Assyrian kuninkaan edellä."],[8,5,"Ja Herra puhui vielä minun kanssani ja sanoi:","Ja Herra puhui vielä minun kanssani ja sanoi:"],[8,6,"Että tämä kansa hylkää Siloan veden, joka hiljaksensa juoksee, ja turvaa Retsiniin ja Remalian poikaan;","Että tämä kansa hylkää Siloan veden, joka hiljaksensa juoksee, ja turvaa Retsiniin ja Remalian poikaan;"],[8,7,"Katso, niin Herra antaa tulla hänen päällensä paljon ja väkevän virtaveden, Assyrian kuninkaan, ja kaiken hänen kunniansa, että se nousee kaikkein parrastensa yli, ja käypi kaikkein rantainsa yli;","Katso, niin Herra antaa tulla hänen päällensä paljon ja väkevän virtaveden, Assyrian kuninkaan, ja kaiken hänen kunniansa, että se nousee kaikkein parrastensa yli, ja käypi kaikkein rantainsa yli;"],[8,8,"Ja käypi Juudan lävitse, tulvaa ja nousee, siihenasti kuin se ulottuu kaulaan asti; ja levittää siipensä, niin että ne täyttävät sinun maas, o Immanuel, niin leviä kuin se on.","Ja käypi Juudan lävitse, tulvaa ja nousee, siihenasti kuin se ulottuu kaulaan asti; ja levittää siipensä, niin että ne täyttävät sinun maas, o Immanuel, niin leviä kuin se on."],[8,9,"Kokoontukaat kansat, ja paetkaat kuitenkin; kuulkaat kaikki, jotka olette kaukaisissa maakunnissa: hankkikaat sotaan ja paetkaat kuitenkin, hankkikaat ja paetkaat kuitenkin.","Kokoontukaat kansat, ja paetkaat kuitenkin; kuulkaat kaikki, jotka olette kaukaisissa maakunnissa: hankkikaat sotaan ja paetkaat kuitenkin, hankkikaat ja paetkaat kuitenkin."],[8,10,"Päättäkäät neuvo, ja ei se miksikään tule; puhukaat keskenänne, ja ei sekään seiso, sillä tässä on Immanuel.","Päättäkäät neuvo, ja ei se miksikään tule; puhukaat keskenänne, ja ei sekään seiso, sillä tässä on Immanuel."],[8,11,"Sillä näin sanoi Herra minulle, kuin hän käteeni rupesi, ja neuvoi minua, etten minä vaeltaisi tämän kansan tiellä, ja sanoi:","Sillä näin sanoi Herra minulle, kuin hän käteeni rupesi, ja neuvoi minua, etten minä vaeltaisi tämän kansan tiellä, ja sanoi:"],[8,12,"Älkäät sanoko liitoksi, mitä tämä kansa liitoksi sanoo: älkäät te peljätkö, niinkuin he tekevät, älkäät myös vapisko.","Älkäät sanoko liitoksi, mitä tämä kansa liitoksi sanoo: älkäät te peljätkö, niinkuin he tekevät, älkäät myös vapisko."],[8,13,"Vaan pyhittäkäät Herra Zebaot; ja hän olkoon teidän pelkonne, hän olkoon teidän vapistuksenne;","Vaan pyhittäkäät Herra Zebaot; ja hän olkoon teidän pelkonne, hän olkoon teidän vapistuksenne;"],[8,14,"Niin hän on pyhitys; mutta loukkauskivi ja kompastuskallio kahdelle Israelin huoneelle, paulaksi ja ansaksi Jerusalemin asuville,","Niin hän on pyhitys; mutta loukkauskivi ja kompastuskallio kahdelle Israelin huoneelle, paulaksi ja ansaksi Jerusalemin asuville,"],[8,15,"Niin että moni heistä loukkaa itsensä, ja lankeevat, särjetään, kiedotaan ja vangitaan.","Niin että moni heistä loukkaa itsensä, ja lankeevat, särjetään, kiedotaan ja vangitaan."],[8,16,"Sido todistus kiinni, lukitse laki minun opetuslapsissani.","Sido todistus kiinni, lukitse laki minun opetuslapsissani."],[8,17,"Sillä minä toivon Herraan, joka kasvonsa Jakobin huoneelta kätkenyt on; mutta minä odotan häntä.","Sillä minä toivon Herraan, joka kasvonsa Jakobin huoneelta kätkenyt on; mutta minä odotan häntä."],[8,18,"Katso, tässä minä olen, ja ne lapset, jotka Herra minulle antanut on merkiksi ja ihmeeksi Israelissa Herralta Zebaotilta, joka Zionin vuorella asuu.","Katso, tässä minä olen, ja ne lapset, jotka Herra minulle antanut on merkiksi ja ihmeeksi Israelissa Herralta Zebaotilta, joka Zionin vuorella asuu."],[8,19,"Kuin siis he teille sanovat: kysykäät noidilta ja tietäjiltä, jotka kuiskuttelevat ja tutkivat, (niin sanokaat:) eikö kansan pidä Jumalaltansa kysymän? (eikö ole parempi kysyä) eläviltä kuin kuolleilta?","Kuin siis he teille sanovat: kysykäät noidilta ja tietäjiltä, jotka kuiskuttelevat ja tutkivat, (niin sanokaat:) eikö kansan pidä Jumalaltansa kysymän? (eikö ole parempi kysyä) eläviltä kuin kuolleilta?"],[8,20,"(Ja pikemmin) lain jälkeen ja todistuksen? Ellei he tämän sanan jälkeen sano, niin ei heidän pidä aamuruskoa saaman.","(Ja pikemmin) lain jälkeen ja todistuksen? Ellei he tämän sanan jälkeen sano, niin ei heidän pidä aamuruskoa saaman."],[8,21,"Vaan heidän pitää kävelemän maakunnassa vaivattuina ja nälkäisinä; mutta kuin he nälkää kärsivät, niin he vihastuvat ja kiroilevat kuningastansa ja Jumalaansa, ja katsovat ylöspäin,","Vaan heidän pitää kävelemän maakunnassa vaivattuina ja nälkäisinä; mutta kuin he nälkää kärsivät, niin he vihastuvat ja kiroilevat kuningastansa ja Jumalaansa, ja katsovat ylöspäin,"],[8,22,"Ja katselevat maata, vaan ei muuta mitään löydä, kuin murheet ja pimeydet; sillä he ovat pimitetyt ahdistuksessa, ja eksyvät pimeydessä.","Ja katselevat maata, vaan ei muuta mitään löydä, kuin murheet ja pimeydet; sillä he ovat pimitetyt ahdistuksessa, ja eksyvät pimeydessä."],[9,1,"Sillä ei ole sillä (maakunnalla) yhtään pääsinpäivää, koska hän ahdistuksessa on; niinkuin entiseen aikaan Sebulonin ja Naphtalin maalle lievitys tapahtui, ja tulivat viimein kunnioitetuksi; niin myös ne meritien vieressä, tällä puolella Jordanin pakanain Galileassa.","Sillä ei ole sillä (maakunnalla) yhtään pääsinpäivää, koska hän ahdistuksessa on; niinkuin entiseen aikaan Sebulonin ja Naphtalin maalle lievitys tapahtui, ja tulivat viimein kunnioitetuksi; niin myös ne meritien vieressä, tällä puolella Jordanin pakanain Galileassa."],[9,2,"Kansa, joka pimeydessä vaelsi, näki suuren valkeuden, ja jotka asuivat kuoleman varjon maassa, niiden ylitse se kirkkaasti paistaa.","Kansa, joka pimeydessä vaelsi, näki suuren valkeuden, ja jotka asuivat kuoleman varjon maassa, niiden ylitse se kirkkaasti paistaa."],[9,3,"Sinä lisäät kansaa, ja lisäät hänelle iloa; sinun edessäs iloitaan, niinkuin elonaikana iloitaan, niinkuin saaliin jaossa iloitaan:","Sinä lisäät kansaa, ja lisäät hänelle iloa; sinun edessäs iloitaan, niinkuin elonaikana iloitaan, niinkuin saaliin jaossa iloitaan:"],[9,4,"Sillä sinä olet heidän kuormansa ikeen, heidän olkainsa vitsan, ja heidän vaatiansa sauvan särkenyt, niinkuin Midianin aikana.","Sillä sinä olet heidän kuormansa ikeen, heidän olkainsa vitsan, ja heidän vaatiansa sauvan särkenyt, niinkuin Midianin aikana."],[9,5,"Sillä kaikki sota ja meteli, ja veriset vaatteet pitää poltettaman ja tulella kulutettaman.","Sillä kaikki sota ja meteli, ja veriset vaatteet pitää poltettaman ja tulella kulutettaman."],[9,6,"Sillä meille on lapsi syntynyt, ja poika on meille annettu, jonka hartioilla herraus on; ja hänen nimensä kutsutaan Ihmeellinen, Neuvonantaja, Väkevä Jumala, Ijankaikkinen Isä, Rauhan päämies:","Sillä meille on lapsi syntynyt, ja poika on meille annettu, jonka hartioilla herraus on; ja hänen nimensä kutsutaan Ihmeellinen, Neuvonantaja, Väkevä Jumala, Ijankaikkinen Isä, Rauhan päämies:"],[9,7,"Että hänen herrautensa pitää suureksi tuleman, ja ei rauhalla loppua, Davidin istuimelle ja hänen valtakunnallensa, valmistamaan sitä ja vahvistamaan tuomiolla ja vanhurskaudella: hamasta nyt niin ijankaikkiseen on Herran Jumalan Zebaotin kiivaus tämän tekevä.","Että hänen herrautensa pitää suureksi tuleman, ja ei rauhalla loppua, Davidin istuimelle ja hänen valtakunnallensa, valmistamaan sitä ja vahvistamaan tuomiolla ja vanhurskaudella: hamasta nyt niin ijankaikkiseen on Herran Jumalan Zebaotin kiivaus tämän tekevä."],[9,8,"Herra on lähettänyt sanan Jakobissa, ja se on langennut Israelissa;","Herra on lähettänyt sanan Jakobissa, ja se on langennut Israelissa;"],[9,9,"Että kaikki Ephraimin kansa ja Samarian asuvaiset pitää sen tietää saaman, jotka ylpeydessä ja korialla mielellä sanovat:","Että kaikki Ephraimin kansa ja Samarian asuvaiset pitää sen tietää saaman, jotka ylpeydessä ja korialla mielellä sanovat:"],[9,10,"Tiilikivet ovat pudonneet, mutta me tahdomme sen rakentaa vuojonkivillä jälleen: Muulbärin puut ovat hakatut maahan, mutta me panemme siaan sedripuita.","Tiilikivet ovat pudonneet, mutta me tahdomme sen rakentaa vuojonkivillä jälleen: Muulbärin puut ovat hakatut maahan, mutta me panemme siaan sedripuita."],[9,11,"Sillä Herra tahtoo korottaa Retsinin sotaväen heitä vastaan, ja heidän vihollisensa nivoa yhteen,","Sillä Herra tahtoo korottaa Retsinin sotaväen heitä vastaan, ja heidän vihollisensa nivoa yhteen,"],[9,12,"Syrialaiset eteen ja Philistealaiset taa, että he söivät Israelin täydellä suulla. Näissä kaikissa ei lakkaa vielä hänen vihansa, vaan hänen kätensä on vielä ojennettu.","Syrialaiset eteen ja Philistealaiset taa, että he söivät Israelin täydellä suulla. Näissä kaikissa ei lakkaa vielä hänen vihansa, vaan hänen kätensä on vielä ojennettu."],[9,13,"Ei myös kansa käännä itseinsä hänen tykönsä, joka heitä lyö, eikä kysy Herraa Zebaotia.","Ei myös kansa käännä itseinsä hänen tykönsä, joka heitä lyö, eikä kysy Herraa Zebaotia."],[9,14,"Sentähden karsii Herra Israelilta pois, yhtenä päivänä, pään ja hännän, oksat ja kannon.","Sentähden karsii Herra Israelilta pois, yhtenä päivänä, pään ja hännän, oksat ja kannon."],[9,15,"Vanhat kunnialliset ihmiset ovat pää; mutta prophetat, jotka opettavat väärin, ovat häntä.","Vanhat kunnialliset ihmiset ovat pää; mutta prophetat, jotka opettavat väärin, ovat häntä."],[9,16,"Sillä tämän kansan johdattajat ovat pettäjät, ja ne, jotka sallivat itsensä johdattaa, ovat kadotetut.","Sillä tämän kansan johdattajat ovat pettäjät, ja ne, jotka sallivat itsensä johdattaa, ovat kadotetut."],[9,17,"Sentähden ei Herra taida iloita heidän nuorista miehistänsä, eikä armahda heidän orpolapsiansa ja leskiänsä; sillä he ovat kaikki ulkokullatut ja pahat, ja jokaisen suu puhuu hulluutta; näissä kaikissa ei lakkaa vielä hänen vihansa, vaan hänen kätensä on vielä ojennettu.","Sentähden ei Herra taida iloita heidän nuorista miehistänsä, eikä armahda heidän orpolapsiansa ja leskiänsä; sillä he ovat kaikki ulkokullatut ja pahat, ja jokaisen suu puhuu hulluutta; näissä kaikissa ei lakkaa vielä hänen vihansa, vaan hänen kätensä on vielä ojennettu."],[9,18,"Sillä jumalatoin meno on sytytetty niinkuin tuli, ja kuluttaa orjantappurat ja ohdakkeet; joka palaa niinkuin paksussa metsässä, ja nostaa savun korkialle.","Sillä jumalatoin meno on sytytetty niinkuin tuli, ja kuluttaa orjantappurat ja ohdakkeet; joka palaa niinkuin paksussa metsässä, ja nostaa savun korkialle."],[9,19,"Sillä maa on pimennyt Herran Zebaotin vihasta; niin että kansa on niinkuin tulen ruoka, ja ei yksikään armaitse toista.","Sillä maa on pimennyt Herran Zebaotin vihasta; niin että kansa on niinkuin tulen ruoka, ja ei yksikään armaitse toista."],[9,20,"Jos he ryöstävät oikialla puolella, niin he nälkää näkevät; jos he syövät vasemmalla puolella, niin ei he tule ravituksi: jokainen syö käsivartensa lihaa.","Jos he ryöstävät oikialla puolella, niin he nälkää näkevät; jos he syövät vasemmalla puolella, niin ei he tule ravituksi: jokainen syö käsivartensa lihaa."],[9,21,"Manasse Ephraimia, Ephraim Manassea, ja ne molemmat yhdestä puolesta Juudaa vastaan. Ei vielä näissä kaikissa hänen vihansa asetu, vaan hänen kätensä on vielä ojennettu.","Manasse Ephraimia, Ephraim Manassea, ja ne molemmat yhdestä puolesta Juudaa vastaan. Ei vielä näissä kaikissa hänen vihansa asetu, vaan hänen kätensä on vielä ojennettu."],[10,1,"Voi kirjanoppineita, jotka väärän lain tekevät ja väärän tuomion kirjoittavat,","Voi kirjanoppineita, jotka väärän lain tekevät ja väärän tuomion kirjoittavat,"],[10,2,"Että he vääntelisivät köyhän asian, ja tekisivät väkivaltaa raadolliselle oikeudessa, minun kansassani; niin että lesket ovat heidän saaliinsa, ja orpoja he raatelevat.","Että he vääntelisivät köyhän asian, ja tekisivät väkivaltaa raadolliselle oikeudessa, minun kansassani; niin että lesket ovat heidän saaliinsa, ja orpoja he raatelevat."],[10,3,"Mitä te tahdotte tehdä etsikkopäivänä, ja hävityksessä, joka kaukaa tulee? kenen tykö te pakenette apua saamaan? ja kuhunka te tahdotte panna teidän kunnianne?","Mitä te tahdotte tehdä etsikkopäivänä, ja hävityksessä, joka kaukaa tulee? kenen tykö te pakenette apua saamaan? ja kuhunka te tahdotte panna teidän kunnianne?"],[10,4,"Ettette vangittuin kanssa taivutettaisi, ja lyötyin seassa lankeaisi; näissä kaikissa ei ole hänen vihansa asetettu, vaan hänen kätensä on vielä nyt ojennettu.","Ettette vangittuin kanssa taivutettaisi, ja lyötyin seassa lankeaisi; näissä kaikissa ei ole hänen vihansa asetettu, vaan hänen kätensä on vielä nyt ojennettu."],[10,5,"Voi Assur, joka minun vihani vitsa on; joiden käsissä minun julmuuteni sauva on.","Voi Assur, joka minun vihani vitsa on; joiden käsissä minun julmuuteni sauva on."],[10,6,"Minä tahdon lähettää hänen ulkokullattua kansaa vastaan, ja antaa hänelle käskyn vihani kansaa vastaan, sitä täydellisesti ryöstämään, ja saalista jakamaan, ja tallaamaan sitä niinkuin lokaa kujilla.","Minä tahdon lähettää hänen ulkokullattua kansaa vastaan, ja antaa hänelle käskyn vihani kansaa vastaan, sitä täydellisesti ryöstämään, ja saalista jakamaan, ja tallaamaan sitä niinkuin lokaa kujilla."],[10,7,"Vaikka ei hän sitä niin luule, eikä hänen sydämensä niin ajattele; vaan hänen sydämensä on turmelemaan ja hävittämään monta kansaa.","Vaikka ei hän sitä niin luule, eikä hänen sydämensä niin ajattele; vaan hänen sydämensä on turmelemaan ja hävittämään monta kansaa."],[10,8,"Sillä hän sanoo: eikö kaikki minun pääruhtinaani ole kuninkaat?","Sillä hän sanoo: eikö kaikki minun pääruhtinaani ole kuninkaat?"],[10,9,"Eikö Kalno ole niinkuin Karkemis? Eikö Hamat ole niinkuin Arpad? Eikö Samaria ole niinkuin Damasku.","Eikö Kalno ole niinkuin Karkemis? Eikö Hamat ole niinkuin Arpad? Eikö Samaria ole niinkuin Damasku."],[10,10,"Niinkuin minun käteni on löytänyt epäjumalain valtakunnat, niin myös heidän epäjumalansa, jotka Jerusalemissa ja Samariassa ovat.","Niinkuin minun käteni on löytänyt epäjumalain valtakunnat, niin myös heidän epäjumalansa, jotka Jerusalemissa ja Samariassa ovat."],[10,11,"Eikö minun tule tehdä Jerusalemille, ja hänen epäjumalillensa, niinkuin minä Samariallekin ja hänen epäjumalillensa tein?","Eikö minun tule tehdä Jerusalemille, ja hänen epäjumalillensa, niinkuin minä Samariallekin ja hänen epäjumalillensa tein?"],[10,12,"Mutta koska Herra on kaikki tekonsa Zionin vuorella ja Jerusalemissa toimittanut, niin minä tahdon etsiä Assurin kuninkaan ylpeän sydämen hedelmää, ja hänen ylpeiden silmäinsä koreutta;","Mutta koska Herra on kaikki tekonsa Zionin vuorella ja Jerusalemissa toimittanut, niin minä tahdon etsiä Assurin kuninkaan ylpeän sydämen hedelmää, ja hänen ylpeiden silmäinsä koreutta;"],[10,13,"Että hän sanoo: minä olen sen toimittanut minun käteni voimalla ja minun taitoni kautta; sillä minä olen taitava: minä olen kansain rajat siirtänyt, ja heidän tavaransa ryöstänyt, ja niinkuin voimallinen lyönyt heidän asujansa maahan.","Että hän sanoo: minä olen sen toimittanut minun käteni voimalla ja minun taitoni kautta; sillä minä olen taitava: minä olen kansain rajat siirtänyt, ja heidän tavaransa ryöstänyt, ja niinkuin voimallinen lyönyt heidän asujansa maahan."],[10,14,"Ja minun käteni on löytänyt kansain tavaran niinkuin linnunpesän, niin että minä olen kaiken maan koonnut niinkuin hyljätyt munat kootaan, kussa ei yhtään ole, joka siipeänsä liikuttaa, nokkansa avaa, eli kirkaisee.","Ja minun käteni on löytänyt kansain tavaran niinkuin linnunpesän, niin että minä olen kaiken maan koonnut niinkuin hyljätyt munat kootaan, kussa ei yhtään ole, joka siipeänsä liikuttaa, nokkansa avaa, eli kirkaisee."],[10,15,"Taitaako kirves kerskata sitä vastaan, joka hänellä hakkaa, eli saha taistella sen kanssa, joka häntä vetää? Se olis niinkuin sauva tahtois liikuttaa sitä, joka sen kantaa, ja sauva nostais itsensä niinkuin ei se puu oliskaan.","Taitaako kirves kerskata sitä vastaan, joka hänellä hakkaa, eli saha taistella sen kanssa, joka häntä vetää? Se olis niinkuin sauva tahtois liikuttaa sitä, joka sen kantaa, ja sauva nostais itsensä niinkuin ei se puu oliskaan."],[10,16,"Sentähden on Herra, Herra Zebaot, lähettävä laihuuden hänen lihavainsa sekaan, ja sytyttävä hänen kunniansa palamaan kuin tulipalon.","Sentähden on Herra, Herra Zebaot, lähettävä laihuuden hänen lihavainsa sekaan, ja sytyttävä hänen kunniansa palamaan kuin tulipalon."],[10,17,"Ja Israelin valkeus on tuleva tuleksi, ja hänen pyhänsä liekiksi, ja pitää palaman, ja kuluttaman hänen orjantappuransa ja ohdakkeensa yhtenä päivänä.","Ja Israelin valkeus on tuleva tuleksi, ja hänen pyhänsä liekiksi, ja pitää palaman, ja kuluttaman hänen orjantappuransa ja ohdakkeensa yhtenä päivänä."],[10,18,"Ja hänen metsänsä ja ketonsa kunnia pitää tyhjään raukeneman, sekä sielu että ruumis, ja pitää tuleman niinkuin koska lipunkantaja nääntyy;","Ja hänen metsänsä ja ketonsa kunnia pitää tyhjään raukeneman, sekä sielu että ruumis, ja pitää tuleman niinkuin koska lipunkantaja nääntyy;"],[10,19,"Niin että hänen metsänsä jääneet puut lukea taidetaan, ja että lapsikin ne pyältää taitaa.","Niin että hänen metsänsä jääneet puut lukea taidetaan, ja että lapsikin ne pyältää taitaa."],[10,20,"Silloin ei pidä jääneet Israelissa, ja ne jotka tallella ovat Jakobin huoneesta, enää turvaaman häneen, joka heitä lyö; vaan pitää todella turvaaman Herraan Israelin pyhään.","Silloin ei pidä jääneet Israelissa, ja ne jotka tallella ovat Jakobin huoneesta, enää turvaaman häneen, joka heitä lyö; vaan pitää todella turvaaman Herraan Israelin pyhään."],[10,21,"Jääneet pitää kääntymän, Jakobin jääneet, väkevän Jumalan tykö.","Jääneet pitää kääntymän, Jakobin jääneet, väkevän Jumalan tykö."],[10,22,"Sillä jos sinun kansas, o Israel, on niinkuin hiekka meressä, niin kuitenkin heidän jääneensä kääntyvät; sillä estetty hävitys pitää vuotaman yltäkylläisen vanhurskauden.","Sillä jos sinun kansas, o Israel, on niinkuin hiekka meressä, niin kuitenkin heidän jääneensä kääntyvät; sillä estetty hävitys pitää vuotaman yltäkylläisen vanhurskauden."],[10,23,"Että Herra, Herra Zebaot, antaa tulla aivotun hävityksen koko maahan, ja hallitsee sen.","Että Herra, Herra Zebaot, antaa tulla aivotun hävityksen koko maahan, ja hallitsee sen."],[10,24,"Sanoo siis Herra, Herra Zebaot: älä pelkää kansani, joka Zionissa asut, Assuria. Hän lyö sinua vitsalla, ja nostaa sauvansa sinua vastaan niinkuin Egyptissä.","Sanoo siis Herra, Herra Zebaot: älä pelkää kansani, joka Zionissa asut, Assuria. Hän lyö sinua vitsalla, ja nostaa sauvansa sinua vastaan niinkuin Egyptissä."],[10,25,"Sillä aivan vähän ajan perästä pitää armottomuus ja minun vihani täytettämän heidän kadotukseksensa.","Sillä aivan vähän ajan perästä pitää armottomuus ja minun vihani täytettämän heidän kadotukseksensa."],[10,26,"Silloin on Herra Zebaot nostava ruoskan heidän päällensä, niinkuin Midianin tapossa Orebin kalliolla, ja on ylentävä sauvansa meren yli, niinkuin Egyptissä.","Silloin on Herra Zebaot nostava ruoskan heidän päällensä, niinkuin Midianin tapossa Orebin kalliolla, ja on ylentävä sauvansa meren yli, niinkuin Egyptissä."],[10,27,"Silloin pitää hänen kuormansa pakeneman pois sinun hartioiltas, ja hänen ikeensä sinun kaulastas, sillä ikeen pitää pirstaantuman lihavuudesta.","Silloin pitää hänen kuormansa pakeneman pois sinun hartioiltas, ja hänen ikeensä sinun kaulastas, sillä ikeen pitää pirstaantuman lihavuudesta."],[10,28,"Hän tulee Ajatiin, hän vaeltaa Migronin lävitse, hän katselee aseensa Mikmaassa.","Hän tulee Ajatiin, hän vaeltaa Migronin lävitse, hän katselee aseensa Mikmaassa."],[10,29,"He vaeltavat luotuspaikan ylitse; he pitävät yösiaa Gebaassa; Raama peljästyy, Saulin Gibea pakenee.","He vaeltavat luotuspaikan ylitse; he pitävät yösiaa Gebaassa; Raama peljästyy, Saulin Gibea pakenee."],[10,30,"Sinä tytär Gallim, huuda vahvasti: ota vaari Laiksesta; sinä raadollinen Anatot.","Sinä tytär Gallim, huuda vahvasti: ota vaari Laiksesta; sinä raadollinen Anatot."],[10,31,"Madmena menee pois tieltä, Gebimin asuvaiset juoksevat matkaansa.","Madmena menee pois tieltä, Gebimin asuvaiset juoksevat matkaansa."],[10,32,"Ollaan vielä päiväkunta Nobissa; niin hän on kääntävä kätensä Zionin tyttären vuoreen päin, ja Jerusalemin korkeuden puoleen.","Ollaan vielä päiväkunta Nobissa; niin hän on kääntävä kätensä Zionin tyttären vuoreen päin, ja Jerusalemin korkeuden puoleen."],[10,33,"Katso, Herra, Herra Zebaot, on hakkaava oksat väellä, ja lyhentävä sitä korkiaa; ja korkiat pitää alennettaman.","Katso, Herra, Herra Zebaot, on hakkaava oksat väellä, ja lyhentävä sitä korkiaa; ja korkiat pitää alennettaman."],[10,34,"Ja tihkiä metsä pitää raudalla maahan hakattaman; ja Libanon pitää voimallisen kautta kaatuman.","Ja tihkiä metsä pitää raudalla maahan hakattaman; ja Libanon pitää voimallisen kautta kaatuman."],[11,1,"Ja vitsa on putkahtava Isain kannosta, ja vesa on hedelmöitsevä hänen juurestansa,","Ja vitsa on putkahtava Isain kannosta, ja vesa on hedelmöitsevä hänen juurestansa,"],[11,2,"Jonka päällä Herran henki lepää, viisauden ja ymmärryksen henki, neuvon ja väkevyyden henki, taidon ja Herran pelvon henki.","Jonka päällä Herran henki lepää, viisauden ja ymmärryksen henki, neuvon ja väkevyyden henki, taidon ja Herran pelvon henki."],[11,3,"Ja hänen haistamisensa on Herran pelvossa oleva: ei hän tuomitse silmäinsä näön jälkeen, eikä nuhtele korvainsa kuulon jälkeen,","Ja hänen haistamisensa on Herran pelvossa oleva: ei hän tuomitse silmäinsä näön jälkeen, eikä nuhtele korvainsa kuulon jälkeen,"],[11,4,"Vaan hän tuomitsee köyhiä vanhurskaudessa, ja nuhtelee maan raadollisia oikeudella, ja lyö maata suunsa sauvalla, ja huultensa hengellä tappaa hän jumalattoman.","Vaan hän tuomitsee köyhiä vanhurskaudessa, ja nuhtelee maan raadollisia oikeudella, ja lyö maata suunsa sauvalla, ja huultensa hengellä tappaa hän jumalattoman."],[11,5,"Vanhurskaus on hänen kupeinsa vyö, ja usko hänen munaskuinsa side.","Vanhurskaus on hänen kupeinsa vyö, ja usko hänen munaskuinsa side."],[11,6,"Sudet asuvat lammasten seassa, ja pardi makaa vohlain kanssa; vasikka myös ja nuori jalopeura, ja syötinnaudat käyvät yhdessä, ja vähä poikainen kaitsee heitä.","Sudet asuvat lammasten seassa, ja pardi makaa vohlain kanssa; vasikka myös ja nuori jalopeura, ja syötinnaudat käyvät yhdessä, ja vähä poikainen kaitsee heitä."],[11,7,"Niin myös lehmät ja karhut käyvät yhdellä laitumella, ja heidän vasikkansa myös ynnä makaavat; jalopeura syö olkia niinkuin härkä.","Niin myös lehmät ja karhut käyvät yhdellä laitumella, ja heidän vasikkansa myös ynnä makaavat; jalopeura syö olkia niinkuin härkä."],[11,8,"Ja imevä lapsi ihastuu vaskikäärmeen lävestä; ja vieroitettu lapsi pistää kätensä basiliskin luolaan.","Ja imevä lapsi ihastuu vaskikäärmeen lävestä; ja vieroitettu lapsi pistää kätensä basiliskin luolaan."],[11,9,"Ei kenkään vahingoitse eikä turmele kaikella pyhyyteni vuorella; sillä maa on täynnä Herran tuntoa, niinkuin meri vedellä peitetty.","Ei kenkään vahingoitse eikä turmele kaikella pyhyyteni vuorella; sillä maa on täynnä Herran tuntoa, niinkuin meri vedellä peitetty."],[11,10,"Ja tapahtuu sinä päivänä, että Isain juurta, joka seisoo kansan lippuna, pitää pakanain etsimän; ja hänen leponsa on kunniallinen oleva.","Ja tapahtuu sinä päivänä, että Isain juurta, joka seisoo kansan lippuna, pitää pakanain etsimän; ja hänen leponsa on kunniallinen oleva."],[11,11,"Ja tapahtuu sinä päivänä, että Herra vielä toisen kerran kokottaa kätensä ostamaan kansansa tähteitä, jotka jääneet ovat, Assyriasta, Egyptistä, Patroksesta, Etiopista, Elamista, Sinearista, Hamatista ja meren luodoista.","Ja tapahtuu sinä päivänä, että Herra vielä toisen kerran kokottaa kätensä ostamaan kansansa tähteitä, jotka jääneet ovat, Assyriasta, Egyptistä, Patroksesta, Etiopista, Elamista, Sinearista, Hamatista ja meren luodoista."],[11,12,"Ja hän nostaa lipun pakanoissa, tuodaksensa Israelin pakolaiset, ja myös kootaksensa Juudan hajoitetut, neljästä maan äärestä.","Ja hän nostaa lipun pakanoissa, tuodaksensa Israelin pakolaiset, ja myös kootaksensa Juudan hajoitetut, neljästä maan äärestä."],[11,13,"Ja kiivaus Ephraimia vastaan pitää lakkaaman, ja Juudan viholliset pitää peräti katooman, niin ettei Ephraimin pidä kadehtiman Juudaa, ja Juudan ei pidä ahdistaman Ephraimia.","Ja kiivaus Ephraimia vastaan pitää lakkaaman, ja Juudan viholliset pitää peräti katooman, niin ettei Ephraimin pidä kadehtiman Juudaa, ja Juudan ei pidä ahdistaman Ephraimia."],[11,14,"Mutta heidän pitää karkaaman Philistealaisten niskaan, länteen päin, ja ryöstämän idän puolella asuvaiset; Edom ja Moab pitää heidän käsiinsä lankeeman, ja Ammonin pojat pitää heille kuuliaiset oleman.","Mutta heidän pitää karkaaman Philistealaisten niskaan, länteen päin, ja ryöstämän idän puolella asuvaiset; Edom ja Moab pitää heidän käsiinsä lankeeman, ja Ammonin pojat pitää heille kuuliaiset oleman."],[11,15,"Ja Herra on kiroova Egyptin meren lahden, ja liikuttava kätensä virtaa vastaan, tuulensa väkevyydessä; ja hän lyö sen seitsemäksi ojaksi, niin että kengässä käydään ylitse.","Ja Herra on kiroova Egyptin meren lahden, ja liikuttava kätensä virtaa vastaan, tuulensa väkevyydessä; ja hän lyö sen seitsemäksi ojaksi, niin että kengässä käydään ylitse."],[11,16,"Ja rata on oleva hänen jääneelle kansallensa, joka Assyrialaisilta jätetty oli; niinkuin Israelille silloin tapahtui, kuin hän Egyptistä läksi.","Ja rata on oleva hänen jääneelle kansallensa, joka Assyrialaisilta jätetty oli; niinkuin Israelille silloin tapahtui, kuin hän Egyptistä läksi."],[12,1,"Silloin pitää sinun sanoman: minä kiitän sinua, Herra, ettäs vihainen olet ollut minun päälleni; mutta sinun vihas on palannut, ja sinä lohdutat minua.","Silloin pitää sinun sanoman: minä kiitän sinua, Herra, ettäs vihainen olet ollut minun päälleni; mutta sinun vihas on palannut, ja sinä lohdutat minua."],[12,2,"Katso, Jumala on minun autuuteni, minä olen turvassa ja en mitään pelkää; sillä Herra, Herra on minun väkevyyteni, ja minun virteni, ja hän on minun autuuteni.","Katso, Jumala on minun autuuteni, minä olen turvassa ja en mitään pelkää; sillä Herra, Herra on minun väkevyyteni, ja minun virteni, ja hän on minun autuuteni."],[12,3,"Teidän pitää ammentaman vettä ilolla autuuden lähteistä.","Teidän pitää ammentaman vettä ilolla autuuden lähteistä."],[12,4,"Ja silloin te sanotte: kiittäkäät Herraa, ja saarnatkaat hänen nimeänsä, julistakaat kansoissa hänen tekojansa, muistakaat kuinka korkia hänen nimensä on.","Ja silloin te sanotte: kiittäkäät Herraa, ja saarnatkaat hänen nimeänsä, julistakaat kansoissa hänen tekojansa, muistakaat kuinka korkia hänen nimensä on."],[12,5,"Veisatkaat kiitosta Herralle, sillä hän on voimallisesti itsensä asettanut; se olkoon tiettävä kaikessa maassa.","Veisatkaat kiitosta Herralle, sillä hän on voimallisesti itsensä asettanut; se olkoon tiettävä kaikessa maassa."],[12,6,"Korota äänes ja veisaa, sinä Zionin asuvainen, sillä Israelin pyhä on suuri sinun keskelläs.","Korota äänes ja veisaa, sinä Zionin asuvainen, sillä Israelin pyhä on suuri sinun keskelläs."],[13,1,"Babelin kuorma, jonka Jesaia Amotsin poika näki.","Babelin kuorma, jonka Jesaia Amotsin poika näki."],[13,2,"Nostakaat lippu korkialle vuorelle, huutakaat kovin heitä vastaan; nostakaat kätenne ylös, antakaat pääruhtinasten mennä porteista sisälle.","Nostakaat lippu korkialle vuorelle, huutakaat kovin heitä vastaan; nostakaat kätenne ylös, antakaat pääruhtinasten mennä porteista sisälle."],[13,3,"Minä olen käskenyt pyhitetyilleni, ja kutsunut väkeväni minun vihaani, jotka iloitsevat minun kunniassani.","Minä olen käskenyt pyhitetyilleni, ja kutsunut väkeväni minun vihaani, jotka iloitsevat minun kunniassani."],[13,4,"Siellä on suuren joukon huuto vuorilla, niinkuin paljon kansan huuto, niinkuin humaus pakanain kootusta valtakunnasta: Herra Zebaot varustaa joukon sotaan,","Siellä on suuren joukon huuto vuorilla, niinkuin paljon kansan huuto, niinkuin humaus pakanain kootusta valtakunnasta: Herra Zebaot varustaa joukon sotaan,"],[13,5,"Jotka kaukaiselta maalta tulevat, taivaan ääristä: tosin itse Herra vihansa joukolla, hävittämään koko maata.","Jotka kaukaiselta maalta tulevat, taivaan ääristä: tosin itse Herra vihansa joukolla, hävittämään koko maata."],[13,6,"Valittakaat, että Herran päivän on juuri läsnä; hän tulee niinkuin hävitys Kaikkivaltiaalta.","Valittakaat, että Herran päivän on juuri läsnä; hän tulee niinkuin hävitys Kaikkivaltiaalta."],[13,7,"Sentähden pitää kaikki kädet lankeeman maahan, ja kaikki ihmisten sydämet vaipuman.","Sentähden pitää kaikki kädet lankeeman maahan, ja kaikki ihmisten sydämet vaipuman."],[13,8,"Hämmästys, tuska ja kipu pitää tuleman heidän päällensä; heillä pitää oleman tuska niinkuin lapsen synnyttäväisellä: yhden pitää toista kauhistuman, heidän kasvonsa pitää oleman punaisen niinkuin tulen.","Hämmästys, tuska ja kipu pitää tuleman heidän päällensä; heillä pitää oleman tuska niinkuin lapsen synnyttäväisellä: yhden pitää toista kauhistuman, heidän kasvonsa pitää oleman punaisen niinkuin tulen."],[13,9,"Sillä katso, Herran päivä tulee kauhiasti vihaisna ja julmana, hävittämään maata, ja siitä teloittamaan syntisiä,","Sillä katso, Herran päivä tulee kauhiasti vihaisna ja julmana, hävittämään maata, ja siitä teloittamaan syntisiä,"],[13,10,"Ettei tähdet taivaassa, ja hänen kointähtensä paista kirkkaasti; aurinko ylenee synkiästi, ja kuu paistaa pimiästi.","Ettei tähdet taivaassa, ja hänen kointähtensä paista kirkkaasti; aurinko ylenee synkiästi, ja kuu paistaa pimiästi."],[13,11,"Minä tahdon rangaista maan piirin hänen pahuutensa tähden ja jumalattomat heidän vikainsa tähden, ja tahdon lopettaa koreiden ylpeyden, ja nöyryyttää jaloin ynseyden;","Minä tahdon rangaista maan piirin hänen pahuutensa tähden ja jumalattomat heidän vikainsa tähden, ja tahdon lopettaa koreiden ylpeyden, ja nöyryyttää jaloin ynseyden;"],[13,12,"Niin että mies pitää oleman kalliimpi puhdasta kultaa, ja ihminen enempi kunnioitettu kuin kappale Ophirin kultaa.","Niin että mies pitää oleman kalliimpi puhdasta kultaa, ja ihminen enempi kunnioitettu kuin kappale Ophirin kultaa."],[13,13,"Sentähden minä liikutan taivaan, niin että maan pitää vapiseman paikastansa Herran Zebaotin vihan kautta, ja hänen julman vihansa päivän kautta.","Sentähden minä liikutan taivaan, niin että maan pitää vapiseman paikastansa Herran Zebaotin vihan kautta, ja hänen julman vihansa päivän kautta."],[13,14,"Ja hänen pitää oleman niinkuin pois ajetun metsävuohen, ja niinkuin lauman ilman paimenta; niin että jokaisen pitää palajaman kansansa tykö, ja jokaisen pakeneman maallensa;","Ja hänen pitää oleman niinkuin pois ajetun metsävuohen, ja niinkuin lauman ilman paimenta; niin että jokaisen pitää palajaman kansansa tykö, ja jokaisen pakeneman maallensa;"],[13,15,"Että jokainen, joka löydetään, pitää pistettämän lävitse, ja jokainen, joka siellä läsnä on, pitää miekalla lankeeman.","Että jokainen, joka löydetään, pitää pistettämän lävitse, ja jokainen, joka siellä läsnä on, pitää miekalla lankeeman."],[13,16,"Pitää myös heidän lapsensa heidän silmäinsä edessä tapettaman, heidän huoneensa ryöstettämän, ja heidän emäntänsä häväistämän.","Pitää myös heidän lapsensa heidän silmäinsä edessä tapettaman, heidän huoneensa ryöstettämän, ja heidän emäntänsä häväistämän."],[13,17,"Katso, minä herätän Mediläiset heidän päällensä, jotka ei etsi hopiaa, eikä kysy kultaa;","Katso, minä herätän Mediläiset heidän päällensä, jotka ei etsi hopiaa, eikä kysy kultaa;"],[13,18,"Vaan ampuvat nuoria miehiä kuoliaaksi joutsilla, ja ei armahda äidin kohdun hedelmää, eikä säästä lastakaan.","Vaan ampuvat nuoria miehiä kuoliaaksi joutsilla, ja ei armahda äidin kohdun hedelmää, eikä säästä lastakaan."],[13,19,"Näin pitää Babeli, se kaikkein kaunein valtakuntain seassa, Kaldealaisten koreus, tuleman; niinkuin Jumala kukisti Sodoman ja Gomorran;","Näin pitää Babeli, se kaikkein kaunein valtakuntain seassa, Kaldealaisten koreus, tuleman; niinkuin Jumala kukisti Sodoman ja Gomorran;"],[13,20,"Niin ettei siellä enää pidä asuttaman ijankaikkisesti, eikä siellä asuntoa pidettämän suvusta sukuun. Niin ettei myös Arabialaisten sinne pidä yhtään majaa tekemän, eikä paimenten pidä siellä lounalla makaaman.","Niin ettei siellä enää pidä asuttaman ijankaikkisesti, eikä siellä asuntoa pidettämän suvusta sukuun. Niin ettei myös Arabialaisten sinne pidä yhtään majaa tekemän, eikä paimenten pidä siellä lounalla makaaman."],[13,21,"Vaan metsän pedot pitää siellä makaaman, ja heidän huoneensa oleman täynnä kauheita petoja, ja yököt pitää siellä asuman, ja siellä liekkiöt hyppelemän,","Vaan metsän pedot pitää siellä makaaman, ja heidän huoneensa oleman täynnä kauheita petoja, ja yököt pitää siellä asuman, ja siellä liekkiöt hyppelemän,"],[13,22,"Ja tarhapöllöt laulaman hänen kaunistetuissa huoneissansa, ja lohikäärmeet iloisissa linnoissa. Ja hänen aikansa on pian tuleva, ja hänen päivänsä ei pidä viipymän.","Ja tarhapöllöt laulaman hänen kaunistetuissa huoneissansa, ja lohikäärmeet iloisissa linnoissa. Ja hänen aikansa on pian tuleva, ja hänen päivänsä ei pidä viipymän."],[14,1,"Sillä Herra armahtaa Jakobia ja valitsee vielä nyt Israelin, ja panee heitä heidän maahansa; ja muukalaisten pitää antaman itsensä heidän allensa, ja suostuman Jakobin huoneeseen.","Sillä Herra armahtaa Jakobia ja valitsee vielä nyt Israelin, ja panee heitä heidän maahansa; ja muukalaisten pitää antaman itsensä heidän allensa, ja suostuman Jakobin huoneeseen."],[14,2,"Ja kansat ottavat heidät, ja vievät heitä heidän paikkaansa, ja Israelin huone on omistava heitä Herran maassa palvelioiksi ja piioiksi; ja pitää heitä vankina pitämän, joilta he olivat vangitut, ja niin he vallitsevat vaivaajiansa.","Ja kansat ottavat heidät, ja vievät heitä heidän paikkaansa, ja Israelin huone on omistava heitä Herran maassa palvelioiksi ja piioiksi; ja pitää heitä vankina pitämän, joilta he olivat vangitut, ja niin he vallitsevat vaivaajiansa."],[14,3,"Ja pitää tapahtuman siihen aikaan kuin Herra on antava sinulle levon sinun surustas ja vaivastas, ja siitä kovasta orjuudesta, jossas orjana pidettiin;","Ja pitää tapahtuman siihen aikaan kuin Herra on antava sinulle levon sinun surustas ja vaivastas, ja siitä kovasta orjuudesta, jossas orjana pidettiin;"],[14,4,"Että sinun pitää puhuman näin Babelin kuningasta vastaan ja sanoman: kuinka vaivaaja on tullut perikatoon, ja veron laskemus on loppuun joutunut.","Että sinun pitää puhuman näin Babelin kuningasta vastaan ja sanoman: kuinka vaivaaja on tullut perikatoon, ja veron laskemus on loppuun joutunut."],[14,5,"Herra on taittanut jumalattomain sauvan, vallitsiain vitsan.","Herra on taittanut jumalattomain sauvan, vallitsiain vitsan."],[14,6,"Joka löi kansaa julmuudessa ilman lakkaamata, ja vallitsi pakanoita ankaruudella, ja vaivasi heitä ilman laupiutta.","Joka löi kansaa julmuudessa ilman lakkaamata, ja vallitsi pakanoita ankaruudella, ja vaivasi heitä ilman laupiutta."],[14,7,"Nyt on kuitenkin koko maailmalla lepo, ja on alallansa ja riemuitsee ilossa.","Nyt on kuitenkin koko maailmalla lepo, ja on alallansa ja riemuitsee ilossa."],[14,8,"Ja hongat myös riemuitsevat sinusta, ja sedrit Libanonissa, (ja sanovat): ettäs makaat, niin ei nouse yhtään, joka meitä maahan hakkaa.","Ja hongat myös riemuitsevat sinusta, ja sedrit Libanonissa, (ja sanovat): ettäs makaat, niin ei nouse yhtään, joka meitä maahan hakkaa."],[14,9,"Helvetti vapisi alhaalla sinua, sinun tulemisestas; se herättää sinulle kuolleet, kaiken maailman päämiehet, ja käski kaikkia pakanain kuninkaita nousta heidän istuimiltansa.","Helvetti vapisi alhaalla sinua, sinun tulemisestas; se herättää sinulle kuolleet, kaiken maailman päämiehet, ja käski kaikkia pakanain kuninkaita nousta heidän istuimiltansa."],[14,10,"Kaikkein pitää vastaaman ja sanoman sinulle: sinä olet myös lyöty niinkuin mekin, ja sinun kätees käy niinkuin meidänkin.","Kaikkein pitää vastaaman ja sanoman sinulle: sinä olet myös lyöty niinkuin mekin, ja sinun kätees käy niinkuin meidänkin."],[14,11,"Sinun ylpeytes on joutunut helvettiin alas, sinun kanteleis kilisemisellä; koin pitää oleman sinun vuotees, ja madot sinun peittees.","Sinun ylpeytes on joutunut helvettiin alas, sinun kanteleis kilisemisellä; koin pitää oleman sinun vuotees, ja madot sinun peittees."],[14,12,"Kuinka sinä kaunis kointähti olet pudonnut taivaasta? kuinkas olet maan päälle langennut, joka pakanat teit heikoksi?","Kuinka sinä kaunis kointähti olet pudonnut taivaasta? kuinkas olet maan päälle langennut, joka pakanat teit heikoksi?"],[14,13,"Vaan sinä ajattelit sydämessäs: minä astun taivaaseen, ja korotan istuimeni Jumalan tähtien ylitse: minä istutan itseni todistuksen vuorelle, sille puolelle pohjaa päin.","Vaan sinä ajattelit sydämessäs: minä astun taivaaseen, ja korotan istuimeni Jumalan tähtien ylitse: minä istutan itseni todistuksen vuorelle, sille puolelle pohjaa päin."],[14,14,"Minä tahdon vaeltaa korkeiden pilvien päällä, ja olla kaikkein Korkeimman vertainen.","Minä tahdon vaeltaa korkeiden pilvien päällä, ja olla kaikkein Korkeimman vertainen."],[14,15,"Kuitenkin sinä sysätään helvettiin, luolan puolelle.","Kuitenkin sinä sysätään helvettiin, luolan puolelle."],[14,16,"Joka sinun näkee, hänen pitää katseleman sinua ja katsoman päälles, (ja sanoman): onko tämä se mies, joka maailman saatti värisemään, ja valtakunnat vapisemaan?","Joka sinun näkee, hänen pitää katseleman sinua ja katsoman päälles, (ja sanoman): onko tämä se mies, joka maailman saatti värisemään, ja valtakunnat vapisemaan?"],[14,17,"Joka maan piirin autioksi saatti, ja kukisti siellä kaupungit, ja ei päästänyt vankejansa kotia?","Joka maan piirin autioksi saatti, ja kukisti siellä kaupungit, ja ei päästänyt vankejansa kotia?"],[14,18,"Kaikki pakanain kuninkaat makaavat kuitenkin kunnialla, jokainen huoneessansa;","Kaikki pakanain kuninkaat makaavat kuitenkin kunnialla, jokainen huoneessansa;"],[14,19,"Mutta sinä olet hyljätty haudastas niinkuin kauhia vesa, niinkuin lyötyin vaatteet, jotka miekalla ovat kuoliaaksi pistetyt, jotka menevät alas kivikuoppaan, niinkuin tallattu raato.","Mutta sinä olet hyljätty haudastas niinkuin kauhia vesa, niinkuin lyötyin vaatteet, jotka miekalla ovat kuoliaaksi pistetyt, jotka menevät alas kivikuoppaan, niinkuin tallattu raato."],[14,20,"Ei sinua pidä niin haudattaman kuin ne; sillä sinä olet hävittänyt maas, ja tappanut kansas; sentähden ei pidä ikänä muistettaman ilkiäin siementä.","Ei sinua pidä niin haudattaman kuin ne; sillä sinä olet hävittänyt maas, ja tappanut kansas; sentähden ei pidä ikänä muistettaman ilkiäin siementä."],[14,21,"Valmistakaat teurastamaan hänen lapsiansa, heidän isäinsä pahain tekoin tähden, ettei he nousisi eli perisi maata, eikä täyttäisi maan piiriä kaupungeilla.","Valmistakaat teurastamaan hänen lapsiansa, heidän isäinsä pahain tekoin tähden, ettei he nousisi eli perisi maata, eikä täyttäisi maan piiriä kaupungeilla."],[14,22,"Ja minä tulen heidän päällensä, sanoo Herra Zebaot, ja hävitän Babelissa hänen nimensä, hänen jääneensä, sikiänsä ja sukukuntansa, sanoo Herra,","Ja minä tulen heidän päällensä, sanoo Herra Zebaot, ja hävitän Babelissa hänen nimensä, hänen jääneensä, sikiänsä ja sukukuntansa, sanoo Herra,"],[14,23,"Ja teen hänen tarhapöllöin perinnöksi ja vesikuljuksi; ja käväisen hänen hävityksen luudalla, sanoo Herra Zebaot.","Ja teen hänen tarhapöllöin perinnöksi ja vesikuljuksi; ja käväisen hänen hävityksen luudalla, sanoo Herra Zebaot."],[14,24,"Herra Zebaot on vannonut ja sanonut: mitämaks, että sen pitää niin tapahtuman kuin minä ajattelen, ja pitää niin pysymän kuin minun mielessäni on:","Herra Zebaot on vannonut ja sanonut: mitämaks, että sen pitää niin tapahtuman kuin minä ajattelen, ja pitää niin pysymän kuin minun mielessäni on:"],[14,25,"Että Assur telataan minun maassani, ja minä tallaan hänen minun vuorellani; että hänen ikeensä heiltä otettaisiin, ja hänen kuormansa heidän kaulastansa tulis pois.","Että Assur telataan minun maassani, ja minä tallaan hänen minun vuorellani; että hänen ikeensä heiltä otettaisiin, ja hänen kuormansa heidän kaulastansa tulis pois."],[14,26,"Nämät ovat hänen juonensa, joita hän pitää kaikissa maan paikoissa; ja se on se kohotettu käsi kaikkein pakanain ylitse.","Nämät ovat hänen juonensa, joita hän pitää kaikissa maan paikoissa; ja se on se kohotettu käsi kaikkein pakanain ylitse."],[14,27,"Sillä Herra Zebaot on sen päättänyt, kuka tahtoo tyhjäksi tehdä? ja hänen kätensä on kokotettu, kuka voi sen vääntää pois?","Sillä Herra Zebaot on sen päättänyt, kuka tahtoo tyhjäksi tehdä? ja hänen kätensä on kokotettu, kuka voi sen vääntää pois?"],[14,28,"Sinä vuonna kuin kuningas Ahas kuoli, nähtiin tämä kuorma:","Sinä vuonna kuin kuningas Ahas kuoli, nähtiin tämä kuorma:"],[14,29,"Sinä Philistea, älä niin kovin riemuitse, että se vitsa, joka sinua löi, on taitettu; sillä käärmeen juuresta on tuleva basiliski, ja hänen hedelmänsä on tulinen lentävä kärme.","Sinä Philistea, älä niin kovin riemuitse, että se vitsa, joka sinua löi, on taitettu; sillä käärmeen juuresta on tuleva basiliski, ja hänen hedelmänsä on tulinen lentävä kärme."],[14,30,"Sillä tarvitsevaisten esikoiset pitää korjaaman itsiänsä, ja köyhät suruttomasti lepäämän; mutta sinun juures tapan minä nälällä, ja suretan sinun jäänees.","Sillä tarvitsevaisten esikoiset pitää korjaaman itsiänsä, ja köyhät suruttomasti lepäämän; mutta sinun juures tapan minä nälällä, ja suretan sinun jäänees."],[14,31,"Surkuttele sinuas, portti, huuda sinä kaupunki, koko Philistealaisten maa on marras! sillä pohjoisesta tulee savu, ja ei yksikään ole majassansa.","Surkuttele sinuas, portti, huuda sinä kaupunki, koko Philistealaisten maa on marras! sillä pohjoisesta tulee savu, ja ei yksikään ole majassansa."],[14,32,"Ja mitä pakanain sanansaattajia vastataan? nimittäin, että Herra on perustanut Zionin, ja siellä pitää hänen kansansa raadollisilla turva oleman.","Ja mitä pakanain sanansaattajia vastataan? nimittäin, että Herra on perustanut Zionin, ja siellä pitää hänen kansansa raadollisilla turva oleman."],[15,1,"Tämä on Moabin kuorma: yöllä tulee hävitys Arin Moabissa, se on jo pois; yöllä tulee hävitys Kirin Moabissa, se on jo pois.","Tämä on Moabin kuorma: yöllä tulee hävitys Arin Moabissa, se on jo pois; yöllä tulee hävitys Kirin Moabissa, se on jo pois."],[15,2,"Bat ja Dibon menevät ylös kukkulalle itkemään, ja Moab suremaan Neboa ja Metbaa; kaikki päät ovat ajellut, koko parta on leikattu.","Bat ja Dibon menevät ylös kukkulalle itkemään, ja Moab suremaan Neboa ja Metbaa; kaikki päät ovat ajellut, koko parta on leikattu."],[15,3,"Kaduillansa käyvät he kiedottuina säkkeihin: kattoinsa päällä ja kaduilla he kaikki itsiänsä surkuttelevat ja tulevat itkein alas.","Kaduillansa käyvät he kiedottuina säkkeihin: kattoinsa päällä ja kaduilla he kaikki itsiänsä surkuttelevat ja tulevat itkein alas."],[15,4,"Hesboni ja Elale huutavat, niin että heidän äänensä kuuluu hamaan Jahtsaan; sentähden asettenkantajat surkuttelevat itsiänsä Moabissa, että heidän sielullensa käy nurin.","Hesboni ja Elale huutavat, niin että heidän äänensä kuuluu hamaan Jahtsaan; sentähden asettenkantajat surkuttelevat itsiänsä Moabissa, että heidän sielullensa käy nurin."],[15,5,"Minun sydämeni huutaa Moabia, heidän kulkiansa pakenevat aina Zoariin, kolmikarjaista lehmää; sillä he menevät Luhitin paltaan ja itkevät, ja tiellä Horonaimiin päin nousee vaikia huuto.","Minun sydämeni huutaa Moabia, heidän kulkiansa pakenevat aina Zoariin, kolmikarjaista lehmää; sillä he menevät Luhitin paltaan ja itkevät, ja tiellä Horonaimiin päin nousee vaikia huuto."],[15,6,"Sillä Nimrimin vedet kuivuvat, niin että heinä siellä kuivettuu, ja ruoho lakastuu; ja ei yhtään viheriäistä ruohoa kasva.","Sillä Nimrimin vedet kuivuvat, niin että heinä siellä kuivettuu, ja ruoho lakastuu; ja ei yhtään viheriäistä ruohoa kasva."],[15,7,"Sillä ne tavarat, jotka he koonneet ovat, ja kansa, jonka he varustaneet ovat, viedään pajuojan ylitse.","Sillä ne tavarat, jotka he koonneet ovat, ja kansa, jonka he varustaneet ovat, viedään pajuojan ylitse."],[15,8,"Huuto hajoo Moabin rajoja ympäri, he itkevät hamaan Eglaimiin, ja itkevät Elimin kaivon tykönä;","Huuto hajoo Moabin rajoja ympäri, he itkevät hamaan Eglaimiin, ja itkevät Elimin kaivon tykönä;"],[15,9,"Että Dimonin vedet ovat verta täynnä. Siihen minä tahdon vielä enempi antaa tulla Dimonin päälle, ja myös heidän päällensä, jotka Moabin jalopeuralta päässeet ovat, ja jääneiden päälle maassa.","Että Dimonin vedet ovat verta täynnä. Siihen minä tahdon vielä enempi antaa tulla Dimonin päälle, ja myös heidän päällensä, jotka Moabin jalopeuralta päässeet ovat, ja jääneiden päälle maassa."],[16,1,"Lähettäkäät maaherran karitsat Selasta korven tyköä Zionin tyttären vuorelle.","Lähettäkäät maaherran karitsat Selasta korven tyköä Zionin tyttären vuorelle."],[16,2,"Mutta niinkuin lintu lentää pois, joka pesästänsä ajettu on, niin pitää Moabin tyttärelle tapahtuman Arnonin luotuspaikoissa.","Mutta niinkuin lintu lentää pois, joka pesästänsä ajettu on, niin pitää Moabin tyttärelle tapahtuman Arnonin luotuspaikoissa."],[16,3,"Pitäkäät neuvoa yhdessä, sanokaat tuomio, tee sinulles puolipäivän varjo niinkuin yö; kätke pois ajetut, ja älä ilmoita kulkioita.","Pitäkäät neuvoa yhdessä, sanokaat tuomio, tee sinulles puolipäivän varjo niinkuin yö; kätke pois ajetut, ja älä ilmoita kulkioita."],[16,4,"Anna minun pois ajettuni asua tykönäs; ole Moab heidän varjeluksensa hävittäjää vastaan; niin vaivaaja saa lopun, kukistaja lakkaa, ja sotkuja taukoo maassa.","Anna minun pois ajettuni asua tykönäs; ole Moab heidän varjeluksensa hävittäjää vastaan; niin vaivaaja saa lopun, kukistaja lakkaa, ja sotkuja taukoo maassa."],[16,5,"Mutta istuin valmistetaan armosta yhdelle istua, totuudessa, Davidin majassa, tuomita ja etsiä oikeutta, ja pikaisesti toimittaa vanhurskautta.","Mutta istuin valmistetaan armosta yhdelle istua, totuudessa, Davidin majassa, tuomita ja etsiä oikeutta, ja pikaisesti toimittaa vanhurskautta."],[16,6,"Mutta me kuulemme Moabin ylpeydestä, että hän on aivan ylpeä, niin että hänen ylpeytensä, koreutensa ja vihansa on suurempi kuin hänen voimansa.","Mutta me kuulemme Moabin ylpeydestä, että hän on aivan ylpeä, niin että hänen ylpeytensä, koreutensa ja vihansa on suurempi kuin hänen voimansa."],[16,7,"Sentähden pitää yhden Moabilaisen itkemän toista, heidän pitää kaikkein itkemän; KirHaresetin (kaupungin) perustuksia pitää teidän huokaaman: ne ovat peräti kukistetut.","Sentähden pitää yhden Moabilaisen itkemän toista, heidän pitää kaikkein itkemän; KirHaresetin (kaupungin) perustuksia pitää teidän huokaaman: ne ovat peräti kukistetut."],[16,8,"Sillä Hesbon on tullut autioksi maaksi, Sibmassa ovat viinapuut turmellut, pakanain herrat ovat sotkuneet hänen parhaat viinapuunsa, ja tulleet Jaeseriin asti, ja vaeltaneet korpea ympäri; hänen viina-oksansa ovat hajoitetut ja viedyt meren ylitse.","Sillä Hesbon on tullut autioksi maaksi, Sibmassa ovat viinapuut turmellut, pakanain herrat ovat sotkuneet hänen parhaat viinapuunsa, ja tulleet Jaeseriin asti, ja vaeltaneet korpea ympäri; hänen viina-oksansa ovat hajoitetut ja viedyt meren ylitse."],[16,9,"Sentähden minä itken Jaeserin tähden, ja Sibman viinapuun, ja vuodatan monta pisaraa Hesbonin ja Elalen tähden; sillä huuto on langennut sinun suvees ja tuloos!","Sentähden minä itken Jaeserin tähden, ja Sibman viinapuun, ja vuodatan monta pisaraa Hesbonin ja Elalen tähden; sillä huuto on langennut sinun suvees ja tuloos!"],[16,10,"Niin että ilo ja riemu lakkaa kedolla, ja ei viinamäissä iloita eikä huudeta, eli puserreta viinaa kuurnissa; minä olen lopettanut ilohuudon.","Niin että ilo ja riemu lakkaa kedolla, ja ei viinamäissä iloita eikä huudeta, eli puserreta viinaa kuurnissa; minä olen lopettanut ilohuudon."],[16,11,"Sentähden minun sydämeni kumisee Moabin tähden kuin kantele, ja minun sisällykseni KirHareksen tähden.","Sentähden minun sydämeni kumisee Moabin tähden kuin kantele, ja minun sisällykseni KirHareksen tähden."],[16,12,"Silloin pitää ilmoitettaman, kuinka Moab on väsynyt korkeuksissa ja mennyt kirkkoonsa rukoilemaan, ja ei kuitenkaan ole mitään aikoin saanut.","Silloin pitää ilmoitettaman, kuinka Moab on väsynyt korkeuksissa ja mennyt kirkkoonsa rukoilemaan, ja ei kuitenkaan ole mitään aikoin saanut."],[16,13,"Tämä on se, minkä Herra siihen aikaan puhui Moabia vastaan.","Tämä on se, minkä Herra siihen aikaan puhui Moabia vastaan."],[16,14,"Mutta nyt puhuu Herra ja sanoo: kolmena vuonna, niinkuin palvelian vuodet ovat, pitää Moabin kunnian, joka suuri on kaikissa kansoissa, tuleman pieneksi, niin että aivan vähä pitää jäämän, ja ei paljo.","Mutta nyt puhuu Herra ja sanoo: kolmena vuonna, niinkuin palvelian vuodet ovat, pitää Moabin kunnian, joka suuri on kaikissa kansoissa, tuleman pieneksi, niin että aivan vähä pitää jäämän, ja ei paljo."],[17,1,"Tämä on Damaskun kuorma: katso, ei Damaskun pidä enää oleman kaupunkina, vaan rauvenneen kiviroukkion.","Tämä on Damaskun kuorma: katso, ei Damaskun pidä enää oleman kaupunkina, vaan rauvenneen kiviroukkion."],[17,2,"Aroerin kaupungeista pitää luovuttaman, niin että karja käy siellä laitumella, ja ei heitä kenkään aja ulos.","Aroerin kaupungeista pitää luovuttaman, niin että karja käy siellä laitumella, ja ei heitä kenkään aja ulos."],[17,3,"Ja Ephraimin linnat pitää tuleman perikatoon, ja Damaskun valtakunta. Ja jääneen Syriassa pitää oleman, niinkuin Israelin lasten kunnia, sanoo Herra Zebaot.","Ja Ephraimin linnat pitää tuleman perikatoon, ja Damaskun valtakunta. Ja jääneen Syriassa pitää oleman, niinkuin Israelin lasten kunnia, sanoo Herra Zebaot."],[17,4,"Silloin pitää Jakobin kunnian ohukaiseksi tuleman, ja hänen lihavan ruumiinsa laihaksi.","Silloin pitää Jakobin kunnian ohukaiseksi tuleman, ja hänen lihavan ruumiinsa laihaksi."],[17,5,"Sillä hänen pitää silloin tuleman, niinkuin koska joku kokois laihoa elonaikana, ja niinkuin koska joku korjais tähkäpäitä käsivarrellansa, ja niinkuin joku noukkis tähkäpäitä Rephaimin laaksossa,","Sillä hänen pitää silloin tuleman, niinkuin koska joku kokois laihoa elonaikana, ja niinkuin koska joku korjais tähkäpäitä käsivarrellansa, ja niinkuin joku noukkis tähkäpäitä Rephaimin laaksossa,"],[17,6,"Ja joku jälkinoukkiminen tulis; niinkuin koska joku puhdistaa öljypuita, ja on kaksi eli kolme marjaa ylhäällä latvassa, eli niinkuin neljä viisi marjaa riippuvat vielä oksissa, sanoo Herra Israelin Jumala,","Ja joku jälkinoukkiminen tulis; niinkuin koska joku puhdistaa öljypuita, ja on kaksi eli kolme marjaa ylhäällä latvassa, eli niinkuin neljä viisi marjaa riippuvat vielä oksissa, sanoo Herra Israelin Jumala,"],[17,7,"Silloin pitää ihmisen pysymän hänessä, joka hänen tehnyt on, ja hänen silmänsä pitää katseleman Israelin Pyhää,","Silloin pitää ihmisen pysymän hänessä, joka hänen tehnyt on, ja hänen silmänsä pitää katseleman Israelin Pyhää,"],[17,8,"Ja ei katseleman alttareita, jotka hänen kätensä ovat tehneet, eikä sitä katsoman, jonka hänen sormensa tehneet ovat, eli metsistöitä taikka kuvia.","Ja ei katseleman alttareita, jotka hänen kätensä ovat tehneet, eikä sitä katsoman, jonka hänen sormensa tehneet ovat, eli metsistöitä taikka kuvia."],[17,9,"Silloin pitää hänen väkevyytensä kaupungin tuleman niinkuin hyljätyn vesan eli oksan, joka oli Israelin lasten edestä hyljätty, ja pitää tuleman autioksi.","Silloin pitää hänen väkevyytensä kaupungin tuleman niinkuin hyljätyn vesan eli oksan, joka oli Israelin lasten edestä hyljätty, ja pitää tuleman autioksi."],[17,10,"Sillä sinä olet unhottanut sinun autuutes Jumalan, ja et ajatellut sinun väkevyytes kalliota; sentähden pitää sinun istuttaman ihania vesoja, mutta niin sinä olet istuttanut viina-oksia muukalaisille.","Sillä sinä olet unhottanut sinun autuutes Jumalan, ja et ajatellut sinun väkevyytes kalliota; sentähden pitää sinun istuttaman ihania vesoja, mutta niin sinä olet istuttanut viina-oksia muukalaisille."],[17,11,"Istuttamisen ajalla sinä kyllä ahkeroitset, että sinun jyväs aikanansa kasvaisivat; mutta syksyllä, kuin sinun lyhteet korjaaman pitäis, saat sinä surullisen murheen siitä.","Istuttamisen ajalla sinä kyllä ahkeroitset, että sinun jyväs aikanansa kasvaisivat; mutta syksyllä, kuin sinun lyhteet korjaaman pitäis, saat sinä surullisen murheen siitä."],[17,12,"Voi sitä peräti paljoa kansaa, se on pauhaava niinkuin meri; ja kansan hyminä on kohiseva, niinkuin iso vesi pauhaa.","Voi sitä peräti paljoa kansaa, se on pauhaava niinkuin meri; ja kansan hyminä on kohiseva, niinkuin iso vesi pauhaa."],[17,13,"Tosin niinkuin iso vesi pauhaa, niin on kansa karkaava, mutta hän on kurittava heitä, ja heidän pitää kauvas pakeneman, ja vainoa kärsimän, niinkuin tomulle tapahtuu vuorella tuulelta, ja niinkuin ympyriäiselle tapahtuu tuulispäältä.","Tosin niinkuin iso vesi pauhaa, niin on kansa karkaava, mutta hän on kurittava heitä, ja heidän pitää kauvas pakeneman, ja vainoa kärsimän, niinkuin tomulle tapahtuu vuorella tuulelta, ja niinkuin ympyriäiselle tapahtuu tuulispäältä."],[17,14,"Katso, ehtoona on peljästys käsillä, ja ennen aamua ei he ensinkään ole. Tämä on heidän palkkansa, jotka meiltä ryöstävät, ja heidän perintönsä, jotka meiltä omamme tempaavat.","Katso, ehtoona on peljästys käsillä, ja ennen aamua ei he ensinkään ole. Tämä on heidän palkkansa, jotka meiltä ryöstävät, ja heidän perintönsä, jotka meiltä omamme tempaavat."],[18,1,"Voi sitä maata, joka vaeltaa siipein varjon alla, tällä puolella Etiopian virtoja!","Voi sitä maata, joka vaeltaa siipein varjon alla, tällä puolella Etiopian virtoja!"],[18,2,"Joka sanansaattajat lähettää merelle, ja kulkee vedellä ruokoisessa haahdessa: menkäät nopiasti matkaan, sanansaattajat, sen kansan tykö, joka reväisty ja ryöstetty on, sen kansan tykö, joka julmempi on kuin joku muu, sen kansan tykö, joka siellä ja täällä mitattu ja tallattu on, jonka maa virtain hallussa on.","Joka sanansaattajat lähettää merelle, ja kulkee vedellä ruokoisessa haahdessa: menkäät nopiasti matkaan, sanansaattajat, sen kansan tykö, joka reväisty ja ryöstetty on, sen kansan tykö, joka julmempi on kuin joku muu, sen kansan tykö, joka siellä ja täällä mitattu ja tallattu on, jonka maa virtain hallussa on."],[18,3,"Te kaikki, jotka asutte maan päällä, ja te, jotka maassa olette, saatte nähdä, kuinka lippu nostetaan vuorella, ja kuulla, kuinka vaskitorvella soitetaan.","Te kaikki, jotka asutte maan päällä, ja te, jotka maassa olette, saatte nähdä, kuinka lippu nostetaan vuorella, ja kuulla, kuinka vaskitorvella soitetaan."],[18,4,"Sillä näin sanoo Herra minulle: minä olen hiljakseni ja katselen majastani, niinkuin palavuus, joka sateen kuivaa, ja niinkuin kaste elonajan palavuudessa.","Sillä näin sanoo Herra minulle: minä olen hiljakseni ja katselen majastani, niinkuin palavuus, joka sateen kuivaa, ja niinkuin kaste elonajan palavuudessa."],[18,5,"Sillä ennen elonaikaa, kuin tulo valmiiksi tulee, ja rohkamarjat kypsentyvät, täytyy oksat leikata sirpillä, ja viinapuut hakata ja heittää pois:","Sillä ennen elonaikaa, kuin tulo valmiiksi tulee, ja rohkamarjat kypsentyvät, täytyy oksat leikata sirpillä, ja viinapuut hakata ja heittää pois:"],[18,6,"Niin että ne jätetään kokonansa linnuille vuorten päällä ja eläimille maassa; niin että linnut suvella tekevät siihen pesänsä, ja kaikkinaiset eläimet makaavat siinä talvella.","Niin että ne jätetään kokonansa linnuille vuorten päällä ja eläimille maassa; niin että linnut suvella tekevät siihen pesänsä, ja kaikkinaiset eläimet makaavat siinä talvella."],[18,7,"Silloin se revitty ja ryöstetty kansa, joka julmempi on kuin joku muu, joka siellä ja täällä mitattu on ja tallattu on, jonka maa virtain hallussa on, tuo Herralle Zebaotille lahjoja siihen paikkaan, jossa Herran Zebaotin nimi on, Zionin vuorelle.","Silloin se revitty ja ryöstetty kansa, joka julmempi on kuin joku muu, joka siellä ja täällä mitattu on ja tallattu on, jonka maa virtain hallussa on, tuo Herralle Zebaotille lahjoja siihen paikkaan, jossa Herran Zebaotin nimi on, Zionin vuorelle."],[19,1,"Tämä on Egyptin maan kuorma: katso, Herra on vaeltava nopiassa pilvessä, ja tuleva Egyptiin. Silloin pitää epäjumalain Egyptissä vapiseman hänen edessänsä, ja Egyptiläisten sydämen pitää vavahtaman.","Tämä on Egyptin maan kuorma: katso, Herra on vaeltava nopiassa pilvessä, ja tuleva Egyptiin. Silloin pitää epäjumalain Egyptissä vapiseman hänen edessänsä, ja Egyptiläisten sydämen pitää vavahtaman."],[19,2,"Ja minä yllytän Egyptiläiset toinen toisensa päälle, niin että yhden pitää sotimaan toista vastaan, yhden ystävän toista vastaan, yhden kaupungin toista vastaan, ja yhden valtakunnan toista vastaan.","Ja minä yllytän Egyptiläiset toinen toisensa päälle, niin että yhden pitää sotimaan toista vastaan, yhden ystävän toista vastaan, yhden kaupungin toista vastaan, ja yhden valtakunnan toista vastaan."],[19,3,"Ja ei Egyptiläisillä pidä oleman sydäntä, ja minä teen heidän neuvonsa tyhjäksi. Niin he siis kysyvät epäjumalilta, velhoilta, noidilta, taikureilta ja tietäjiltä.","Ja ei Egyptiläisillä pidä oleman sydäntä, ja minä teen heidän neuvonsa tyhjäksi. Niin he siis kysyvät epäjumalilta, velhoilta, noidilta, taikureilta ja tietäjiltä."],[19,4,"Mutta minä annan Egyptiläiset julmain herrain käsiin; ja kovan kuninkaan pitää hallitseman heitä, sanoo Herra, Herra Zebaot.","Mutta minä annan Egyptiläiset julmain herrain käsiin; ja kovan kuninkaan pitää hallitseman heitä, sanoo Herra, Herra Zebaot."],[19,5,"Ja vesi pitää meressä vähenemän, niin myös virrat pitää kuivuman ja kureentuman.","Ja vesi pitää meressä vähenemän, niin myös virrat pitää kuivuman ja kureentuman."],[19,6,"Järvien pitää juokseman pois, niin että lampivedet pitää vähenemän ja kuivuman, ruoko ja kaisla katoaman.","Järvien pitää juokseman pois, niin että lampivedet pitää vähenemän ja kuivuman, ruoko ja kaisla katoaman."],[19,7,"Ja ruoho ojain tykönä, virtain reunalla, ja kaikkinainen jyvä vetten tykönä pitää lakastuman ja tyhjään tuleman.","Ja ruoho ojain tykönä, virtain reunalla, ja kaikkinainen jyvä vetten tykönä pitää lakastuman ja tyhjään tuleman."],[19,8,"Ja kalamiesten pitää murehtiman, ja kaikki, jotka ongen heittävät veteen, pitää valittaman, ja kaikki ne, jotka verkot veteen laskevat, pitää nääntymän.","Ja kalamiesten pitää murehtiman, ja kaikki, jotka ongen heittävät veteen, pitää valittaman, ja kaikki ne, jotka verkot veteen laskevat, pitää nääntymän."],[19,9,"Niin pitää häväistämän, jotka hyvää lankaa tekevät ja verkkoa kutovat.","Niin pitää häväistämän, jotka hyvää lankaa tekevät ja verkkoa kutovat."],[19,10,"Ja ne, joilla on kala-arkut, kaikkein niiden kanssa, jotka lammikoita palkan edestä tekevät, pitää sureman.","Ja ne, joilla on kala-arkut, kaikkein niiden kanssa, jotka lammikoita palkan edestä tekevät, pitää sureman."],[19,11,"Zoanin pääruhtinaat ovat tyhmät, Pharaon taitavat neuvonantajat ovat neuvossansa hulluiksi tulleet; miksi te siis sanotte Pharaosta: minä olen viisasten poika, ja olen vanhain kuningasten poika?","Zoanin pääruhtinaat ovat tyhmät, Pharaon taitavat neuvonantajat ovat neuvossansa hulluiksi tulleet; miksi te siis sanotte Pharaosta: minä olen viisasten poika, ja olen vanhain kuningasten poika?"],[19,12,"Kussa siis nyt ovat sinun taitavas? Anna heidän sanoa, ja opettaa sinuas, mitä Herra Zebaot on Egyptistä aikonut.","Kussa siis nyt ovat sinun taitavas? Anna heidän sanoa, ja opettaa sinuas, mitä Herra Zebaot on Egyptistä aikonut."],[19,13,"Mutta Zoanin pääruhtinaat ovat tulleet tyhmiksi; Nophin pääruhtinaat ovat petetyt, he peipoittelevat Egyptin sukuin kulmakiven.","Mutta Zoanin pääruhtinaat ovat tulleet tyhmiksi; Nophin pääruhtinaat ovat petetyt, he peipoittelevat Egyptin sukuin kulmakiven."],[19,14,"Sillä Herra on vuodattanut heidän sekaansa väärän hengen, pettämään Egyptiä kaikissa, mitä he tekevät, niinkuin juopunut horjuu oksentaessansa.","Sillä Herra on vuodattanut heidän sekaansa väärän hengen, pettämään Egyptiä kaikissa, mitä he tekevät, niinkuin juopunut horjuu oksentaessansa."],[19,15,"Ja ei pidä Egyptillä oleman päätä eli häntää, oksaa eli kantoa.","Ja ei pidä Egyptillä oleman päätä eli häntää, oksaa eli kantoa."],[19,16,"Silloin pitää Egyptin oleman niinkuin vaimot, pelkäämän ja vavahtuman, koska Herra Zebaot häälyttää kättänsä heidän päällänsä.","Silloin pitää Egyptin oleman niinkuin vaimot, pelkäämän ja vavahtuman, koska Herra Zebaot häälyttää kättänsä heidän päällänsä."],[19,17,"Ja Egyptin pitää pelkäämän Juudan maata, niin että sen, joka sitä ajattelee, pitää peljästymän Herran Zebaotin neuvoa, jonka hän siitä on pitänyt.","Ja Egyptin pitää pelkäämän Juudan maata, niin että sen, joka sitä ajattelee, pitää peljästymän Herran Zebaotin neuvoa, jonka hän siitä on pitänyt."],[19,18,"Siihen aikaan pitää viisi kaupunkia Egyptissä Kanaanin maan kielellä puhuman, ja vannoman Herran Zebaotin kautta; jokainen heistä pitää hävityksen kaupungiksi kutsuttaman.","Siihen aikaan pitää viisi kaupunkia Egyptissä Kanaanin maan kielellä puhuman, ja vannoman Herran Zebaotin kautta; jokainen heistä pitää hävityksen kaupungiksi kutsuttaman."],[19,19,"Silloin pitää Herran Zebaotin alttari keskellä Egyptin maata oleman, ja Herran vartiovaha hänen äärissänsä,","Silloin pitää Herran Zebaotin alttari keskellä Egyptin maata oleman, ja Herran vartiovaha hänen äärissänsä,"],[19,20,"Joka pitää merkiksi ja todistukseksi oleman Herralle Zebaotille Egyptin maassa; sillä heidän pitää Herran tykö huutaman vaivaajainsa tähden, niin hän heille lähettää vapahtajan ja sankarin, joka heitä auttaa.","Joka pitää merkiksi ja todistukseksi oleman Herralle Zebaotille Egyptin maassa; sillä heidän pitää Herran tykö huutaman vaivaajainsa tähden, niin hän heille lähettää vapahtajan ja sankarin, joka heitä auttaa."],[19,21,"Ja sinä päivänä pitää Herra tunnettaman Egyptissä ja Egyptiläisten pitää tunteman Herran. Ja he palvelevat häntä uhrilla ja ruokauhrilla, ja lupaavat Herralle lupausta, ja sen pitävät.","Ja sinä päivänä pitää Herra tunnettaman Egyptissä ja Egyptiläisten pitää tunteman Herran. Ja he palvelevat häntä uhrilla ja ruokauhrilla, ja lupaavat Herralle lupausta, ja sen pitävät."],[19,22,"Ja Herra on vaivaava Egyptiläisiä, hän on vaivaava ja parantava jälleen; sillä he palajavat Herran tykö, ja he rukoilevat häntä, ja hän parantaa heitä.","Ja Herra on vaivaava Egyptiläisiä, hän on vaivaava ja parantava jälleen; sillä he palajavat Herran tykö, ja he rukoilevat häntä, ja hän parantaa heitä."],[19,23,"Silloin on tie avoin Egyptistä Assyriaan, Assyrialaisten mennä Egyptiin, ja Egyptiläisten Assyriaan; että Egyptiläiset ja Assyrialaiset ynnä palvelisivat (Jumalaa).","Silloin on tie avoin Egyptistä Assyriaan, Assyrialaisten mennä Egyptiin, ja Egyptiläisten Assyriaan; että Egyptiläiset ja Assyrialaiset ynnä palvelisivat (Jumalaa)."],[19,24,"Silloin Israel pitää itse kolmantena oleman, Assyrialaisten ja Egyptiläisten kanssa, sen siunauksen kautta, joka on oleva keskellä maata.","Silloin Israel pitää itse kolmantena oleman, Assyrialaisten ja Egyptiläisten kanssa, sen siunauksen kautta, joka on oleva keskellä maata."],[19,25,"Sillä Herra Zebaot on siunaava heitä ja sanova: siunattu olkoon Egypti minun kansani, ja Assur minun käsialani, ja Israel minun perimiseni!","Sillä Herra Zebaot on siunaava heitä ja sanova: siunattu olkoon Egypti minun kansani, ja Assur minun käsialani, ja Israel minun perimiseni!"],[20,1,"Sinä vuonna, kuin Tartan tuli Asdodiin, jonka Assyrian kuningas Sargon oli lähettänyt, ja soti Asdodia vastaan ja voitti sen:","Sinä vuonna, kuin Tartan tuli Asdodiin, jonka Assyrian kuningas Sargon oli lähettänyt, ja soti Asdodia vastaan ja voitti sen:"],[20,2,"Silloin puhui Herra Jesaian Amotsin pojan kautta ja sanoi: mene ja riisu säkki kupeistas ja kengät jaloistas: ja hän teki niin, ja kävi alasti ja paljain jaloin.","Silloin puhui Herra Jesaian Amotsin pojan kautta ja sanoi: mene ja riisu säkki kupeistas ja kengät jaloistas: ja hän teki niin, ja kävi alasti ja paljain jaloin."],[20,3,"Sanoi siis Herra: niinkuin palveliani Jesaia käy alasti ja paljailla jaloilla, kolmen ajastajan merkiksi ja ihmeeksi Egyptille ja Etiopialle:","Sanoi siis Herra: niinkuin palveliani Jesaia käy alasti ja paljailla jaloilla, kolmen ajastajan merkiksi ja ihmeeksi Egyptille ja Etiopialle:"],[20,4,"Niin on Assyrian kuningas ajava vangittua Egyptiä ja hävitettyä Etiopiaa, sekä nuoria että vanhoja, alastomia ja paljasjalkaisia, paljastetun hävyn kanssa, Egyptille hävyksi.","Niin on Assyrian kuningas ajava vangittua Egyptiä ja hävitettyä Etiopiaa, sekä nuoria että vanhoja, alastomia ja paljasjalkaisia, paljastetun hävyn kanssa, Egyptille hävyksi."],[20,5,"Ja heidän pitää peljästymän ja häpeemän Etiopiaa, johon he luottivat, ja Egyptiläisiä, joista he kerskasivat.","Ja heidän pitää peljästymän ja häpeemän Etiopiaa, johon he luottivat, ja Egyptiläisiä, joista he kerskasivat."],[20,6,"Ja tämän luodon asuvaiset pitää silloin sanoman: onko tämä meidän turvamme, johon olemme paenneet apua saamaan, että me Assyrian kuninkaalta pelastettaisiin? kuinka me olemme päässeet?","Ja tämän luodon asuvaiset pitää silloin sanoman: onko tämä meidän turvamme, johon olemme paenneet apua saamaan, että me Assyrian kuninkaalta pelastettaisiin? kuinka me olemme päässeet?"],[21,1,"Tämä on korven kuorma meren tykönä: niinkuin tuulispää tulee etelästä, joka kääntää ylösalaisin, niin se tulee korvesta, kauhiasta maasta.","Tämä on korven kuorma meren tykönä: niinkuin tuulispää tulee etelästä, joka kääntää ylösalaisin, niin se tulee korvesta, kauhiasta maasta."],[21,2,"Sillä minulle on osoitettu kova näky: pettäjä tulee toista vastaan, hävittäjä toista vastaan. Mene ylös Elam, piiritä heitä Madai: minä lopetan kaikki hänen huokauksensa.","Sillä minulle on osoitettu kova näky: pettäjä tulee toista vastaan, hävittäjä toista vastaan. Mene ylös Elam, piiritä heitä Madai: minä lopetan kaikki hänen huokauksensa."],[21,3,"Sentähden ovat minun kupeeni täynnä kipua, ja ahdistus on minun käsittänyt, niinkuin lapsen synnyttäjän ahdistus; minä kyyristän minuni, koska minä sen kuulen, ja peljästyn, koska minä sen näen.","Sentähden ovat minun kupeeni täynnä kipua, ja ahdistus on minun käsittänyt, niinkuin lapsen synnyttäjän ahdistus; minä kyyristän minuni, koska minä sen kuulen, ja peljästyn, koska minä sen näen."],[21,4,"Minun sydämeni vapisee, kauhistus on minun peljättänyt; sentähden ei ole minulla ollut suloisella yöllä yhtään lepoa.","Minun sydämeni vapisee, kauhistus on minun peljättänyt; sentähden ei ole minulla ollut suloisella yöllä yhtään lepoa."],[21,5,"Valmista pöytä, anna valvojain valvoa, syö, juo: nouskaat te pääruhtinaat ja voidelkaat kilvet.","Valmista pöytä, anna valvojain valvoa, syö, juo: nouskaat te pääruhtinaat ja voidelkaat kilvet."],[21,6,"Sillä Herra sanoo näin minulle: mene ja toimita vartio, joka katselis ja ilmoittais.","Sillä Herra sanoo näin minulle: mene ja toimita vartio, joka katselis ja ilmoittais."],[21,7,"Mutta hän näki ratsastajat ajavan ja menevän aaseilla ja kameleilla, ja piti siitä visun vaarin.","Mutta hän näki ratsastajat ajavan ja menevän aaseilla ja kameleilla, ja piti siitä visun vaarin."],[21,8,"Ja hän huusi niinkuin jalopeura: Herra, minä olen vartiolla yli päivää, ja olen minun vartiollani kaikki yöt:","Ja hän huusi niinkuin jalopeura: Herra, minä olen vartiolla yli päivää, ja olen minun vartiollani kaikki yöt:"],[21,9,"Ja katso, siellä tulee yksi vaunuissa ja kaksi ratsahin, joka vastaa ja sanoo: kaatunut, kaatunut on Babylon, ja kaikki hänen jumalainsa kuvat lyötiin maahan.","Ja katso, siellä tulee yksi vaunuissa ja kaksi ratsahin, joka vastaa ja sanoo: kaatunut, kaatunut on Babylon, ja kaikki hänen jumalainsa kuvat lyötiin maahan."],[21,10,"O minun tappamiseni ja minun riiheni permanto! mitä minä olen Herralta Zebaotilta, Israelin Jumalalta, kuullut, sen minä teille ilmoitan.","O minun tappamiseni ja minun riiheni permanto! mitä minä olen Herralta Zebaotilta, Israelin Jumalalta, kuullut, sen minä teille ilmoitan."],[21,11,"Tämä on Duman kuorma: Seiristä huudetaan minua: vartia, mitä yö kuluu? vartia, mitä yö kuluu?","Tämä on Duman kuorma: Seiristä huudetaan minua: vartia, mitä yö kuluu? vartia, mitä yö kuluu?"],[21,12,"Vartia sanoi: kuin aamu tulee, niin vielä yö on; jos te vielä kysytte, niin teidän pitää vielä sitte palajaman ja taas kysymän.","Vartia sanoi: kuin aamu tulee, niin vielä yö on; jos te vielä kysytte, niin teidän pitää vielä sitte palajaman ja taas kysymän."],[21,13,"Tämä on Arabian kuorma: teidän pitää yötymän Arabian metsässä, Dedanimin tiellä.","Tämä on Arabian kuorma: teidän pitää yötymän Arabian metsässä, Dedanimin tiellä."],[21,14,"Kantakaat vettä janoovaa vastaan, te jotka asutte Temanin maassa: taritkaat pakenevaisille leipää.","Kantakaat vettä janoovaa vastaan, te jotka asutte Temanin maassa: taritkaat pakenevaisille leipää."],[21,15,"Sillä he pakenevat miekkaa, paljasta miekkaa, jännitettyä jousta ja isoa sotaa.","Sillä he pakenevat miekkaa, paljasta miekkaa, jännitettyä jousta ja isoa sotaa."],[21,16,"Sillä näin sanoo Herra minulle: vielä nyt vuosi, niinkuin palkollisen vuodet ovat, niin pitää kaiken Kedarin kunnian hukkuman.","Sillä näin sanoo Herra minulle: vielä nyt vuosi, niinkuin palkollisen vuodet ovat, niin pitää kaiken Kedarin kunnian hukkuman."],[21,17,"Ja jääneet ampujat, väkevät Kedarin lapsista, pitää vähemmäksi joutuman; sillä Herra Israelin Jumala on sen sanonut.","Ja jääneet ampujat, väkevät Kedarin lapsista, pitää vähemmäksi joutuman; sillä Herra Israelin Jumala on sen sanonut."],[22,1,"Tämä on Näkylaakson kuorma: mikä sinun nyt on, että te niin kaikki olette astuneet kattoin päälle?","Tämä on Näkylaakson kuorma: mikä sinun nyt on, että te niin kaikki olette astuneet kattoin päälle?"],[22,2,"Sinä olet täynnä humua: kaupunki täynnä väkeä, iloinen kaupunki: sinun lyötys ei ole miekalla lyödyt, ja ei ole kuolleet sodassa.","Sinä olet täynnä humua: kaupunki täynnä väkeä, iloinen kaupunki: sinun lyötys ei ole miekalla lyödyt, ja ei ole kuolleet sodassa."],[22,3,"Vaan kaikki sinun päämiehes ovat poikenneet joutsesta pois, ja ovat vangitut; kaikki kuin sinussa löyttiin, ovat vangitut, ja kauvas paenneet.","Vaan kaikki sinun päämiehes ovat poikenneet joutsesta pois, ja ovat vangitut; kaikki kuin sinussa löyttiin, ovat vangitut, ja kauvas paenneet."],[22,4,"Sentähden minä sanon: menkäät pois minun tyköäni, antakaat minun itkeä vaikiasti; älkäät ahkeroitko lohduttaa, minun kansani tyttären hävityksen tähden.","Sentähden minä sanon: menkäät pois minun tyköäni, antakaat minun itkeä vaikiasti; älkäät ahkeroitko lohduttaa, minun kansani tyttären hävityksen tähden."],[22,5,"Sillä se on kapinan, sortamisen ja surun päivä Herralta, Herralta Zebaotilta, Näkylaaksossa muurien kukistamisen tähden, ja huudon tähden vuorella;","Sillä se on kapinan, sortamisen ja surun päivä Herralta, Herralta Zebaotilta, Näkylaaksossa muurien kukistamisen tähden, ja huudon tähden vuorella;"],[22,6,"Että Elam lähtee viinellä, vaunuilla, väellä, ratsasmiehillä, ja Kir välkkyy kilvistä.","Että Elam lähtee viinellä, vaunuilla, väellä, ratsasmiehillä, ja Kir välkkyy kilvistä."],[22,7,"Ja tapahtuu, että sinun valitut laaksos ovat täynnä vaunuja; ja ratsastajat sioittavat itsensä portin eteen.","Ja tapahtuu, että sinun valitut laaksos ovat täynnä vaunuja; ja ratsastajat sioittavat itsensä portin eteen."],[22,8,"Silloin pitää Juudan peite avattaman, että aseet nähdään silloin metsähuoneessa.","Silloin pitää Juudan peite avattaman, että aseet nähdään silloin metsähuoneessa."],[22,9,"Ja te olette näkevä monta reikää Davidin kaupungissa; ja kokootte veden alimmaiseen lammikkoon.","Ja te olette näkevä monta reikää Davidin kaupungissa; ja kokootte veden alimmaiseen lammikkoon."],[22,10,"Teidän pitää lukeman huoneet Jerusalemissa, ja teidän pitää jaottaman huoneet vahvistaaksenne muureja.","Teidän pitää lukeman huoneet Jerusalemissa, ja teidän pitää jaottaman huoneet vahvistaaksenne muureja."],[22,11,"Ja teidän pitää tekemän vesihaudan molempain muurien välille, vanhan kalalammin vedestä; kuitenkin ette katso häntä, joka tämän tekee, ettekä katsele sitä, joka senkaltaisia on kaukaa toimittanut.","Ja teidän pitää tekemän vesihaudan molempain muurien välille, vanhan kalalammin vedestä; kuitenkin ette katso häntä, joka tämän tekee, ettekä katsele sitä, joka senkaltaisia on kaukaa toimittanut."],[22,12,"Sentähden antaa Herra, Herra Zebaot, silloin julistaa, että itketään ja murehditaan, ja hiukset ajellaan ja puetaan säkkiin.","Sentähden antaa Herra, Herra Zebaot, silloin julistaa, että itketään ja murehditaan, ja hiukset ajellaan ja puetaan säkkiin."],[22,13,"(Vaikka nyt) katso, ilo ja riemu, teurastaa härkiä, tappaa lampaita, syödä lihaa, juoda viinaa, (ja sanoa): syökäämme ja juokaamme, meidän pitää kuitenkin huomenna kuoleman.","(Vaikka nyt) katso, ilo ja riemu, teurastaa härkiä, tappaa lampaita, syödä lihaa, juoda viinaa, (ja sanoa): syökäämme ja juokaamme, meidän pitää kuitenkin huomenna kuoleman."],[22,14,"Tämä on, (sanoo) Herra Zebaot, minun korvilleni tullut: mitämaks, jos minä tämän pahan teon annan anteeksi, siihenasti kuin te kuolette, sanoo Herra, Herra Zebaot.","Tämä on, (sanoo) Herra Zebaot, minun korvilleni tullut: mitämaks, jos minä tämän pahan teon annan anteeksi, siihenasti kuin te kuolette, sanoo Herra, Herra Zebaot."],[22,15,"Näin sanoo Herra, Herra Zebaot: mene tavarahuoneen haltian Sebnan tykö ja sano hänelle:","Näin sanoo Herra, Herra Zebaot: mene tavarahuoneen haltian Sebnan tykö ja sano hänelle:"],[22,16,"Mitä sinun tässä on, kenenkä oma sinä olet? ettäs annat hakata itselles haudan niinkuin se, joka hakkauttaa itsellensä haudan korkeuteen, ja olet niinkuin se, joka antaa itsellensä tehdä asumasian vuorelle?","Mitä sinun tässä on, kenenkä oma sinä olet? ettäs annat hakata itselles haudan niinkuin se, joka hakkauttaa itsellensä haudan korkeuteen, ja olet niinkuin se, joka antaa itsellensä tehdä asumasian vuorelle?"],[22,17,"Katso, Herra ajaa sinun pois, niinkuin väkevä mies heittää jonkun pois, ja peittää sinun kokonansa,","Katso, Herra ajaa sinun pois, niinkuin väkevä mies heittää jonkun pois, ja peittää sinun kokonansa,"],[22,18,"Ja pyörittää sinun kohta, ja peräti niinkuin kierikan aukialle kedolle; siellä sinun pitää kuoleman, siellä pitää sinun kalliit vaunus, sinun Herras huoneen kanssa, tuleman häväistykseksi.","Ja pyörittää sinun kohta, ja peräti niinkuin kierikan aukialle kedolle; siellä sinun pitää kuoleman, siellä pitää sinun kalliit vaunus, sinun Herras huoneen kanssa, tuleman häväistykseksi."],[22,19,"Ja minä kukistan sinun säädystäs, ja sinä pannaan pois viraltas.","Ja minä kukistan sinun säädystäs, ja sinä pannaan pois viraltas."],[22,20,"Ja silloin pitää tapahtuman, että minä kutsun palveliani Eliakimin, Hilkian pojan,","Ja silloin pitää tapahtuman, että minä kutsun palveliani Eliakimin, Hilkian pojan,"],[22,21,"Ja panen hänen yllensä sinun hamees, ja vyötän hänen sinun vyölläs, ja annan sinun valtas hänelle; että hän on niiden isä, jotka Jerusalemissa ja Juudan huoneessa asuvat.","Ja panen hänen yllensä sinun hamees, ja vyötän hänen sinun vyölläs, ja annan sinun valtas hänelle; että hän on niiden isä, jotka Jerusalemissa ja Juudan huoneessa asuvat."],[22,22,"Ja panen Davidin huoneen avaimen hänen olallensa, että hän avaa, ja ei kenkään sulje, että hän sulkee, ja ei kenkään avaa.","Ja panen Davidin huoneen avaimen hänen olallensa, että hän avaa, ja ei kenkään sulje, että hän sulkee, ja ei kenkään avaa."],[22,23,"Ja lyön hänen niinkuin naulan vahvaan paikkaan; ja hänellä on oleva kunnian istuin, hänen isänsä huoneessa,","Ja lyön hänen niinkuin naulan vahvaan paikkaan; ja hänellä on oleva kunnian istuin, hänen isänsä huoneessa,"],[22,24,"Että hänen päällensä ripustetaan kaikki hänen isänsä huoneen kunnia, lapset ja lasten lapset, kaikki pienet kappaleet, juoma-astiat, ja kaikkinaiset kanteleet.","Että hänen päällensä ripustetaan kaikki hänen isänsä huoneen kunnia, lapset ja lasten lapset, kaikki pienet kappaleet, juoma-astiat, ja kaikkinaiset kanteleet."],[22,25,"Silloin, sanoo Herra Zebaot, naula pitää otettaman pois, joka vahvassa paikassa on, niin että hänen pitää rikkoontuman, lankeeman, putooman, ja se kuorma kuin hänen päällänsä on, pitää hukkuman; sillä Herra sen sanoo.","Silloin, sanoo Herra Zebaot, naula pitää otettaman pois, joka vahvassa paikassa on, niin että hänen pitää rikkoontuman, lankeeman, putooman, ja se kuorma kuin hänen päällänsä on, pitää hukkuman; sillä Herra sen sanoo."],[23,1,"Tämä on Tyron kuorma: valittakaat, te haahdet merellä; sillä se on kukistettu, niin ettei siellä ole yhtään huonetta, eikä sinne mene kenkään; Kittimin maasta pitää heidän sen äkkäämän.","Tämä on Tyron kuorma: valittakaat, te haahdet merellä; sillä se on kukistettu, niin ettei siellä ole yhtään huonetta, eikä sinne mene kenkään; Kittimin maasta pitää heidän sen äkkäämän."],[23,2,"Olkaat ääneti, te luotoin asuvaiset: Zidonin kauppamiehet, jotka merellä vaelsivat, täyttivät sinun.","Olkaat ääneti, te luotoin asuvaiset: Zidonin kauppamiehet, jotka merellä vaelsivat, täyttivät sinun."],[23,3,"Ja kaikkinainen hedelmä, joka Sihorin tykönä kasvaa, ja jyvät virran tykönä vietiin sinne veden ylitse; ja on pakanain kaupaksi tullut.","Ja kaikkinainen hedelmä, joka Sihorin tykönä kasvaa, ja jyvät virran tykönä vietiin sinne veden ylitse; ja on pakanain kaupaksi tullut."],[23,4,"Sinä mahdat kyllä hämmästyä, Zidon; sillä meri lausuu ja vahvin meren tykönä sanoo: en minä ole silleen raskas, en minä synnytä, enkä myös kasvata yhtään nuorukaista, enkä ruoki neitsyttä.","Sinä mahdat kyllä hämmästyä, Zidon; sillä meri lausuu ja vahvin meren tykönä sanoo: en minä ole silleen raskas, en minä synnytä, enkä myös kasvata yhtään nuorukaista, enkä ruoki neitsyttä."],[23,5,"Niinkuin kuultaissa Egyptistä hämmästyttiin, niin pitää myös hämmästyttämän, koska Tyrosta kuullaan.","Niinkuin kuultaissa Egyptistä hämmästyttiin, niin pitää myös hämmästyttämän, koska Tyrosta kuullaan."],[23,6,"Menkäät merille, valittakaat, jotka luodoissa asutte.","Menkäät merille, valittakaat, jotka luodoissa asutte."],[23,7,"Eikö tämä ole teidän ilokaupunkinne, joka kerskaa itsiänsä vanhuudestansa? Hänen jalkansa pitää viemän hänen pitkän matkan taa vaeltamaan.","Eikö tämä ole teidän ilokaupunkinne, joka kerskaa itsiänsä vanhuudestansa? Hänen jalkansa pitää viemän hänen pitkän matkan taa vaeltamaan."],[23,8,"Kuka olis sitä ajatellut, että kruunatulle Tyrolle piti niin käymän? että sen kauppamiehet ovat pääruhtinaat, ja sen kauppiaat ylimmäiset maassa?","Kuka olis sitä ajatellut, että kruunatulle Tyrolle piti niin käymän? että sen kauppamiehet ovat pääruhtinaat, ja sen kauppiaat ylimmäiset maassa?"],[23,9,"Herra Zebaot on sen niin ajatellut, että hän kaikki hänen kaunistuksensa prameuden heikoksi tekis; ja tekis ylönkatsotuksi kaikki kuuluisat maassa.","Herra Zebaot on sen niin ajatellut, että hän kaikki hänen kaunistuksensa prameuden heikoksi tekis; ja tekis ylönkatsotuksi kaikki kuuluisat maassa."],[23,10,"Vaella maas lävitse niinkuin virta, sinä Tarsiksen tytär; ei siellä ole enään yhtään vyötä.","Vaella maas lävitse niinkuin virta, sinä Tarsiksen tytär; ei siellä ole enään yhtään vyötä."],[23,11,"Hän kokottaa kätensä meren päälle, ja peljättää valtakunnat; Herra käski Kananin hävittämään sen linnat,","Hän kokottaa kätensä meren päälle, ja peljättää valtakunnat; Herra käski Kananin hävittämään sen linnat,"],[23,12,"Ja sanoi: ei sinun pidä enään iloitseman, sinä häväisty neitsy Zidonin tytär: nouse ja mene matkaas Kittimiin, ei sinulla pidä sielläkään lepoa oleman.","Ja sanoi: ei sinun pidä enään iloitseman, sinä häväisty neitsy Zidonin tytär: nouse ja mene matkaas Kittimiin, ei sinulla pidä sielläkään lepoa oleman."],[23,13,"Katso, Kaldealaisten maassa ei yhtään kansaa ollut, vaan Assur on sen perustanut korven asuvaisille, ja rakentanut hänen linnansa, pannut ylös hänen huoneensa, ja on kuitenkin pantu kukistettavaksi.","Katso, Kaldealaisten maassa ei yhtään kansaa ollut, vaan Assur on sen perustanut korven asuvaisille, ja rakentanut hänen linnansa, pannut ylös hänen huoneensa, ja on kuitenkin pantu kukistettavaksi."],[23,14,"Surekaat, te haahdet merillä; sillä teidän voimanne on tyhjä.","Surekaat, te haahdet merillä; sillä teidän voimanne on tyhjä."],[23,15,"Silloin pitää Tyro unhotettaman seitsemänkymmentä vuotta, niinkauvan kuin yksi kuningas elää; mutta seitsemänkymmenen vuoden perästä käypi Tyron niinkuin portosta veisataan:","Silloin pitää Tyro unhotettaman seitsemänkymmentä vuotta, niinkauvan kuin yksi kuningas elää; mutta seitsemänkymmenen vuoden perästä käypi Tyron niinkuin portosta veisataan:"],[23,16,"Ota kantele, mene ympäri kaupunkia, sinä unhotettu portto: soita vahvasti kantelettas, ja laula lohdullisesti, että sinua taas muistettaisiin.","Ota kantele, mene ympäri kaupunkia, sinä unhotettu portto: soita vahvasti kantelettas, ja laula lohdullisesti, että sinua taas muistettaisiin."],[23,17,"Sillä seitsemänkymmenen vuoden perästä on Herra etsivä Tyroa, että hän tulis jälleen porttopalkoillensa, ja huorin tekis kaikkein valtakuntain kanssa maan päällä.","Sillä seitsemänkymmenen vuoden perästä on Herra etsivä Tyroa, että hän tulis jälleen porttopalkoillensa, ja huorin tekis kaikkein valtakuntain kanssa maan päällä."],[23,18,"Mutta hänen kauppansa ja porttopalkkansa pitää oleman pyhä Herralle. Ei sitä koota tavaraksi, eikä salata, vaan jotka asuvat Herran edessä, niillä pitää hänen kauppakalunsa oleman, siitä syödä, ravita ja itsiänsä vaatettaa.","Mutta hänen kauppansa ja porttopalkkansa pitää oleman pyhä Herralle. Ei sitä koota tavaraksi, eikä salata, vaan jotka asuvat Herran edessä, niillä pitää hänen kauppakalunsa oleman, siitä syödä, ravita ja itsiänsä vaatettaa."],[24,1,"Katso, Herra tekee maan tyhjäksi ja autioksi, ja kukistaa, mitä siinä on, ja hävittää sen asuvaiset.","Katso, Herra tekee maan tyhjäksi ja autioksi, ja kukistaa, mitä siinä on, ja hävittää sen asuvaiset."],[24,2,"Ja papeille tapahtuu niinkuin kansallekin, herralle niinkuin palveliallekin, emännälle niinkuin piiallekin, myyjälle niinkuin ostajallekin, lainaajalle niinkuin lainaksi ottajallekin, korkorahan ottajalle niinkuin antajallekin.","Ja papeille tapahtuu niinkuin kansallekin, herralle niinkuin palveliallekin, emännälle niinkuin piiallekin, myyjälle niinkuin ostajallekin, lainaajalle niinkuin lainaksi ottajallekin, korkorahan ottajalle niinkuin antajallekin."],[24,3,"Sillä maan pitää peräti tyhjäksi ja kokonansa ryöstetyksi tuleman; sillä Herra on tämän sanonut.","Sillä maan pitää peräti tyhjäksi ja kokonansa ryöstetyksi tuleman; sillä Herra on tämän sanonut."],[24,4,"Maa on surkia ja hävitetään, maa pelehtyy ja häviää; kansan ylimmäiset nääntyvät maassa.","Maa on surkia ja hävitetään, maa pelehtyy ja häviää; kansan ylimmäiset nääntyvät maassa."],[24,5,"Maa on saastaiseksi tullut asuvaisistansa; sillä he tekevät lakia vastaan ja muuttavat säädyt, ja luopuvat ijankaikkisesta liitosta.","Maa on saastaiseksi tullut asuvaisistansa; sillä he tekevät lakia vastaan ja muuttavat säädyt, ja luopuvat ijankaikkisesta liitosta."],[24,6,"Sentähden kuluttaa kirous maan ja sen asuvaiset hävitetään; sentähden maan asuvaiset kuivettuvat, niin että vähä jää väkeä.","Sentähden kuluttaa kirous maan ja sen asuvaiset hävitetään; sentähden maan asuvaiset kuivettuvat, niin että vähä jää väkeä."],[24,7,"Viina katoo, viinapuu surkastuu, ja kaikki, jotka sydämestänsä iloisina olivat, huokaavat.","Viina katoo, viinapuu surkastuu, ja kaikki, jotka sydämestänsä iloisina olivat, huokaavat."],[24,8,"Vaskirumpuin riemu taukoo, iloitsevaisten ilo puuttuu, kanteleiden riemu loppuu.","Vaskirumpuin riemu taukoo, iloitsevaisten ilo puuttuu, kanteleiden riemu loppuu."],[24,9,"Ei lauleta viinaa juotaissa, ja hyvä juoma on karvas juoville.","Ei lauleta viinaa juotaissa, ja hyvä juoma on karvas juoville."],[24,10,"Tyhjä kaupunki on kukistettu maahan; kaikki huoneet ovat teljetyt, niin ettei yksikään sinne mene.","Tyhjä kaupunki on kukistettu maahan; kaikki huoneet ovat teljetyt, niin ettei yksikään sinne mene."],[24,11,"Viinan puutteen tähden valitetaan kaduilla: kaikki ilo on pois, kaikki maan riemu on matkassansa.","Viinan puutteen tähden valitetaan kaduilla: kaikki ilo on pois, kaikki maan riemu on matkassansa."],[24,12,"Ei ole muuta jäänyt kaupunkiin kuin hävitys, ja portit ovat autiot.","Ei ole muuta jäänyt kaupunkiin kuin hävitys, ja portit ovat autiot."],[24,13,"Sillä kansalle tapahtuu myös maassa niinkuin öljypuillekin, koska siitä on poimittu; niinkuin sitte poimittaisiin kuin oikia viinan kokousaika on pois.","Sillä kansalle tapahtuu myös maassa niinkuin öljypuillekin, koska siitä on poimittu; niinkuin sitte poimittaisiin kuin oikia viinan kokousaika on pois."],[24,14,"Ne korottavat äänensä ja iloitsevat; Herran kunniasta he iloitsevat, hamasta merestä asti.","Ne korottavat äänensä ja iloitsevat; Herran kunniasta he iloitsevat, hamasta merestä asti."],[24,15,"Niin kiittäkäät nyt Herraa laaksoissa, luodoissa Herran, Israelin Jumalan nimeä.","Niin kiittäkäät nyt Herraa laaksoissa, luodoissa Herran, Israelin Jumalan nimeä."],[24,16,"Me kuulemme kiitosvirren maailman äärestä, vanhurskaalle kunniaksi. Ja minun pitää sanoman: miksi minä olen niin laiha? miksi minä olen niin laiha? voi minua! sillä ylönkatsojat ylönkatsovat, ja ylönkatsojat ylönkatsovat,","Me kuulemme kiitosvirren maailman äärestä, vanhurskaalle kunniaksi. Ja minun pitää sanoman: miksi minä olen niin laiha? miksi minä olen niin laiha? voi minua! sillä ylönkatsojat ylönkatsovat, ja ylönkatsojat ylönkatsovat,"],[24,17,"Sentähden tulee teidän asuvainne päälle maassa hämmästys, kuoppa ja paula.","Sentähden tulee teidän asuvainne päälle maassa hämmästys, kuoppa ja paula."],[24,18,"Ja jos joku pakenis hämmästyksen huutoa, niin hän kuitenkin putoo kuoppaan; ja jos hän pääsee kuopasta ylös, niin hän kuitenkin käsitetään paulaan, sillä korkeuden akkunat avataan, ja maan perustukset vapisevat.","Ja jos joku pakenis hämmästyksen huutoa, niin hän kuitenkin putoo kuoppaan; ja jos hän pääsee kuopasta ylös, niin hän kuitenkin käsitetään paulaan, sillä korkeuden akkunat avataan, ja maan perustukset vapisevat."],[24,19,"Maan käy aivan pahoin: ei sen pidä ollenkaan menestymän, vaan pitää peräti raukeaman.","Maan käy aivan pahoin: ei sen pidä ollenkaan menestymän, vaan pitää peräti raukeaman."],[24,20,"Maan pitää kovin hoiperteleman niinkuin juopuneen, ja vietämän pois niinkuin majan; sillä sen pahat teot painavat sen, niin että sen pitää lankeeman, ja ei enään nouseman.","Maan pitää kovin hoiperteleman niinkuin juopuneen, ja vietämän pois niinkuin majan; sillä sen pahat teot painavat sen, niin että sen pitää lankeeman, ja ei enään nouseman."],[24,21,"Silloin on Herra etsivä sitä korkiaa sotaväkeä, joka korkeudessa on, ja maan kuninkaita, jotka ovat maan päällä.","Silloin on Herra etsivä sitä korkiaa sotaväkeä, joka korkeudessa on, ja maan kuninkaita, jotka ovat maan päällä."],[24,22,"Että he kootaan yhteen niinkuin kuopassa sidotut, ja pitää oleman suljetut vankeudessa, ja suuren ajan perästä taas etsittämän.","Että he kootaan yhteen niinkuin kuopassa sidotut, ja pitää oleman suljetut vankeudessa, ja suuren ajan perästä taas etsittämän."],[24,23,"Ja kuun pitää häpeemän, ja auringon ujoileman, koska Herra Zebaot on tuleva kuninkaaksi Zionin vuorella ja Jerusalemissa; ja hänen vanhimpainsa edessä pitää kunnia oleman.","Ja kuun pitää häpeemän, ja auringon ujoileman, koska Herra Zebaot on tuleva kuninkaaksi Zionin vuorella ja Jerusalemissa; ja hänen vanhimpainsa edessä pitää kunnia oleman."],[25,1,"Herra, sinä olet minun Jumalani, sinua minä ylistän, minä kiitän sinun nimeäs; sillä sinä teet ihmeitä: sinun vanhat aivoitukses ovat uskolliset ja todet.","Herra, sinä olet minun Jumalani, sinua minä ylistän, minä kiitän sinun nimeäs; sillä sinä teet ihmeitä: sinun vanhat aivoitukses ovat uskolliset ja todet."],[25,2,"Sillä sinä teet kaupungin kiviraunioksi, sen vahvan kaupungin, että hän läjässä on; muukalaisten palatsit, niin ettei ne enää ole kaupungit, eikä ikänä enää rakenneta.","Sillä sinä teet kaupungin kiviraunioksi, sen vahvan kaupungin, että hän läjässä on; muukalaisten palatsit, niin ettei ne enää ole kaupungit, eikä ikänä enää rakenneta."],[25,3,"Sentähden kunnioittaa sinua väkevä kansa, urhoolliset pakanain kaupungit pelkäävät sinua.","Sentähden kunnioittaa sinua väkevä kansa, urhoolliset pakanain kaupungit pelkäävät sinua."],[25,4,"Sillä sinä olet heikkoin väkevyys ja köyhäin vahvuus heidän vaivoissansa: myrskyssä turva, varjo helteessä, kuin tyrannit julmistuvat niinkuin raju-ilma seinää vastoin.","Sillä sinä olet heikkoin väkevyys ja köyhäin vahvuus heidän vaivoissansa: myrskyssä turva, varjo helteessä, kuin tyrannit julmistuvat niinkuin raju-ilma seinää vastoin."],[25,5,"Sinä nöyryytät muukalaisten metelin, niinkuin helteen kuivassa paikassa, niinkuin helle pilven varjolla, niin tyrannein ilo painetaan alas.","Sinä nöyryytät muukalaisten metelin, niinkuin helteen kuivassa paikassa, niinkuin helle pilven varjolla, niin tyrannein ilo painetaan alas."],[25,6,"Ja Herra Zebaot tekee kaikille kansoille tällä vuorella lihavan pidon, pidon selkiästä viinasta, rasvasta, ytimestä ja puhtaasta viinasta.","Ja Herra Zebaot tekee kaikille kansoille tällä vuorella lihavan pidon, pidon selkiästä viinasta, rasvasta, ytimestä ja puhtaasta viinasta."],[25,7,"Ja tällä vuorella on hän kääriliinan paneva pois, jolla kaikki ihmiset käärityt ovat, ja peittovaatteen, jolla kaikki pakanat peitetyt ovat.","Ja tällä vuorella on hän kääriliinan paneva pois, jolla kaikki ihmiset käärityt ovat, ja peittovaatteen, jolla kaikki pakanat peitetyt ovat."],[25,8,"Sillä kuolema pitää nieltämän ijankaikkisesti, ja Herra, Herra on kyyneleet pyyhkivä pois jokaisen kasvoista, ja on ottava kansansa häväistykset pois kaikissa maakunnissa; sillä Herra on sen sanonut.","Sillä kuolema pitää nieltämän ijankaikkisesti, ja Herra, Herra on kyyneleet pyyhkivä pois jokaisen kasvoista, ja on ottava kansansa häväistykset pois kaikissa maakunnissa; sillä Herra on sen sanonut."],[25,9,"Silloin sanotaan: katso, tämä on meidän Jumalamme jota me odotamme, ja hän auttaa meitä; tämä on Herra, häntä me odotamme, iloitaksemme ja riemuitaksemme hänen autuudessansa.","Silloin sanotaan: katso, tämä on meidän Jumalamme jota me odotamme, ja hän auttaa meitä; tämä on Herra, häntä me odotamme, iloitaksemme ja riemuitaksemme hänen autuudessansa."],[25,10,"Sillä Herran käsi lepää tällä vuorella; mutta Moab runnellaan sen alla, niinkuin korret sotkutaan loassa.","Sillä Herran käsi lepää tällä vuorella; mutta Moab runnellaan sen alla, niinkuin korret sotkutaan loassa."],[25,11,"Ja Herra hajoittaa kätensä heidän sekaansa, niinkuin uija hajoittaa uidaksensa; ja hän on käsivarrellansa heidän prameutensa alentava.","Ja Herra hajoittaa kätensä heidän sekaansa, niinkuin uija hajoittaa uidaksensa; ja hän on käsivarrellansa heidän prameutensa alentava."],[25,12,"Ja sinun muuries korkiat vahvistukset hän kallistaa, alentaa ja heittää tomuun.","Ja sinun muuries korkiat vahvistukset hän kallistaa, alentaa ja heittää tomuun."],[26,1,"Siihen aikaan pitää Juudan maassa tämä veisu veisattaman: meillä on vahva kaupunki, hän pani autuuden muuriksi ja varjelukseksi.","Siihen aikaan pitää Juudan maassa tämä veisu veisattaman: meillä on vahva kaupunki, hän pani autuuden muuriksi ja varjelukseksi."],[26,2,"Avatkaat portit, vanhurskaan kansan, joka uskossa pysyy, käydä sisälle.","Avatkaat portit, vanhurskaan kansan, joka uskossa pysyy, käydä sisälle."],[26,3,"Sinä pidät aina rauhan, vahvan lupaukses jälkeen; sillä sinuun turvataan.","Sinä pidät aina rauhan, vahvan lupaukses jälkeen; sillä sinuun turvataan."],[26,4,"Sentähden luottakaat Herraan ijankaikkisesti; sillä Herra, Herra on kallio ijankaikkisesti.","Sentähden luottakaat Herraan ijankaikkisesti; sillä Herra, Herra on kallio ijankaikkisesti."],[26,5,"Ja hän notkistaa alas ne, jotka korkialla asuvat, hän alentaa korotetun kaupungin; hän sysää sen maahan, niin että se tomussa makaa,","Ja hän notkistaa alas ne, jotka korkialla asuvat, hän alentaa korotetun kaupungin; hän sysää sen maahan, niin että se tomussa makaa,"],[26,6,"Että hän jaloilla poljetaan, vaivaisten jaloilla ja köyhäin kantapäillä.","Että hän jaloilla poljetaan, vaivaisten jaloilla ja köyhäin kantapäillä."],[26,7,"Mutta vanhurskasten tie on tasainen; sinä ojennat vanhurskasten polut.","Mutta vanhurskasten tie on tasainen; sinä ojennat vanhurskasten polut."],[26,8,"Herra, me odotamme sinua oikeutes tiellä; sydän himoitsee sinun nimeäs ja muistoas.","Herra, me odotamme sinua oikeutes tiellä; sydän himoitsee sinun nimeäs ja muistoas."],[26,9,"Minä halajan sinua sydämestäni yöllä, minun henkeni valvoo myös minussa varhain sinun tykös; sillä kussa sinun oikeutes maakunnassa on, niin maan piirin asuvaiset oppivat vanhurskautta.","Minä halajan sinua sydämestäni yöllä, minun henkeni valvoo myös minussa varhain sinun tykös; sillä kussa sinun oikeutes maakunnassa on, niin maan piirin asuvaiset oppivat vanhurskautta."],[26,10,"Mutta ehkä jumalattomille armoja tarittaisiin, niin ei he opi kuitenkaan vanhurskautta, vaan tekevät ainoastaan pahaa oikeuden maalla; sillä ei he näe Herran kunniaa.","Mutta ehkä jumalattomille armoja tarittaisiin, niin ei he opi kuitenkaan vanhurskautta, vaan tekevät ainoastaan pahaa oikeuden maalla; sillä ei he näe Herran kunniaa."],[26,11,"Herra, sinun kätes on ylennetty, vaan ei he sitä näe; mutta kuin he sen nähdä saavat, niin he häpiään tulevat kansan kiivaudesta, ja vielä sitte tuli sinun vihollises kuluttaa.","Herra, sinun kätes on ylennetty, vaan ei he sitä näe; mutta kuin he sen nähdä saavat, niin he häpiään tulevat kansan kiivaudesta, ja vielä sitte tuli sinun vihollises kuluttaa."],[26,12,"Mutta sinä, Herra, saatat meille rauhan; sillä kaikki, mitä me toimitamme, olet sinä meille antanut.","Mutta sinä, Herra, saatat meille rauhan; sillä kaikki, mitä me toimitamme, olet sinä meille antanut."],[26,13,"Herra meidän Jumalamme: muut herrat tosin meitä myös vallitsevat paitsi sinua; mutta me muistamme ainoastaan kuitenkin sinussa sinun nimeäs.","Herra meidän Jumalamme: muut herrat tosin meitä myös vallitsevat paitsi sinua; mutta me muistamme ainoastaan kuitenkin sinussa sinun nimeäs."],[26,14,"Ei kuolleet eläviksi tule ja nukkuneet ei nouse; sillä sinä olet heitä etsinyt ja hävittänyt, ja kaiken heidän muistonsa kadottanut.","Ei kuolleet eläviksi tule ja nukkuneet ei nouse; sillä sinä olet heitä etsinyt ja hävittänyt, ja kaiken heidän muistonsa kadottanut."],[26,15,"Mutta sinä, Herra, olet lisännyt kansaa, sinä Herra olet lisännyt kansaa, sinä olet kunnialliseksi tullut; sinä olet pannut heitä kauvas maailman ääriin.","Mutta sinä, Herra, olet lisännyt kansaa, sinä Herra olet lisännyt kansaa, sinä olet kunnialliseksi tullut; sinä olet pannut heitä kauvas maailman ääriin."],[26,16,"Herra, kuin tuska tulee, niin sinua etsitään: koskas heitä kuritat, niin he parkuvat surkiasti.","Herra, kuin tuska tulee, niin sinua etsitään: koskas heitä kuritat, niin he parkuvat surkiasti."],[26,17,"Niinkuin raskaalla vaimolla, kuin hän synnyttämällänsä on, on ahdistus, ja hän parkuu kivullansa, niin meille myös tapahtuu, Herra, sinun kasvois edessä.","Niinkuin raskaalla vaimolla, kuin hän synnyttämällänsä on, on ahdistus, ja hän parkuu kivullansa, niin meille myös tapahtuu, Herra, sinun kasvois edessä."],[26,18,"Me olemme raskaat ja meillä on kipu, niinkuin tuulen synnyttäväisellä; emme kuitenkaan voi maata auttaa, eikä maan piirin asuvaiset tahtoneet langeta.","Me olemme raskaat ja meillä on kipu, niinkuin tuulen synnyttäväisellä; emme kuitenkaan voi maata auttaa, eikä maan piirin asuvaiset tahtoneet langeta."],[26,19,"Mutta sinun kuollees elävät, ja minun kuolleet ruumiini nousevat jälleen kuolleista. Herätkäät ja kerskatkaat te, jotka makaatte maan alla; sillä sinun kastees on viheriäisen kedon kaste, ja maa on kuolleet itsestänsä antava.","Mutta sinun kuollees elävät, ja minun kuolleet ruumiini nousevat jälleen kuolleista. Herätkäät ja kerskatkaat te, jotka makaatte maan alla; sillä sinun kastees on viheriäisen kedon kaste, ja maa on kuolleet itsestänsä antava."],[26,20,"Mene, kansani, ja käy sisälle kammioos, ja sulje sinun oves jälkees; lymytä sinus silmänräpäykseksi, niin kauvan kuin viha käy ylitse.","Mene, kansani, ja käy sisälle kammioos, ja sulje sinun oves jälkees; lymytä sinus silmänräpäykseksi, niin kauvan kuin viha käy ylitse."],[26,21,"Sillä katso, Herra on käyvä ulos siastansa etsimään maan asuvaisten pahuutta heidän päällensä; niin että maa ilmoittaa heidän verensä, ja ei niitä enää peitä, jotka hänessä tapetut ovat.","Sillä katso, Herra on käyvä ulos siastansa etsimään maan asuvaisten pahuutta heidän päällensä; niin että maa ilmoittaa heidän verensä, ja ei niitä enää peitä, jotka hänessä tapetut ovat."],[27,1,"Silloin on Herra kovalla, suurella ja väkevällä miekallansa etsivä Leviatania, joka on pitkä kärme, ja Leviatania, joka on kiperä kärme; ja on tappava lohikärmeen meressä.","Silloin on Herra kovalla, suurella ja väkevällä miekallansa etsivä Leviatania, joka on pitkä kärme, ja Leviatania, joka on kiperä kärme; ja on tappava lohikärmeen meressä."],[27,2,"Silloin pitää oleman punaisen viinan viinamäen; laulakaat hänestä:","Silloin pitää oleman punaisen viinan viinamäen; laulakaat hänestä:"],[27,3,"Minä Herra varjelen hänen, ja kastan hänen aikanansa, ettei hänen lehtensä hukkuisi, minä varjelen häntä päivällä ja yöllä.","Minä Herra varjelen hänen, ja kastan hänen aikanansa, ettei hänen lehtensä hukkuisi, minä varjelen häntä päivällä ja yöllä."],[27,4,"En ole minä vihainen. Voi jos minä saisin sotia ohdakkeiden ja orjantappurain kanssa! niin minä menisin heidän tykönsä, ja polttaisin heidät kaikki tyynni.","En ole minä vihainen. Voi jos minä saisin sotia ohdakkeiden ja orjantappurain kanssa! niin minä menisin heidän tykönsä, ja polttaisin heidät kaikki tyynni."],[27,5,"Hän on minua tallella pitävä, ja toimittava minulle rauhan; rauhan on hän vielä sitte minulle saattava.","Hän on minua tallella pitävä, ja toimittava minulle rauhan; rauhan on hän vielä sitte minulle saattava."],[27,6,"Siihen on se kuitenkin joutuva, että Jakob juurtuu ja Israel vihoittaa ja kukoistaa, niin että he maan piirin hedelmällä täyttävät.","Siihen on se kuitenkin joutuva, että Jakob juurtuu ja Israel vihoittaa ja kukoistaa, niin että he maan piirin hedelmällä täyttävät."],[27,7,"Eikö hän kumminkaan tule lyödyksi, niinkuin hänen vihollisensa lyövät häntä? ja eikö hän tule tapetuksi, niinkuin hänen vihollisensa häntä tappavat?","Eikö hän kumminkaan tule lyödyksi, niinkuin hänen vihollisensa lyövät häntä? ja eikö hän tule tapetuksi, niinkuin hänen vihollisensa häntä tappavat?"],[27,8,"Vaan sinä tuomitset heitä määrällä, ja kirvoitat heitä sittekuin sinä ankaralla tuulellas olet heitä murheelliseksi saattanut, koska idästä tuulee.","Vaan sinä tuomitset heitä määrällä, ja kirvoitat heitä sittekuin sinä ankaralla tuulellas olet heitä murheelliseksi saattanut, koska idästä tuulee."],[27,9,"Sentähden pitää Jakobin synti sen kautta anteeksi annettaman; ja se on siitä kaikki hyödytys, että hänen syntinsä otetaan pois, koska hän tekee kaikki alttarin kivet niinkuin tuhaksi muserretut kivet, ettei yhtään metsistöä eli kuvaa pidä enää jäämän.","Sentähden pitää Jakobin synti sen kautta anteeksi annettaman; ja se on siitä kaikki hyödytys, että hänen syntinsä otetaan pois, koska hän tekee kaikki alttarin kivet niinkuin tuhaksi muserretut kivet, ettei yhtään metsistöä eli kuvaa pidä enää jäämän."],[27,10,"Sillä vahvan kaupungin pitää yksinänsä oleman, kauniit huoneet hyljättämän ja jätettämän niinkuin korpi; niin että vasikat käyvät siellä laitumella, oleskelevat siellä ja pureskelevat oksia.","Sillä vahvan kaupungin pitää yksinänsä oleman, kauniit huoneet hyljättämän ja jätettämän niinkuin korpi; niin että vasikat käyvät siellä laitumella, oleskelevat siellä ja pureskelevat oksia."],[27,11,"Hänen oksansa pitää murtuman kuivuuden tähden, niin että vaimot niillä valkeata tekevät; sillä se on ymmärtämätöin kansa, sentähden ei myös se, joka heidät tehnyt on, armahda heitä, ja joka heidät luonut on, ei ole heille armollinen.","Hänen oksansa pitää murtuman kuivuuden tähden, niin että vaimot niillä valkeata tekevät; sillä se on ymmärtämätöin kansa, sentähden ei myös se, joka heidät tehnyt on, armahda heitä, ja joka heidät luonut on, ei ole heille armollinen."],[27,12,"Silloin on Herra heittävä meren rannasta Egyptin virtaan, ja te Israelin lapset kootaan yksi toisensa perästä.","Silloin on Herra heittävä meren rannasta Egyptin virtaan, ja te Israelin lapset kootaan yksi toisensa perästä."],[27,13,"Silloin soitetaan suurella basunalla, niin tulevat kadotetut Assyrian maalla, ja karkoitetut Egyptin maalla, ja rukoilevat Herraa pyhällä Jerusalemin vuorella.","Silloin soitetaan suurella basunalla, niin tulevat kadotetut Assyrian maalla, ja karkoitetut Egyptin maalla, ja rukoilevat Herraa pyhällä Jerusalemin vuorella."],[28,1,"Voi ylpiää Ephraimin juopuneiden kruunua! jonka kaunis kunnia on pudonnut kukkanen, joka on ylemmäisellä puolella lihavaa laaksoa, jossa he viinasta hoipertelevat.","Voi ylpiää Ephraimin juopuneiden kruunua! jonka kaunis kunnia on pudonnut kukkanen, joka on ylemmäisellä puolella lihavaa laaksoa, jossa he viinasta hoipertelevat."],[28,2,"Katso, väkevä ja voimallinen Herralta, niinkuin raesade, niinkuin vahingollinen tuuli, niinkuin vesimyrsky, joka väkevästi lankee, pitää väkivallalla maahan päästettämän;","Katso, väkevä ja voimallinen Herralta, niinkuin raesade, niinkuin vahingollinen tuuli, niinkuin vesimyrsky, joka väkevästi lankee, pitää väkivallalla maahan päästettämän;"],[28,3,"Että Ephraimin juopuneiden ylpiä kruunu jaloilla tallatan.","Että Ephraimin juopuneiden ylpiä kruunu jaloilla tallatan."],[28,4,"Ja hänen kunniansa kaunistuksen pudonneet kukkaset, jotka lihavata laaksoa ylemmäisellä puolella ovat, pitää tuleman niinkuin se, joka varhain suvella kypsyy, jonka joku nähtyänsä ja käsillä pidellessänsä syö.","Ja hänen kunniansa kaunistuksen pudonneet kukkaset, jotka lihavata laaksoa ylemmäisellä puolella ovat, pitää tuleman niinkuin se, joka varhain suvella kypsyy, jonka joku nähtyänsä ja käsillä pidellessänsä syö."],[28,5,"Silloin Herra Zebaot on jääneelle kansallensa kunnian kruunu ja kaunis seppele,","Silloin Herra Zebaot on jääneelle kansallensa kunnian kruunu ja kaunis seppele,"],[28,6,"Ja tuomion henki hänelle, joka oikeudessa istuu, ja väkevyys niille, jotka sodasta palaavat portin tykö.","Ja tuomion henki hänelle, joka oikeudessa istuu, ja väkevyys niille, jotka sodasta palaavat portin tykö."],[28,7,"Siihen myös ovat nämät hulluksi tulleet viinasta, ja hoipertelevat väkevistä juomista; sillä papit ja prophetat ovat hullut väkevästä juomasta, he ovat uponneet viinaan, ja hoipertelevat väkevästä juomasta, he ovat erhettyneet ennustuksessa, ja ei osanneet oikeutta tuomiossa.","Siihen myös ovat nämät hulluksi tulleet viinasta, ja hoipertelevat väkevistä juomista; sillä papit ja prophetat ovat hullut väkevästä juomasta, he ovat uponneet viinaan, ja hoipertelevat väkevästä juomasta, he ovat erhettyneet ennustuksessa, ja ei osanneet oikeutta tuomiossa."],[28,8,"Sillä kaikki pöydät ovat täynnä oksennusta ja riettautta joka paikassa.","Sillä kaikki pöydät ovat täynnä oksennusta ja riettautta joka paikassa."],[28,9,"Kenelle hän siis opettaa viisautta? kenenkä hän antaa ymmärtää saarnaa? Vieroitettuin rieskasta, eroitettuin nisistä.","Kenelle hän siis opettaa viisautta? kenenkä hän antaa ymmärtää saarnaa? Vieroitettuin rieskasta, eroitettuin nisistä."],[28,10,"Sillä (he sanovat:) käske, käske vielä, käske, käske vielä, odota, odota vielä, odota, odota vielä, tässä vähä, siellä vähä.","Sillä (he sanovat:) käske, käske vielä, käske, käske vielä, odota, odota vielä, odota, odota vielä, tässä vähä, siellä vähä."],[28,11,"Sillä hän on vihdoin pilkkaavaisilla huulilla ja toisella kielellä puhuva kansalle, jolle nyt näitä saarnataan.","Sillä hän on vihdoin pilkkaavaisilla huulilla ja toisella kielellä puhuva kansalle, jolle nyt näitä saarnataan."],[28,12,"Niin saadaan lepo, näin virvoitetaan väsyneet, niin ollaan alallansa; ja ei kuitenkaan tahdota kuulla (tätä saarnaa).","Niin saadaan lepo, näin virvoitetaan väsyneet, niin ollaan alallansa; ja ei kuitenkaan tahdota kuulla (tätä saarnaa)."],[28,13,"Sentähden pitää myös Herran sana heille juuri niin oleman: käske, käske vielä, käske, käske vielä, odota, odota vielä, odota, odota vielä, tässä vähä, siellä vähä, että heidän pitää menemän pois ja kaatuman takaperin, musertuman, kiedottaman ja vangiksi tuleman.","Sentähden pitää myös Herran sana heille juuri niin oleman: käske, käske vielä, käske, käske vielä, odota, odota vielä, odota, odota vielä, tässä vähä, siellä vähä, että heidän pitää menemän pois ja kaatuman takaperin, musertuman, kiedottaman ja vangiksi tuleman."],[28,14,"Kuulkaat siis Herran sanaa, te pilkkakirveet, jotka vallitsette tätä kansaa, joka on Jerusalemissa.","Kuulkaat siis Herran sanaa, te pilkkakirveet, jotka vallitsette tätä kansaa, joka on Jerusalemissa."],[28,15,"Sillä te sanotte: me olemme tehneet liiton kuoleman kanssa ja sovinnon helvetin kanssa. Kuin rangaistuksen virta tulee, ei hänen pidä meitä kohtaaman; sillä me olemme tehneet valheen turvaksemme, ja petoksen varjelukseksemme.","Sillä te sanotte: me olemme tehneet liiton kuoleman kanssa ja sovinnon helvetin kanssa. Kuin rangaistuksen virta tulee, ei hänen pidä meitä kohtaaman; sillä me olemme tehneet valheen turvaksemme, ja petoksen varjelukseksemme."],[28,16,"Sentähden sanoo Herra, Herra: katso, minä lasken Zioniin perustuskiven, koetellun kiven, kalliin kulmakiven, joka hyvin on perustettu: joka uskoo, ei hänen pidä peljästymän.","Sentähden sanoo Herra, Herra: katso, minä lasken Zioniin perustuskiven, koetellun kiven, kalliin kulmakiven, joka hyvin on perustettu: joka uskoo, ei hänen pidä peljästymän."],[28,17,"Ja minä teen tuomion ojennusnuoraksi ja vanhurskauden mitaksi, niin pitää rakeet karkoittaman pois väärän turvan, ja veden pitää viemän tulen pois;","Ja minä teen tuomion ojennusnuoraksi ja vanhurskauden mitaksi, niin pitää rakeet karkoittaman pois väärän turvan, ja veden pitää viemän tulen pois;"],[28,18,"Että teidän liittonne kuoleman kanssa pitää tyhjäksi tuleman, ja teidän sovintonne helvetin kanssa ei pidä vahva oleman; ja koska rangaistuksen virta tulee, pitää sen tallaaman teitä.","Että teidän liittonne kuoleman kanssa pitää tyhjäksi tuleman, ja teidän sovintonne helvetin kanssa ei pidä vahva oleman; ja koska rangaistuksen virta tulee, pitää sen tallaaman teitä."],[28,19,"Niin pian kuin se tulee, niin sen pitää teitä viemän pois: jos se tulee aamulla, niin tapahtuu se aamulla, niin myös päivällä ja yöllä; sillä ainoastaan rangaistus opettaa ottamaan sanoista vaarin.","Niin pian kuin se tulee, niin sen pitää teitä viemän pois: jos se tulee aamulla, niin tapahtuu se aamulla, niin myös päivällä ja yöllä; sillä ainoastaan rangaistus opettaa ottamaan sanoista vaarin."],[28,20,"Sillä vuode on niin lyhyt, ettei saa itsiänsä ojentaa, ja peite on niin soukka, ettei sen alla taida mykärässä olla.","Sillä vuode on niin lyhyt, ettei saa itsiänsä ojentaa, ja peite on niin soukka, ettei sen alla taida mykärässä olla."],[28,21,"Sillä Herra on nouseva niinkuin Peratsimin vuorella, ja vihastuva niinkuin Gibeonin laaksossa, että hän tekis työnsä, muukalaisen työnsä, ja että hän toimittais tekonsa, oudon tekonsa.","Sillä Herra on nouseva niinkuin Peratsimin vuorella, ja vihastuva niinkuin Gibeonin laaksossa, että hän tekis työnsä, muukalaisen työnsä, ja että hän toimittais tekonsa, oudon tekonsa."],[28,22,"Pankaat siis pilkkanne pois, ettei siteenne kovemmaksi tulisi; sillä minä olen kuullut hävityksen ja teloituksen, joka Herralta, Herralta Zebaotilta on tapahtuva kaikessa maailmassa.","Pankaat siis pilkkanne pois, ettei siteenne kovemmaksi tulisi; sillä minä olen kuullut hävityksen ja teloituksen, joka Herralta, Herralta Zebaotilta on tapahtuva kaikessa maailmassa."],[28,23,"Ottakaat korviinne ja kuulkaat minun ääneni, ymmärtäkäät ja kuulkaat minun puheeni.","Ottakaat korviinne ja kuulkaat minun ääneni, ymmärtäkäät ja kuulkaat minun puheeni."],[28,24,"Kyntääkö eli jyrästääkö taikka viljeleekö peltomies peltonsa aina jyviksi?","Kyntääkö eli jyrästääkö taikka viljeleekö peltomies peltonsa aina jyviksi?"],[28,25,"Eikö niin ole? koska hän sen on tasoittanut, niin hän kylvää siihen herneitä ja heittää kuminoita, ja kylvää nisuja, ohria, jokaista kuhunka hän tahtoo, ja kaurat paikkaansa.","Eikö niin ole? koska hän sen on tasoittanut, niin hän kylvää siihen herneitä ja heittää kuminoita, ja kylvää nisuja, ohria, jokaista kuhunka hän tahtoo, ja kaurat paikkaansa."],[28,26,"Juuri niin kurittaa myös heidän Jumalansa heitä rangaistuksella, ja opettaa heitä.","Juuri niin kurittaa myös heidän Jumalansa heitä rangaistuksella, ja opettaa heitä."],[28,27,"Sillä ei herneitä tapeta varstalla, eikä vaunuratas anneta kuminain päällä käydä, vaan herneet varistetaan sauvalla ja kuminat vitsalla.","Sillä ei herneitä tapeta varstalla, eikä vaunuratas anneta kuminain päällä käydä, vaan herneet varistetaan sauvalla ja kuminat vitsalla."],[28,28,"Se jauhetaan ja leivotaan, eikä peräti tyhjäksi tapeta, koska se vaunurattaalla ja hevosilla tapetaan.","Se jauhetaan ja leivotaan, eikä peräti tyhjäksi tapeta, koska se vaunurattaalla ja hevosilla tapetaan."],[28,29,"Näin tekee myös Herra Zebaot; sillä hänen neuvonsa on ihmeellinen, ja sen jalosti toimittaa.","Näin tekee myös Herra Zebaot; sillä hänen neuvonsa on ihmeellinen, ja sen jalosti toimittaa."],[29,1,"Voi Ariel, Ariel! sinä Davidin leirin kaupunki! te pidätte vuoden ajat ja pyhäpäivät.","Voi Ariel, Ariel! sinä Davidin leirin kaupunki! te pidätte vuoden ajat ja pyhäpäivät."],[29,2,"Mutta minä vaivaan Arielia, niin että hänen pitää murehtiman ja sureman ja oleman minulle oikia Ariel.","Mutta minä vaivaan Arielia, niin että hänen pitää murehtiman ja sureman ja oleman minulle oikia Ariel."],[29,3,"Sillä minä piiritän sinun joka kulmalta, ja ahdistan sinun saarrolla, ja annan panna vallit sinun ympärilles.","Sillä minä piiritän sinun joka kulmalta, ja ahdistan sinun saarrolla, ja annan panna vallit sinun ympärilles."],[29,4,"Silloin pitää sinun itses alentaman, ja maasta puhuman, ja mutiseman puheellas tomusta; että sinun äänes on niinkuin noidan maasta, ja sinun puhees pitää oleman niinkuin tomusta haisevaisen.","Silloin pitää sinun itses alentaman, ja maasta puhuman, ja mutiseman puheellas tomusta; että sinun äänes on niinkuin noidan maasta, ja sinun puhees pitää oleman niinkuin tomusta haisevaisen."],[29,5,"Ja niitä, jotka sinua hajoittavat, pitää oleman niin monta kuin pientä tomua, ja tyranneja niin monta kuin lentäviä akanoita; ja sen pitää ratki äkisti tapahtuman.","Ja niitä, jotka sinua hajoittavat, pitää oleman niin monta kuin pientä tomua, ja tyranneja niin monta kuin lentäviä akanoita; ja sen pitää ratki äkisti tapahtuman."],[29,6,"Sillä sinun pitää Herralta Zebaotilta etsityksi tuleman pitkäisen jylinällä, maan järinällä, suurella äänellä, tuulen pyöriäisellä, raju-ilmalla ja kuluttavaisen tulen liekillä.","Sillä sinun pitää Herralta Zebaotilta etsityksi tuleman pitkäisen jylinällä, maan järinällä, suurella äänellä, tuulen pyöriäisellä, raju-ilmalla ja kuluttavaisen tulen liekillä."],[29,7,"Mutta niinkuin yön näkö unessa, niin pitää kaikkein pakanain joukko oleman, jotka sotivat Arielia vastaan, kaiken joukkonsa ja saartonsa kanssa, ja niitä, jotka häntä ahdistavat.","Mutta niinkuin yön näkö unessa, niin pitää kaikkein pakanain joukko oleman, jotka sotivat Arielia vastaan, kaiken joukkonsa ja saartonsa kanssa, ja niitä, jotka häntä ahdistavat."],[29,8,"Sillä niinkuin isoovainen on unessa syövinänsä, mutta herättyänsä on hänen sielunsa vielä tyhjä; ja niinkuin janoova on unessa juovinansa, mutta herättyänsä on hän voimatoin ja janoissansa: juuri niin pitää myös kaikkein pakanain joukko oleman, jotka sotivat Zionin vuorta vastaan.","Sillä niinkuin isoovainen on unessa syövinänsä, mutta herättyänsä on hänen sielunsa vielä tyhjä; ja niinkuin janoova on unessa juovinansa, mutta herättyänsä on hän voimatoin ja janoissansa: juuri niin pitää myös kaikkein pakanain joukko oleman, jotka sotivat Zionin vuorta vastaan."],[29,9,"Olkaat hitaat ja ihmetelkäät, eläkäät hekumassa, huutakaat, ja juopukaat, ei kuitenkaan viinasta; horjukaat, ei kuitenkaan väkevästä juomasta.","Olkaat hitaat ja ihmetelkäät, eläkäät hekumassa, huutakaat, ja juopukaat, ei kuitenkaan viinasta; horjukaat, ei kuitenkaan väkevästä juomasta."],[29,10,"Sillä Herra on teille raskaan unen hengen lähettänyt, ja teidän silmänne sulkenut; teidän prophetanne, päämiehenne ja näkiänne on hän sokaissut;","Sillä Herra on teille raskaan unen hengen lähettänyt, ja teidän silmänne sulkenut; teidän prophetanne, päämiehenne ja näkiänne on hän sokaissut;"],[29,11,"Niin että kaikkein prophetain näyt ovat heille niinkuin lukitun kirjan sanat. Jos joku sen antais sille, joka lukea taitaa, ja sanois: lue tätä, ja hän vastaa: en minä taida, sillä se on lukittu.","Niin että kaikkein prophetain näyt ovat heille niinkuin lukitun kirjan sanat. Jos joku sen antais sille, joka lukea taitaa, ja sanois: lue tätä, ja hän vastaa: en minä taida, sillä se on lukittu."],[29,12,"Eli jos joku antais sille, joka ei lukea taida, ja sanois: lues tätä, ja hän vastaa: en minä taida ensinkään lukea.","Eli jos joku antais sille, joka ei lukea taida, ja sanois: lues tätä, ja hän vastaa: en minä taida ensinkään lukea."],[29,13,"Ja Herra sanoo: että tämä kansa lähestyy minua suullansa, ja kunnioittaa minua huulillansa; mutta heidän sydämensä on kaukana minusta, ja pelkäävät minua ihmisten käskyin jälkeen, joita he opettavat;","Ja Herra sanoo: että tämä kansa lähestyy minua suullansa, ja kunnioittaa minua huulillansa; mutta heidän sydämensä on kaukana minusta, ja pelkäävät minua ihmisten käskyin jälkeen, joita he opettavat;"],[29,14,"Niin minä myös teen tälle kansalle ihmeellisesti, hirmuisesti, ja kamalasti, että heidän viisastensa viisaus hukkuu, ja heidän ymmärtäväistensä ymmärrys kätketään.","Niin minä myös teen tälle kansalle ihmeellisesti, hirmuisesti, ja kamalasti, että heidän viisastensa viisaus hukkuu, ja heidän ymmärtäväistensä ymmärrys kätketään."],[29,15,"Voi niitä, jotka tahtovat olla salatut Herran edessä, ja peittää aivoituksensa, ja tekonsa pimeydessä pitää, ja sanovat: kukapa meidät näkee? eli kuka tuntee meitä?","Voi niitä, jotka tahtovat olla salatut Herran edessä, ja peittää aivoituksensa, ja tekonsa pimeydessä pitää, ja sanovat: kukapa meidät näkee? eli kuka tuntee meitä?"],[29,16,"Miksi te niin nurjat olette? Niinkuin savenvalaja pidettäisiin savena; käsiala puhuis tekiästänsä: ei hän ole minua tehnyt, ja teko sanois tekiästänsä: ei hän minua tunne.","Miksi te niin nurjat olette? Niinkuin savenvalaja pidettäisiin savena; käsiala puhuis tekiästänsä: ei hän ole minua tehnyt, ja teko sanois tekiästänsä: ei hän minua tunne."],[29,17,"Eikö vähän hetken perästä Libanonin pidä hedelmälliseksi kedoksi tuleman, ja hedelmällinen keto metsäksi luettaman?","Eikö vähän hetken perästä Libanonin pidä hedelmälliseksi kedoksi tuleman, ja hedelmällinen keto metsäksi luettaman?"],[29,18,"Silloin kuulevat kuurot tämän kirjan sanoja; ja sokian silmät näkevät synkeydessä ja pimeydessä.","Silloin kuulevat kuurot tämän kirjan sanoja; ja sokian silmät näkevät synkeydessä ja pimeydessä."],[29,19,"Ja raadolliset saavat ilon Herrasta; ja köyhät ihmisten seassa riemuitsevat Israelin Pyhässä,","Ja raadolliset saavat ilon Herrasta; ja köyhät ihmisten seassa riemuitsevat Israelin Pyhässä,"],[29,20,"Koska tyrannit hukkuvat, ja pilkkaajat loppuvat, ja ne kaikki teloitetaan, jotka valvovat pahaa tehdäksensä,","Koska tyrannit hukkuvat, ja pilkkaajat loppuvat, ja ne kaikki teloitetaan, jotka valvovat pahaa tehdäksensä,"],[29,21,"Jotka ihmisen tekevät syntiseksi sanan tähden, ja vainoovat rankaisiaansa portissa, ja poikkeevat oikeudesta valheen kautta.","Jotka ihmisen tekevät syntiseksi sanan tähden, ja vainoovat rankaisiaansa portissa, ja poikkeevat oikeudesta valheen kautta."],[29,22,"Sentähden sanoo Herra, Abrahamin lunastaja, Jakobin huoneelle näin: ei Jakob tule enää häpiään, eikä hänen kasvonsa ole enää häpeevä.","Sentähden sanoo Herra, Abrahamin lunastaja, Jakobin huoneelle näin: ei Jakob tule enää häpiään, eikä hänen kasvonsa ole enää häpeevä."],[29,23,"Sillä koska he saavat lapsensa nähdä, minun käsialani heidän seassansa, niin he pyhittävät minun nimeni; ja heidän pitää Jakobin Pyhän pyhittämän, ja Israelin Jumalaa pelkäämän.","Sillä koska he saavat lapsensa nähdä, minun käsialani heidän seassansa, niin he pyhittävät minun nimeni; ja heidän pitää Jakobin Pyhän pyhittämän, ja Israelin Jumalaa pelkäämän."],[29,24,"Sillä joilla eksyväinen henki on, ne ottavat ymmärryksen; turhan puhujat sallivat heitänsä opetettaa.","Sillä joilla eksyväinen henki on, ne ottavat ymmärryksen; turhan puhujat sallivat heitänsä opetettaa."],[30,1,"Voi luopuvaisia lapsia! sanoo Herra: jotka ilman minua neuvoa pitävät, ja ilman minun henkeäni varjelusta etsivät, kokoovat syntiä synnin päälle;","Voi luopuvaisia lapsia! sanoo Herra: jotka ilman minua neuvoa pitävät, ja ilman minun henkeäni varjelusta etsivät, kokoovat syntiä synnin päälle;"],[30,2,"Jotka menevät alas Egyptiin, ja ei kysy minun suutani, varustaaksensa itsiänsä Pharaon voimalla, ja varjellaksensa itsensä Egyptin varjolla.","Jotka menevät alas Egyptiin, ja ei kysy minun suutani, varustaaksensa itsiänsä Pharaon voimalla, ja varjellaksensa itsensä Egyptin varjolla."],[30,3,"Ja Pharaon väkevyys pitää oleman teille häpiäksi, ja Egyptin varjon turva häväistykseksi.","Ja Pharaon väkevyys pitää oleman teille häpiäksi, ja Egyptin varjon turva häväistykseksi."],[30,4,"Sillä heidän pääruhtinaansa ovat olleet Zoanissa; ja heidän sanansaattajansa ovat tulleet Hanekseen.","Sillä heidän pääruhtinaansa ovat olleet Zoanissa; ja heidän sanansaattajansa ovat tulleet Hanekseen."],[30,5,"Mutta heidän pitää kaikkein kuitenkin häpiään tuleman, sen kansan tähden, joka ei heille hyväksi eli avuksi olla taida, eikä muutoin hyödytykseksi, vaan ainoasti häpiäksi ja myös pilkaksi.","Mutta heidän pitää kaikkein kuitenkin häpiään tuleman, sen kansan tähden, joka ei heille hyväksi eli avuksi olla taida, eikä muutoin hyödytykseksi, vaan ainoasti häpiäksi ja myös pilkaksi."],[30,6,"Tämä on niiden petoin kuorma, jotka etelään päin ovat, kussa vanha ja nuori jalopeura on, tuliset kyykärmeet ja lentäväiset kärmeet murheen ja ahdistuksen maassa. He vievät riistansa varsoilla, ja tavaransa kamelein selässä sille kansalle, joka ei heille ensinkään hyödytykseksi olla taida.","Tämä on niiden petoin kuorma, jotka etelään päin ovat, kussa vanha ja nuori jalopeura on, tuliset kyykärmeet ja lentäväiset kärmeet murheen ja ahdistuksen maassa. He vievät riistansa varsoilla, ja tavaransa kamelein selässä sille kansalle, joka ei heille ensinkään hyödytykseksi olla taida."],[30,7,"Sillä ei Egypti mitään ole, ja hänen apunsa on turha, sentähden minä saarnaan siitä näin: alallansa olla on paras.","Sillä ei Egypti mitään ole, ja hänen apunsa on turha, sentähden minä saarnaan siitä näin: alallansa olla on paras."],[30,8,"Mene siis nyt ja kirjoita tämä heidän eteensä tauluun, ja pane kirjaan, pysymään viimeiseen päivään asti, alati ja ijankaikkisesti.","Mene siis nyt ja kirjoita tämä heidän eteensä tauluun, ja pane kirjaan, pysymään viimeiseen päivään asti, alati ja ijankaikkisesti."],[30,9,"Sillä se on tottelematoin kansa, ja valhetteliat lapset: lapset, jotka ei tahdo kuulla Herran lakia.","Sillä se on tottelematoin kansa, ja valhetteliat lapset: lapset, jotka ei tahdo kuulla Herran lakia."],[30,10,"Vaan sanovat näkiöille: ei teidän pidä näkemän, ja katsojille: ei teidän pidä katsoman meille oikeutta; mutta saarnatkaat meille suloisesti, katsokaat petos.","Vaan sanovat näkiöille: ei teidän pidä näkemän, ja katsojille: ei teidän pidä katsoman meille oikeutta; mutta saarnatkaat meille suloisesti, katsokaat petos."],[30,11,"Poiketkaat teiltä, luopukaat tästä retkestä: antakaat Israelin Pyhän lakata meistä.","Poiketkaat teiltä, luopukaat tästä retkestä: antakaat Israelin Pyhän lakata meistä."],[30,12,"Sentähden sanoo Israelin Pyhä näin: että te hylkäätte tämän sanan, ja luotatte väkivaltaan ja vääryyteen, ja kerskaatte siitä;","Sentähden sanoo Israelin Pyhä näin: että te hylkäätte tämän sanan, ja luotatte väkivaltaan ja vääryyteen, ja kerskaatte siitä;"],[30,13,"Niin pitää tämän pahan teon oleman teille niinkuin rako korkiassa muurissa, kuin se rupee hajoomaan, joka äkisti kaatuu maahan ylösalaisin, ja murentuu.","Niin pitää tämän pahan teon oleman teille niinkuin rako korkiassa muurissa, kuin se rupee hajoomaan, joka äkisti kaatuu maahan ylösalaisin, ja murentuu."],[30,14,"Niinkuin savi-astia muserrettu olis, joka muserretaan ja ei säästetä, siihenasti ettei siitä löydä niin suurta kappaletta, että tulta tuotaisiin totoista, eli ammennettaisiin vettä kaivosta.","Niinkuin savi-astia muserrettu olis, joka muserretaan ja ei säästetä, siihenasti ettei siitä löydä niin suurta kappaletta, että tulta tuotaisiin totoista, eli ammennettaisiin vettä kaivosta."],[30,15,"Sillä näin sanoo Herra, Herra Israelin Pyhä: kääntymisellä ja hiljaisuudella te tulette autetuksi, hiljaisuudessa ja toivossa te väkeväksi tulette, mutta ette tahtoneet;","Sillä näin sanoo Herra, Herra Israelin Pyhä: kääntymisellä ja hiljaisuudella te tulette autetuksi, hiljaisuudessa ja toivossa te väkeväksi tulette, mutta ette tahtoneet;"],[30,16,"Vaan sanoitte: ei, vaan me tahdomme paeta hevosilla; sentähden teidän pitää kulkiana oleman: ja me tahdomme nopiasti ajaa; sentähden pitää teidän vainoojanne myös nopiat oleman.","Vaan sanoitte: ei, vaan me tahdomme paeta hevosilla; sentähden teidän pitää kulkiana oleman: ja me tahdomme nopiasti ajaa; sentähden pitää teidän vainoojanne myös nopiat oleman."],[30,17,"Tuhannen teistä pitää pakeneman yhden miehen uhkauksesta, viiden uhkauksesta pitää teidän pakeneman, siihenasti että teistä jää niinkuin pielipuu vuorelle, ja niinkuin lippu korkeudelle.","Tuhannen teistä pitää pakeneman yhden miehen uhkauksesta, viiden uhkauksesta pitää teidän pakeneman, siihenasti että teistä jää niinkuin pielipuu vuorelle, ja niinkuin lippu korkeudelle."],[30,18,"Sentähden Herra odottaa, että hän olis teille armoinen, ja sentähden on hän noussut teitä armahtamaan; sillä Herra on oikeuden Jumala. Autuaat ovat kaikki, jotka häntä odottavat.","Sentähden Herra odottaa, että hän olis teille armoinen, ja sentähden on hän noussut teitä armahtamaan; sillä Herra on oikeuden Jumala. Autuaat ovat kaikki, jotka häntä odottavat."],[30,19,"Sillä Zionin kansa on asuva Jerusalemissa, ja et sinä ole katkerasti itkevä. Hän kaiketi armahtaa sinua, kuin sinä huudat; hän vastaa sinua niin pian kuin hän sen kuulee.","Sillä Zionin kansa on asuva Jerusalemissa, ja et sinä ole katkerasti itkevä. Hän kaiketi armahtaa sinua, kuin sinä huudat; hän vastaa sinua niin pian kuin hän sen kuulee."],[30,20,"Ja Herra antaa teille leipää tuskassanne ja vettä ahdistuksessanne; sillä ei sinun opettajas lennä enää pois, vaan sinun silmäs näkevät opettajas.","Ja Herra antaa teille leipää tuskassanne ja vettä ahdistuksessanne; sillä ei sinun opettajas lennä enää pois, vaan sinun silmäs näkevät opettajas."],[30,21,"Ja korvas kuulevat sanan takanas, sanoen: tämä on tie käykäät sitä, kuin te oikialle eli vasemmalle kädelle eksyneet olette.","Ja korvas kuulevat sanan takanas, sanoen: tämä on tie käykäät sitä, kuin te oikialle eli vasemmalle kädelle eksyneet olette."],[30,22,"Silloin pitää teidän saastuttaman teidän hopialla silatut kuvanne, ja teidän kuvainne kultaiset vaatteet; ja teidän pitää ne heittämän pois niinkuin saastaisuuden, ja niille sanoman: mene ulos.","Silloin pitää teidän saastuttaman teidän hopialla silatut kuvanne, ja teidän kuvainne kultaiset vaatteet; ja teidän pitää ne heittämän pois niinkuin saastaisuuden, ja niille sanoman: mene ulos."],[30,23,"Silloin hän antaa sateen siemenelles, jonka pellolles kylvänyt olet, ja leipää pellon tulosta ylen runsaasti; ja karjas kaitaan avaralla kedolla.","Silloin hän antaa sateen siemenelles, jonka pellolles kylvänyt olet, ja leipää pellon tulosta ylen runsaasti; ja karjas kaitaan avaralla kedolla."],[30,24,"Härjät ja varsat, jotka peltos kyntävät, syövät sekoitettuja ohria, jotka viskimellä ja pohtimella ovat pohditut.","Härjät ja varsat, jotka peltos kyntävät, syövät sekoitettuja ohria, jotka viskimellä ja pohtimella ovat pohditut."],[30,25,"Ja kaikkein suurten vuorten päällä, ja kaikkein suurten kukkulain päällä pitää eroitetut virrat käymän, suuren surmaamisen aikana, ja kuin tornit kaatuvat.","Ja kaikkein suurten vuorten päällä, ja kaikkein suurten kukkulain päällä pitää eroitetut virrat käymän, suuren surmaamisen aikana, ja kuin tornit kaatuvat."],[30,26,"Ja kuun valo on oleva kuin auringon paiste ja auringon paiste on oleva seitsemän kertaa kirkkaampi kuin seitsemän päivän kirkkaus; kuin Herra sitoo kansansa haavat, ja sen loukkaamat parantaa.","Ja kuun valo on oleva kuin auringon paiste ja auringon paiste on oleva seitsemän kertaa kirkkaampi kuin seitsemän päivän kirkkaus; kuin Herra sitoo kansansa haavat, ja sen loukkaamat parantaa."],[30,27,"Katso, Herran nimi tulee kaukaa, hänen vihansa polttaa ja on sangen raskas; hänen huulensa ovat hirmuisuutta täynnä, ja hänen kielensä on niinkuin kuluttava tuli.","Katso, Herran nimi tulee kaukaa, hänen vihansa polttaa ja on sangen raskas; hänen huulensa ovat hirmuisuutta täynnä, ja hänen kielensä on niinkuin kuluttava tuli."],[30,28,"Ja hänen henkensä niinkuin tulvaava virta, joka hamaan kurkkuun asti ulottuu, hajoittamaan pakanoita, siihenasti että he tyhjäksi tulevat, ja ajamaan kansaa sinne ja tänne, suitsilla heidän suussansa.","Ja hänen henkensä niinkuin tulvaava virta, joka hamaan kurkkuun asti ulottuu, hajoittamaan pakanoita, siihenasti että he tyhjäksi tulevat, ja ajamaan kansaa sinne ja tänne, suitsilla heidän suussansa."],[30,29,"Silloin pitää teidän veisaaman niinkuin juhlayönä, ja sydämestänne riemuitseman niinkuin huiluilla käytäisiin Herran vuorelle, Israelin turvan tykö.","Silloin pitää teidän veisaaman niinkuin juhlayönä, ja sydämestänne riemuitseman niinkuin huiluilla käytäisiin Herran vuorelle, Israelin turvan tykö."],[30,30,"Ja Herra kuuluttaa kunniallisen äänensä, että hänen kokotettu käsivartensa nähtäisiin, vihaisella haastamisella, ja kuluttavaisen tulen liekillä, säteillä, väkevällä sateella ja rakehilla.","Ja Herra kuuluttaa kunniallisen äänensä, että hänen kokotettu käsivartensa nähtäisiin, vihaisella haastamisella, ja kuluttavaisen tulen liekillä, säteillä, väkevällä sateella ja rakehilla."],[30,31,"Sillä Assurin pitää peljästymän Herran ääntä, joka häntä lyö vitsalla.","Sillä Assurin pitää peljästymän Herran ääntä, joka häntä lyö vitsalla."],[30,32,"Sillä vitsan pitää kyllä sattuman ja koskeman, kuin Herra sen vie heidän ylitsensä rummuilla ja kanteleilla, ja joka paikassa sotii heitä vastaan.","Sillä vitsan pitää kyllä sattuman ja koskeman, kuin Herra sen vie heidän ylitsensä rummuilla ja kanteleilla, ja joka paikassa sotii heitä vastaan."],[30,33,"Sillä kuoppa on jo entisestä valmistettu, ja se on myös kuninkaalle valmistettu, kyllä syvä ja leviä. Siellä on asumus, tuli ja paljo puita; Herran Henki on sen sytyttävä niinkuin jonkun tulikivisen virran.","Sillä kuoppa on jo entisestä valmistettu, ja se on myös kuninkaalle valmistettu, kyllä syvä ja leviä. Siellä on asumus, tuli ja paljo puita; Herran Henki on sen sytyttävä niinkuin jonkun tulikivisen virran."],[31,1,"Voi niitä, jotka menevät alas Egyptiin apua kerjäämään, ja luottavat hevosiin, ja turvaavat vaunuihin, että niitä on monta, ja ratsasmiehiin, että he juuri väkevät ovat, eivätkä turvaa Israelin Pyhään, eikä kysy Herraa.","Voi niitä, jotka menevät alas Egyptiin apua kerjäämään, ja luottavat hevosiin, ja turvaavat vaunuihin, että niitä on monta, ja ratsasmiehiin, että he juuri väkevät ovat, eivätkä turvaa Israelin Pyhään, eikä kysy Herraa."],[31,2,"Mutta hän on viisas ja antaa tulla onnettomuuden, ja ei muuta sanojansa; vaan asettaa itsensä pahain huonetta vastaan, ja pahantekiäin apua vastaan.","Mutta hän on viisas ja antaa tulla onnettomuuden, ja ei muuta sanojansa; vaan asettaa itsensä pahain huonetta vastaan, ja pahantekiäin apua vastaan."],[31,3,"Sillä Egypti on ihminen ja ei Jumala, ja heidän hevosensa ovat liha ja ei henki. Ja Herra on kokottava kätensä, niin että auttajan pitää hoiperteleman, ja sen, jota autetaan, pitää lankeeman, ja ynnä molemmat toinen toisensa kanssa hukkuman.","Sillä Egypti on ihminen ja ei Jumala, ja heidän hevosensa ovat liha ja ei henki. Ja Herra on kokottava kätensä, niin että auttajan pitää hoiperteleman, ja sen, jota autetaan, pitää lankeeman, ja ynnä molemmat toinen toisensa kanssa hukkuman."],[31,4,"Sillä näin sanoo Herra minulle: niinkuin jalopeura ja nuori jalopeura kiljuu saaliinsa päällä, kuin paimenten joukko on kokoontunut sitä vastaan, ei peljästy heidän huudostansa, eikä hämmästy vaikka heitä monta on: juuri niin on Herra Zebaot menevä alas sotimaan Zionin vuorella ja sen korkeudella.","Sillä näin sanoo Herra minulle: niinkuin jalopeura ja nuori jalopeura kiljuu saaliinsa päällä, kuin paimenten joukko on kokoontunut sitä vastaan, ei peljästy heidän huudostansa, eikä hämmästy vaikka heitä monta on: juuri niin on Herra Zebaot menevä alas sotimaan Zionin vuorella ja sen korkeudella."],[31,5,"Niinkuin linnut siivillänsä tekevät, niin Herra Zebaot on varjeleva Jerusalemin: hän on suojeleva, auttava, siellä oleva ja holhova häntä.","Niinkuin linnut siivillänsä tekevät, niin Herra Zebaot on varjeleva Jerusalemin: hän on suojeleva, auttava, siellä oleva ja holhova häntä."],[31,6,"Palatkaat, te Israelin lapset, sen tykö, josta te peräti harhailleet olette.","Palatkaat, te Israelin lapset, sen tykö, josta te peräti harhailleet olette."],[31,7,"Sillä silloin jokainen hylkää hopia- ja kulta-epäjumalansa, joita omat kätenne ovat tehneet teille synniksi.","Sillä silloin jokainen hylkää hopia- ja kulta-epäjumalansa, joita omat kätenne ovat tehneet teille synniksi."],[31,8,"Ja Assurin pitää lankeeman, ei miehen miekalla, ja pitää kulutettaman, ei ihmisen miekalla; ja pitää kuitenkin pakeneman miekkaa, ja hänen nuorukaisensa pitää verollisiksi tuleman.","Ja Assurin pitää lankeeman, ei miehen miekalla, ja pitää kulutettaman, ei ihmisen miekalla; ja pitää kuitenkin pakeneman miekkaa, ja hänen nuorukaisensa pitää verollisiksi tuleman."],[31,9,"Ja hänen pitää pelvon tähden menemän kallionsa ohitse, ja hänen pääruhtinaansa pitää lippunsa edestä pakoon menemän, sanoo Herra Zebaot, jolla Zionissa tuli ja Jerusalemissa totto on.","Ja hänen pitää pelvon tähden menemän kallionsa ohitse, ja hänen pääruhtinaansa pitää lippunsa edestä pakoon menemän, sanoo Herra Zebaot, jolla Zionissa tuli ja Jerusalemissa totto on."],[32,1,"Katso, kuningas on hallitseva oikeudella; ja pääruhtinaat vallitsevat, oikeutta pitämään voimassa.","Katso, kuningas on hallitseva oikeudella; ja pääruhtinaat vallitsevat, oikeutta pitämään voimassa."],[32,2,"Että jokainen on niinkuin joku, joka tuulelta varjeltu on, ja niinkuin joku, joka sadekuurolta on peitetty, niinkuin vesi-ojat kuivassa paikassa, niinkuin suuren vuoren varjo kuivassa maassa.","Että jokainen on niinkuin joku, joka tuulelta varjeltu on, ja niinkuin joku, joka sadekuurolta on peitetty, niinkuin vesi-ojat kuivassa paikassa, niinkuin suuren vuoren varjo kuivassa maassa."],[32,3,"Ja näkeväiset silmät ei pidä pimenemän; ja kuulevaisten korvat pitää visun vaarin ottaman.","Ja näkeväiset silmät ei pidä pimenemän; ja kuulevaisten korvat pitää visun vaarin ottaman."],[32,4,"Ja hulluin pitää oppiman taitoa, ja sopera kieli pitää selkeäksi tuleman ja selkeästi puhuman.","Ja hulluin pitää oppiman taitoa, ja sopera kieli pitää selkeäksi tuleman ja selkeästi puhuman."],[32,5,"Ei hullua pidä enää pääruhtinaaksi kutsuttaman, eikä ahnetta herraksi.","Ei hullua pidä enää pääruhtinaaksi kutsuttaman, eikä ahnetta herraksi."],[32,6,"Sillä tyhmä puhuu tyhmyydessä, ja hänen sydämensä on pahuudessa; että hän olis ulkokullaisuudessa; ja saarnais Herrasta väärin, että hän sillä isoovaiset sielut nälkään näännyttäis, ja kieltäis janoovaisilta juoman.","Sillä tyhmä puhuu tyhmyydessä, ja hänen sydämensä on pahuudessa; että hän olis ulkokullaisuudessa; ja saarnais Herrasta väärin, että hän sillä isoovaiset sielut nälkään näännyttäis, ja kieltäis janoovaisilta juoman."],[32,7,"Sillä ahneen hallitus ei ole muu kuin vahinko; sillä hän löytää kavaluuden hävittääksensä raadollisia väärillä sanoilla, silloinkin kun köyhä oikeuttansa puhuu.","Sillä ahneen hallitus ei ole muu kuin vahinko; sillä hän löytää kavaluuden hävittääksensä raadollisia väärillä sanoilla, silloinkin kun köyhä oikeuttansa puhuu."],[32,8,"Mutta toimellinen päämies pitää toimellisia neuvoja; ja toimellisissa menoissa hän vahvana pysyy.","Mutta toimellinen päämies pitää toimellisia neuvoja; ja toimellisissa menoissa hän vahvana pysyy."],[32,9,"Nouskaat, te suruttomat vaimot, kuulkaat minun ääntäni; te rohkiat tyttäret, ottakaat korviinne minun puheeni.","Nouskaat, te suruttomat vaimot, kuulkaat minun ääntäni; te rohkiat tyttäret, ottakaat korviinne minun puheeni."],[32,10,"Ajastajan ja päivän perästä pitää teidän vapiseman, jotka niin rohkiat olette; sillä ei tule yhtään viinan eloa, eikä tule yhtään kokoomusta.","Ajastajan ja päivän perästä pitää teidän vapiseman, jotka niin rohkiat olette; sillä ei tule yhtään viinan eloa, eikä tule yhtään kokoomusta."],[32,11,"Peljästykäät, te suruttomat vaimot, vaviskaat, te rohkiat; te riisutaan, paljastetaan ja kupeista vyötetään.","Peljästykäät, te suruttomat vaimot, vaviskaat, te rohkiat; te riisutaan, paljastetaan ja kupeista vyötetään."],[32,12,"Rinnoille lyödään valittaen ihanaisista pelloista ja hedelmällisistä viinapuista.","Rinnoille lyödään valittaen ihanaisista pelloista ja hedelmällisistä viinapuista."],[32,13,"Sillä minun kansani pellossa pitää orjantappurat ja ohdakkeet kasvaman; niin myös kaikissa ilohuoneissa, iloisessa kaupungissa.","Sillä minun kansani pellossa pitää orjantappurat ja ohdakkeet kasvaman; niin myös kaikissa ilohuoneissa, iloisessa kaupungissa."],[32,14,"Sillä salit pitää hyljättämän, ja kansan paljous kaupungissa pitää vähenemän; niin että tornit ja linnat pitää tuleman ijankaikkiseksi luolaksi, ja metsän pedoille iloksi, ja laumoille laitumeksi;","Sillä salit pitää hyljättämän, ja kansan paljous kaupungissa pitää vähenemän; niin että tornit ja linnat pitää tuleman ijankaikkiseksi luolaksi, ja metsän pedoille iloksi, ja laumoille laitumeksi;"],[32,15,"Siihenasti että Henki korkeudesta vuodatetaan meidän päällemme: silloin tulee korpi peltomaaksi, ja peltomaa luetaan metsäksi.","Siihenasti että Henki korkeudesta vuodatetaan meidän päällemme: silloin tulee korpi peltomaaksi, ja peltomaa luetaan metsäksi."],[32,16,"Ja oikeus asuu korvessa, ja vanhurskaus peltomaassas;","Ja oikeus asuu korvessa, ja vanhurskaus peltomaassas;"],[32,17,"Ja vanhurskauden työ on rauha, ja vanhurskauden hyödytys ijankaikkinen hiljaisuus ja lepo.","Ja vanhurskauden työ on rauha, ja vanhurskauden hyödytys ijankaikkinen hiljaisuus ja lepo."],[32,18,"Niin että minun kansani on asuva rauhan huoneessa, turvallisissa majoissa ja jalossa levossa.","Niin että minun kansani on asuva rauhan huoneessa, turvallisissa majoissa ja jalossa levossa."],[32,19,"Mutta rakeet pitää oleman alhaalla metsissä; ja kaupungin pitää alhaalla mataloissa paikoissa oleman.","Mutta rakeet pitää oleman alhaalla metsissä; ja kaupungin pitää alhaalla mataloissa paikoissa oleman."],[32,20,"Hyvin teidän menestyy, jotka kylvätte joka paikassa vetten tykö; ja annatte härkäin ja aasein käydä jaloillansa niiden päällä.","Hyvin teidän menestyy, jotka kylvätte joka paikassa vetten tykö; ja annatte härkäin ja aasein käydä jaloillansa niiden päällä."],[33,1,"Voi sinuas hävittäjä! luuletkos, ettei sinun pidä hävitetyksi tuleman? ja sinuas ylönkatsoja! luuletkos, ettei sinua ylönkatsota? Koska sinä olet täyttänyt hävitykses, niin sinun myös pitää tuleman hävitetyksi; koska sinä olet täyttänyt ylönkatsees, niin sinua pitää jälleen katsottaman ylön.","Voi sinuas hävittäjä! luuletkos, ettei sinun pidä hävitetyksi tuleman? ja sinuas ylönkatsoja! luuletkos, ettei sinua ylönkatsota? Koska sinä olet täyttänyt hävitykses, niin sinun myös pitää tuleman hävitetyksi; koska sinä olet täyttänyt ylönkatsees, niin sinua pitää jälleen katsottaman ylön."],[33,2,"Herra, ole meille armollinen; sillä me odotamme sinua: ole heidän käsivartensa varhain, niin myös meidän autuutemme murheen ajalla.","Herra, ole meille armollinen; sillä me odotamme sinua: ole heidän käsivartensa varhain, niin myös meidän autuutemme murheen ajalla."],[33,3,"Kansat pakenevat sitä suurta pauhinaa; pakanat hajoitetaan, kuin sinä korotetaan.","Kansat pakenevat sitä suurta pauhinaa; pakanat hajoitetaan, kuin sinä korotetaan."],[33,4,"Silloin pitää teidän saalinne korjattaman niinkuin perhonen otetaan, ja niinkuin heinäsirkat karkoitetaan, koska heidän päällensä tullaan.","Silloin pitää teidän saalinne korjattaman niinkuin perhonen otetaan, ja niinkuin heinäsirkat karkoitetaan, koska heidän päällensä tullaan."],[33,5,"Herra on korotettu; sillä hän asuu korkeudessa: hän on täyttänyt Zionin oikeudella ja vanhurskaudella.","Herra on korotettu; sillä hän asuu korkeudessa: hän on täyttänyt Zionin oikeudella ja vanhurskaudella."],[33,6,"Ja sinun ajallas pitää oleman usko ja voima, autuus, tieto, toimi, ja Herran pelko pitää oleman hänen tavaransa.","Ja sinun ajallas pitää oleman usko ja voima, autuus, tieto, toimi, ja Herran pelko pitää oleman hänen tavaransa."],[33,7,"Katso, heidän sanansaattajansa huutavat ulkona: rauhan enkelit itkevät haikiasti.","Katso, heidän sanansaattajansa huutavat ulkona: rauhan enkelit itkevät haikiasti."],[33,8,"Polut ovat autiot, ei käy yksikään enään tiellä; ei hän pidä liittoa, hän hylkää kaupungit, ja ei pidä lukua kansasta.","Polut ovat autiot, ei käy yksikään enään tiellä; ei hän pidä liittoa, hän hylkää kaupungit, ja ei pidä lukua kansasta."],[33,9,"Hän murehtii,ja maa on surkialla muodolla, Libanon on häpiällä hakattu; Saron on niinkuin tasainen keto, Basan ja Karmeli ovat hävitetyt.","Hän murehtii,ja maa on surkialla muodolla, Libanon on häpiällä hakattu; Saron on niinkuin tasainen keto, Basan ja Karmeli ovat hävitetyt."],[33,10,"Nyt minä tahdon nousta, sanoo Herra: nyt minä tahdon itseni korottaa, nyt minä tahdon korkiaksi tulla.","Nyt minä tahdon nousta, sanoo Herra: nyt minä tahdon itseni korottaa, nyt minä tahdon korkiaksi tulla."],[33,11,"Oljista olette te raskaat, korsia te synnytätte; tulen pitää teitä kuluttaman teidän ylpeytenne kanssa;","Oljista olette te raskaat, korsia te synnytätte; tulen pitää teitä kuluttaman teidän ylpeytenne kanssa;"],[33,12,"Sillä kansa pitää poltettaman kalkiksi, niinkuin hakatut orjantappurat tulelle sytytetään.","Sillä kansa pitää poltettaman kalkiksi, niinkuin hakatut orjantappurat tulelle sytytetään."],[33,13,"Niin kuulkaat nyt te, jotka kaukana olette, mitä minä olen tehnyt; ja te, jotka olette läsnä, havaitkaat minun väkevyyteni.","Niin kuulkaat nyt te, jotka kaukana olette, mitä minä olen tehnyt; ja te, jotka olette läsnä, havaitkaat minun väkevyyteni."],[33,14,"Syntiset Zionissa ovat peljästyneet, hämmästys on tullut ulkokullattuin päälle (ja sanovat): kuka on meidän seassamme, joka taitaa asua kuluttavaisen tulen tykönä? kuka on meidän seassamme, joka voi asua ijankaikkisten hiilten tykönä?","Syntiset Zionissa ovat peljästyneet, hämmästys on tullut ulkokullattuin päälle (ja sanovat): kuka on meidän seassamme, joka taitaa asua kuluttavaisen tulen tykönä? kuka on meidän seassamme, joka voi asua ijankaikkisten hiilten tykönä?"],[33,15,"Joka vanhurskaudessa vaeltaa ja puhuu oikeutta; joka vääryyttä ja ahneutta vihaa, ja vetää kätensä pois, ettei hän ota lahjoja; joka tukitsee korvansa kuulemasta veren vikoja, ja peittää silmänsä näkemästä pahaa:","Joka vanhurskaudessa vaeltaa ja puhuu oikeutta; joka vääryyttä ja ahneutta vihaa, ja vetää kätensä pois, ettei hän ota lahjoja; joka tukitsee korvansa kuulemasta veren vikoja, ja peittää silmänsä näkemästä pahaa:"],[33,16,"Hän on korkeudessa asuva, ja kalliot ovat hänen linnansa ja tukeensa: hänelle annetaan hänen leipänsä, eikä hän ole epäilevä vedestänsä.","Hän on korkeudessa asuva, ja kalliot ovat hänen linnansa ja tukeensa: hänelle annetaan hänen leipänsä, eikä hän ole epäilevä vedestänsä."],[33,17,"Sinun silmäs näkevät kuninkaan kunniassansa: ne näkevät maan levitettynä.","Sinun silmäs näkevät kuninkaan kunniassansa: ne näkevät maan levitettynä."],[33,18,"Sinun sydämes ihmettelee, (ja sanoo:) kussa nyt ovat kirjanoppineet? kussa ovat neuvonantajat? kussa tämän maailman tutkia on?","Sinun sydämes ihmettelee, (ja sanoo:) kussa nyt ovat kirjanoppineet? kussa ovat neuvonantajat? kussa tämän maailman tutkia on?"],[33,19,"Etkä myös sinä ole näkevä sitä väkevää kansaa, sitä syväkielistä kansaa, jota ei ymmärretä, ja oudosta kielestä, jota ei taideta ymmärtää.","Etkä myös sinä ole näkevä sitä väkevää kansaa, sitä syväkielistä kansaa, jota ei ymmärretä, ja oudosta kielestä, jota ei taideta ymmärtää."],[33,20,"Katso Zionia, juhlakaupunkiamme; sinun silmäs on näkevä Jerusalemin kauniin asumuksen, majan, jota ei viedä pois, jonka paanuja ei ikänä pidä temmattaman ylös, ja jonka köysiä ei ikänä pidä katkottaman.","Katso Zionia, juhlakaupunkiamme; sinun silmäs on näkevä Jerusalemin kauniin asumuksen, majan, jota ei viedä pois, jonka paanuja ei ikänä pidä temmattaman ylös, ja jonka köysiä ei ikänä pidä katkottaman."],[33,21,"Sillä Herra on siellä oleva väkevä meidän tykönämme, ja siellä pitää oleman leviät virrat ja ojat; ei venheellä taideta mennä sieltä ylitse, eikä laiva taida sinne purjehtia;","Sillä Herra on siellä oleva väkevä meidän tykönämme, ja siellä pitää oleman leviät virrat ja ojat; ei venheellä taideta mennä sieltä ylitse, eikä laiva taida sinne purjehtia;"],[33,22,"Sillä Herra on meidän tuomarimme, Herra on meidän opettajamme; Herra on meidän kuninkaamme, hän auttaa meitä.","Sillä Herra on meidän tuomarimme, Herra on meidän opettajamme; Herra on meidän kuninkaamme, hän auttaa meitä."],[33,23,"Anna heidän pingoittaa köytensä, ei ne pidä kuitenkaan pitämän, niin ei pidä myös heidän hajoittaman lippua pielten päälle; sillä paljo kalliimpi saalis pitää jaettaman, niin että ontuvat myös ryöstävät.","Anna heidän pingoittaa köytensä, ei ne pidä kuitenkaan pitämän, niin ei pidä myös heidän hajoittaman lippua pielten päälle; sillä paljo kalliimpi saalis pitää jaettaman, niin että ontuvat myös ryöstävät."],[33,24,"Ja ei yhdenkään asuvaisen pidä sanoman: minä olen heikko; että kansalla, joka siellä asuu, pitää oleman syntein päästö.","Ja ei yhdenkään asuvaisen pidä sanoman: minä olen heikko; että kansalla, joka siellä asuu, pitää oleman syntein päästö."],[34,1,"Tulkaat, te pakanat, ja kuulkaat, kansat ottakaat vaari; maa kuulkaan ja mitä siinä on, maan piiri ja kaikki, mitä siinä syntyy.","Tulkaat, te pakanat, ja kuulkaat, kansat ottakaat vaari; maa kuulkaan ja mitä siinä on, maan piiri ja kaikki, mitä siinä syntyy."],[34,2,"Sillä Herra on vihainen kaikille pakanoille, ja on närkästynyt kaikille heidän joukoillensa; hän on heitä kiroova, ja antaa teurastaa heitä.","Sillä Herra on vihainen kaikille pakanoille, ja on närkästynyt kaikille heidän joukoillensa; hän on heitä kiroova, ja antaa teurastaa heitä."],[34,3,"Heidän lyötynsä pitää heitettämän pois, niin että pahan hajun pitää tuleman heidän ruumiistansa, ja vuoret kuohuman heidän verestänsä.","Heidän lyötynsä pitää heitettämän pois, niin että pahan hajun pitää tuleman heidän ruumiistansa, ja vuoret kuohuman heidän verestänsä."],[34,4,"Ja koko taivaan joukko pitää mätänemän, ja taivas pitää käärittämän kokon niinkuin kirja; ja kaikki hänen joukkonsa putooman niinkuin lehti putoo viinapuusta, ja niinkuin kuivettunut lehti fikunapuusta.","Ja koko taivaan joukko pitää mätänemän, ja taivas pitää käärittämän kokon niinkuin kirja; ja kaikki hänen joukkonsa putooman niinkuin lehti putoo viinapuusta, ja niinkuin kuivettunut lehti fikunapuusta."],[34,5,"Sillä minun miekkani on taivaissa juovuksissa; ja katso, sen pitää tuleman alas Edomin päälle ja kirotun kansan päälle, sitä rankaisemaan.","Sillä minun miekkani on taivaissa juovuksissa; ja katso, sen pitää tuleman alas Edomin päälle ja kirotun kansan päälle, sitä rankaisemaan."],[34,6,"Herran miekka on verta täynnä, ja on paksu lihavuudesta, karitsain ja kauristen verestä, ja jääräin munaskuiden lihavuudesta; sillä Herralla pitää oleman uhri Botsrassa, ja suuri teurastaminen Edomin maalla.","Herran miekka on verta täynnä, ja on paksu lihavuudesta, karitsain ja kauristen verestä, ja jääräin munaskuiden lihavuudesta; sillä Herralla pitää oleman uhri Botsrassa, ja suuri teurastaminen Edomin maalla."],[34,7,"Yksisarvillisten pitää myös kulkeman alas heidän kanssansa, ja mullit syötettyin härkäin kanssa; sillä heidän maansa pitää juopuman verestä, ja heidän multansa lihavaksi tuleman lihavuudesta.","Yksisarvillisten pitää myös kulkeman alas heidän kanssansa, ja mullit syötettyin härkäin kanssa; sillä heidän maansa pitää juopuman verestä, ja heidän multansa lihavaksi tuleman lihavuudesta."],[34,8,"Sillä ne ovat Herran kostopäivät, ja kostamisen vuodet, Zionin tähden.","Sillä ne ovat Herran kostopäivät, ja kostamisen vuodet, Zionin tähden."],[34,9,"Silloin sen ojat muutetaan pieksi, ja hänen multansa tulikiveksi; ja sen maakunta pitää muuttuman palavaksi pieksi,","Silloin sen ojat muutetaan pieksi, ja hänen multansa tulikiveksi; ja sen maakunta pitää muuttuman palavaksi pieksi,"],[34,10,"Jonka ei pidä päivällä eikä yöllä sammuman, mutta savun pitää siitä ijankaikkisesti nouseman; ja se pitää hävitettämän suvusta sukuun, niin ettei yhdenkään pidä käymän sen lävitse ijankaikkisesta ijankaikkiseen.","Jonka ei pidä päivällä eikä yöllä sammuman, mutta savun pitää siitä ijankaikkisesti nouseman; ja se pitää hävitettämän suvusta sukuun, niin ettei yhdenkään pidä käymän sen lävitse ijankaikkisesta ijankaikkiseen."],[34,11,"Vaan ruovonpäristäjäin ja tarhapöllöin pitää sen omistaman, yökköin ja kaarneitten pitää siellä asuman; sillä hän on vetävä nuoran sen ylitse, niin että sen pitää autioksi tuleman, ja ojennuskiven, niin että sen pitää tyhjäksi tuleman.","Vaan ruovonpäristäjäin ja tarhapöllöin pitää sen omistaman, yökköin ja kaarneitten pitää siellä asuman; sillä hän on vetävä nuoran sen ylitse, niin että sen pitää autioksi tuleman, ja ojennuskiven, niin että sen pitää tyhjäksi tuleman."],[34,12,"Niin että sen herrat pitää kutsuttaman herroiksi ilman maakuntaa: ja kaikki sen pääruhtinaat pitää saaman lopun.","Niin että sen herrat pitää kutsuttaman herroiksi ilman maakuntaa: ja kaikki sen pääruhtinaat pitää saaman lopun."],[34,13,"Ja orjantappurat pitää kasvaman hänen salissansa, nokulaiset ja ohdakkeet sen linnoissa; ja pitää oleman lohikärmeitten asumasia ja yökköin laitumet.","Ja orjantappurat pitää kasvaman hänen salissansa, nokulaiset ja ohdakkeet sen linnoissa; ja pitää oleman lohikärmeitten asumasia ja yökköin laitumet."],[34,14,"Silloin pitää metsän eläimet kohtaaman toinen toistansa, yhden liekkiön pitää toista huutaman; ja kauhiat yölinnut pitää myös siellä asumasiansa saaman ja siellä levon löytämän.","Silloin pitää metsän eläimet kohtaaman toinen toistansa, yhden liekkiön pitää toista huutaman; ja kauhiat yölinnut pitää myös siellä asumasiansa saaman ja siellä levon löytämän."],[34,15,"Hyypiän pitää myös siellä pesänsä pitämän ja muniman, hautoman ja kuoriman sen varjon alla; ja korpihaukat parinensa pitää myös sinne kokoontuman.","Hyypiän pitää myös siellä pesänsä pitämän ja muniman, hautoman ja kuoriman sen varjon alla; ja korpihaukat parinensa pitää myös sinne kokoontuman."],[34,16,"Etsikäät nyt Herran kirjaa ja lukekaat: ei yhtään näistä pidä puuttuman, ei pidä näistä kaivattaman yhtä eli toista; sillä hän on se, joka minun suuni kautta käskee, ja hänen henkensä tuo sen kokoon.","Etsikäät nyt Herran kirjaa ja lukekaat: ei yhtään näistä pidä puuttuman, ei pidä näistä kaivattaman yhtä eli toista; sillä hän on se, joka minun suuni kautta käskee, ja hänen henkensä tuo sen kokoon."],[34,17,"Hän heittää arpaa heistä, ja kädellänsä jakaa mitan heidän seassansa; että heillä pitää siellä oleman perintö ijankaikkisesti, ja suvusta sukuun siellä asuman.","Hän heittää arpaa heistä, ja kädellänsä jakaa mitan heidän seassansa; että heillä pitää siellä oleman perintö ijankaikkisesti, ja suvusta sukuun siellä asuman."],[35,1,"Korvet ja erämaat pitää iloitseman, ja autio sia pitää iloinen oleman, ja niinkuin kukkanen kukoistaman.","Korvet ja erämaat pitää iloitseman, ja autio sia pitää iloinen oleman, ja niinkuin kukkanen kukoistaman."],[35,2,"Hän on kasvain vihoittava ja seisova riemuisna kaikessa ilossa ja riemussa; sillä Libanonin kunnia annetaan hänelle, Karmelin ja Saronin kaunistus; ja he näkevät Herran kunnian ja meidän Jumalan kauneuden.","Hän on kasvain vihoittava ja seisova riemuisna kaikessa ilossa ja riemussa; sillä Libanonin kunnia annetaan hänelle, Karmelin ja Saronin kaunistus; ja he näkevät Herran kunnian ja meidän Jumalan kauneuden."],[35,3,"Vahvistakaat väsyneet kädet, ja tuetkaat nääntyneet polvet.","Vahvistakaat väsyneet kädet, ja tuetkaat nääntyneet polvet."],[35,4,"Sanokaat heikkomielisille: olkaat turvassa ja älkäät peljätkö; katso, teidän Jumalanne tulee kostamaan, Jumala, joka maksaa, hän tulee ja vapahtaa teidät.","Sanokaat heikkomielisille: olkaat turvassa ja älkäät peljätkö; katso, teidän Jumalanne tulee kostamaan, Jumala, joka maksaa, hän tulee ja vapahtaa teidät."],[35,5,"Silloin avataan sokiain silmät, ja kuuroin korvat aukenevat.","Silloin avataan sokiain silmät, ja kuuroin korvat aukenevat."],[35,6,"Silloin rammat hyppäävät niinkuin peurat, ja mykkäin kieli pakahtuu kiitokseen; sillä korvessa pitää vedet vuotaman, ja virrat erämaassa.","Silloin rammat hyppäävät niinkuin peurat, ja mykkäin kieli pakahtuu kiitokseen; sillä korvessa pitää vedet vuotaman, ja virrat erämaassa."],[35,7,"Ja karkia paikka pitää järveksi tuleman, ja kuiva maa kuohuvaksi vedeksi; ja kuopassa, jossa kärme makasi, pitää heinän, ruovon ja kaislan oleman.","Ja karkia paikka pitää järveksi tuleman, ja kuiva maa kuohuvaksi vedeksi; ja kuopassa, jossa kärme makasi, pitää heinän, ruovon ja kaislan oleman."],[35,8,"Siinä myös pitää matka ja tie oleman, joka pitää pyhäksi tieksi kutsuttaman, ettei kenkään saastainen sitä vaeltaisi, ja se pitää heidän edessänsä oleman; jota käydään, niin ettei tyhmäkään eksy.","Siinä myös pitää matka ja tie oleman, joka pitää pyhäksi tieksi kutsuttaman, ettei kenkään saastainen sitä vaeltaisi, ja se pitää heidän edessänsä oleman; jota käydään, niin ettei tyhmäkään eksy."],[35,9,"Ei siellä jalopeura oleman pidä, eikä joku julma peto mene sitä myöten, eli sieltä löydetä; vaan lunastetut sitä vaeltavat.","Ei siellä jalopeura oleman pidä, eikä joku julma peto mene sitä myöten, eli sieltä löydetä; vaan lunastetut sitä vaeltavat."],[35,10,"Herran lunastetut palajavat ja tulevat sen kautta riemulla Zioniin, ja ijankaikkinen ilo on oleva heidän päänsä päällä. Ilon ja riemun he käsittävät, ja murhe ja huokaus pitää pakeneman.","Herran lunastetut palajavat ja tulevat sen kautta riemulla Zioniin, ja ijankaikkinen ilo on oleva heidän päänsä päällä. Ilon ja riemun he käsittävät, ja murhe ja huokaus pitää pakeneman."],[36,1,"Ja tapahtui kuningas Hiskian neljännellätoistakymmenennellä vuodella, että Assyrian kuningas Sanherib nousi kaikkia Juudan vahvoja kaupungeita vastaan, ja voitti ne.","Ja tapahtui kuningas Hiskian neljännellätoistakymmenennellä vuodella, että Assyrian kuningas Sanherib nousi kaikkia Juudan vahvoja kaupungeita vastaan, ja voitti ne."],[36,2,"Ja Assyrian kuningas lähetti Rabsaken Lakiksesta Jerusalemiin, kuningas Hiskian tykö, suurella väellä; ja hän astui edes ylimmäisen vesilammin kanavan päähän tiellä vanuttajan kedolle.","Ja Assyrian kuningas lähetti Rabsaken Lakiksesta Jerusalemiin, kuningas Hiskian tykö, suurella väellä; ja hän astui edes ylimmäisen vesilammin kanavan päähän tiellä vanuttajan kedolle."],[36,3,"Ja hänen tykönsä menivät ulos Eliakim Hilkian poika, huoneenhaltia, ja Sebna kirjoittaja, ja Joah Assaphin poika, kansleri.","Ja hänen tykönsä menivät ulos Eliakim Hilkian poika, huoneenhaltia, ja Sebna kirjoittaja, ja Joah Assaphin poika, kansleri."],[36,4,"Ja Rabsake sanoi heille: sanokaat siis Hiskialle: näin sanoo suuri kuningas, Assyrian kuningas: millainen on se turva, johonkas turvaat?","Ja Rabsake sanoi heille: sanokaat siis Hiskialle: näin sanoo suuri kuningas, Assyrian kuningas: millainen on se turva, johonkas turvaat?"],[36,5,"Minä taidan arvata, ettäs luulet itselläs vielä olevan neuvoa ja voimaa sotiakses; keneen sinä siis luotat, ettäs olet minusta luopunut?","Minä taidan arvata, ettäs luulet itselläs vielä olevan neuvoa ja voimaa sotiakses; keneen sinä siis luotat, ettäs olet minusta luopunut?"],[36,6,"Katso, luotatkos musertuneeseen ruokosauvaan Egyptiin? joka silloin kuin nojataan sen päälle, menee käden lävitse ja pistää sen lävitse: niin on myös Pharao Egyptin kuningas kaikille niille, jotka häneen luottavat.","Katso, luotatkos musertuneeseen ruokosauvaan Egyptiin? joka silloin kuin nojataan sen päälle, menee käden lävitse ja pistää sen lävitse: niin on myös Pharao Egyptin kuningas kaikille niille, jotka häneen luottavat."],[36,7,"Ja jos sinä tahdot sanoa minulle: me luotamme Herraan meidän Jumalaamme: eikö hän ole se, jonka korkeudet ja alttarit Hiskia on heittänyt pois? ja sanonut Juudalle ja Jerusalemille: tämän alttarin edessä pitää teidän rukoileman.","Ja jos sinä tahdot sanoa minulle: me luotamme Herraan meidän Jumalaamme: eikö hän ole se, jonka korkeudet ja alttarit Hiskia on heittänyt pois? ja sanonut Juudalle ja Jerusalemille: tämän alttarin edessä pitää teidän rukoileman."],[36,8,"Lyö siis nyt veto herrani Assyrian kuninkaan kanssa; minä annan sinulle kaksituhatta hevosta, saa nähdä, jos sinä voit toimittaa niitä tyköäs, jotka niillä ajavat.","Lyö siis nyt veto herrani Assyrian kuninkaan kanssa; minä annan sinulle kaksituhatta hevosta, saa nähdä, jos sinä voit toimittaa niitä tyköäs, jotka niillä ajavat."],[36,9,"Kuinka sinä siis tahdot ajaa takaperin yhden sodanpäämiehen, joka minun herrani vähimmistä palvelioista on? Mutta sinä luotat Egyptiin, ratasten ja ratsasmiesten tähden.","Kuinka sinä siis tahdot ajaa takaperin yhden sodanpäämiehen, joka minun herrani vähimmistä palvelioista on? Mutta sinä luotat Egyptiin, ratasten ja ratsasmiesten tähden."],[36,10,"Niin sinä luulet myös, että minä ilman Herraa olen lähtenyt maakuntaan sitä hävittämään? Herra sanoi minulle: mene ylös siihen maakuntaan ja hävitä se.","Niin sinä luulet myös, että minä ilman Herraa olen lähtenyt maakuntaan sitä hävittämään? Herra sanoi minulle: mene ylös siihen maakuntaan ja hävitä se."],[36,11,"Mutta Eliakim, Sebna ja Joah sanoivat Rabsakelle: puhu palveliais kanssa Syrian kielellä, sillä me ymmärrämme kyllä sen, ja älä puhu Juudan kielellä meidän kanssamme, kansan kuullen, joka muurin päällä on.","Mutta Eliakim, Sebna ja Joah sanoivat Rabsakelle: puhu palveliais kanssa Syrian kielellä, sillä me ymmärrämme kyllä sen, ja älä puhu Juudan kielellä meidän kanssamme, kansan kuullen, joka muurin päällä on."],[36,12,"Niin sanoi Rabsake: luuletkos minun herrani lähettäneen minun sinun herras, eli sinun tykös näitä sanoja puhumaan? ja ei paljo enemmin niille miehille, jotka istuvat muurin päällä, teidän kanssanne syömässä omaa lokaansa, ja juomassa omaa vettänsä?","Niin sanoi Rabsake: luuletkos minun herrani lähettäneen minun sinun herras, eli sinun tykös näitä sanoja puhumaan? ja ei paljo enemmin niille miehille, jotka istuvat muurin päällä, teidän kanssanne syömässä omaa lokaansa, ja juomassa omaa vettänsä?"],[36,13,"Ja Rabsake seisoi ja huusi vahvasti Juudan kielellä, ja sanoi: kuulkaat suuren kuninkaan sanoja, Assyrian kuninkaan.","Ja Rabsake seisoi ja huusi vahvasti Juudan kielellä, ja sanoi: kuulkaat suuren kuninkaan sanoja, Assyrian kuninkaan."],[36,14,"Näin sanoo kuningas: älkäät antako Hiskian pettää teitänne; sillä ei hän voi teitä pelastaa.","Näin sanoo kuningas: älkäät antako Hiskian pettää teitänne; sillä ei hän voi teitä pelastaa."],[36,15,"Ja älkäät antako Hiskian saattaa teidät turvaamaan Herraan, sanoen: kyllä Herra auttaa meitä: ei tätä kaupunkia anneta Assyrian kuninkaan käsiin.","Ja älkäät antako Hiskian saattaa teidät turvaamaan Herraan, sanoen: kyllä Herra auttaa meitä: ei tätä kaupunkia anneta Assyrian kuninkaan käsiin."],[36,16,"Älkäät kuulko Hiskiaa; sillä näin sanoo Assyrian kuningas: olkaat minun mieleni nouteeksi, ja tulkaat ulos minun tyköni, niin te syötte itsekukin viinapuustansa ja fikunapuustansa, ja juotte vettä kukin kaivostansa,","Älkäät kuulko Hiskiaa; sillä näin sanoo Assyrian kuningas: olkaat minun mieleni nouteeksi, ja tulkaat ulos minun tyköni, niin te syötte itsekukin viinapuustansa ja fikunapuustansa, ja juotte vettä kukin kaivostansa,"],[36,17,"Siihenasti että minä tulen ja vien teidät senkaltaiseen maahan kuin teidänkin maanne on, maahan, jossa jyviä ja viinaa on, maahan, jossa leipää ja viinamäkiä on.","Siihenasti että minä tulen ja vien teidät senkaltaiseen maahan kuin teidänkin maanne on, maahan, jossa jyviä ja viinaa on, maahan, jossa leipää ja viinamäkiä on."],[36,18,"Älkäät antako Hiskian pettää teitänne, että hän sanoo: Herra pelastaa meitä. Ovatko myös pakanain jumalat jokainen maansa vapahtaneet Assyrian kuninkaan käsistä?","Älkäät antako Hiskian pettää teitänne, että hän sanoo: Herra pelastaa meitä. Ovatko myös pakanain jumalat jokainen maansa vapahtaneet Assyrian kuninkaan käsistä?"],[36,19,"Kussa ovat Hamatin ja Arpadin Jumalat? ja kussa ovat Sepharvaimin jumalat? ovatko he myös vapahtaneet Samarian minun kädestäni?","Kussa ovat Hamatin ja Arpadin Jumalat? ja kussa ovat Sepharvaimin jumalat? ovatko he myös vapahtaneet Samarian minun kädestäni?"],[36,20,"Kuka näistä kaikista maan jumalista on auttanut maansa minun kädestäni? että Herra pelastais Jerusalemin minun kädestäni?","Kuka näistä kaikista maan jumalista on auttanut maansa minun kädestäni? että Herra pelastais Jerusalemin minun kädestäni?"],[36,21,"Mutta he olivat ääneti, ja ei vastanneet häntä mitään; sillä kuningas oli käskenyt ja sanonut: älkäät häntä mitään vastatko.","Mutta he olivat ääneti, ja ei vastanneet häntä mitään; sillä kuningas oli käskenyt ja sanonut: älkäät häntä mitään vastatko."],[36,22,"Niin tulivat Eliakim Hilkian poika, huoneenhaltia, ja Sebna kirjoittaja ja Joah Assaphin poika, kansleri, Hiskian tykö, reväistyillä vaatteilla, ja ilmoittivat hänelle Rabsaken sanat.","Niin tulivat Eliakim Hilkian poika, huoneenhaltia, ja Sebna kirjoittaja ja Joah Assaphin poika, kansleri, Hiskian tykö, reväistyillä vaatteilla, ja ilmoittivat hänelle Rabsaken sanat."],[37,1,"Kuin kuningas Hiskia tämän kuuli, repäisi hän vaatteensa, ja kääri säkin ympärillensä, ja meni Herran huoneeseen,","Kuin kuningas Hiskia tämän kuuli, repäisi hän vaatteensa, ja kääri säkin ympärillensä, ja meni Herran huoneeseen,"],[37,2,"Ja lähetti Eliakimin, huoneenhaltian, ja Sebnan, kirjoittajan, ylimmäisten pappein kanssa, puettuna säkkeihin, propheta Jesaian Amotsin pojan tykö,","Ja lähetti Eliakimin, huoneenhaltian, ja Sebnan, kirjoittajan, ylimmäisten pappein kanssa, puettuna säkkeihin, propheta Jesaian Amotsin pojan tykö,"],[37,3,"Sanomaan hänelle: näin sanoo Hiskia: tämä on vaivan, toran ja häväistyksen päivä; sillä lapset ovat tulleet synnyttämiselle ja ei ole voimaa synnyttää.","Sanomaan hänelle: näin sanoo Hiskia: tämä on vaivan, toran ja häväistyksen päivä; sillä lapset ovat tulleet synnyttämiselle ja ei ole voimaa synnyttää."],[37,4,"Jospa siis Herra sinun Jumalas tahtois kuulla Rabsaken sanat, jonka hänen herransa Assyrian kuningas lähetti häpäisemään elävää Jumalaa, ja pilkkaamaan senkaltaisilla sanoilla kuin Herra sinun Jumalas on kuullut; ja ettäs tahtoisit korottaa rukoukses jääneiden edestä, jotka vielä käsissä ovat.","Jospa siis Herra sinun Jumalas tahtois kuulla Rabsaken sanat, jonka hänen herransa Assyrian kuningas lähetti häpäisemään elävää Jumalaa, ja pilkkaamaan senkaltaisilla sanoilla kuin Herra sinun Jumalas on kuullut; ja ettäs tahtoisit korottaa rukoukses jääneiden edestä, jotka vielä käsissä ovat."],[37,5,"Ja kuningas Hiskian palveliat tulivat Jesaian tykö.","Ja kuningas Hiskian palveliat tulivat Jesaian tykö."],[37,6,"Mutta Jesaia sanoi heille: näin sanokaat teidän herrallenne: Herra sanoo näin: älä pelkää niitä sanoja, joita sinä kuulit, joilla Assyrian kuninkaan palveliat ovat häväisseet minua.","Mutta Jesaia sanoi heille: näin sanokaat teidän herrallenne: Herra sanoo näin: älä pelkää niitä sanoja, joita sinä kuulit, joilla Assyrian kuninkaan palveliat ovat häväisseet minua."],[37,7,"Katso, minä annan hänelle hengen, ja hänen pitää saaman kuulla sanoman, ja palajaman omalle maallensa; ja minä tahdon kaataa hänen miekalla hänen maassansa.","Katso, minä annan hänelle hengen, ja hänen pitää saaman kuulla sanoman, ja palajaman omalle maallensa; ja minä tahdon kaataa hänen miekalla hänen maassansa."],[37,8,"Mutta kuin Rabsake palasi, löysi hän Assyrian kuninkaan sotimasta Libnaa vastaan; sillä hän oli kuullut hänen matkustaneen Lakiksesta.","Mutta kuin Rabsake palasi, löysi hän Assyrian kuninkaan sotimasta Libnaa vastaan; sillä hän oli kuullut hänen matkustaneen Lakiksesta."],[37,9,"Sillä sanoma tuli Tirhakasta Etiopian kuninkaasta, sanoen: hän on lähtenyt sotimaan sinua vastaan. Kuin hän tämän kuuli, lähetti hän sanan Hiskialle, ja käski hänelle sanoa:","Sillä sanoma tuli Tirhakasta Etiopian kuninkaasta, sanoen: hän on lähtenyt sotimaan sinua vastaan. Kuin hän tämän kuuli, lähetti hän sanan Hiskialle, ja käski hänelle sanoa:"],[37,10,"Sanokaat Hiskialle Juudan kuninkaalle näin: älä anna sinun Jumalas pettää sinuas, johon sinä luotat, ja sanot: ei Jerusalem anneta Assyrian kuninkaan käteen.","Sanokaat Hiskialle Juudan kuninkaalle näin: älä anna sinun Jumalas pettää sinuas, johon sinä luotat, ja sanot: ei Jerusalem anneta Assyrian kuninkaan käteen."],[37,11,"Katso, sinä olet kuullut, mitä Assyrian kuninkaat kaikille maakunnille tehneet ovat, ja ne hävittäneet; ja sinä pelastettaisiin?","Katso, sinä olet kuullut, mitä Assyrian kuninkaat kaikille maakunnille tehneet ovat, ja ne hävittäneet; ja sinä pelastettaisiin?"],[37,12,"Ovatko myös pakanain jumalat auttaneet niitä, joita minun isäni ovat hävittäneet, Gosanin ja Haranin, Resephin, ja Edenin lapset, jotka Telassarissa olivat?","Ovatko myös pakanain jumalat auttaneet niitä, joita minun isäni ovat hävittäneet, Gosanin ja Haranin, Resephin, ja Edenin lapset, jotka Telassarissa olivat?"],[37,13,"Kussa on Hamatin kuningas, ja Arphadin kuningas, ja Sepharvaimin, Henan ja Ivvan kaupungin kuningas?","Kussa on Hamatin kuningas, ja Arphadin kuningas, ja Sepharvaimin, Henan ja Ivvan kaupungin kuningas?"],[37,14,"Ja kuin Hiskia oli saanut kirjan sanansaattajalta ja lukenut sen, meni hän ylös Herran huoneeseen, ja Hiskia levitti sen Herran eteen.","Ja kuin Hiskia oli saanut kirjan sanansaattajalta ja lukenut sen, meni hän ylös Herran huoneeseen, ja Hiskia levitti sen Herran eteen."],[37,15,"Ja Hiskia rukoili Herraa ja sanoi:","Ja Hiskia rukoili Herraa ja sanoi:"],[37,16,"Herra Zebaot, Israelin Jumala, joka istut Kerubimin päällä, sinä, joka olet ainoa Jumala kaikkein maakuntain ylitse maan päällä: sinä olet tehnyt taivaan ja maan:","Herra Zebaot, Israelin Jumala, joka istut Kerubimin päällä, sinä, joka olet ainoa Jumala kaikkein maakuntain ylitse maan päällä: sinä olet tehnyt taivaan ja maan:"],[37,17,"Herra, kallista korvas ja kuule, Herra, avaa silmäs ja näe: kuule siis kaikki Sanheribin sanat, joka on lähettänyt häpäisemään elävää Jumalaa.","Herra, kallista korvas ja kuule, Herra, avaa silmäs ja näe: kuule siis kaikki Sanheribin sanat, joka on lähettänyt häpäisemään elävää Jumalaa."],[37,18,"Tosi se on, Herra, että Assyrian kuninkaat ovat autioksi tehneet kaikki valtakunnat heidän maakuntainsa kanssa,","Tosi se on, Herra, että Assyrian kuninkaat ovat autioksi tehneet kaikki valtakunnat heidän maakuntainsa kanssa,"],[37,19,"Ja ovat heittäneet heidän Jumalansa tuleen; sillä ei ne olleet jumalat, vaan ihmisten kätten työt, puut ja kivet, ja ne he ovat hävittäneet.","Ja ovat heittäneet heidän Jumalansa tuleen; sillä ei ne olleet jumalat, vaan ihmisten kätten työt, puut ja kivet, ja ne he ovat hävittäneet."],[37,20,"Mutta nyt, Herra meidän Jumalamme, auta meitä hänen kädestänsä; että kaikki valtakunnat maan päällä ymmärtäisivät sinun ainoan olevan Herran.","Mutta nyt, Herra meidän Jumalamme, auta meitä hänen kädestänsä; että kaikki valtakunnat maan päällä ymmärtäisivät sinun ainoan olevan Herran."],[37,21,"Silloin lähetti Jesaia Amotsin poika Hiskian tykö, ja käski hänelle sanoa: näin sanoo Herra Israelin Jumala: (minä olen kuullut) sen, kuin sinä minua rukoillut olet Assyrian kuninkaan Sanheribin tähden.","Silloin lähetti Jesaia Amotsin poika Hiskian tykö, ja käski hänelle sanoa: näin sanoo Herra Israelin Jumala: (minä olen kuullut) sen, kuin sinä minua rukoillut olet Assyrian kuninkaan Sanheribin tähden."],[37,22,"Niin on tämä se minkä Herra hänestä sanoo: neitsy, Zionin tytär katsoo sinun ylön, ja pilkkaa sinua, ja Jerusalemin tytär vääntelee päätänsä sinun perääs.","Niin on tämä se minkä Herra hänestä sanoo: neitsy, Zionin tytär katsoo sinun ylön, ja pilkkaa sinua, ja Jerusalemin tytär vääntelee päätänsä sinun perääs."],[37,23,"Ketäs olet pilkannut ja häväissyt? ketä vastaan sinä olet korottanut äänes? sinä olet nostanut silmäs Israelin Pyhää vastaan.","Ketäs olet pilkannut ja häväissyt? ketä vastaan sinä olet korottanut äänes? sinä olet nostanut silmäs Israelin Pyhää vastaan."],[37,24,"Sinun palveliais kautta olet sinä häväissyt Herraa, ja sanonut: minun monilla rattaillani olen minä mennyt ylös vuorten kukkuloille Libanonin puolelle, ja tahdon hakata maahan hänen korkiat sedripuunsa ja valitut honkansa, ja mennä kukkulain ylitse hänen ääreensä, hänen ihanan vainionsa metsään.","Sinun palveliais kautta olet sinä häväissyt Herraa, ja sanonut: minun monilla rattaillani olen minä mennyt ylös vuorten kukkuloille Libanonin puolelle, ja tahdon hakata maahan hänen korkiat sedripuunsa ja valitut honkansa, ja mennä kukkulain ylitse hänen ääreensä, hänen ihanan vainionsa metsään."],[37,25,"Minä olen kaivanut ja juonut vettä; ja minun jalkapöytäni on kuivannut kaikki piiritetyt ojat.","Minä olen kaivanut ja juonut vettä; ja minun jalkapöytäni on kuivannut kaikki piiritetyt ojat."],[37,26,"Etkös ole kaukaa kuullut, että minä muinen juuri niin tehnyt ja sen toimittanut olen, ja vielä nyt niin teen, että vahvat kaupungit kukistetaan kiviraunioiksi?","Etkös ole kaukaa kuullut, että minä muinen juuri niin tehnyt ja sen toimittanut olen, ja vielä nyt niin teen, että vahvat kaupungit kukistetaan kiviraunioiksi?"],[37,27,"Ja heidän asujansa voimattomiksi ja epäileväisiksi tulevat, ja häpiään joutuvat; ja tulevat niinkuin kedon ruoho ja viheriäinen ruoho, niinkuin ruoho kattoin päällä, joka ennen kuivettuu kuin tuleentuu.","Ja heidän asujansa voimattomiksi ja epäileväisiksi tulevat, ja häpiään joutuvat; ja tulevat niinkuin kedon ruoho ja viheriäinen ruoho, niinkuin ruoho kattoin päällä, joka ennen kuivettuu kuin tuleentuu."],[37,28,"Mutta minä tiedän sinun asumukses hyvin, sinun uloslähtemises ja sisällekäymises; ja sinun kiukuitsemises minua vastaan.","Mutta minä tiedän sinun asumukses hyvin, sinun uloslähtemises ja sisällekäymises; ja sinun kiukuitsemises minua vastaan."],[37,29,"Ettäs kiukuitset minua vastaan, ja sinun ylpeytes on joutunut minun korvilleni, panen minä renkaani sinun sieraimiis ja suitseni sinun suuhus, ja vien sinun sitä tietä jälleen takaperin, jotas tullutkin olet.","Ettäs kiukuitset minua vastaan, ja sinun ylpeytes on joutunut minun korvilleni, panen minä renkaani sinun sieraimiis ja suitseni sinun suuhus, ja vien sinun sitä tietä jälleen takaperin, jotas tullutkin olet."],[37,30,"Ja tämä pitää oleman sinulle merkiksi: syö tänä vuonna, mitä kasvanut on, toisena vuonna, mitä itsestänsä kasvaa, kolmantena vuonna kylväkäät ja leikatkaat, istuttakaat viinapuita, ja syökäät heidän hedelmäänsä.","Ja tämä pitää oleman sinulle merkiksi: syö tänä vuonna, mitä kasvanut on, toisena vuonna, mitä itsestänsä kasvaa, kolmantena vuonna kylväkäät ja leikatkaat, istuttakaat viinapuita, ja syökäät heidän hedelmäänsä."],[37,31,"Ja pelastettuin ja jääneiden Juudan huoneesta pitää taas alhaalta juurtuman,ja ylhäältä kantaman hedelmän.","Ja pelastettuin ja jääneiden Juudan huoneesta pitää taas alhaalta juurtuman,ja ylhäältä kantaman hedelmän."],[37,32,"Sillä Jerusalemista pitää vielä nyt jääneiden tuleman ulos, ja vapahdetut Zionin vuorelta. Tätä on Herran Zebaotin kiivaus tekevä.","Sillä Jerusalemista pitää vielä nyt jääneiden tuleman ulos, ja vapahdetut Zionin vuorelta. Tätä on Herran Zebaotin kiivaus tekevä."],[37,33,"Sentähden sanoo Herra Assyrian kuninkaasta näin: ei hänen pidä tuleman tähän kaupunkiin, eikä yhtään nuolta sinne ampuman, eli yhtä kilpeä tuoman sen eteen, taikka yhtään vallia tekemän sen ympärille;","Sentähden sanoo Herra Assyrian kuninkaasta näin: ei hänen pidä tuleman tähän kaupunkiin, eikä yhtään nuolta sinne ampuman, eli yhtä kilpeä tuoman sen eteen, taikka yhtään vallia tekemän sen ympärille;"],[37,34,"Vaan pitää palajaman sitä tietä takaperin, jota hän tullut on, ja ei tähän kaupunkiin ensinkään tuleman, sanoo Herra.","Vaan pitää palajaman sitä tietä takaperin, jota hän tullut on, ja ei tähän kaupunkiin ensinkään tuleman, sanoo Herra."],[37,35,"Sillä minä varjelen tämän kaupungin, niin että minä autan häntä, minun tähteni ja minun palveliani Davidin tähden.","Sillä minä varjelen tämän kaupungin, niin että minä autan häntä, minun tähteni ja minun palveliani Davidin tähden."],[37,36,"Silloin läksi Herran enkeli ja löi Assyrian leirissä sata ja viisiyhdeksättäkymmentä tuhatta miestä. Ja kuin he varhain huomeneltain nousivat, katso, ne kaikki olivat kuolleiden ruumiit.","Silloin läksi Herran enkeli ja löi Assyrian leirissä sata ja viisiyhdeksättäkymmentä tuhatta miestä. Ja kuin he varhain huomeneltain nousivat, katso, ne kaikki olivat kuolleiden ruumiit."],[37,37,"Ja Assyrian kuningas Sanherib läksi matkaansa ja palasi, ja asui Ninivessä.","Ja Assyrian kuningas Sanherib läksi matkaansa ja palasi, ja asui Ninivessä."],[37,38,"Ja tapahtui, kuin hän rukoili jumalansa Nisrokin huoneessa, löivät hänen poikansa Adramelek ja Saretser hänen miekalla, ja pakenivat Araratin maalle. Ja hänen poikansa Assarhaddon tuli kuinkaaksi hänen siaansa.","Ja tapahtui, kuin hän rukoili jumalansa Nisrokin huoneessa, löivät hänen poikansa Adramelek ja Saretser hänen miekalla, ja pakenivat Araratin maalle. Ja hänen poikansa Assarhaddon tuli kuinkaaksi hänen siaansa."],[38,1,"Silloin tuli Hiskia kuoleman kieliin. Ja propheta Jesaia Amotsinpoika tuli hänen tykönsä ja sanoi hänelle: näin sanoo Herra: toimita talos, sillä sinun pitää kuoleman ja ei elämän.","Silloin tuli Hiskia kuoleman kieliin. Ja propheta Jesaia Amotsinpoika tuli hänen tykönsä ja sanoi hänelle: näin sanoo Herra: toimita talos, sillä sinun pitää kuoleman ja ei elämän."],[38,2,"Niin käänsi Hiskia kasvonsa seinään päin, ja rukoili Herraa,","Niin käänsi Hiskia kasvonsa seinään päin, ja rukoili Herraa,"],[38,3,"Ja sanoi: ah Herra, muista, kuinka minä sinun edessäs olen totuudessa ja vaalla sydämellä vaeltanut, ja olen tehnyt mitä sinulle on ollut otollinen! ja Hiskia itki katkerasti.","Ja sanoi: ah Herra, muista, kuinka minä sinun edessäs olen totuudessa ja vaalla sydämellä vaeltanut, ja olen tehnyt mitä sinulle on ollut otollinen! ja Hiskia itki katkerasti."],[38,4,"Ja Herran sana tuli Jesaian tykä ja sanoi:","Ja Herran sana tuli Jesaian tykä ja sanoi:"],[38,5,"Mene ja sano Hiskialle: näin sanoo Herra sinun isäs Davidin Jumala: Minä olen kuullut sinun rukoukses ja nähnyt sinun kyynelees; katso, minä lisään vielä nyt sinun päiviis viisitoistakymmentä vuotta,","Mene ja sano Hiskialle: näin sanoo Herra sinun isäs Davidin Jumala: Minä olen kuullut sinun rukoukses ja nähnyt sinun kyynelees; katso, minä lisään vielä nyt sinun päiviis viisitoistakymmentä vuotta,"],[38,6,"Ja minä vapahdan sinun ja tämän kaupungin Assyrian kuninkaan kädestä, ja tahdon hyvin varjella tämän kaupungin.","Ja minä vapahdan sinun ja tämän kaupungin Assyrian kuninkaan kädestä, ja tahdon hyvin varjella tämän kaupungin."],[38,7,"Ja tämä olkoon sinulle merkiksi Herralta, että Herra on tämän tekevä niinkuin hän on sanonut:","Ja tämä olkoon sinulle merkiksi Herralta, että Herra on tämän tekevä niinkuin hän on sanonut:"],[38,8,"Katso, minä tahdon vetää varjon takaperin Ahaksen Säijäristä, kymmenen juonta, kuin hän on juossut ylitse; ja niin aurinko kävi takaperin kymmenen juonta, jotka hän Säijärissä oli juossut ylitse.","Katso, minä tahdon vetää varjon takaperin Ahaksen Säijäristä, kymmenen juonta, kuin hän on juossut ylitse; ja niin aurinko kävi takaperin kymmenen juonta, jotka hän Säijärissä oli juossut ylitse."],[38,9,"Tämä on Hiskian Juudan kuninkaan kirjoitus, kuin hän sairastanut oli, ja taudistansa terveeksi tullut:","Tämä on Hiskian Juudan kuninkaan kirjoitus, kuin hän sairastanut oli, ja taudistansa terveeksi tullut:"],[38,10,"Minä sanoin minun päiviäni lyhennettäissä: nyt minun täytyy mennä haudan ovelle, ja vuoteni lopettaa.","Minä sanoin minun päiviäni lyhennettäissä: nyt minun täytyy mennä haudan ovelle, ja vuoteni lopettaa."],[38,11,"Minä sanoin: en minä enää Herraa näe, Herraa eläväin maassa; en minä enään ihmisiä näe niiden seassa, jotka maailmassa asuvat.","Minä sanoin: en minä enää Herraa näe, Herraa eläväin maassa; en minä enään ihmisiä näe niiden seassa, jotka maailmassa asuvat."],[38,12,"Minun aikani kului ja on minulta otettu pois, niinkuin paimenen maja; ja minä leikkasin poikki elämäni niinkuin kankuri. Hän katkaisi minun niinkuin hienon langan, sinä lopetat minun huomenesta ehtooseen asti.","Minun aikani kului ja on minulta otettu pois, niinkuin paimenen maja; ja minä leikkasin poikki elämäni niinkuin kankuri. Hän katkaisi minun niinkuin hienon langan, sinä lopetat minun huomenesta ehtooseen asti."],[38,13,"Minä asetin itseni niinkuin jalopeura aamuun asti; kuitenkin särki hän kaikki minun luuni; sinä lopetat minun huomenesta ehtooseen asti.","Minä asetin itseni niinkuin jalopeura aamuun asti; kuitenkin särki hän kaikki minun luuni; sinä lopetat minun huomenesta ehtooseen asti."],[38,14,"Minä kuikutin niinkuin kurki ja pääskynen, ja vaikeroitsin ninkuin mettinen; minun silmäni rupesivat puhkeemaan; Herra, minä kärsin tuskaa, huojenna se minulta.","Minä kuikutin niinkuin kurki ja pääskynen, ja vaikeroitsin ninkuin mettinen; minun silmäni rupesivat puhkeemaan; Herra, minä kärsin tuskaa, huojenna se minulta."],[38,15,"Mitä minun pitää puhuman, että hän sen minulle lupasi, ja teki myös sen? Sentähden minä tahdon kaikkena elinaikanani tämän minun sieluni murheen tähden kartella.","Mitä minun pitää puhuman, että hän sen minulle lupasi, ja teki myös sen? Sentähden minä tahdon kaikkena elinaikanani tämän minun sieluni murheen tähden kartella."],[38,16,"Herra, siitä eletään, ja minun henkeni elämä on siinä kokonansa; sillä sinä annoit minun nukkua, ja teit minun taas eläväksi.","Herra, siitä eletään, ja minun henkeni elämä on siinä kokonansa; sillä sinä annoit minun nukkua, ja teit minun taas eläväksi."],[38,17,"Katso, suuri hätä oli minulla turvasta; mutta sinä olet minun sieluni sydämellisesti vapahtanut, ettei se hukkuisi; sillä sinä heitit kaikki minun syntini selkäs taa.","Katso, suuri hätä oli minulla turvasta; mutta sinä olet minun sieluni sydämellisesti vapahtanut, ettei se hukkuisi; sillä sinä heitit kaikki minun syntini selkäs taa."],[38,18,"Sillä ei helvetti sinua kiitä, eikä kuolema sinua ylistä; ei myös ne sinun totuuttas odota, jotka alas kuoppaan menevät.","Sillä ei helvetti sinua kiitä, eikä kuolema sinua ylistä; ei myös ne sinun totuuttas odota, jotka alas kuoppaan menevät."],[38,19,"Vaan ainoastansa elävät kiittävät sinua, niinkuin minäkin nyt teen; isän pitää lapsillensa sinun totuuttas ilmoittaman.","Vaan ainoastansa elävät kiittävät sinua, niinkuin minäkin nyt teen; isän pitää lapsillensa sinun totuuttas ilmoittaman."],[38,20,"Herra, auta minua; niin me veisaamme minun veisuni, niinkauvan kuin me elämme, Herran huoneessa.","Herra, auta minua; niin me veisaamme minun veisuni, niinkauvan kuin me elämme, Herran huoneessa."],[38,21,"Ja Jesaia käski ottaa voidetta fikunista ja panna paisuman päälle, että se tulis terveeksi.","Ja Jesaia käski ottaa voidetta fikunista ja panna paisuman päälle, että se tulis terveeksi."],[38,22,"Mutta Hiskia sanoi: mikä merkki on, että minun pitää menemän ylös Herran huoneeseen?","Mutta Hiskia sanoi: mikä merkki on, että minun pitää menemän ylös Herran huoneeseen?"],[39,1,"Silloin lähetti Merodak Baladan, Baladanin poika, Babelin kuningas kirjoituksen ja lahjoja Hiskialle; sillä hän oli kuullut hänen sairastaneen, ja tulleen terveeksi jälleen.","Silloin lähetti Merodak Baladan, Baladanin poika, Babelin kuningas kirjoituksen ja lahjoja Hiskialle; sillä hän oli kuullut hänen sairastaneen, ja tulleen terveeksi jälleen."],[39,2,"Niin Hiskia tuli iloiseksi heidän kanssansa, ja näytti heille tavarahuoneensa, hopian ja kullan, yrtit, kalliit voiteet, ja kaikki asehuoneensa, ja kaiken tavaran, mikä hänellä oli; ei ollut mitään, jota ei Hiskia heille näyttänyt, hänen huoneessansa ja hänen takanansa.","Niin Hiskia tuli iloiseksi heidän kanssansa, ja näytti heille tavarahuoneensa, hopian ja kullan, yrtit, kalliit voiteet, ja kaikki asehuoneensa, ja kaiken tavaran, mikä hänellä oli; ei ollut mitään, jota ei Hiskia heille näyttänyt, hänen huoneessansa ja hänen takanansa."],[39,3,"Niin tuli propheta Jesaia kuningas Hiskian tykö, ja sanoi hänelle: mitä nämät miehet ovat sanoneet, ja kusta he sinun tykös ovat tulleet? Hiskia sanoi: he ovat tulleet kaukaiselta maalta minun tyköni, aina Babelista.","Niin tuli propheta Jesaia kuningas Hiskian tykö, ja sanoi hänelle: mitä nämät miehet ovat sanoneet, ja kusta he sinun tykös ovat tulleet? Hiskia sanoi: he ovat tulleet kaukaiselta maalta minun tyköni, aina Babelista."],[39,4,"Mutta hän sanoi: mitä he ovat nähneet sinun huoneessas? Hiskia sanoi: kaikki mitä minun huoneessani on, ovat he nähneet, ja ei ole mitään minun tavaroissani, jota en minä ole näyttänyt heille.","Mutta hän sanoi: mitä he ovat nähneet sinun huoneessas? Hiskia sanoi: kaikki mitä minun huoneessani on, ovat he nähneet, ja ei ole mitään minun tavaroissani, jota en minä ole näyttänyt heille."],[39,5,"Ja Jesaia sanoi Hiskialle: kuule Herra Zebaotin sana.","Ja Jesaia sanoi Hiskialle: kuule Herra Zebaotin sana."],[39,6,"Katso, se aika tulee, että kaikki, mitä sinun huoneessas on, ja mitä sinun isäs koonneet ovat tähän päivään asti, pitää vietämän pois Babeliin; niin ettei mitään pidä jäämän, sanoo Herra.","Katso, se aika tulee, että kaikki, mitä sinun huoneessas on, ja mitä sinun isäs koonneet ovat tähän päivään asti, pitää vietämän pois Babeliin; niin ettei mitään pidä jäämän, sanoo Herra."],[39,7,"Heidän pitää myös ottaman sinun lapses, jotka sinusta tulevat, ja sinulle synnytetään; ja heidän pitää oleman kamaripalvelioina Babelin kuninkaan huoneessa.","Heidän pitää myös ottaman sinun lapses, jotka sinusta tulevat, ja sinulle synnytetään; ja heidän pitää oleman kamaripalvelioina Babelin kuninkaan huoneessa."],[39,8,"Ja Hiskia sanoi Jesaialle: Herran sana on hyvä, jonka sinä puhunut olet. Ja sanoi: olkoon kuitenkin rauha ja uskollisuus minun päivinäni.","Ja Hiskia sanoi Jesaialle: Herran sana on hyvä, jonka sinä puhunut olet. Ja sanoi: olkoon kuitenkin rauha ja uskollisuus minun päivinäni."],[40,1,"Lohduttakaat, lohduttakaat minun kansaani, sanoo teidän Jumalanne.","Lohduttakaat, lohduttakaat minun kansaani, sanoo teidän Jumalanne."],[40,2,"Puhukaat suloisesti Jerusalemin kanssa, ja saarnatkaat hänelle, että hänen sotimisensa on täytetty; sillä hänen rikoksensa on annettu anteeksi, että hän on saanut kaksinkertaisesti Herran kädestä, kaikkein synteinsä tähden.","Puhukaat suloisesti Jerusalemin kanssa, ja saarnatkaat hänelle, että hänen sotimisensa on täytetty; sillä hänen rikoksensa on annettu anteeksi, että hän on saanut kaksinkertaisesti Herran kädestä, kaikkein synteinsä tähden."],[40,3,"Huutavaisen ääni on korvessa: valmistakaat Herran tietä, tehkäät tasaiset polut erämaassa meidän Jumalallemme.","Huutavaisen ääni on korvessa: valmistakaat Herran tietä, tehkäät tasaiset polut erämaassa meidän Jumalallemme."],[40,4,"Kaikki laaksot pitää korotettaman, ja kaikki vuoret ja kukkulat pitää alennettaman, ja mitä on tasoittamatta, pitää tasattaman ja koliat silitettämän.","Kaikki laaksot pitää korotettaman, ja kaikki vuoret ja kukkulat pitää alennettaman, ja mitä on tasoittamatta, pitää tasattaman ja koliat silitettämän."],[40,5,"Sillä Herran kunnia ilmoitetaan: ja kaikki liha on ynnä näkevä Herran suun puhuvan.","Sillä Herran kunnia ilmoitetaan: ja kaikki liha on ynnä näkevä Herran suun puhuvan."],[40,6,"Ääni sanoo: saarnaa. Ja hän sanoi: Mitä minun pitää saarnaaman? Kaikki liha on ruoho, ja kaikki hänen hyvyytensä niinkuin kedon kukkanen.","Ääni sanoo: saarnaa. Ja hän sanoi: Mitä minun pitää saarnaaman? Kaikki liha on ruoho, ja kaikki hänen hyvyytensä niinkuin kedon kukkanen."],[40,7,"Ruoho kuivuu pois ja kukkanen lakastuu, sillä Herra puhalsi siihen. Kansa tosin on ruoho.","Ruoho kuivuu pois ja kukkanen lakastuu, sillä Herra puhalsi siihen. Kansa tosin on ruoho."],[40,8,"Ruoho kuivettuu ja kukkanen lakastuu; mutta meidän Jumalamme sana pysyy ijankaikkisesti.","Ruoho kuivettuu ja kukkanen lakastuu; mutta meidän Jumalamme sana pysyy ijankaikkisesti."],[40,9,"Zion, sinä suloinen saarnaaja, astu korkialle vuorelle; Jerusalem, sinä suloinen saarnaaja, korota äänes väkevästi: korota ja älä pelkää; sano Juudan kaupungeille: katso, teidän Jumalanne.","Zion, sinä suloinen saarnaaja, astu korkialle vuorelle; Jerusalem, sinä suloinen saarnaaja, korota äänes väkevästi: korota ja älä pelkää; sano Juudan kaupungeille: katso, teidän Jumalanne."],[40,10,"Sillä katso, Herra, Herra tulee väkevyydessä, ja hänen käsivartensa on hallitseva: katso, hänen palkkansa on hänen myötänsä, ja hänen tekonsa on hänen edessänsä,","Sillä katso, Herra, Herra tulee väkevyydessä, ja hänen käsivartensa on hallitseva: katso, hänen palkkansa on hänen myötänsä, ja hänen tekonsa on hänen edessänsä,"],[40,11,"Niinkuin paimen on hän kaitseva laumaansa, kokoo karitsat syliinsä ja kantaa helmassansa: tiineet lampaat hän johdattaa.","Niinkuin paimen on hän kaitseva laumaansa, kokoo karitsat syliinsä ja kantaa helmassansa: tiineet lampaat hän johdattaa."],[40,12,"Kuka on vedet pivollansa mitannut, ja käsittänyt vaaksallansa taivaat? ja maan tomun sulkenut kolmannekseen? ja vuoret puntarilla punninnut, ja kukkulat vaalla?","Kuka on vedet pivollansa mitannut, ja käsittänyt vaaksallansa taivaat? ja maan tomun sulkenut kolmannekseen? ja vuoret puntarilla punninnut, ja kukkulat vaalla?"],[40,13,"Kuka on Herran henkeä opettanut? eli kuka on hänen neuvonantajansa ollut?","Kuka on Herran henkeä opettanut? eli kuka on hänen neuvonantajansa ollut?"],[40,14,"Keneltä hän neuvoa kysyy, joka hänelle ymmärrystä antais, ja opettais hänelle oikeuden tien, ja antais hänelle tiedon, ja opettais hänelle ymmärryksen tien?","Keneltä hän neuvoa kysyy, joka hänelle ymmärrystä antais, ja opettais hänelle oikeuden tien, ja antais hänelle tiedon, ja opettais hänelle ymmärryksen tien?"],[40,15,"Katso, pakanat ovat niinkuin pisara, joka jää ämpäriin, ja niinkuin rahtu, joka jää vaakaan; katso, luodot hän kuljettaa niinkuin piskuisen tomun.","Katso, pakanat ovat niinkuin pisara, joka jää ämpäriin, ja niinkuin rahtu, joka jää vaakaan; katso, luodot hän kuljettaa niinkuin piskuisen tomun."],[40,16,"Libanon olis sangen vähä tuleksi; ja hänen eläimensä ylen harvat polttouhriksi.","Libanon olis sangen vähä tuleksi; ja hänen eläimensä ylen harvat polttouhriksi."],[40,17,"Kaikki pakanat ovat niinkuin ei mitään hänen edessänsä, ja juuri tyhjän ja turhan edestä pidetään häneltä.","Kaikki pakanat ovat niinkuin ei mitään hänen edessänsä, ja juuri tyhjän ja turhan edestä pidetään häneltä."],[40,18,"Keneenkä te tahdotte verrata Jumalaa? eli mitä kuvaa te tahdotte hänelle tehdä?","Keneenkä te tahdotte verrata Jumalaa? eli mitä kuvaa te tahdotte hänelle tehdä?"],[40,19,"Seppä valaa kuvan, ja hopiaseppä kultaa sen ja tekee siihen hopiakäädyt.","Seppä valaa kuvan, ja hopiaseppä kultaa sen ja tekee siihen hopiakäädyt."],[40,20,"Niin myös jolla vähä vara on tehdä ylennysuhria, hän valitsee puun, joka ei mätäne, ja etsii siihen taitavan tekiän valmistamaan kuvaa, joka on kestäväinen.","Niin myös jolla vähä vara on tehdä ylennysuhria, hän valitsee puun, joka ei mätäne, ja etsii siihen taitavan tekiän valmistamaan kuvaa, joka on kestäväinen."],[40,21,"Ettekö te tiedä? ettekö te kuule? eikö tämä ole ennen teille ilmoitettu? ettekö te ole sitä ymmärtäneet maan alusta?","Ettekö te tiedä? ettekö te kuule? eikö tämä ole ennen teille ilmoitettu? ettekö te ole sitä ymmärtäneet maan alusta?"],[40,22,"Hän istuu maan piirin päällä, ja ne, jotka sen päällä asuvat, ovat niinkuin heinäsirkat; joka taivaan venyttää niinkuin ohukaisen nahan, ja levittää sen niinkuin teltan, asuttavaksi.","Hän istuu maan piirin päällä, ja ne, jotka sen päällä asuvat, ovat niinkuin heinäsirkat; joka taivaan venyttää niinkuin ohukaisen nahan, ja levittää sen niinkuin teltan, asuttavaksi."],[40,23,"Joka pääruhtinaat tyhjäksi tekee, ja hävittää tuomarit maan päältä,","Joka pääruhtinaat tyhjäksi tekee, ja hävittää tuomarit maan päältä,"],[40,24,"Niinkuin ei he olisi istutetut, eikä kylvetyt, eli heidän kantonsa juurtuneet maahan; niin että he kuivettuvat, kuin tuuli heidän päällensä puhaltaa, ja tuulispää vie heidät matkaansa niinkuin akanat.","Niinkuin ei he olisi istutetut, eikä kylvetyt, eli heidän kantonsa juurtuneet maahan; niin että he kuivettuvat, kuin tuuli heidän päällensä puhaltaa, ja tuulispää vie heidät matkaansa niinkuin akanat."],[40,25,"Keneenkä te siis minun verrata tahdotte, jonka kaltainen minä olisin? sanoo Pyhä.","Keneenkä te siis minun verrata tahdotte, jonka kaltainen minä olisin? sanoo Pyhä."],[40,26,"Nostakaat silmänne korkeuteen ja katsokaat, kuka ne kappaleet luonut on, ja vie edes heidän joukkonsa luvulla? kutsuu ne kaikki nimeltänsä? Hänen varansa ja väkevä voimansa on niin suuri, ettei häneltä mitään puutu.","Nostakaat silmänne korkeuteen ja katsokaat, kuka ne kappaleet luonut on, ja vie edes heidän joukkonsa luvulla? kutsuu ne kaikki nimeltänsä? Hänen varansa ja väkevä voimansa on niin suuri, ettei häneltä mitään puutu."],[40,27,"Miksis siis sinä Jakob sanot, ja sinä Israel puhut: minun tieni on Herralta salattu, ja minun oikeuteni käy minun Jumalani ohitse?","Miksis siis sinä Jakob sanot, ja sinä Israel puhut: minun tieni on Herralta salattu, ja minun oikeuteni käy minun Jumalani ohitse?"],[40,28,"Etkös tiedä? etkös ole kuullut? Herra ijankaikkinen Jumala, joka maan ääret on luonut, ei väsy eikä näänny; hänen ymmärryksensä on tutkimatoin.","Etkös tiedä? etkös ole kuullut? Herra ijankaikkinen Jumala, joka maan ääret on luonut, ei väsy eikä näänny; hänen ymmärryksensä on tutkimatoin."],[40,29,"Hän antaa väsyneille voiman, ja väettömille kyllä väkeä.","Hän antaa väsyneille voiman, ja väettömille kyllä väkeä."],[40,30,"Nuorukaiset väsyvät ja nääntyvät, ja nuoret miehet peräti lankeevat;","Nuorukaiset väsyvät ja nääntyvät, ja nuoret miehet peräti lankeevat;"],[40,31,"Mutta jotka Herraa odottavat, ne saavat uuden voiman, niin että he menevät siivillä ylös kuin kotkat; että he juoksevat ja ei näänny, he vaeltavat ja ei väsy.","Mutta jotka Herraa odottavat, ne saavat uuden voiman, niin että he menevät siivillä ylös kuin kotkat; että he juoksevat ja ei näänny, he vaeltavat ja ei väsy."],[41,1,"Luodot olkaan ääneti minun edessäni, ja kansa vahvistukoon; astukaan edes ja puhukaan: käykäämme oikeudelle toinen toisemme kanssa.","Luodot olkaan ääneti minun edessäni, ja kansa vahvistukoon; astukaan edes ja puhukaan: käykäämme oikeudelle toinen toisemme kanssa."],[41,2,"Kuka on herättänyt vanhurskaan idästä? kuka hänen kutsui käymään? kuka antoi pakanat ja kuninkaat hänen eteensä, että hän tuli voimalliseksi heidän päällensä, ja antoi heidän hänen miekallensa niinkuin tomun, ja hänen joutsellensa niinkuin akanat, jotka hajoitetaan?","Kuka on herättänyt vanhurskaan idästä? kuka hänen kutsui käymään? kuka antoi pakanat ja kuninkaat hänen eteensä, että hän tuli voimalliseksi heidän päällensä, ja antoi heidän hänen miekallensa niinkuin tomun, ja hänen joutsellensa niinkuin akanat, jotka hajoitetaan?"],[41,3,"Ja hän ajoi heitä takaa, ja pääsi rauhassa sitä tietä, jota ei hänen jalkansa ennen käyneet.","Ja hän ajoi heitä takaa, ja pääsi rauhassa sitä tietä, jota ei hänen jalkansa ennen käyneet."],[41,4,"Kuka tekee ja toimittaa sen, ja kutsuu sukukunnat alusta? Minä Herra olen ensimäinen, niin myös viimeinen, itse minä.","Kuka tekee ja toimittaa sen, ja kutsuu sukukunnat alusta? Minä Herra olen ensimäinen, niin myös viimeinen, itse minä."],[41,5,"Kuin luodot näkivät sen, pelkäsivät he, ja maan ääret peljästyivät; he lähestyivät ja astuivat edes,","Kuin luodot näkivät sen, pelkäsivät he, ja maan ääret peljästyivät; he lähestyivät ja astuivat edes,"],[41,6,"Auttivat toinen toistansa, ja sanoivat lähimmäisellensä: ole hyvässä turvassa.","Auttivat toinen toistansa, ja sanoivat lähimmäisellensä: ole hyvässä turvassa."],[41,7,"Puuseppä rohkaisi hopiaseppää, joka tasoitti vasaralla alasimen päällä, ja sanoi: kyllä se pysyy, ja he vahvistivat sen nauloilla, ettei se sinne tänne huljuisi.","Puuseppä rohkaisi hopiaseppää, joka tasoitti vasaralla alasimen päällä, ja sanoi: kyllä se pysyy, ja he vahvistivat sen nauloilla, ettei se sinne tänne huljuisi."],[41,8,"Mutta sinä Israel, minun palveliani Jakob, jonka minä olen valinnut, sinä Abrahamin minun ystäväni siemen.","Mutta sinä Israel, minun palveliani Jakob, jonka minä olen valinnut, sinä Abrahamin minun ystäväni siemen."],[41,9,"Jonka minä olen ottanut maailman äärestä, ja olen sinun kutsunut hänen voimallisistansa, ja sanoin sinulle: minun palveliani sinä olet; sillä minä valitsin sinun, ja en hylkää sinua;","Jonka minä olen ottanut maailman äärestä, ja olen sinun kutsunut hänen voimallisistansa, ja sanoin sinulle: minun palveliani sinä olet; sillä minä valitsin sinun, ja en hylkää sinua;"],[41,10,"Älä pelkää, sillä minä olen sinun kanssas; älä harhaile; sillä minä olen sinun Jumalas: minä vahvistan sinun, minä autan myös sinua, ja tuen myös sinun vanhurskauteni oikialla kädellä.","Älä pelkää, sillä minä olen sinun kanssas; älä harhaile; sillä minä olen sinun Jumalas: minä vahvistan sinun, minä autan myös sinua, ja tuen myös sinun vanhurskauteni oikialla kädellä."],[41,11,"Katso, kaikki ne jotka ovat ankarat sinua vastaan, pitää häpiään tuleman ja häpeämän; ja ne miehet, jotka sinun kanssas riitelevät, pitää joutuman niinkuin tyhjäksi ja hukkuman;","Katso, kaikki ne jotka ovat ankarat sinua vastaan, pitää häpiään tuleman ja häpeämän; ja ne miehet, jotka sinun kanssas riitelevät, pitää joutuman niinkuin tyhjäksi ja hukkuman;"],[41,12,"Niin että sinun pitää kysymän heitä, ja ei löytämän. Ne miehet, jotka sinun kanssas riitelevät, pitää tuleman niinkuin ei mitään, ja ne miehet, jotka sotivat sinua vastaan, pitää saaman loppunsa.","Niin että sinun pitää kysymän heitä, ja ei löytämän. Ne miehet, jotka sinun kanssas riitelevät, pitää tuleman niinkuin ei mitään, ja ne miehet, jotka sotivat sinua vastaan, pitää saaman loppunsa."],[41,13,"Sillä minä olen Herra sinun Jumalas, joka tartun sinun oikiaan kätees ja sanon sinulle: älä pelkää, minä autan sinua.","Sillä minä olen Herra sinun Jumalas, joka tartun sinun oikiaan kätees ja sanon sinulle: älä pelkää, minä autan sinua."],[41,14,"Älä siis pelkää, sinä mato Jakob, te vähä joukko Israel, minä autan sinua, sanoo Herra ja sinun vapahtajas, Israelin Pyhä.","Älä siis pelkää, sinä mato Jakob, te vähä joukko Israel, minä autan sinua, sanoo Herra ja sinun vapahtajas, Israelin Pyhä."],[41,15,"Katso, minä olen sinun tehnyt uudeksi teräväksi rautaiseksi varstaksi, että sinä tapat vuoria, ja muserrat ne, ja teet kukkulat niinkuin akanaksi.","Katso, minä olen sinun tehnyt uudeksi teräväksi rautaiseksi varstaksi, että sinä tapat vuoria, ja muserrat ne, ja teet kukkulat niinkuin akanaksi."],[41,16,"Sinun pitää hajoittaman heitä, niin että tuuli vie heidät pois, ja tuulispää viskoo heidät sinne ja tänne; mutta sinä iloitset Herrassa, ja kerskaat Israelin Pyhästä.","Sinun pitää hajoittaman heitä, niin että tuuli vie heidät pois, ja tuulispää viskoo heidät sinne ja tänne; mutta sinä iloitset Herrassa, ja kerskaat Israelin Pyhästä."],[41,17,"Raadolliset ja köyhät etsivät vettä; ja ei ole; heidän kielensä kuivettuu janosta; mutta minä, Herra, tahdon heitä kuulla, minä Israelin Jumala en tahdo heitä hyljätä.","Raadolliset ja köyhät etsivät vettä; ja ei ole; heidän kielensä kuivettuu janosta; mutta minä, Herra, tahdon heitä kuulla, minä Israelin Jumala en tahdo heitä hyljätä."],[41,18,"Vaan minä avaan virrat korkeilla paikoilla, ja lähteet keskellä ketoja; minä teen korven vesilammikoksi ja kuivan maan luontolähteiksi.","Vaan minä avaan virrat korkeilla paikoilla, ja lähteet keskellä ketoja; minä teen korven vesilammikoksi ja kuivan maan luontolähteiksi."],[41,19,"Minä annan korvessa sedripuita, sittimipuita, myrttejä, ja öljypuita; minä annan kedolla honkia, böökejä ja buksipuita ynnä,","Minä annan korvessa sedripuita, sittimipuita, myrttejä, ja öljypuita; minä annan kedolla honkia, böökejä ja buksipuita ynnä,"],[41,20,"Nähtää, tuta ja ymmärtää ja huomattaa, että Herran käsi on nämät tehnyt, ja Israelin Pyhä on nämät luonut.","Nähtää, tuta ja ymmärtää ja huomattaa, että Herran käsi on nämät tehnyt, ja Israelin Pyhä on nämät luonut."],[41,21,"Antakaat siis teidän asianne tulla edes, sanoo Herra; antakaat teidän väkevänne tulla edes, sanoo Jakobin kuningas.","Antakaat siis teidän asianne tulla edes, sanoo Herra; antakaat teidän väkevänne tulla edes, sanoo Jakobin kuningas."],[41,22,"Anna heidän astua edes ja ilmoittaa meille tulevaisia asioita, ilmoittakaat ja ennustakaat jotain edellä, ja me tahdomme ottaa sydämellemme vaarin ja ajatella, kuinka tästedes tuleva on, eli antakaat meidän kuulla, mitä tuleman pitää.","Anna heidän astua edes ja ilmoittaa meille tulevaisia asioita, ilmoittakaat ja ennustakaat jotain edellä, ja me tahdomme ottaa sydämellemme vaarin ja ajatella, kuinka tästedes tuleva on, eli antakaat meidän kuulla, mitä tuleman pitää."],[41,23,"Ilmoittakaat, mitä tästedes on tuleva, niin me ymmärrämme teidän olevan jumalat; tehkäät hyvää eli pahaa, niin me puhumme siitä ja katselemme ynnä.","Ilmoittakaat, mitä tästedes on tuleva, niin me ymmärrämme teidän olevan jumalat; tehkäät hyvää eli pahaa, niin me puhumme siitä ja katselemme ynnä."],[41,24,"Katso, te olette tyhjästä, ja teidän tekonne on myös tyhjästä; ja joka teitä valitsee, se on kauhistus.","Katso, te olette tyhjästä, ja teidän tekonne on myös tyhjästä; ja joka teitä valitsee, se on kauhistus."],[41,25,"Mutta minä herätän yhden pohjasta, ja hän tulee; idästä hän on heille saarnaava minun nimeeni; ja hän käy voimallisten päällä niinkuin saven, ja sotkuu savea niinkuin savenvalaja.","Mutta minä herätän yhden pohjasta, ja hän tulee; idästä hän on heille saarnaava minun nimeeni; ja hän käy voimallisten päällä niinkuin saven, ja sotkuu savea niinkuin savenvalaja."],[41,26,"Kuka taitaa jotain ilmoittaa alusta, että me ymmärtäisimme? eli ennustaa edellä, että me sanoa mahtaisimme: sinä olet vanhurskas. Mutta ei tässä ole yhtään ilmoittajaa, ei yhtään joka jotain antaa kuulla, ei yhtään joka teidän sanojanne kuulee.","Kuka taitaa jotain ilmoittaa alusta, että me ymmärtäisimme? eli ennustaa edellä, että me sanoa mahtaisimme: sinä olet vanhurskas. Mutta ei tässä ole yhtään ilmoittajaa, ei yhtään joka jotain antaa kuulla, ei yhtään joka teidän sanojanne kuulee."],[41,27,"Minä olen ensimäinen, joka sanon Zionille; katso, siellä on se; ja tahdon antaa Jerusalemille suloisen saarnaajan.","Minä olen ensimäinen, joka sanon Zionille; katso, siellä on se; ja tahdon antaa Jerusalemille suloisen saarnaajan."],[41,28,"Mutta minä katselen, ei siellä ole ketään, ja katson heidän keskellänsä, mutta ei siellä ole yhtään neuvonantajaa; minä kysyn heiltä, ja heidän pitäis vastaaman minua.","Mutta minä katselen, ei siellä ole ketään, ja katson heidän keskellänsä, mutta ei siellä ole yhtään neuvonantajaa; minä kysyn heiltä, ja heidän pitäis vastaaman minua."],[41,29,"Katso, se on kaikki vääryys, heidän työnsä on turha; heidän epäjumalansa ovat tuuli ja tyhjyys.","Katso, se on kaikki vääryys, heidän työnsä on turha; heidän epäjumalansa ovat tuuli ja tyhjyys."],[42,1,"Katso, minun palveliani, minä häntä tuen, ja minun valittuni, jossa minun sieluni mielistyi. Minä olen hänelle minun Henkeni antanut, hänen pitää oikeuden saattaman pakanoille.","Katso, minun palveliani, minä häntä tuen, ja minun valittuni, jossa minun sieluni mielistyi. Minä olen hänelle minun Henkeni antanut, hänen pitää oikeuden saattaman pakanoille."],[42,2,"Ei hän huuda, eikä riitele, ja hänen ääntänsä ei kuulla kaduilla.","Ei hän huuda, eikä riitele, ja hänen ääntänsä ei kuulla kaduilla."],[42,3,"Särjettyä ruokoa ei hänen pidä murentaman, ja suitsevaista kynttilän sydäntä ei pidä hänen sammuttaman; hän saattaa oikeuden totuudella.","Särjettyä ruokoa ei hänen pidä murentaman, ja suitsevaista kynttilän sydäntä ei pidä hänen sammuttaman; hän saattaa oikeuden totuudella."],[42,4,"Ei hänen pidä nurjan eikä hirmuisen oleman, sillä hänen pitää oikeuden maan päälle säätämän; ja luodotkin pitää hänen lakiansa odottaman.","Ei hänen pidä nurjan eikä hirmuisen oleman, sillä hänen pitää oikeuden maan päälle säätämän; ja luodotkin pitää hänen lakiansa odottaman."],[42,5,"Näitä sanoo Herra Jumala, joka luo taivaat, ja venyttää ne, joka levittää maan, ja hänen kasvonsa; joka kansalle, joka sen päällä on, hengittämisen antaa, ja hengen niille, jotka siinä käyvät.","Näitä sanoo Herra Jumala, joka luo taivaat, ja venyttää ne, joka levittää maan, ja hänen kasvonsa; joka kansalle, joka sen päällä on, hengittämisen antaa, ja hengen niille, jotka siinä käyvät."],[42,6,"Minä Herra olen sinun kutsunut vanhurskaudessa, ja rupesin sinun kätees, ja varjelin sinua, ja olen sinun antanut kansoille liitoksi ja pakanoille valkeudeksi.","Minä Herra olen sinun kutsunut vanhurskaudessa, ja rupesin sinun kätees, ja varjelin sinua, ja olen sinun antanut kansoille liitoksi ja pakanoille valkeudeksi."],[42,7,"Avaamaan sokiain silmiä, ja vankeja pelastamaan vankeudesta, ja tornista niitä, jotka pimeydessä istuvat.","Avaamaan sokiain silmiä, ja vankeja pelastamaan vankeudesta, ja tornista niitä, jotka pimeydessä istuvat."],[42,8,"Minä Herra, se on minun nimeni: en minä anna toiselle kunniaani, enkä ylistystäni epäjumalille.","Minä Herra, se on minun nimeni: en minä anna toiselle kunniaani, enkä ylistystäni epäjumalille."],[42,9,"Katso, entiset ovat tapahtuneet, ja vastuutista minä ilmoitan; ennenkuin se tapahtuu, annan minä teidän sen kuulla.","Katso, entiset ovat tapahtuneet, ja vastuutista minä ilmoitan; ennenkuin se tapahtuu, annan minä teidän sen kuulla."],[42,10,"Veisatkaat Herralle uutta veisua; hänen ylistyksensä on maailman äärestä, jotka meressä vaellatte, ja mitä siinä on, luodot, ja jotka niissä asutte.","Veisatkaat Herralle uutta veisua; hänen ylistyksensä on maailman äärestä, jotka meressä vaellatte, ja mitä siinä on, luodot, ja jotka niissä asutte."],[42,11,"Huutakaat korkiasti, te korvet ja kaupungit niissä, ja ne kylät, joissa Kedar asuu; riemuitkaan ne, jotka kallioissa asuvat, ja huutakaan vuorten kukkuloilta.","Huutakaat korkiasti, te korvet ja kaupungit niissä, ja ne kylät, joissa Kedar asuu; riemuitkaan ne, jotka kallioissa asuvat, ja huutakaan vuorten kukkuloilta."],[42,12,"Antakaan Herralle kunnia, ja hänen nimensä luodoissa ilmoittakaan.","Antakaan Herralle kunnia, ja hänen nimensä luodoissa ilmoittakaan."],[42,13,"Herra käy niinkuin sankari ulos, hän herättää kiivautensa niinkuin sotamies; hän riemuitsee ja huutaa, hän voittaa vihollisensa.","Herra käy niinkuin sankari ulos, hän herättää kiivautensa niinkuin sotamies; hän riemuitsee ja huutaa, hän voittaa vihollisensa."],[42,14,"Vanhasta minä olen vaiti ollut, olin hiljainen ja pidätin itseni; mutta nyt minä tahdon huutaa niinkuin synnyttäjä, minä tahdon hävittää ja kaikki niellä.","Vanhasta minä olen vaiti ollut, olin hiljainen ja pidätin itseni; mutta nyt minä tahdon huutaa niinkuin synnyttäjä, minä tahdon hävittää ja kaikki niellä."],[42,15,"Minä hävitän vuoret ja kukkulat, ja annan kaikki heidän ruohonsa kuivua; minä teen virrat luodoiksi, ja järvet kuivaan pois.","Minä hävitän vuoret ja kukkulat, ja annan kaikki heidän ruohonsa kuivua; minä teen virrat luodoiksi, ja järvet kuivaan pois."],[42,16,"Mutta sokiat minä johdatan sitä tietä, jota ei he tiedä, minä vien heidät niitä polkuja, joita ei he tunne; minä teen heille pimeyden valkeudeksi ja kolian tasaiseksi, näitä tahdon minä heille tehdä, ja en hylkää heitä.","Mutta sokiat minä johdatan sitä tietä, jota ei he tiedä, minä vien heidät niitä polkuja, joita ei he tunne; minä teen heille pimeyden valkeudeksi ja kolian tasaiseksi, näitä tahdon minä heille tehdä, ja en hylkää heitä."],[42,17,"Mutta niiden pitää kääntymän takaperin, ja häpiään tuleman, jotka uskaltavat epäjumaliin ja sanovat valetuille kuville: te olette meidän Jumalamme.","Mutta niiden pitää kääntymän takaperin, ja häpiään tuleman, jotka uskaltavat epäjumaliin ja sanovat valetuille kuville: te olette meidän Jumalamme."],[42,18,"Kuulkaat, te kuurot, ja katsokaat, te sokiat, että te näkisitte.","Kuulkaat, te kuurot, ja katsokaat, te sokiat, että te näkisitte."],[42,19,"Kuka on niin sokia kuin minun palveliani? ja kuka on niin kuuro kuin minun käskyläiseni, jonka minä lähetän? Kuka on niin sokia kuin se täydellinen? ja niin sokia kuin Herran palvelia?","Kuka on niin sokia kuin minun palveliani? ja kuka on niin kuuro kuin minun käskyläiseni, jonka minä lähetän? Kuka on niin sokia kuin se täydellinen? ja niin sokia kuin Herran palvelia?"],[42,20,"Sinä näet paljon, ja et kuitenkaan pidä; korvat ovat avoimet, ja ei kenkään kuule.","Sinä näet paljon, ja et kuitenkaan pidä; korvat ovat avoimet, ja ei kenkään kuule."],[42,21,"Kuitenkin suo Herra heille hyvää vanhurskautensa tähden, hän tekee lakinsa suureksi ja kunnialliseksi.","Kuitenkin suo Herra heille hyvää vanhurskautensa tähden, hän tekee lakinsa suureksi ja kunnialliseksi."],[42,22,"Mutta se on raadeltu ja ryöstetty kansa; he ovat kaikki saadut kiinni kuopasta, ja vankein huoneeseen lymytetyt; he ovat tehdyt saaliiksi, eikä ole yhtään auttajaa, raadellut, ja ei kuitenkaan sano: tuo ne jälleen.","Mutta se on raadeltu ja ryöstetty kansa; he ovat kaikki saadut kiinni kuopasta, ja vankein huoneeseen lymytetyt; he ovat tehdyt saaliiksi, eikä ole yhtään auttajaa, raadellut, ja ei kuitenkaan sano: tuo ne jälleen."],[42,23,"Kuka on teidän seassanne, joka näitä ottaa korviinsa? hän havaitkaan ja kuulkaan, mitä tästedes tulee.","Kuka on teidän seassanne, joka näitä ottaa korviinsa? hän havaitkaan ja kuulkaan, mitä tästedes tulee."],[42,24,"Kuka on Jakobin raatelukseksi antanut, ja Israelin ryöväreille? Eikö Herra itse, jota vastaan me syntiä tehneet olemme? Ja ei he tahtoneet hänen teillänsä vaeltaa, eikä totelleet hänen lakiansa.","Kuka on Jakobin raatelukseksi antanut, ja Israelin ryöväreille? Eikö Herra itse, jota vastaan me syntiä tehneet olemme? Ja ei he tahtoneet hänen teillänsä vaeltaa, eikä totelleet hänen lakiansa."],[42,25,"Sentähden on hän heidän päällensä vuodattanut vihansa hirmuisuuden ja väkevän sodan: ja on heidät sytyttänyt ympäri, mutta ei he tunteneet, ja hän sytytti heitä, mutta ei he sitä ottaneet mieleensä.","Sentähden on hän heidän päällensä vuodattanut vihansa hirmuisuuden ja väkevän sodan: ja on heidät sytyttänyt ympäri, mutta ei he tunteneet, ja hän sytytti heitä, mutta ei he sitä ottaneet mieleensä."],[43,1,"Ja nyt, näin sanoo Herra, joka sinun, Jakob, loi, ja joka sinun, Israel, teki: älä pelkää; sillä minä olen sinun lunastanut; minä olen sinun nimeltäs kutsunut, sinä olet minun.","Ja nyt, näin sanoo Herra, joka sinun, Jakob, loi, ja joka sinun, Israel, teki: älä pelkää; sillä minä olen sinun lunastanut; minä olen sinun nimeltäs kutsunut, sinä olet minun."],[43,2,"Sillä jos sinä vesissä käyt, niin minä olen tykönäs, ettei virrat sinua upota; ja jos sinä tulessa käyt, et sinä pala, ja liekin ei pidä sinua sytyttämän.","Sillä jos sinä vesissä käyt, niin minä olen tykönäs, ettei virrat sinua upota; ja jos sinä tulessa käyt, et sinä pala, ja liekin ei pidä sinua sytyttämän."],[43,3,"Sillä minä olen Herra sinun Jumalas, Israelin Pyhä, sinun vapahtajas. Minä olen Egyptin, Etiopian ja Seban antanut edestäs sovinnoksi.","Sillä minä olen Herra sinun Jumalas, Israelin Pyhä, sinun vapahtajas. Minä olen Egyptin, Etiopian ja Seban antanut edestäs sovinnoksi."],[43,4,"Ettäs niin kalliiksi olet luettu minun silmäini edessä, niin sinä olet myös kunniallisena pidetty, ja minä rakastin sinua, ja annan sentähden ihmiset sinun edestäs, ja kansat sinun sielus edestä.","Ettäs niin kalliiksi olet luettu minun silmäini edessä, niin sinä olet myös kunniallisena pidetty, ja minä rakastin sinua, ja annan sentähden ihmiset sinun edestäs, ja kansat sinun sielus edestä."],[43,5,"Älä siis nyt pelkää; sillä minä olen sinun tykönäs; idästä tahdon minä siemenes saattaa, ja lännestä tahdon sinua koota.","Älä siis nyt pelkää; sillä minä olen sinun tykönäs; idästä tahdon minä siemenes saattaa, ja lännestä tahdon sinua koota."],[43,6,"Minä tahdon sanoa pohjoiselle: tuo tänne, ja etelälle: älä kiellä. Tuo tänne minun poikani taampaa, ja minun tyttäreni hamasta maailman ääristä:","Minä tahdon sanoa pohjoiselle: tuo tänne, ja etelälle: älä kiellä. Tuo tänne minun poikani taampaa, ja minun tyttäreni hamasta maailman ääristä:"],[43,7,"Kaikki, jotka minun nimelläni ovat nimitetyt, jotka minä luonut olen, valmistanut ja tehnyt minun kunniakseni.","Kaikki, jotka minun nimelläni ovat nimitetyt, jotka minä luonut olen, valmistanut ja tehnyt minun kunniakseni."],[43,8,"Tuo edes sokia kansa, jolla kuitenkin silmät ovat, ja kuurot, joilla kuitenkin korvat ovat.","Tuo edes sokia kansa, jolla kuitenkin silmät ovat, ja kuurot, joilla kuitenkin korvat ovat."],[43,9,"Anna kaikki pakanat tulla kokoon, ja kansan kokoontua, kuka on heidän seassansa, joka näitä ilmoittaa tietää, ja kuuluttaa meille edellä, mitä tapahtuman pitää? Anna heidän tuoda edes todistuksensa ja asiansa oikiaksi tehdä, niin saadaan kuulla, ja sanoa: se on totuus.","Anna kaikki pakanat tulla kokoon, ja kansan kokoontua, kuka on heidän seassansa, joka näitä ilmoittaa tietää, ja kuuluttaa meille edellä, mitä tapahtuman pitää? Anna heidän tuoda edes todistuksensa ja asiansa oikiaksi tehdä, niin saadaan kuulla, ja sanoa: se on totuus."],[43,10,"Mutta te olette minun todistajani, sanoo Herra, ja minun palveliani, jonka minä valitsin, että te tietäisitte, ja uskoisitte minua, ja ymmärtäisitte, että minä se olen. Ei yhtään Jumalaa ole minun edelläni tehty, ei myös kenkään tule minun jälkeeni.","Mutta te olette minun todistajani, sanoo Herra, ja minun palveliani, jonka minä valitsin, että te tietäisitte, ja uskoisitte minua, ja ymmärtäisitte, että minä se olen. Ei yhtään Jumalaa ole minun edelläni tehty, ei myös kenkään tule minun jälkeeni."],[43,11,"Minä, minä olen Herra, ja paitsi minua ei ole yhtään vapahtajaa.","Minä, minä olen Herra, ja paitsi minua ei ole yhtään vapahtajaa."],[43,12,"Minä sen olen ilmoittanut, ja olen myös auttanut, ja olen sen teille antanut sanoa, ja ei ole muukalainen (Jumala) teidän seassanne: ja te olette minun todistajani, sanoo Herra, ja minä olen Jumala.","Minä sen olen ilmoittanut, ja olen myös auttanut, ja olen sen teille antanut sanoa, ja ei ole muukalainen (Jumala) teidän seassanne: ja te olette minun todistajani, sanoo Herra, ja minä olen Jumala."],[43,13,"Ja minä olen itse ennenkuin joku päivä olikaan, ja ei kenkään voi minun kädestäni pelastaa; minä vaikutan, ja kuka tahtoo sitä estää?","Ja minä olen itse ennenkuin joku päivä olikaan, ja ei kenkään voi minun kädestäni pelastaa; minä vaikutan, ja kuka tahtoo sitä estää?"],[43,14,"Näin sanoo Herra teidän lunastajanne, Israelin Pyhä: teidän tähtenne olen minä lähettänyt Babeliin, ja olen kukistanut kaikki teljet, ja ajanut murheelliset Kaldealaiset haaksiin.","Näin sanoo Herra teidän lunastajanne, Israelin Pyhä: teidän tähtenne olen minä lähettänyt Babeliin, ja olen kukistanut kaikki teljet, ja ajanut murheelliset Kaldealaiset haaksiin."],[43,15,"Minä olen Herra teidän Pyhänne, joka Israelin luonut olen, teidän Kuninkaanne.","Minä olen Herra teidän Pyhänne, joka Israelin luonut olen, teidän Kuninkaanne."],[43,16,"Näin sanoo Herra, joka tien tekee meressä ja polun väkevässä vedessä,","Näin sanoo Herra, joka tien tekee meressä ja polun väkevässä vedessä,"],[43,17,"Joka vie rattaan ja hevosen, joukon ja voiman, niin että he yhdessä roukkiossa makaavat, eikä nouse; he sammuvat, niinkuin kynttilän sydän sammuu.","Joka vie rattaan ja hevosen, joukon ja voiman, niin että he yhdessä roukkiossa makaavat, eikä nouse; he sammuvat, niinkuin kynttilän sydän sammuu."],[43,18,"Älkäät muistelko entisiä, ja älkäät pitäkö lukua vanhoista.","Älkäät muistelko entisiä, ja älkäät pitäkö lukua vanhoista."],[43,19,"Sillä katso, minä teen uutta, juuri nyt pitää sen tuleman edes; ettekö te ymmärrä sitä? minä teen tietä korpeen, ja virtoja erämaihin.","Sillä katso, minä teen uutta, juuri nyt pitää sen tuleman edes; ettekö te ymmärrä sitä? minä teen tietä korpeen, ja virtoja erämaihin."],[43,20,"Että eläimet kedolla kunnioittavat minua, lohikärmeet ja yököt; sillä minä annan vettä korvessa, ja virrat erämaassa, antaakseni kansalleni, valituilleni juoda.","Että eläimet kedolla kunnioittavat minua, lohikärmeet ja yököt; sillä minä annan vettä korvessa, ja virrat erämaassa, antaakseni kansalleni, valituilleni juoda."],[43,21,"Tämän kansan olen minä minulleni valmistanut: sen pitää minun ylistykseni julistaman.","Tämän kansan olen minä minulleni valmistanut: sen pitää minun ylistykseni julistaman."],[43,22,"Ja et sinä Jakob huutanut minua avukses, ja et sinä Israel ole työtä tehnyt minun tähteni.","Ja et sinä Jakob huutanut minua avukses, ja et sinä Israel ole työtä tehnyt minun tähteni."],[43,23,"Etpä sinä minulle tuonut edes polttouhris lampaita, etkä kunnioittanut minua sinun uhrillas. En minä sinua saattanut ruokauhrias uhraamaan, enkä myös vaatinut sinua pyhää savuas tekemään.","Etpä sinä minulle tuonut edes polttouhris lampaita, etkä kunnioittanut minua sinun uhrillas. En minä sinua saattanut ruokauhrias uhraamaan, enkä myös vaatinut sinua pyhää savuas tekemään."],[43,24,"Etpä sinä minulle ostanut rahalla hajavaa kalmusta, et myös minua uhris rasvalla täyttänyt; vaan sinä sait minun työtä tekemään sinun synnissäs, ja olet tehnyt minulle vaivaa sinun pahoissa teoissas.","Etpä sinä minulle ostanut rahalla hajavaa kalmusta, et myös minua uhris rasvalla täyttänyt; vaan sinä sait minun työtä tekemään sinun synnissäs, ja olet tehnyt minulle vaivaa sinun pahoissa teoissas."],[43,25,"Minä, minä pyyhin sinun ylitsekäymises pois minun tähteni, ja en muista sinun syntejäs.","Minä, minä pyyhin sinun ylitsekäymises pois minun tähteni, ja en muista sinun syntejäs."],[43,26,"Muistuta minulle, koetelkaamme oikeudella: sano sinä, millä tavalla sinä tahdot vanhurskaaksi tulla?","Muistuta minulle, koetelkaamme oikeudella: sano sinä, millä tavalla sinä tahdot vanhurskaaksi tulla?"],[43,27,"Sinun ensimäinen isäs on syntiä tehnyt, ja sinun opettajas ovat minua vastaan vääryyttä tehneet.","Sinun ensimäinen isäs on syntiä tehnyt, ja sinun opettajas ovat minua vastaan vääryyttä tehneet."],[43,28,"Sentähden minä saastutin pyhät esimiehet, ja olen antanut Jakobin raatelukseksi, ja Israelin pilkaksi.","Sentähden minä saastutin pyhät esimiehet, ja olen antanut Jakobin raatelukseksi, ja Israelin pilkaksi."],[44,1,"Niin kuule nyt, minun palveliani Jakob, ja Israel, jonka minä valitsin.","Niin kuule nyt, minun palveliani Jakob, ja Israel, jonka minä valitsin."],[44,2,"Näin sanoo Herra, joka sinun tehnyt ja valmistanut on äitis kohdusta, joka sinua auttaa: älä pelkää, minun palveliani Jakob, ja sinä hurskas, jonka minä valitsin.","Näin sanoo Herra, joka sinun tehnyt ja valmistanut on äitis kohdusta, joka sinua auttaa: älä pelkää, minun palveliani Jakob, ja sinä hurskas, jonka minä valitsin."],[44,3,"Sillä minä tahdon vuodattaa vedet janoovaisen päälle, ja virrat kuivan päälle; minä tahdon vuodattaa henkeni sinun siemenes päälle, ja siunaukseni jälkeentulevaistes päälle.","Sillä minä tahdon vuodattaa vedet janoovaisen päälle, ja virrat kuivan päälle; minä tahdon vuodattaa henkeni sinun siemenes päälle, ja siunaukseni jälkeentulevaistes päälle."],[44,4,"Että he kasvaisivat niinkuin ruoho, ja niinkuin pajut vesivirtain tykönä.","Että he kasvaisivat niinkuin ruoho, ja niinkuin pajut vesivirtain tykönä."],[44,5,"Tämän pitää sanoman: Herran minä olen, ja se pitää Jakobin nimellä kutsuttaman, ja tämän pitää itsensä omalla kädellänsä Herralle kirjoittaman, ja pitää nimitettämän Israelin nimellä.","Tämän pitää sanoman: Herran minä olen, ja se pitää Jakobin nimellä kutsuttaman, ja tämän pitää itsensä omalla kädellänsä Herralle kirjoittaman, ja pitää nimitettämän Israelin nimellä."],[44,6,"Näin sanoo Herra Israelin kuningas, ja hänen pelastajansa Herra Zebaot: minä olen ensimäinen ja minä olen viimeinen, ja paitsi minua ei ole yhtään Jumalaa.","Näin sanoo Herra Israelin kuningas, ja hänen pelastajansa Herra Zebaot: minä olen ensimäinen ja minä olen viimeinen, ja paitsi minua ei ole yhtään Jumalaa."],[44,7,"Ja kuka on minun kaltaiseni, joka kutsuu ja ilmoittaa sen, ja sen minulle valmistaa? minä, joka asetan kansat maailman alusta: anna heidän ilmoittaa merkkejä ja mitä tuleva on.","Ja kuka on minun kaltaiseni, joka kutsuu ja ilmoittaa sen, ja sen minulle valmistaa? minä, joka asetan kansat maailman alusta: anna heidän ilmoittaa merkkejä ja mitä tuleva on."],[44,8,"Älkää peljätkö ja älkäät hämmästykö. Enkö minä silloin antanut kuulla, ja ilmoittaa sitä sinulle? Sillä te olette minun todistajani. Onko joku Jumala paitsi minua? Ei ole yhtään turvaa, en minä tiedä ketään.","Älkää peljätkö ja älkäät hämmästykö. Enkö minä silloin antanut kuulla, ja ilmoittaa sitä sinulle? Sillä te olette minun todistajani. Onko joku Jumala paitsi minua? Ei ole yhtään turvaa, en minä tiedä ketään."],[44,9,"Epäjumalain tekiät ovat kaikki turhat, ja joista he paljon pitävät, ei ne ole mitään tarpeelliset; he ovat heidän todistajansa, ja ei näe mitään, eikä mitään ymmärrä: sentähden pitää heidän häpiään tuleman.","Epäjumalain tekiät ovat kaikki turhat, ja joista he paljon pitävät, ei ne ole mitään tarpeelliset; he ovat heidän todistajansa, ja ei näe mitään, eikä mitään ymmärrä: sentähden pitää heidän häpiään tuleman."],[44,10,"Kutka ovat ne, jotka Jumalan tekevät, ja valavat epäjumalan, joka ei mihinkään kelpaa?","Kutka ovat ne, jotka Jumalan tekevät, ja valavat epäjumalan, joka ei mihinkään kelpaa?"],[44,11,"Katso, kaikki heidän kumppaninsa tulevat häpiään, sillä he ovat tekiät ihmisistä. Jos he kaikki kokoontuisivat ja astuisivat edes, niin heidän pitää kuitenkin pelkäämän ja häpiään tuleman.","Katso, kaikki heidän kumppaninsa tulevat häpiään, sillä he ovat tekiät ihmisistä. Jos he kaikki kokoontuisivat ja astuisivat edes, niin heidän pitää kuitenkin pelkäämän ja häpiään tuleman."],[44,12,"Rautaseppä tarttuu rautaan pihdeillä, pitää sen hiilissä ja valmistaa sen vasaralla, ja takoo sitä kaikella käsivartensa väellä; kärsii myös nälkää, siihenasti ettei hän enää voi, eikä juo vettä, siihenasti että hän väsyy.","Rautaseppä tarttuu rautaan pihdeillä, pitää sen hiilissä ja valmistaa sen vasaralla, ja takoo sitä kaikella käsivartensa väellä; kärsii myös nälkää, siihenasti ettei hän enää voi, eikä juo vettä, siihenasti että hän väsyy."],[44,13,"Puuseppä veistelee puuta, ja mittaa sitä nuoralla, ja arvoittelee sen langalla, ja hakkaa sen, ja piirittää sen sirkkelillä; ja tekee sen miehen kuvaksi, niinkuin kauniiksi ihmiseksi, jonka pitäis asuman huoneessa.","Puuseppä veistelee puuta, ja mittaa sitä nuoralla, ja arvoittelee sen langalla, ja hakkaa sen, ja piirittää sen sirkkelillä; ja tekee sen miehen kuvaksi, niinkuin kauniiksi ihmiseksi, jonka pitäis asuman huoneessa."],[44,14,"Hän hakkaa sedripuita, ja ottaa böökiä ja tammea, joka metsän puiden seassa vahvistuu, ja sedripuuta, joka istutettu on ja sateesta on kasvanut.","Hän hakkaa sedripuita, ja ottaa böökiä ja tammea, joka metsän puiden seassa vahvistuu, ja sedripuuta, joka istutettu on ja sateesta on kasvanut."],[44,15,"Joka kelpaa ihmiselle polttaa, ja josta lämmitellä saadaan, jonka palamisella myös leipää kypsennetään; siitä hän myös tekee Jumalan, ja palvelee sitä; hän tekee siitä epäjumalan ja lankee sen eteen polvillensa.","Joka kelpaa ihmiselle polttaa, ja josta lämmitellä saadaan, jonka palamisella myös leipää kypsennetään; siitä hän myös tekee Jumalan, ja palvelee sitä; hän tekee siitä epäjumalan ja lankee sen eteen polvillensa."],[44,16,"Puolen polttaa hän tulessa, ja toisen puolen tykönä syö hän lihaa, hän paistaa paistin ja ravitsee itsensä, lämmittää myös itsiänsä, ja sanoo: hoi! minä olen lämmin, että sain nähdä tulen.","Puolen polttaa hän tulessa, ja toisen puolen tykönä syö hän lihaa, hän paistaa paistin ja ravitsee itsensä, lämmittää myös itsiänsä, ja sanoo: hoi! minä olen lämmin, että sain nähdä tulen."],[44,17,"Mutta mitä siitä jää, siitä tekee hän jumalan epäjumalaksensa; sen eteen lankee hän polvillensa, ja kumartelee sitä, rukoilee ja sanoo: vapahda minua, sillä sinä olet minun jumalani.","Mutta mitä siitä jää, siitä tekee hän jumalan epäjumalaksensa; sen eteen lankee hän polvillensa, ja kumartelee sitä, rukoilee ja sanoo: vapahda minua, sillä sinä olet minun jumalani."],[44,18,"Ei he tiedä eikä ymmärrä mitään; sillä he ovat sovaistut, niin että heidän silmänsä ei näe mitään, ja heidän sydämensä ei äkkää mitään.","Ei he tiedä eikä ymmärrä mitään; sillä he ovat sovaistut, niin että heidän silmänsä ei näe mitään, ja heidän sydämensä ei äkkää mitään."],[44,19,"Ja ei he johdata sydämeensä, ei ole siinä yhtään tointa eli järkeä, että he sittenkin ajattelisivat: minä olen puolen polttanut tulessa, ja olen hiilillä kypsentänyt leipiä, ja paistanut lihaa ja syönyt; pitäiskö minun nyt tekemän sen, mikä jäänyt on, kauhistukseksi? ja pitäiskö minun kumartaman kantoa?","Ja ei he johdata sydämeensä, ei ole siinä yhtään tointa eli järkeä, että he sittenkin ajattelisivat: minä olen puolen polttanut tulessa, ja olen hiilillä kypsentänyt leipiä, ja paistanut lihaa ja syönyt; pitäiskö minun nyt tekemän sen, mikä jäänyt on, kauhistukseksi? ja pitäiskö minun kumartaman kantoa?"],[44,20,"Hän ravitsee itsiänsä tuhalla, hänen vimmattu sydämensä pettää hänen, ettei hän taida sieluansa pelastaa, eikä ajattele: eikö petos ole minun oikiassa kädessääni?","Hän ravitsee itsiänsä tuhalla, hänen vimmattu sydämensä pettää hänen, ettei hän taida sieluansa pelastaa, eikä ajattele: eikö petos ole minun oikiassa kädessääni?"],[44,21,"Ajattele näitä, Jakob ja Israel, sillä sinä olet minun palveliani; minä olen sinun valmistanut, ettäs minun palveliani olisit, Israel, älä minua unohda.","Ajattele näitä, Jakob ja Israel, sillä sinä olet minun palveliani; minä olen sinun valmistanut, ettäs minun palveliani olisit, Israel, älä minua unohda."],[44,22,"Minä pyyhin sinun pahat tekos pois niinkuin pilven, ja sinun syntis niinkuin sumun; käännä sinuas minun puoleeni, sillä minä sinun lunastin.","Minä pyyhin sinun pahat tekos pois niinkuin pilven, ja sinun syntis niinkuin sumun; käännä sinuas minun puoleeni, sillä minä sinun lunastin."],[44,23,"Iloitkaat te taivaat, sillä Herra itse sen teki; riemuitse sinä maa täällä alhaalla, paukkukaat te vuoret ihastuksella, metsä ja kaikki hänen puunsa; sillä Herra lunasti Jakobin, ja on Israelissa kunniallinen.","Iloitkaat te taivaat, sillä Herra itse sen teki; riemuitse sinä maa täällä alhaalla, paukkukaat te vuoret ihastuksella, metsä ja kaikki hänen puunsa; sillä Herra lunasti Jakobin, ja on Israelissa kunniallinen."],[44,24,"Näitä sanoo Herra sinun lunastajas, joka sinun äitis kohdusta valmistanut on: minä olen Herra joka kaikki teen, joka taivaat yksinäni venytän, ja levitän maan ilman apulaista;","Näitä sanoo Herra sinun lunastajas, joka sinun äitis kohdusta valmistanut on: minä olen Herra joka kaikki teen, joka taivaat yksinäni venytän, ja levitän maan ilman apulaista;"],[44,25,"Joka noitain merkit tyhjäksi teen, ja tietäjät teen hulluksi; joka viisaat ajan takaperin, ja heidän taitonsa teen hulluudeksi.","Joka noitain merkit tyhjäksi teen, ja tietäjät teen hulluksi; joka viisaat ajan takaperin, ja heidän taitonsa teen hulluudeksi."],[44,26,"Mutta hän vahvistaa palveliansa sanan ja käskyläistensä neuvon täyttää. Joka Jerusalemille sanon: ole asuva: ja Juudan kaupungeille: olkaat rakennetut, ja heidän aukionsa minä nostan ylös.","Mutta hän vahvistaa palveliansa sanan ja käskyläistensä neuvon täyttää. Joka Jerusalemille sanon: ole asuva: ja Juudan kaupungeille: olkaat rakennetut, ja heidän aukionsa minä nostan ylös."],[44,27,"Joka syvyydelle sanon: tule kuivaksi: minä tahdon sinun virtas kuivata.","Joka syvyydelle sanon: tule kuivaksi: minä tahdon sinun virtas kuivata."],[44,28,"Joka sanon Korekselle: hän on minun paimeneni, ja hänen pitää kaiken minun tahtoni täyttämän; niin että Jerusalemille sanotaan: ole rakennettu, ja templille: ole perustettu.","Joka sanon Korekselle: hän on minun paimeneni, ja hänen pitää kaiken minun tahtoni täyttämän; niin että Jerusalemille sanotaan: ole rakennettu, ja templille: ole perustettu."],[45,1,"Näin sanoo Herra voidellullensa Korekselle, jonka oikiaan käteen minä rupeen: minä taivutan pakanat hänen eteensä, ja päästän kuningasten miekat heidän suoliltansa, että ovet avataan hänen eteensä, eikä uksia suljeta.","Näin sanoo Herra voidellullensa Korekselle, jonka oikiaan käteen minä rupeen: minä taivutan pakanat hänen eteensä, ja päästän kuningasten miekat heidän suoliltansa, että ovet avataan hänen eteensä, eikä uksia suljeta."],[45,2,"Minä tahdon käydä sinun edelläs, ja tehdä koliat tasaisiksi; minä tahdon rikkoa vaskiovet, ja särkeä rautateljet;","Minä tahdon käydä sinun edelläs, ja tehdä koliat tasaisiksi; minä tahdon rikkoa vaskiovet, ja särkeä rautateljet;"],[45,3,"Ja annan sinulle salatut tavarat ja kätketyt kalliit kalut, että ymmärtäisit minun olevan Herran Israelin Jumalan, joka sinun nimeltäs kutsun,","Ja annan sinulle salatut tavarat ja kätketyt kalliit kalut, että ymmärtäisit minun olevan Herran Israelin Jumalan, joka sinun nimeltäs kutsun,"],[45,4,"Jakobin minun palveliani tähden, ja Israelin minun valittuni tähden: minä kutsuin sinun nimeltäs, ja nimitin sinun, kuin et sinä minua vielä tuntenut.","Jakobin minun palveliani tähden, ja Israelin minun valittuni tähden: minä kutsuin sinun nimeltäs, ja nimitin sinun, kuin et sinä minua vielä tuntenut."],[45,5,"Minä olen Herra, ja ei yksikään muu; paitsi minua ei ole yhtään Jumalaa. Minä varustin sinun, kuin sinä et vielä minua tuntenut,","Minä olen Herra, ja ei yksikään muu; paitsi minua ei ole yhtään Jumalaa. Minä varustin sinun, kuin sinä et vielä minua tuntenut,"],[45,6,"Että sekä idästä ja lännestä ymmärrettäisiin, ettei ilman minua mitään ole. Minä olen Herra, ja ei kenkään muu.","Että sekä idästä ja lännestä ymmärrettäisiin, ettei ilman minua mitään ole. Minä olen Herra, ja ei kenkään muu."],[45,7,"Minä joka teen valkeuden ja luon pimeyden, minä joka annan rauhan ja luon pahan; minä olen Herra, joka kaikki nämät teen.","Minä joka teen valkeuden ja luon pimeyden, minä joka annan rauhan ja luon pahan; minä olen Herra, joka kaikki nämät teen."],[45,8,"Te taivaat, tiukkukaat ylhäältä, ja pilvet satakoon vanhurskauden; maa avatkoon itsensä ja kantakoon autuuden, ja vanhurskaus kasvakoon myös. Minä Herra luon sen.","Te taivaat, tiukkukaat ylhäältä, ja pilvet satakoon vanhurskauden; maa avatkoon itsensä ja kantakoon autuuden, ja vanhurskaus kasvakoon myös. Minä Herra luon sen."],[45,9,"Voi sitä, joka riitelee Luojansa kanssa, saviastia savenvalajan kanssa. Sanoneeko savi savenvalajalle: mitäs teet? et sinä osoita kättäs sinun teossas.","Voi sitä, joka riitelee Luojansa kanssa, saviastia savenvalajan kanssa. Sanoneeko savi savenvalajalle: mitäs teet? et sinä osoita kättäs sinun teossas."],[45,10,"Voi sitä, joka isälle sanoo: miksis minun olet siittänyt? ja vaimolle: miksis minun synnytit?","Voi sitä, joka isälle sanoo: miksis minun olet siittänyt? ja vaimolle: miksis minun synnytit?"],[45,11,"Näin sanoo Herra, Israelin Pyhä ja tekiä: anokaat minulta tulevaisia merkkejä, neuvokaat lapseni ja kätteni työ minun tyköni.","Näin sanoo Herra, Israelin Pyhä ja tekiä: anokaat minulta tulevaisia merkkejä, neuvokaat lapseni ja kätteni työ minun tyköni."],[45,12,"Minä olen tehnyt maan, ja luonut ihmisen sen päälle; minä olen se, jonka kädet ovat levittäneet taivaan, ja antanut käskyn kaikelle sen joukolle.","Minä olen tehnyt maan, ja luonut ihmisen sen päälle; minä olen se, jonka kädet ovat levittäneet taivaan, ja antanut käskyn kaikelle sen joukolle."],[45,13,"Minä olen herättänyt hänen vanhurskaudessa, ja minä teen kaikki hänen tiensä tasaiseksi. Hänen pitää rakentaman minun kaupunkini, ja päästämän minun vankini vallallensa, ei rahan eli lahjan tähden, sanoo Hera Zebaot.","Minä olen herättänyt hänen vanhurskaudessa, ja minä teen kaikki hänen tiensä tasaiseksi. Hänen pitää rakentaman minun kaupunkini, ja päästämän minun vankini vallallensa, ei rahan eli lahjan tähden, sanoo Hera Zebaot."],[45,14,"Näin sanoo Herra: Egyptilästen saanto ja Etiopialaisten kauppa, ja se suuri Seban kansa pitää itsensä antaman sinun alles, ja oleman sinun omas; heidän pitää noudattaman sinua, jalkapuissa pitää heidän käymän, ja pitää lankeeman maahan sinun etees, ja rukoileman sinua, sillä Jumala on sinun tykönäs, ja ei ole yhtään muuta Jumalaa.","Näin sanoo Herra: Egyptilästen saanto ja Etiopialaisten kauppa, ja se suuri Seban kansa pitää itsensä antaman sinun alles, ja oleman sinun omas; heidän pitää noudattaman sinua, jalkapuissa pitää heidän käymän, ja pitää lankeeman maahan sinun etees, ja rukoileman sinua, sillä Jumala on sinun tykönäs, ja ei ole yhtään muuta Jumalaa."],[45,15,"Totisesti sinä olet salattu Jumala, sinä Jumala, Israelin Vapahtaja.","Totisesti sinä olet salattu Jumala, sinä Jumala, Israelin Vapahtaja."],[45,16,"Mutta epäjumalain tekiät täytyy kaikki häpiässä ja häväistyksessä pysyä, ja yksi toisensa kanssa häväistynä mennä pois.","Mutta epäjumalain tekiät täytyy kaikki häpiässä ja häväistyksessä pysyä, ja yksi toisensa kanssa häväistynä mennä pois."],[45,17,"Mutta Israel lunastetaan Herran kautta ijankaikkisella lunastuksella, eikä tule häpiään eli pilkkaan koskaan ijankaikkisesti.","Mutta Israel lunastetaan Herran kautta ijankaikkisella lunastuksella, eikä tule häpiään eli pilkkaan koskaan ijankaikkisesti."],[45,18,"Sillä näin sanoo Herra, joka taivaan luonut on, Jumala, joka maan on valmistanut, ja on sen tehnyt ja vahvistanut sen, ja ei niin sitä tehnyt, että se olis tyhjänä ollut, vaan valmisti sen että siinä asuttaisiin: Minä olen Herra, ja ei kenkään muu.","Sillä näin sanoo Herra, joka taivaan luonut on, Jumala, joka maan on valmistanut, ja on sen tehnyt ja vahvistanut sen, ja ei niin sitä tehnyt, että se olis tyhjänä ollut, vaan valmisti sen että siinä asuttaisiin: Minä olen Herra, ja ei kenkään muu."],[45,19,"En minä ole salaa puhunut, pimiässä paikassa maan päällä, enkä ole Jakobin siemenelle sanonut: etsikäät minua hukkaan; sillä minä olen Herra, joka vanhurskaudesta puhun, ja ilmoitan oikeutta.","En minä ole salaa puhunut, pimiässä paikassa maan päällä, enkä ole Jakobin siemenelle sanonut: etsikäät minua hukkaan; sillä minä olen Herra, joka vanhurskaudesta puhun, ja ilmoitan oikeutta."],[45,20,"Anna pakanain sankarien kokoontua ja tulla yhteen, jotka ei mitään tiedä, ja kantavat epäjumalansa kannot, ja rukoilevat sitä jumalaa, joka ei auttaa taida.","Anna pakanain sankarien kokoontua ja tulla yhteen, jotka ei mitään tiedä, ja kantavat epäjumalansa kannot, ja rukoilevat sitä jumalaa, joka ei auttaa taida."],[45,21,"Ilmoittakaat ja tulkaat tänne, pitäkäät neuvoa keskenänne, kuka näitä alusta kuulutti, ja silloin on sen ilmoittanut? Enkö minä Herra? Ja ei ole ensinkään Jumalaa paitsi minua: hurskas Jumala ja Vapahtaja, ei ole yksikään paitsi minua.","Ilmoittakaat ja tulkaat tänne, pitäkäät neuvoa keskenänne, kuka näitä alusta kuulutti, ja silloin on sen ilmoittanut? Enkö minä Herra? Ja ei ole ensinkään Jumalaa paitsi minua: hurskas Jumala ja Vapahtaja, ei ole yksikään paitsi minua."],[45,22,"Kääntykäät minun tyköni, niin te autuaaksi tulette, kaikki maailman ääret; sillä minä olen Jumala, ja ei kenkään muu.","Kääntykäät minun tyköni, niin te autuaaksi tulette, kaikki maailman ääret; sillä minä olen Jumala, ja ei kenkään muu."],[45,23,"Minä vannon itse kauttani, ja minun suustani on vanhurskauden sana käyvä ulos, ja sen pitää vahvana pysymän: minulle pitää kaikki polvet kumartaman, ja kaikki kielet vannoman,","Minä vannon itse kauttani, ja minun suustani on vanhurskauden sana käyvä ulos, ja sen pitää vahvana pysymän: minulle pitää kaikki polvet kumartaman, ja kaikki kielet vannoman,"],[45,24,"Ja sanoman: Herrassa on minulla vanhurskaus ja väkevyys; senkaltaiset tulevat hänen tykönsä, mutta kaikki, jotka seisovat häntä vastaan, ne häpiään tulevat.","Ja sanoman: Herrassa on minulla vanhurskaus ja väkevyys; senkaltaiset tulevat hänen tykönsä, mutta kaikki, jotka seisovat häntä vastaan, ne häpiään tulevat."],[45,25,"Sillä Herrassa kaikki Israelin siemen vanhurskautetaan, ja saavat hänestä kerskata.","Sillä Herrassa kaikki Israelin siemen vanhurskautetaan, ja saavat hänestä kerskata."],[46,1,"Bel kallistuu kovin, Nebo on pudonnut; heidän epäjumalansa ovat joutuneet eläinten ja juhtain päälle, että he väsyvät teidän kuormianne kantaissansa.","Bel kallistuu kovin, Nebo on pudonnut; heidän epäjumalansa ovat joutuneet eläinten ja juhtain päälle, että he väsyvät teidän kuormianne kantaissansa."],[46,2,"Ja ne notkistuvat ja kallistuvat kaikki tyynni, ja ei taida kantaa pois kuormaa; vaan heidän sielunsa pitää käymän vankeudessa.","Ja ne notkistuvat ja kallistuvat kaikki tyynni, ja ei taida kantaa pois kuormaa; vaan heidän sielunsa pitää käymän vankeudessa."],[46,3,"Kuulkaat minua, te Jakobin huone, ja kaikki Israelin huoneen tähteet, jotka kohdussa kannetaan ja äidistänne olette.","Kuulkaat minua, te Jakobin huone, ja kaikki Israelin huoneen tähteet, jotka kohdussa kannetaan ja äidistänne olette."],[46,4,"Minä, minä tahdon teitä kantaa hamaan vanhuuteen, ja siihenasti kuin te harmaaksi tulette; minä sen teen, minä nostan, kannan ja pelastan.","Minä, minä tahdon teitä kantaa hamaan vanhuuteen, ja siihenasti kuin te harmaaksi tulette; minä sen teen, minä nostan, kannan ja pelastan."],[46,5,"Keneenkä te vertaatte minun, ja kenenkä kaltaiseksi te teette minun? ja kenen verraksi te minua mittaatte, jonka kaltainen minä olisin?","Keneenkä te vertaatte minun, ja kenenkä kaltaiseksi te teette minun? ja kenen verraksi te minua mittaatte, jonka kaltainen minä olisin?"],[46,6,"He kaatavat kultaa säkistä, ja hopian painolla punnitsevat; ja hopiasepän palkkaavat, että hän jumalan tekis, jonka eteen he polvillensa lankeevat ja sitä kumartavat.","He kaatavat kultaa säkistä, ja hopian painolla punnitsevat; ja hopiasepän palkkaavat, että hän jumalan tekis, jonka eteen he polvillensa lankeevat ja sitä kumartavat."],[46,7,"He nostavat sen hartioillensa ja kantavat sitä, ja panevat sen siallensa, siinä se seisoo ja ei liiku siastansa. Jos joku häntä huutaa, niin ei hän vastaa, ja ei auta häntä hänen tuskastansa.","He nostavat sen hartioillensa ja kantavat sitä, ja panevat sen siallensa, siinä se seisoo ja ei liiku siastansa. Jos joku häntä huutaa, niin ei hän vastaa, ja ei auta häntä hänen tuskastansa."],[46,8,"Muistakaat tätä, ja olkaat vahvat: te väärintekiät, menkäät sydämiinne.","Muistakaat tätä, ja olkaat vahvat: te väärintekiät, menkäät sydämiinne."],[46,9,"Muistakaat entisiä, jotka vanhasta ovat olleet; sillä minä olen Jumala ja ei ole muuta Jumalaa, eikä minun vertaistani ole,","Muistakaat entisiä, jotka vanhasta ovat olleet; sillä minä olen Jumala ja ei ole muuta Jumalaa, eikä minun vertaistani ole,"],[46,10,"Joka edellä ennustan, mitä vasta tuleva on, ja ennenkuin se tapahtuu, sanon minä. Minun aivoitukseni pysyvät, ja minä teen kaikki mieleni perään.","Joka edellä ennustan, mitä vasta tuleva on, ja ennenkuin se tapahtuu, sanon minä. Minun aivoitukseni pysyvät, ja minä teen kaikki mieleni perään."],[46,11,"Minä kutsun linnun idästä, ja kaukaiselta maalta miehen, joka minun aivoitukseni tekee; minä olen sen puhunut, minä tahdon myös sen tuoda; minä olen sen aikonut ja tahdon myös sen tehdä.","Minä kutsun linnun idästä, ja kaukaiselta maalta miehen, joka minun aivoitukseni tekee; minä olen sen puhunut, minä tahdon myös sen tuoda; minä olen sen aikonut ja tahdon myös sen tehdä."],[46,12,"Kuulkaat minua, te ylpiät sydämet, te jotka olette kaukana vanhurskaudesta:","Kuulkaat minua, te ylpiät sydämet, te jotka olette kaukana vanhurskaudesta:"],[46,13,"Minä olen vanhurskauteni antanut lähestyä, ei se ole kaukana, ja ei minun autuuteni viivy; sillä minä annan autuuden Zionissa, ja kunniani Israelissa.","Minä olen vanhurskauteni antanut lähestyä, ei se ole kaukana, ja ei minun autuuteni viivy; sillä minä annan autuuden Zionissa, ja kunniani Israelissa."],[47,1,"Astu alas, ja istu tomuun, sinä neitsy Babelin tytär; istu maahan, sillä ei ole yhtään istuinta enään, sinä Kaldean tytär; sillä ei sinua pidä enää kutsuttaman ihanaiseksi ja iloiseksi.","Astu alas, ja istu tomuun, sinä neitsy Babelin tytär; istu maahan, sillä ei ole yhtään istuinta enään, sinä Kaldean tytär; sillä ei sinua pidä enää kutsuttaman ihanaiseksi ja iloiseksi."],[47,2,"Ota mylly ja jauha jauhoja; päästä hiustes palmikot, riisu kenkäs, paljasta sääres, mene virran ylitse.","Ota mylly ja jauha jauhoja; päästä hiustes palmikot, riisu kenkäs, paljasta sääres, mene virran ylitse."],[47,3,"Että sinun häpys ilmoitetuksi, ja sinun riettautes nähdyksi tulis. Minä kostan, ja ei yksikään ihminen pidä rukouksellansa minua siitä estämän.","Että sinun häpys ilmoitetuksi, ja sinun riettautes nähdyksi tulis. Minä kostan, ja ei yksikään ihminen pidä rukouksellansa minua siitä estämän."],[47,4,"(Tämän tekee) meidän pelastajamme, Herra Zebaot on hänen nimensä, Israelin Pyhä.","(Tämän tekee) meidän pelastajamme, Herra Zebaot on hänen nimensä, Israelin Pyhä."],[47,5,"Istu alallas, mene pimeyteen, sinä Kaldealaisten tytär; sillä ei sinua enää pidä kutsuttaman valtakuntain kuningattareksi.","Istu alallas, mene pimeyteen, sinä Kaldealaisten tytär; sillä ei sinua enää pidä kutsuttaman valtakuntain kuningattareksi."],[47,6,"Sillä kuin minä olin vihainen kansalleni, turmelin minä perintöni, ja hylkäsin heidät sinun kätees; mutta et sinä tehnyt heille laupiutta, ja vanhoille teit sinä ikees peräti raskaaksi,","Sillä kuin minä olin vihainen kansalleni, turmelin minä perintöni, ja hylkäsin heidät sinun kätees; mutta et sinä tehnyt heille laupiutta, ja vanhoille teit sinä ikees peräti raskaaksi,"],[47,7,"Ja ajattelit: minä olen hallitsia ijankaikkisesti: et sinä tähän päivään asti vielä ole sitä johdattanut sydämees, eli ajatellut, kuinka heille viimein on tapahtuva.","Ja ajattelit: minä olen hallitsia ijankaikkisesti: et sinä tähän päivään asti vielä ole sitä johdattanut sydämees, eli ajatellut, kuinka heille viimein on tapahtuva."],[47,8,"Niin kuule nyt tätä, sinä, joka elät hekumassa, ja istut niin surutoinna, ja sanot sydämessäs: minä olen, ja ei yksikään muu; en minä leskeksi eli hedelmättömäksi tule.","Niin kuule nyt tätä, sinä, joka elät hekumassa, ja istut niin surutoinna, ja sanot sydämessäs: minä olen, ja ei yksikään muu; en minä leskeksi eli hedelmättömäksi tule."],[47,9,"Molemmat nämät pitää sinua äkisti kohtaaman yhtenä päivänä, ettäs tulet hedelmättömäksi ja leskeksi; ja ne pitää sinuun täydellisesti sattuman, sinun monen velhos tähden, ja sinun noitais tähden, joista suuri paljous on sinun tykönäs.","Molemmat nämät pitää sinua äkisti kohtaaman yhtenä päivänä, ettäs tulet hedelmättömäksi ja leskeksi; ja ne pitää sinuun täydellisesti sattuman, sinun monen velhos tähden, ja sinun noitais tähden, joista suuri paljous on sinun tykönäs."],[47,10,"Sillä sinä olet luottanut pahuutees, koskas ajattelit: ei minua nähdä. Taitos ja tietos on sinun kukistanut, ettäs sanot sydämessäs: minäpä olen, ja ei yksikään muu.","Sillä sinä olet luottanut pahuutees, koskas ajattelit: ei minua nähdä. Taitos ja tietos on sinun kukistanut, ettäs sanot sydämessäs: minäpä olen, ja ei yksikään muu."],[47,11,"Sentähden pitää onnettomuuden tuleman sinun päälles, niin ettei sinun pidä tietämän, koska se tulee, ja sinun vastoinkäymises pitää lankeeman sinun päälles, jotka ei sinun pidä taitaman sovittaa; sillä hävitys pitää äkisti tuleman sinun päälles, jota et sinä edellä tiedä.","Sentähden pitää onnettomuuden tuleman sinun päälles, niin ettei sinun pidä tietämän, koska se tulee, ja sinun vastoinkäymises pitää lankeeman sinun päälles, jotka ei sinun pidä taitaman sovittaa; sillä hävitys pitää äkisti tuleman sinun päälles, jota et sinä edellä tiedä."],[47,12,"Käy nyt edes velhois kanssa, ja sinun monien noitais kanssa, joiden seassa sinä olet itsiäs nuoruudessas vaivannut: jos taitaisit auttaa itsiäs, jos taitaisit vahvistaa itsiäs.","Käy nyt edes velhois kanssa, ja sinun monien noitais kanssa, joiden seassa sinä olet itsiäs nuoruudessas vaivannut: jos taitaisit auttaa itsiäs, jos taitaisit vahvistaa itsiäs."],[47,13,"Sinä olet väsyksissä monen koettelemukses tähden. Tulkaan nyt edes ja auttakoon sinua ne taivaan juoksun tietäjät ja tähtein kurkisteliat, jotka kuukausien jälkeen lukevat, mitä sinulle pitää tapahtuman.","Sinä olet väsyksissä monen koettelemukses tähden. Tulkaan nyt edes ja auttakoon sinua ne taivaan juoksun tietäjät ja tähtein kurkisteliat, jotka kuukausien jälkeen lukevat, mitä sinulle pitää tapahtuman."],[47,14,"Katso, he ovat niinkuin korret, jotka tuli polttaa, ei he taida pelastaa henkeänsä liekistä; sillä ei pidä yhtään hiilistöä oleman, jossa joku taitais itsensä lämmitellä, eli tulta, jonka tykönä istuttaisiin.","Katso, he ovat niinkuin korret, jotka tuli polttaa, ei he taida pelastaa henkeänsä liekistä; sillä ei pidä yhtään hiilistöä oleman, jossa joku taitais itsensä lämmitellä, eli tulta, jonka tykönä istuttaisiin."],[47,15,"Juuri niin ovat ne sinulle, joiden alla sinä sinus vaivannut olet: sinun kauppamiehes sinun nuoruudestas pitää jokaisen käymän sinne ja tänne, ja sinulla ei ole yhtään auttajaa.","Juuri niin ovat ne sinulle, joiden alla sinä sinus vaivannut olet: sinun kauppamiehes sinun nuoruudestas pitää jokaisen käymän sinne ja tänne, ja sinulla ei ole yhtään auttajaa."],[48,1,"Kuulkaat tätä, te Jakobin huone, te, joita kutsutaan Israelin nimellä, ja olette kulkeneet Juudan vedestä, te, jotka vannotte Herran nimeen, ja muistatte Israelin Jumalaa, ei kuitenkaan totuudessa eikä vanhurskaudessa.","Kuulkaat tätä, te Jakobin huone, te, joita kutsutaan Israelin nimellä, ja olette kulkeneet Juudan vedestä, te, jotka vannotte Herran nimeen, ja muistatte Israelin Jumalaa, ei kuitenkaan totuudessa eikä vanhurskaudessa."],[48,2,"Sillä he nimittävät itsensä pyhästä kaupungista, ja luottavat Israelin Jumalaan, jonka nimi on Herra Zebaot.","Sillä he nimittävät itsensä pyhästä kaupungista, ja luottavat Israelin Jumalaan, jonka nimi on Herra Zebaot."],[48,3,"Minä olen ennen ilmoittanut tulevaisia, minun suustani on se lähtenyt, ja minä olen antanut sitä kuulla, ja teen sen myös äkisti, että se tulee.","Minä olen ennen ilmoittanut tulevaisia, minun suustani on se lähtenyt, ja minä olen antanut sitä kuulla, ja teen sen myös äkisti, että se tulee."],[48,4,"Sillä minä tiedän sinun kovaksi, ja sinun niskas on rautasuoni, ja sinun otsas on vaskesta.","Sillä minä tiedän sinun kovaksi, ja sinun niskas on rautasuoni, ja sinun otsas on vaskesta."],[48,5,"Minä olen sen ilmoittanut ennen, ja olen sinun antanut kuulla, ennenkuin se tulikaan, ettes sanoisi: epäjumalani sen tekee, ja kuvani ja epäjumalani on sen käskenyt.","Minä olen sen ilmoittanut ennen, ja olen sinun antanut kuulla, ennenkuin se tulikaan, ettes sanoisi: epäjumalani sen tekee, ja kuvani ja epäjumalani on sen käskenyt."],[48,6,"Kaikki nämät sinä kuulit ja näit, ja ette ole sitä ilmoittaneet; sillä minä olen edellä antanut sinun kuulla uusia ja salaisia, joita et sinä tietänyt.","Kaikki nämät sinä kuulit ja näit, ja ette ole sitä ilmoittaneet; sillä minä olen edellä antanut sinun kuulla uusia ja salaisia, joita et sinä tietänyt."],[48,7,"Mutta nyt on se luotu, ja ei siihen aikaan; ja et sinä ole kuullut päivääkään ennen, ettei sinun pitäisi sanoman: katso, sen minä hyvin tiesin;","Mutta nyt on se luotu, ja ei siihen aikaan; ja et sinä ole kuullut päivääkään ennen, ettei sinun pitäisi sanoman: katso, sen minä hyvin tiesin;"],[48,8,"Sillä et sinä sitä kuullut, etkä sinä tietänyt, ja sinun korvas ei ollut siihen aikaan avattu; sillä minä kyllä tiesin sinun peräti sen katsovan ylön, joka olet nimitetty rikkojaksi sinun äitis kohdusta.","Sillä et sinä sitä kuullut, etkä sinä tietänyt, ja sinun korvas ei ollut siihen aikaan avattu; sillä minä kyllä tiesin sinun peräti sen katsovan ylön, joka olet nimitetty rikkojaksi sinun äitis kohdusta."],[48,9,"Minun nimeni tähden olen minä pitkämielinen, ja minun ylistykseni tähden tahdon minä säästää sinua, ettes tulisi hävitetyksi.","Minun nimeni tähden olen minä pitkämielinen, ja minun ylistykseni tähden tahdon minä säästää sinua, ettes tulisi hävitetyksi."],[48,10,"Katso, minä tahdon koetella sinua, mutta ei niinkuin hopiata, vaan minä teen sinun valituksi murheen pätsissä.","Katso, minä tahdon koetella sinua, mutta ei niinkuin hopiata, vaan minä teen sinun valituksi murheen pätsissä."],[48,11,"Minun tähteni, tosin minun tähteni tahdon minä tehdä, etten minä häväistyksi tulisi; sillä en minä anna kunniatani toiselle.","Minun tähteni, tosin minun tähteni tahdon minä tehdä, etten minä häväistyksi tulisi; sillä en minä anna kunniatani toiselle."],[48,12,"Kuule minua, Jakob, ja sinä minun kutsuttuni Israel: minä olen, minä olen ensimmäinen ja viimeinen.","Kuule minua, Jakob, ja sinä minun kutsuttuni Israel: minä olen, minä olen ensimmäinen ja viimeinen."],[48,13,"Minun käteni on myös perustanut maan ja minun oikia käteni on kämmenellä mitannut taivaan: mitä minä kutsun, se on kohta valmis.","Minun käteni on myös perustanut maan ja minun oikia käteni on kämmenellä mitannut taivaan: mitä minä kutsun, se on kohta valmis."],[48,14,"Kootkaat teitänne kaiki ja kuulkaat, kuka on heidän seassansa näitä ilmoittanut? Herra rakastaa häntä, sentähden on hän osoittava tahtonsa Babelissa, ja käsivartensa Kaldealaisissa.","Kootkaat teitänne kaiki ja kuulkaat, kuka on heidän seassansa näitä ilmoittanut? Herra rakastaa häntä, sentähden on hän osoittava tahtonsa Babelissa, ja käsivartensa Kaldealaisissa."],[48,15,"Minä, minä olen sen sanonut; minä olen hänen kutsunut, ja hänen johdattanut, ja hänen tiensä menestyy hänelle.","Minä, minä olen sen sanonut; minä olen hänen kutsunut, ja hänen johdattanut, ja hänen tiensä menestyy hänelle."],[48,16,"Tulkaat tänne minun tyköni, ja kuulkaat tätä: en minä ole ennen salaa puhunut, siitä ajasta, kuin se oli puhuttu, olin minä siellä; ja nyt lähetti minun Herra, Herra, ja hänen henkensä.","Tulkaat tänne minun tyköni, ja kuulkaat tätä: en minä ole ennen salaa puhunut, siitä ajasta, kuin se oli puhuttu, olin minä siellä; ja nyt lähetti minun Herra, Herra, ja hänen henkensä."],[48,17,"Näin sanoo Herra sinun pelastajas, Israelin Pyhä: minä olen Herra sinun Jumalas, joka sinulle opetan mikä tarpeellinen on, ja johdatan sinua tietä, jotas käyt.","Näin sanoo Herra sinun pelastajas, Israelin Pyhä: minä olen Herra sinun Jumalas, joka sinulle opetan mikä tarpeellinen on, ja johdatan sinua tietä, jotas käyt."],[48,18,"O jospa sinä pitäisit minun käskyistäni vaarin! niin sinun rauhas olis niinkuin virta, ja vanhurskautes niinkuin meren aalto.","O jospa sinä pitäisit minun käskyistäni vaarin! niin sinun rauhas olis niinkuin virta, ja vanhurskautes niinkuin meren aalto."],[48,19,"Ja sinun siemenes olis niinkuin santa ja kohtus hedelmä niinkuin hänen someronsa; joiden nimeä ei pitäisi hävitettämän eli pyyhittämän pois minun edestäni.","Ja sinun siemenes olis niinkuin santa ja kohtus hedelmä niinkuin hänen someronsa; joiden nimeä ei pitäisi hävitettämän eli pyyhittämän pois minun edestäni."],[48,20,"Lähtekäät Babelista, paetkaat Kaldealaisten tyköä iloisella äänellä, ilmoittakaat ja kuuluttakaat tätä, viekäät se aina maailman ääriin, ja sanokaat: Herra on pelastanut palveliansa Jakobin.","Lähtekäät Babelista, paetkaat Kaldealaisten tyköä iloisella äänellä, ilmoittakaat ja kuuluttakaat tätä, viekäät se aina maailman ääriin, ja sanokaat: Herra on pelastanut palveliansa Jakobin."],[48,21,"Ei heitä jano vaivannut, kuin hän johdatti heitä korvessa, hän antoi heille vuotaa vettä kalliosta; hän halkasi kallion, ja siitä vuosi vesi.","Ei heitä jano vaivannut, kuin hän johdatti heitä korvessa, hän antoi heille vuotaa vettä kalliosta; hän halkasi kallion, ja siitä vuosi vesi."],[48,22,"Mutta jumalattomalla, sanoo Herra, ei ole rauhaa.","Mutta jumalattomalla, sanoo Herra, ei ole rauhaa."],[49,1,"Kuulkaat minua, te luodot, ja te kaukaiset kansat, ottakaat vaari: Herra on minun äidin kohdusta kutsunut, hän muisti minun nimeni, kuin minä vielä äitini kohdussa olin,","Kuulkaat minua, te luodot, ja te kaukaiset kansat, ottakaat vaari: Herra on minun äidin kohdusta kutsunut, hän muisti minun nimeni, kuin minä vielä äitini kohdussa olin,"],[49,2,"Ja teki minun suuni niinkuin terävän miekan, kätensä varjolla hän minua peitti; ja pani minun kiiltäväksi nuoleksi; pisti minun viineensä,","Ja teki minun suuni niinkuin terävän miekan, kätensä varjolla hän minua peitti; ja pani minun kiiltäväksi nuoleksi; pisti minun viineensä,"],[49,3,"Ja sanoi minulle: sinä olet minun palveliani; Israel, sinussa minä kunnioitetaan.","Ja sanoi minulle: sinä olet minun palveliani; Israel, sinussa minä kunnioitetaan."],[49,4,"Mutta minä sanoin: hukkaan minä työtä tein, turhaan ja tyhjään minä tässä kulutin väkeni; kuitenkin on minun asiani Herran kanssa, ja minun työni on minun Jumalani kanssa.","Mutta minä sanoin: hukkaan minä työtä tein, turhaan ja tyhjään minä tässä kulutin väkeni; kuitenkin on minun asiani Herran kanssa, ja minun työni on minun Jumalani kanssa."],[49,5,"Ja nyt sanoo Herra, joka loi minun äidin kohdusta itsellensä palveliaksi, palauttamaan Jakobin hänelle, ettei Israel hukkuisi: sentähden olen minä kaunis Herran edessä, ja minun Jumalani on minun väkevyyteni.","Ja nyt sanoo Herra, joka loi minun äidin kohdusta itsellensä palveliaksi, palauttamaan Jakobin hänelle, ettei Israel hukkuisi: sentähden olen minä kaunis Herran edessä, ja minun Jumalani on minun väkevyyteni."],[49,6,"Ja hän sanoi: vähä se on, ettäs olet minun palveliani, korjaamassa Jakobin sukukuntia, ja tuomassa jälleen Israelin hajoitettuja; mutta minä panin sinun myös pakanain valkeudeksi, olemaan minun autuuteni hamaan maailman ääriin.","Ja hän sanoi: vähä se on, ettäs olet minun palveliani, korjaamassa Jakobin sukukuntia, ja tuomassa jälleen Israelin hajoitettuja; mutta minä panin sinun myös pakanain valkeudeksi, olemaan minun autuuteni hamaan maailman ääriin."],[49,7,"Näin puhuu Herra Israelin lunastaja, hänen Pyhänsä, ylönkatsotuille sieluille, sille kansalle, josta me kauhistumme, sille palvelialle, joka tuimain herrain alla on: kuningasten pitää näkemän ja nouseman, päämiesten pitää rukoileman Herran tähden, joka uskollinen on, Israelin Pyhän tähden, joka sinun valinnut on.","Näin puhuu Herra Israelin lunastaja, hänen Pyhänsä, ylönkatsotuille sieluille, sille kansalle, josta me kauhistumme, sille palvelialle, joka tuimain herrain alla on: kuningasten pitää näkemän ja nouseman, päämiesten pitää rukoileman Herran tähden, joka uskollinen on, Israelin Pyhän tähden, joka sinun valinnut on."],[49,8,"Näin sanoo Herra: minä olen sinun rukoukses otollisella ajalla kuullut, ja olen autuuden päivänä sinua auttanut; ja olen varjellut sinua, ja liitoksi kansain sekaan olen sinun säätänyt, korjaamaan maata, ja haaskatuita perimisiä omistamaan,","Näin sanoo Herra: minä olen sinun rukoukses otollisella ajalla kuullut, ja olen autuuden päivänä sinua auttanut; ja olen varjellut sinua, ja liitoksi kansain sekaan olen sinun säätänyt, korjaamaan maata, ja haaskatuita perimisiä omistamaan,"],[49,9,"Sanomaan vangituille: menkäät ulos, ja jotka pimiässä ovat: tulkaat edes, että he teiden ohessa heitänsä elättäisivät, ja saisivat joka kukkulalla elatuksensa.","Sanomaan vangituille: menkäät ulos, ja jotka pimiässä ovat: tulkaat edes, että he teiden ohessa heitänsä elättäisivät, ja saisivat joka kukkulalla elatuksensa."],[49,10,"Ei heidän pidä isooman eikä janooman, ei helle eikä aurinko pidä heitä polttaman; sillä heidän armahtajansa johdattaa heitä, ja vie heitä vesilähteille.","Ei heidän pidä isooman eikä janooman, ei helle eikä aurinko pidä heitä polttaman; sillä heidän armahtajansa johdattaa heitä, ja vie heitä vesilähteille."],[49,11,"Ja minä panen kaikki vuoreni tieksi, ja minun polkuni pitää korotettaman.","Ja minä panen kaikki vuoreni tieksi, ja minun polkuni pitää korotettaman."],[49,12,"Katso, nämät tulevat kaukaa, ja katso, nämät pohjan puolesta, nämät etelän puolesta, ja muut Sinimin maalta.","Katso, nämät tulevat kaukaa, ja katso, nämät pohjan puolesta, nämät etelän puolesta, ja muut Sinimin maalta."],[49,13,"Iloitkaat te taivaat, riemuitse sinä maa, kiittäkäät te vuoret ihastuksella; sillä Herra on kansaansa lohduttanut, ja on raadollisiansa armahtanut.","Iloitkaat te taivaat, riemuitse sinä maa, kiittäkäät te vuoret ihastuksella; sillä Herra on kansaansa lohduttanut, ja on raadollisiansa armahtanut."],[49,14,"Mutta Zion sanoo: Herra hylkäsi minun, Herra unohti minun.","Mutta Zion sanoo: Herra hylkäsi minun, Herra unohti minun."],[49,15,"Unohtaako vaimo lapsukaisensa, niin ettei hän armahda kohtunsa poikaa? ja vaikka hän unohtais, niin en minä kuitenkaan sinua unohda.","Unohtaako vaimo lapsukaisensa, niin ettei hän armahda kohtunsa poikaa? ja vaikka hän unohtais, niin en minä kuitenkaan sinua unohda."],[49,16,"Katso, käsiini olen minä sinun pyhältänyt; sinun muuris ovat alati minun silmäini edessä.","Katso, käsiini olen minä sinun pyhältänyt; sinun muuris ovat alati minun silmäini edessä."],[49,17,"Sinun rakentajas rientävät; mutta sinun kukistajas ja hävittäjäs pitää pakeneman sinusta pois.","Sinun rakentajas rientävät; mutta sinun kukistajas ja hävittäjäs pitää pakeneman sinusta pois."],[49,18,"Nosta silmäs ympäri ja katso, kaikki nämät kootut tulevat sinun tykös. Niin totta kuin minä elän, sanoo Herra, sinun pitää kaikilla näillä niinkuin kaunistuksella itses puettaman, ja sinä käärit ne ympärilles niinkuin morsian;","Nosta silmäs ympäri ja katso, kaikki nämät kootut tulevat sinun tykös. Niin totta kuin minä elän, sanoo Herra, sinun pitää kaikilla näillä niinkuin kaunistuksella itses puettaman, ja sinä käärit ne ympärilles niinkuin morsian;"],[49,19,"Sillä sinun autio, hävitetty ja turmeltu maas pitää silloin ahdas oleman asuakses, kuin sinun raatelias sinusta kauvas pakenevat,","Sillä sinun autio, hävitetty ja turmeltu maas pitää silloin ahdas oleman asuakses, kuin sinun raatelias sinusta kauvas pakenevat,"],[49,20,"Niin että sinun hedelmättömyytes lapset pitää vielä korviis sanoman: ahdas on minulla sia, istu puolees, että minäkin asuisin sinun tykönäs.","Niin että sinun hedelmättömyytes lapset pitää vielä korviis sanoman: ahdas on minulla sia, istu puolees, että minäkin asuisin sinun tykönäs."],[49,21,"Mutta sinä olet sanova sydämessäs: kuka nämät minulle synnytti? sillä minä olen hedelmätöin, yksinäinen, ajettu pois ja syösty ulos. Kuka nämät on minulle kasvattanut? katso, minä olen yksinäni jätetty, kussa nämät silloin olivat?","Mutta sinä olet sanova sydämessäs: kuka nämät minulle synnytti? sillä minä olen hedelmätöin, yksinäinen, ajettu pois ja syösty ulos. Kuka nämät on minulle kasvattanut? katso, minä olen yksinäni jätetty, kussa nämät silloin olivat?"],[49,22,"Näin sanoo Herra, Herra: katso, minä nostan käteni pakanain puoleen, ja korotan lippuni kansain puoleen, niin he tuovat edes helmassansa sinun poikias, ja sinun tyttäriäs hartioilla kannetaan.","Näin sanoo Herra, Herra: katso, minä nostan käteni pakanain puoleen, ja korotan lippuni kansain puoleen, niin he tuovat edes helmassansa sinun poikias, ja sinun tyttäriäs hartioilla kannetaan."],[49,23,"Ja kuninkaat pitää oleman sinun holhojas, ja heidän kuningattarensa sinun imettäjäs, heidän pitää lankeeman kasvoillensa maahan sinun edessäs, ja nuoleskelemaan sinun jalkais tomua. Silloin sinä tiedät, että minä olen Herra, ja ettei kenkään tule häpiään, joka minua toivoo.","Ja kuninkaat pitää oleman sinun holhojas, ja heidän kuningattarensa sinun imettäjäs, heidän pitää lankeeman kasvoillensa maahan sinun edessäs, ja nuoleskelemaan sinun jalkais tomua. Silloin sinä tiedät, että minä olen Herra, ja ettei kenkään tule häpiään, joka minua toivoo."],[49,24,"Otetaanko saalis väkevältä pois? taitaako joku päästää hurskaan vangit?","Otetaanko saalis väkevältä pois? taitaako joku päästää hurskaan vangit?"],[49,25,"Sillä näin sanoo Herra: nyt pitää vangit väkevältä otettaman pois, ja tuimain saalis irralle pääsemän; ja minä tahdon riidellä sinun riitaveljeis kanssa, ja varjella sinun lapsias.","Sillä näin sanoo Herra: nyt pitää vangit väkevältä otettaman pois, ja tuimain saalis irralle pääsemän; ja minä tahdon riidellä sinun riitaveljeis kanssa, ja varjella sinun lapsias."],[49,26,"Ja minä annan sinun hävittäjäs syödä omaa lihaansa, ja heidän pitää juopuman omasta verestänsä, niinkuin makiasta viinasta; ja kaikki liha pitää tietämän, että minä olen Herra, sinun auttajas ja sinun lunastajas, Jakobin väkevä.","Ja minä annan sinun hävittäjäs syödä omaa lihaansa, ja heidän pitää juopuman omasta verestänsä, niinkuin makiasta viinasta; ja kaikki liha pitää tietämän, että minä olen Herra, sinun auttajas ja sinun lunastajas, Jakobin väkevä."],[50,1,"Näin sanoo Herra: kussa on äitinne erokirja, jolla minä olen hänen hyljännyt? eli kuka on minun korkorahani kantaja, jolle minä teidät olen myynyt? Katso, te olette synteinne tähden myydyt, ja äitinne on teidän rikostenne tähden hyljätty.","Näin sanoo Herra: kussa on äitinne erokirja, jolla minä olen hänen hyljännyt? eli kuka on minun korkorahani kantaja, jolle minä teidät olen myynyt? Katso, te olette synteinne tähden myydyt, ja äitinne on teidän rikostenne tähden hyljätty."],[50,2,"Miksi minä tulin, ja ei ollut siellä ketään? Minä huusin, ja ei yksikään vastannut? onko minun käteni niin peräti lyhentynyt, ettei hän voi pelastaa? ja eikö minulla ole voimaa vapahtaa? Katso, nuhtelemisellani teen minä meren kuivaksi, ja teen virrat korveksi, niin että kalat haisevat veden puuttumisen tähden ja kuolevat janosta.","Miksi minä tulin, ja ei ollut siellä ketään? Minä huusin, ja ei yksikään vastannut? onko minun käteni niin peräti lyhentynyt, ettei hän voi pelastaa? ja eikö minulla ole voimaa vapahtaa? Katso, nuhtelemisellani teen minä meren kuivaksi, ja teen virrat korveksi, niin että kalat haisevat veden puuttumisen tähden ja kuolevat janosta."],[50,3,"Minä puetan taivaan pimeydellä, ja teen hänen peitteensä niinkuin säkin.","Minä puetan taivaan pimeydellä, ja teen hänen peitteensä niinkuin säkin."],[50,4,"Herra, Herra antoi minulle oppineen kielen, taitaakseni puhua väsyneille ajallansa. Hän herättää minun joka aamu, hän herättää minulle korvan kuulemaan niinkuin opetuslapsen.","Herra, Herra antoi minulle oppineen kielen, taitaakseni puhua väsyneille ajallansa. Hän herättää minun joka aamu, hän herättää minulle korvan kuulemaan niinkuin opetuslapsen."],[50,5,"Herra, Herra avasi minulle korvan, ja en ole minä tottelematoin, enkä mene takaperin.","Herra, Herra avasi minulle korvan, ja en ole minä tottelematoin, enkä mene takaperin."],[50,6,"Minä annoin selkäni niille, jotka minua pieksivät, ja poskeni niille, jotka minua repelivät; en minä kääntänyt kasvojani pois häväistyksistä ja syljestä.","Minä annoin selkäni niille, jotka minua pieksivät, ja poskeni niille, jotka minua repelivät; en minä kääntänyt kasvojani pois häväistyksistä ja syljestä."],[50,7,"Ja Herra, Herra minua auttaa, sentähden en minä tule häpiään; sentähden panin minä kasvoni niinkuin limsiön, sillä minä tiedän, etten minä tule häpiään.","Ja Herra, Herra minua auttaa, sentähden en minä tule häpiään; sentähden panin minä kasvoni niinkuin limsiön, sillä minä tiedän, etten minä tule häpiään."],[50,8,"Se on läsnä, joka minun vanhurskauttaa; kuka tahtoo riidellä minun kanssani? Seisokaamme ynnä; kellä on oikeus minua vastaan, se tulkoon tänne minun tyköni.","Se on läsnä, joka minun vanhurskauttaa; kuka tahtoo riidellä minun kanssani? Seisokaamme ynnä; kellä on oikeus minua vastaan, se tulkoon tänne minun tyköni."],[50,9,"Katso, Herra, Herra auttaa minua, kuka tahtoo minua kadottaa? Katso, ne kaikki vanhenevat niinkuin vaate, koit syövät heidät.","Katso, Herra, Herra auttaa minua, kuka tahtoo minua kadottaa? Katso, ne kaikki vanhenevat niinkuin vaate, koit syövät heidät."],[50,10,"Kuka on teidän seassanne, joka pelkää Herraa, joka hänen palveliansa ääntä kuultelee. Joka pimeydessä vaeltaa, ja ei näe valkeutta, se toivokaan Herran nimen päälle, ja luottakaan Jumalansa päälle.","Kuka on teidän seassanne, joka pelkää Herraa, joka hänen palveliansa ääntä kuultelee. Joka pimeydessä vaeltaa, ja ei näe valkeutta, se toivokaan Herran nimen päälle, ja luottakaan Jumalansa päälle."],[50,11,"Katso, te kaikki, jotka tulen sytytätte, jotka olette liekillä hankitut, vaeltakaat teidän tulenne valkeudessa, ja siinä liekissä, jonka te sytytitte. Se tapahtuu teille minun kädestäni; kivussa täytyy teidän levätä.","Katso, te kaikki, jotka tulen sytytätte, jotka olette liekillä hankitut, vaeltakaat teidän tulenne valkeudessa, ja siinä liekissä, jonka te sytytitte. Se tapahtuu teille minun kädestäni; kivussa täytyy teidän levätä."],[51,1,"Kuulkaat minua te, jotka vanhurskautta noudatatte, te jotka Herraa etsitte. Katsokaat sitä kalliota, josta te lohaistut olette, ja sitä kaivoa, josta te kaivetut olette.","Kuulkaat minua te, jotka vanhurskautta noudatatte, te jotka Herraa etsitte. Katsokaat sitä kalliota, josta te lohaistut olette, ja sitä kaivoa, josta te kaivetut olette."],[51,2,"Katsokaat Abrahamia teidän isäänne, ja Saaraa, joka teidät synnytti; sillä minä kutsuin hänen, kuin hän oli vielä yksinäinen, siunasin ja enensin hänen.","Katsokaat Abrahamia teidän isäänne, ja Saaraa, joka teidät synnytti; sillä minä kutsuin hänen, kuin hän oli vielä yksinäinen, siunasin ja enensin hänen."],[51,3,"Sillä Herra lohduttaa Zionia, hän lohduttaa kaiken hänen aukiutensa, ja tekee hänen aukiutensa niinkuin Edenin, ja hänen erämaansa niinkuin Herran yrttitarhan; että siellä löytään ilo ja riemu, kiitos ja veisun ääni.","Sillä Herra lohduttaa Zionia, hän lohduttaa kaiken hänen aukiutensa, ja tekee hänen aukiutensa niinkuin Edenin, ja hänen erämaansa niinkuin Herran yrttitarhan; että siellä löytään ilo ja riemu, kiitos ja veisun ääni."],[51,4,"Ottakaat minusta vaari, minun kansani, ja kuulkaat minua minun sukukuntani; sillä minulta on laki käyvä ulos, ja minä panen oikeuteni kansoille valkeudeksi.","Ottakaat minusta vaari, minun kansani, ja kuulkaat minua minun sukukuntani; sillä minulta on laki käyvä ulos, ja minä panen oikeuteni kansoille valkeudeksi."],[51,5,"Minun vanhurskauteni on läsnä, minun autuuteni käy ulos, ja minun käsivarteni on kansoja tuomitseva. Luodot odottavat minua, ja vartioitsevat minun käsivarttani.","Minun vanhurskauteni on läsnä, minun autuuteni käy ulos, ja minun käsivarteni on kansoja tuomitseva. Luodot odottavat minua, ja vartioitsevat minun käsivarttani."],[51,6,"Nostakaat teidän silmänne taivaasen, ja katsokaat alas maan päälle; sillä taivas on katoova niinkuin savu, ja maa vanhenee niinkuin vaate, niin myös sen asuvaiset kuolevat; mutta minun autuuteni pysyy ijankaikkisesti, ja minun vanhurskauteni ei ole puuttuva.","Nostakaat teidän silmänne taivaasen, ja katsokaat alas maan päälle; sillä taivas on katoova niinkuin savu, ja maa vanhenee niinkuin vaate, niin myös sen asuvaiset kuolevat; mutta minun autuuteni pysyy ijankaikkisesti, ja minun vanhurskauteni ei ole puuttuva."],[51,7,"Kuulkaat minua te, jotka vanhurskauden tunnette, kansa, jonka sydämessä minun lakini on. Älkäät peljätkö, kussa ihmiset teitä häpäisevät, ja älkäät vavisko, kuin he teitä pilkkaavat.","Kuulkaat minua te, jotka vanhurskauden tunnette, kansa, jonka sydämessä minun lakini on. Älkäät peljätkö, kussa ihmiset teitä häpäisevät, ja älkäät vavisko, kuin he teitä pilkkaavat."],[51,8,"Sillä koin pitää heitä syömän niinkuin vaatetta, ja madot pitää heidän syömän niinkuin villaisia; mutta minun vanhurskauteni pysyy ijankaikkisesti, ja minun autuuteni suvusta sukuun.","Sillä koin pitää heitä syömän niinkuin vaatetta, ja madot pitää heidän syömän niinkuin villaisia; mutta minun vanhurskauteni pysyy ijankaikkisesti, ja minun autuuteni suvusta sukuun."],[51,9,"Ylös, ylös, pue päälles väkevyyttä, sinä Herran käsivarsi; ylös, niinkuin muinen vanhaan aikaan. Etkös se ole, joka löit ylpiän, ja haavoitit lohikärmeen?","Ylös, ylös, pue päälles väkevyyttä, sinä Herran käsivarsi; ylös, niinkuin muinen vanhaan aikaan. Etkös se ole, joka löit ylpiän, ja haavoitit lohikärmeen?"],[51,10,"Etkös se ole, joka meren, suuren syvän veden kuivasit? joka syvän meren tieksi teit, että lunastetut kävivät sitä myöten.","Etkös se ole, joka meren, suuren syvän veden kuivasit? joka syvän meren tieksi teit, että lunastetut kävivät sitä myöten."],[51,11,"Niin Herran lunastetut palajavat ja tulevat Zioniin riemulla, ja ijankaikkinen ilo on heidän päänsä päällä oleva; ilon ja riemun he käsittävät, murhe ja huokaus pakenee heitä.","Niin Herran lunastetut palajavat ja tulevat Zioniin riemulla, ja ijankaikkinen ilo on heidän päänsä päällä oleva; ilon ja riemun he käsittävät, murhe ja huokaus pakenee heitä."],[51,12,"Minä, minä olen teidän lohduttajanne; kuka siis sinä olet, ettäs kuolevaista ihmistä pelkäät, ja ihmisten lapsia, jotka kulutetaan niinkuin heinä?","Minä, minä olen teidän lohduttajanne; kuka siis sinä olet, ettäs kuolevaista ihmistä pelkäät, ja ihmisten lapsia, jotka kulutetaan niinkuin heinä?"],[51,13,"Ja unohdat Herran, joka sinun tehnyt on, joka taivaat levittää, ja maan perustaa? Mutta sinä pelkäät alati yli päivää vaivaajan julmuutta, kuin hän rupee hukuttamaan. Ja kuhunka jäi vaivaajan julmuus?","Ja unohdat Herran, joka sinun tehnyt on, joka taivaat levittää, ja maan perustaa? Mutta sinä pelkäät alati yli päivää vaivaajan julmuutta, kuin hän rupee hukuttamaan. Ja kuhunka jäi vaivaajan julmuus?"],[51,14,"Koska hän vaadittiin rientämään ja juoksemaan ympäri, että hän päästäis, ettei he kuolisi kadotukseen, eikä hänen leipänsä puuttuisi?","Koska hän vaadittiin rientämään ja juoksemaan ympäri, että hän päästäis, ettei he kuolisi kadotukseen, eikä hänen leipänsä puuttuisi?"],[51,15,"Sillä minä olen Herra sinun Jumalas, joka meren liikutan, että sen aallot pauhaavat: hänen nimensä on Herra Zebaot.","Sillä minä olen Herra sinun Jumalas, joka meren liikutan, että sen aallot pauhaavat: hänen nimensä on Herra Zebaot."],[51,16,"Minä panen sanani sinun suuhus, ja peitän sinun käteni varjolla, että minä taivaan istuttaisin, ja maan perustaisin ja sanoisin Zionille: sinä olet minun kansani.","Minä panen sanani sinun suuhus, ja peitän sinun käteni varjolla, että minä taivaan istuttaisin, ja maan perustaisin ja sanoisin Zionille: sinä olet minun kansani."],[51,17,"Herää, herää, nouse Jerusalem, joka joit Herran kädestä hänen vihansa kalkin, sen kompastuskalkin rahkan olet sinä juonut ja särkenyt ulos.","Herää, herää, nouse Jerusalem, joka joit Herran kädestä hänen vihansa kalkin, sen kompastuskalkin rahkan olet sinä juonut ja särkenyt ulos."],[51,18,"Ei kenkään hänen pojistansa, jotka hän oli synnyttänyt, häntä holhonnut: eikä kenkään kaikista hänen lapsistansa, jotka hän oli kasvattanut, hänen käteensä ruvennut.","Ei kenkään hänen pojistansa, jotka hän oli synnyttänyt, häntä holhonnut: eikä kenkään kaikista hänen lapsistansa, jotka hän oli kasvattanut, hänen käteensä ruvennut."],[51,19,"Nämät kaksi sinua kohtasivat, kuka sinua armahti? hävitys, vahinko, nälkä ja miekka: millä minä sinua lohdutan?","Nämät kaksi sinua kohtasivat, kuka sinua armahti? hävitys, vahinko, nälkä ja miekka: millä minä sinua lohdutan?"],[51,20,"Sinun lapses olivat pintuneet ja makasivat kaikissa katujen päissä, niinkuin paulalla sidottu metsähärkä, täynnä Herran vihaa ja sinun Jumalas rangaistusta.","Sinun lapses olivat pintuneet ja makasivat kaikissa katujen päissä, niinkuin paulalla sidottu metsähärkä, täynnä Herran vihaa ja sinun Jumalas rangaistusta."],[51,21,"Sentähden kuule nyt tätä sinä raadollinen, ja sinä juopunut ilman viinaa.","Sentähden kuule nyt tätä sinä raadollinen, ja sinä juopunut ilman viinaa."],[51,22,"Näin sanoo Herra, sinun Herras ja sinun Jumalas, joka kansansa edestä sotii: katso, minä otan kompastuskalkin sinun kädestäs, ja minun vihani kalkin rahkan; ei sinun pidä sitä enään juoman.","Näin sanoo Herra, sinun Herras ja sinun Jumalas, joka kansansa edestä sotii: katso, minä otan kompastuskalkin sinun kädestäs, ja minun vihani kalkin rahkan; ei sinun pidä sitä enään juoman."],[51,23,"Vaan minä panen sen sinun raateliais käteen, jotka sanoivat sinun sielulles: kumarra sinus, että me kävisimme sinun ylitses, ja pane sinun selkäs maahan, että niinkuin katua myöten sen ylitse mentäisiin.","Vaan minä panen sen sinun raateliais käteen, jotka sanoivat sinun sielulles: kumarra sinus, että me kävisimme sinun ylitses, ja pane sinun selkäs maahan, että niinkuin katua myöten sen ylitse mentäisiin."],[52,1,"Nouse, nouse, Zion, pue väkevyytes päälles, kaunista sinuas jalosti, sinä pyhä kaupunki Jerusalem; sillä ei tästedes yksikään ympärileikkaamatoin eikä saastainen pidä sinussa hallitseman.","Nouse, nouse, Zion, pue väkevyytes päälles, kaunista sinuas jalosti, sinä pyhä kaupunki Jerusalem; sillä ei tästedes yksikään ympärileikkaamatoin eikä saastainen pidä sinussa hallitseman."],[52,2,"Puhdista itses tomusta, nouse ja istu Jerusalem; päästä sinuas kahleista, sinä vangittu Zionin tytär.","Puhdista itses tomusta, nouse ja istu Jerusalem; päästä sinuas kahleista, sinä vangittu Zionin tytär."],[52,3,"Sillä näin sanoo Herra: te olette tyhjään myydyt, ja ilman rahaa te lunastetaan.","Sillä näin sanoo Herra: te olette tyhjään myydyt, ja ilman rahaa te lunastetaan."],[52,4,"Sillä näin sanoo Herra, Herra: minun kansani meni ensin alas Egyptiin, olemaan siellä vieraana; ja Assur on heille väkivaltaa tehnyt ilman syytä.","Sillä näin sanoo Herra, Herra: minun kansani meni ensin alas Egyptiin, olemaan siellä vieraana; ja Assur on heille väkivaltaa tehnyt ilman syytä."],[52,5,"Vaan mitä nyt minulle tämän edestä tehdään? sanoo Herra; sillä minun kansani ilman syytä viedään pois? että ne, jotka heitä hallitsevat, saattavat heidät itkemään, sanoo Herra, ja minun nimeäni pilkataan päivä päivältä.","Vaan mitä nyt minulle tämän edestä tehdään? sanoo Herra; sillä minun kansani ilman syytä viedään pois? että ne, jotka heitä hallitsevat, saattavat heidät itkemään, sanoo Herra, ja minun nimeäni pilkataan päivä päivältä."],[52,6,"Sentähden pitää minun kansani sinä päivänä minun nimeni tunteman, että minä itse olen se, joka puhun, katso, minä se olen.","Sentähden pitää minun kansani sinä päivänä minun nimeni tunteman, että minä itse olen se, joka puhun, katso, minä se olen."],[52,7,"O kuinka suloiset ovat evankeliumin saarnaajain jalat vuorilla, jotka rauhaa julistavat, jotka hyvää saarnaavat, autuuden ilmoittavat, jotka Zionille sanovat: sinun Jumalas on kuningas.","O kuinka suloiset ovat evankeliumin saarnaajain jalat vuorilla, jotka rauhaa julistavat, jotka hyvää saarnaavat, autuuden ilmoittavat, jotka Zionille sanovat: sinun Jumalas on kuningas."],[52,8,"Sinun vartias huutavat korkiasti ja iloitsevat ynnä, sillä se nähdään ilmeisesti, koska Herra kääntää Zionin.","Sinun vartias huutavat korkiasti ja iloitsevat ynnä, sillä se nähdään ilmeisesti, koska Herra kääntää Zionin."],[52,9,"Iloitkaat ja riemuitkaat ynnä, te Jerusalemin autiot; sillä Herra on kansaansa lohduttanut, ja Jerusalemin päästänyt.","Iloitkaat ja riemuitkaat ynnä, te Jerusalemin autiot; sillä Herra on kansaansa lohduttanut, ja Jerusalemin päästänyt."],[52,10,"Herra on ilmoittanut pyhän käsivartensa kaikkein pakanain silmäin edessä, niin että kaikki maailman ääret näkevät meidän Jumalamme autuuden.","Herra on ilmoittanut pyhän käsivartensa kaikkein pakanain silmäin edessä, niin että kaikki maailman ääret näkevät meidän Jumalamme autuuden."],[52,11,"Paetkaat, paetkaat, lähtekäät sieltä, ja älkäät mihinkään saastaiseen sattuko; menkäät ulos heidän tyköänsä, puhdistakaat teitänne, te jotka Herran kalua kannatte.","Paetkaat, paetkaat, lähtekäät sieltä, ja älkäät mihinkään saastaiseen sattuko; menkäät ulos heidän tyköänsä, puhdistakaat teitänne, te jotka Herran kalua kannatte."],[52,12,"Sillä ei teidän pidä lähtemän nopiasti, eli vaeltaman pakenemisella; sillä Herra on lähtevä teidän edellänne, ja Israelin Jumala on kokoova teitä.","Sillä ei teidän pidä lähtemän nopiasti, eli vaeltaman pakenemisella; sillä Herra on lähtevä teidän edellänne, ja Israelin Jumala on kokoova teitä."],[52,13,"Katso, minun palveliani tekee toimellisesti: hän korotetaan, nostetaan ylös, ja tulee sangen korkiaksi.","Katso, minun palveliani tekee toimellisesti: hän korotetaan, nostetaan ylös, ja tulee sangen korkiaksi."],[52,14,"Niin että moni sinun ylitses hämmästyy, että hänen muotonsa on rumempi muita ihmisiä, ja hänen hahmonsa huonompi kuin ihmisten lasten.","Niin että moni sinun ylitses hämmästyy, että hänen muotonsa on rumempi muita ihmisiä, ja hänen hahmonsa huonompi kuin ihmisten lasten."],[52,15,"Mutta niin on hän monta pakanaa priiskottava, että myös kuningasten täytyy suunsa hänen edessänsä tukita; sillä joille ei mitään hänestä ilmoitettu ollut, nekin hänen ilolla näkevät, ja jota ei he kuulleet ole, sen ne ymmärtävät.","Mutta niin on hän monta pakanaa priiskottava, että myös kuningasten täytyy suunsa hänen edessänsä tukita; sillä joille ei mitään hänestä ilmoitettu ollut, nekin hänen ilolla näkevät, ja jota ei he kuulleet ole, sen ne ymmärtävät."],[53,1,"Kuka uskoo meidän saarnamme, ja kenelle Herran käsivarsi ilmoitetaan?","Kuka uskoo meidän saarnamme, ja kenelle Herran käsivarsi ilmoitetaan?"],[53,2,"Sillä hän nousee ylös hänen edessänsä niinkuin vesa, ja niinkuin juuri kuivasta maasta; ei hänellä ole muotoa, eikä kauneutta; me näimme hänen, vaan ei ollut hänellä sitä muotoa, joka meille olis kelvannut.","Sillä hän nousee ylös hänen edessänsä niinkuin vesa, ja niinkuin juuri kuivasta maasta; ei hänellä ole muotoa, eikä kauneutta; me näimme hänen, vaan ei ollut hänellä sitä muotoa, joka meille olis kelvannut."],[53,3,"Hän oli kaikkein ylönkatsottava ja kaikkein halvin, kipua ja sairautta täynnä. Hän oli niin ylönkatsottu, ettei kenkään kehdannut katsoa hänen päällensä, sentähden emme häntä minäkään pitäneet.","Hän oli kaikkein ylönkatsottava ja kaikkein halvin, kipua ja sairautta täynnä. Hän oli niin ylönkatsottu, ettei kenkään kehdannut katsoa hänen päällensä, sentähden emme häntä minäkään pitäneet."],[53,4,"Totisesti hän kantoi meidän sairautemme, ja meidän kipumme hän sälytti päällensä; mutta me pidimme hänen Jumalalta rangaistuna, piestynä ja vaivattuna.","Totisesti hän kantoi meidän sairautemme, ja meidän kipumme hän sälytti päällensä; mutta me pidimme hänen Jumalalta rangaistuna, piestynä ja vaivattuna."],[53,5,"Vaan hän on haavoitettu meidän pahain tekoimme tähden, ja meidän synteimme tähden on hän hosuttu. Rangaistus on hänen päällänsä, että meillä rauha olis, ja hänen haavainsa kautta olemme me parannetut.","Vaan hän on haavoitettu meidän pahain tekoimme tähden, ja meidän synteimme tähden on hän hosuttu. Rangaistus on hänen päällänsä, että meillä rauha olis, ja hänen haavainsa kautta olemme me parannetut."],[53,6,"Kaikki me vaelsimme eksyksissä niinkuin lampaat: itsekukin meistä poikkesi omalle tiellensä; mutta Herra heitti kaiken meidän vääryytemme hänen päällensä.","Kaikki me vaelsimme eksyksissä niinkuin lampaat: itsekukin meistä poikkesi omalle tiellensä; mutta Herra heitti kaiken meidän vääryytemme hänen päällensä."],[53,7,"Kuin hän rangaistiin ja vaivattiin, niin ei hän suutansa avannut; niinkuin karitsa, joka teuraaksi viedään, ja niinkuin lammas, joka keritsiänsä edessä vaikenee, niin ei hänkään suutansa avannut.","Kuin hän rangaistiin ja vaivattiin, niin ei hän suutansa avannut; niinkuin karitsa, joka teuraaksi viedään, ja niinkuin lammas, joka keritsiänsä edessä vaikenee, niin ei hänkään suutansa avannut."],[53,8,"Mutta hän on otettu pois ahdistuksesta ja tuomiosta; kuka taitaa sanoa hänen elämänsä pituuden? sillä hän on sivallettu pois eläväin maalta, kuin hän minun kansani pahain tekoin tähden rangaistiin.","Mutta hän on otettu pois ahdistuksesta ja tuomiosta; kuka taitaa sanoa hänen elämänsä pituuden? sillä hän on sivallettu pois eläväin maalta, kuin hän minun kansani pahain tekoin tähden rangaistiin."],[53,9,"Hänen hautansa aiottiin jumalattomain sekaan, rikkaan tykö tuli hän kuitenkin kuoltuansa. Ei hän kellenkään vääryyttä tehnyt, eikä petosta ollut hänen suussansa.","Hänen hautansa aiottiin jumalattomain sekaan, rikkaan tykö tuli hän kuitenkin kuoltuansa. Ei hän kellenkään vääryyttä tehnyt, eikä petosta ollut hänen suussansa."],[53,10,"Mutta Herra tahtoi hänen niin piestä sairaudella; koska hän on henkensä vikauhriksi antanut, niin hän saa nähdä siemenen ja elää kauvan, ja Herran aivoitus on hänen kädessänsä menestyvä.","Mutta Herra tahtoi hänen niin piestä sairaudella; koska hän on henkensä vikauhriksi antanut, niin hän saa nähdä siemenen ja elää kauvan, ja Herran aivoitus on hänen kädessänsä menestyvä."],[53,11,"Että hänen sielunsa on työtä tehnyt, saa hän ilonsa nähdä, ja tulee ravituksi. Tuntemisensa kautta minun vanhurskas palveliani monta vanhurskauttaa; sillä hän kantaa heidän syntinsä.","Että hänen sielunsa on työtä tehnyt, saa hän ilonsa nähdä, ja tulee ravituksi. Tuntemisensa kautta minun vanhurskas palveliani monta vanhurskauttaa; sillä hän kantaa heidän syntinsä."],[53,12,"Sentähden annan minä hänelle osan monessa, ja hänen pitää väkeväin kanssa saalista jakaman; sentähden että hän antoi henkensä kuolemaan, ja oli pahantekiäin sekaan luettu, ja hän kantoi monen synnit, ja rukoili pahantekiäin edestä.","Sentähden annan minä hänelle osan monessa, ja hänen pitää väkeväin kanssa saalista jakaman; sentähden että hän antoi henkensä kuolemaan, ja oli pahantekiäin sekaan luettu, ja hän kantoi monen synnit, ja rukoili pahantekiäin edestä."],[54,1,"Riemuitse sinä hedelmätöin, joka et synnytä: iloitse riemulla ja ihastu sinä, joka et raskas ole; sillä yksinäisellä on enempi lapsia kuin sillä, jolla mies on, sanoo Herra.","Riemuitse sinä hedelmätöin, joka et synnytä: iloitse riemulla ja ihastu sinä, joka et raskas ole; sillä yksinäisellä on enempi lapsia kuin sillä, jolla mies on, sanoo Herra."],[54,2,"Levitä majas sia, ja venytä asumises vaate, älä säästä; pitennä köytes, ja kiinnitä vaajas lujasti.","Levitä majas sia, ja venytä asumises vaate, älä säästä; pitennä köytes, ja kiinnitä vaajas lujasti."],[54,3,"Sillä sinun pitää oikialle ja vasemmalle puolelle levenemän, ja sinun siemenes pitää pakanat perimän, ja aukeissa kaupungeissa asuman.","Sillä sinun pitää oikialle ja vasemmalle puolelle levenemän, ja sinun siemenes pitää pakanat perimän, ja aukeissa kaupungeissa asuman."],[54,4,"Älä pelkää, sillä et sinä tule häpiään; älä ole kaino, sillä ei sinun pidä häpiään tuleman. Vaan sinun pitää nuoruutes häpiän unohtaman, ja sinun leskeytes kainoutta ei enään muistaman.","Älä pelkää, sillä et sinä tule häpiään; älä ole kaino, sillä ei sinun pidä häpiään tuleman. Vaan sinun pitää nuoruutes häpiän unohtaman, ja sinun leskeytes kainoutta ei enään muistaman."],[54,5,"Sillä joka sinun tehnyt on, hän on sinun miehes, Herra Zebaot on hänen nimensä; ja Israelin Pyhä sinun lunastajas, joka kaiken maailman Jumalaksi kutsutaan.","Sillä joka sinun tehnyt on, hän on sinun miehes, Herra Zebaot on hänen nimensä; ja Israelin Pyhä sinun lunastajas, joka kaiken maailman Jumalaksi kutsutaan."],[54,6,"Sillä Herra on kutsunut sinun niinkuin hyljätyn ja sydämestä murheellisen vaimon; ja sinä olit niinkuin nuori emäntä, joka hyljätty on, sanoo sinun Jumalas.","Sillä Herra on kutsunut sinun niinkuin hyljätyn ja sydämestä murheellisen vaimon; ja sinä olit niinkuin nuori emäntä, joka hyljätty on, sanoo sinun Jumalas."],[54,7,"Minä olen vähäksi silmänräpäykseksi sinun hyljännyt, mutta minä tahdon sinua suurella laupiudella koota.","Minä olen vähäksi silmänräpäykseksi sinun hyljännyt, mutta minä tahdon sinua suurella laupiudella koota."],[54,8,"Minä olen vihassani vähäksi silmänräpäykseksi kasvoni kätkenyt sinulta; mutta minä tahdon armahtaa sinua ijankaikkisessa armossa, sanoo Herra, sinun lunastajas.","Minä olen vihassani vähäksi silmänräpäykseksi kasvoni kätkenyt sinulta; mutta minä tahdon armahtaa sinua ijankaikkisessa armossa, sanoo Herra, sinun lunastajas."],[54,9,"Sillä tämä on minulle oleva niinkuin Noan vesi, josta minä vannoin, ettei Noan vedet pitänyt enään käymän maan ylitse: juuri niin olen minä nyt vannonut, ettei minun enään pidä sinulle vihastuman, eikä sinua rankaiseman.","Sillä tämä on minulle oleva niinkuin Noan vesi, josta minä vannoin, ettei Noan vedet pitänyt enään käymän maan ylitse: juuri niin olen minä nyt vannonut, ettei minun enään pidä sinulle vihastuman, eikä sinua rankaiseman."],[54,10,"Sillä vuoret pitää välttämän ja kukkulat lankeeman; mutta minun armoni ei pidä sinusta poikkeeman, ja minun rauhani liitto ei pidä lankeeman pois, sanoo Herra sinun armahtajas.","Sillä vuoret pitää välttämän ja kukkulat lankeeman; mutta minun armoni ei pidä sinusta poikkeeman, ja minun rauhani liitto ei pidä lankeeman pois, sanoo Herra sinun armahtajas."],[54,11,"Sinä raadollinen, kovalta tuulelta häälytetty, ja sinä turvatoin! katso, minä panen sinun kives niinkuin kaunistuksen, ja tahdon sinun perustukses saphireilla laskea,","Sinä raadollinen, kovalta tuulelta häälytetty, ja sinä turvatoin! katso, minä panen sinun kives niinkuin kaunistuksen, ja tahdon sinun perustukses saphireilla laskea,"],[54,12,"Ja sinun akkunas kristallista rakentaa, ja sinun porttis rubinista, ja kaikki sinun rajas valituista kivistä.","Ja sinun akkunas kristallista rakentaa, ja sinun porttis rubinista, ja kaikki sinun rajas valituista kivistä."],[54,13,"Ja kaikki sinun lapses pitää oleman opetetut Herralta, ja suuri rauha sinun lapsilles.","Ja kaikki sinun lapses pitää oleman opetetut Herralta, ja suuri rauha sinun lapsilles."],[54,14,"Vanhurskaudella pitää sinun valmistetuksi tuleman: sinun pitää oleman kaukana väkivallasta, ettei sinun pidä pelkäämän, ja hämmästyksestä; sillä ei sen pidä sinua lähestymän.","Vanhurskaudella pitää sinun valmistetuksi tuleman: sinun pitää oleman kaukana väkivallasta, ettei sinun pidä pelkäämän, ja hämmästyksestä; sillä ei sen pidä sinua lähestymän."],[54,15,"Katso, kuka tahtoo sinua vastaan koota ja sortaa sinua, jos he ilman minua kokoontuvat?","Katso, kuka tahtoo sinua vastaan koota ja sortaa sinua, jos he ilman minua kokoontuvat?"],[54,16,"Katso, minä teen sepän, joka hiilet tulessa lietsoo, ja tekee aseen työtänsä varten: niin minä myös teen raatelian hukuttamaan.","Katso, minä teen sepän, joka hiilet tulessa lietsoo, ja tekee aseen työtänsä varten: niin minä myös teen raatelian hukuttamaan."],[54,17,"Ei yksikään ase, joka valmistetaan sinua vastaan, pidä menestymän; ja kaikki kielet, jotka heitänsä asettavat sinua vastaan, pitää sinun tuomiollas kadotettaman. Tämä on Herran palveliain perimys, ja heidän vanhurskautensa minusta, sanoo Herra.","Ei yksikään ase, joka valmistetaan sinua vastaan, pidä menestymän; ja kaikki kielet, jotka heitänsä asettavat sinua vastaan, pitää sinun tuomiollas kadotettaman. Tämä on Herran palveliain perimys, ja heidän vanhurskautensa minusta, sanoo Herra."],[55,1,"Kaikki janoovaiset, tulkaat vetten tykö, tekin, joilla ei ole rahaa, tulkaat, ostakaat ja syökäät; tulkaat, ostakaat, ilman rahaa ja ilman hintaa, viinaa ja rieskaa.","Kaikki janoovaiset, tulkaat vetten tykö, tekin, joilla ei ole rahaa, tulkaat, ostakaat ja syökäät; tulkaat, ostakaat, ilman rahaa ja ilman hintaa, viinaa ja rieskaa."],[55,2,"Miksi te annatte rahan siinä, kussa ei leipää ole, ja teidän työnne siinä, kussa ei ole ravintoa? Kuulkaat minua, ja nauttikaat hyvää, ja teidän sielunne riemuitkaan lihavuudessa.","Miksi te annatte rahan siinä, kussa ei leipää ole, ja teidän työnne siinä, kussa ei ole ravintoa? Kuulkaat minua, ja nauttikaat hyvää, ja teidän sielunne riemuitkaan lihavuudessa."],[55,3,"Kallistakaat korvanne ja tulkaat minun tyköni, kuulkaat, niin teidän sielunne saa elää; ja minä teen teidän kanssanne ijankaikkisen liiton, lujat Davidin armot.","Kallistakaat korvanne ja tulkaat minun tyköni, kuulkaat, niin teidän sielunne saa elää; ja minä teen teidän kanssanne ijankaikkisen liiton, lujat Davidin armot."],[55,4,"Katso, minä panin hänen kansoille todistajaksi, päämieheksi ja opettajaksi kansoille.","Katso, minä panin hänen kansoille todistajaksi, päämieheksi ja opettajaksi kansoille."],[55,5,"Katso, sinun pitää kutsuman pakanat, joita et sinä tunne, ja ne pakanat, jotka ei sinua tunteneet, pitää juokseman sinun tykös, Herran sinun Jumalas tähden, ja Israelin Pyhän tähden, joka sinua kaunisti.","Katso, sinun pitää kutsuman pakanat, joita et sinä tunne, ja ne pakanat, jotka ei sinua tunteneet, pitää juokseman sinun tykös, Herran sinun Jumalas tähden, ja Israelin Pyhän tähden, joka sinua kaunisti."],[55,6,"Etsikäät Herraa, kuin hän löytää taitaan: rukoilkaat häntä, koska hän läsnä on.","Etsikäät Herraa, kuin hän löytää taitaan: rukoilkaat häntä, koska hän läsnä on."],[55,7,"Jumalatoin hyljätköön tiensä, ja pahointekiä ajatuksensa, ja palatkaan Herran tykö, niin hän armahtaa häntä, ja meidän Jumalamme tykö, sillä hänen tykönänsä on paljon anteeksiantamusta.","Jumalatoin hyljätköön tiensä, ja pahointekiä ajatuksensa, ja palatkaan Herran tykö, niin hän armahtaa häntä, ja meidän Jumalamme tykö, sillä hänen tykönänsä on paljon anteeksiantamusta."],[55,8,"Sillä minun ajatukseni ei ole teidän ajatuksenne, ja teidän tienne ei ole minun tieni, sanoo Herra.","Sillä minun ajatukseni ei ole teidän ajatuksenne, ja teidän tienne ei ole minun tieni, sanoo Herra."],[55,9,"Vaan niin paljo korkeampi kuin taivas on maasta, niin ovat myös minun tieni korkeammat teidän teitänne, ja minun ajatukseni teidän ajatuksianne.","Vaan niin paljo korkeampi kuin taivas on maasta, niin ovat myös minun tieni korkeammat teidän teitänne, ja minun ajatukseni teidän ajatuksianne."],[55,10,"Sillä niinkuin sade ja lumi tulee taivaasta alas, ja ei mene sinne jälleen, vaan tuorettaa maan, ja tekee sen hedelmälliseksi ja antaa sen kasvaa, ja antaa siemenen kylvettää ja leivän syötää;","Sillä niinkuin sade ja lumi tulee taivaasta alas, ja ei mene sinne jälleen, vaan tuorettaa maan, ja tekee sen hedelmälliseksi ja antaa sen kasvaa, ja antaa siemenen kylvettää ja leivän syötää;"],[55,11,"Niin on myös minun sanani, joka minun suustani lähtee, ei sen pidä tyhjänä palajaman minun tyköni, vaan tekemän mitä minulle otollinen on, ja sen pitää menestymän, jota varten minä sen lähettänytkin olen.","Niin on myös minun sanani, joka minun suustani lähtee, ei sen pidä tyhjänä palajaman minun tyköni, vaan tekemän mitä minulle otollinen on, ja sen pitää menestymän, jota varten minä sen lähettänytkin olen."],[55,12,"Sillä ilossa teidän pitää lähtemän ja rauhassa saatettaman; vuoret ja kukkulat pitää teidän edessänne kiitosta veisaaman, ja kaikki puut kedolla käsillänsä yhteen lyömän.","Sillä ilossa teidän pitää lähtemän ja rauhassa saatettaman; vuoret ja kukkulat pitää teidän edessänne kiitosta veisaaman, ja kaikki puut kedolla käsillänsä yhteen lyömän."],[55,13,"Hongat pitää orjantappurain siassa kasvaman, ja myrttipuu nukulaisten edestä; ja se pitää oleman Herralle nimeksi, ijankaikkiseksi merkiksi, jota ei pidä hävitettämän.","Hongat pitää orjantappurain siassa kasvaman, ja myrttipuu nukulaisten edestä; ja se pitää oleman Herralle nimeksi, ijankaikkiseksi merkiksi, jota ei pidä hävitettämän."],[56,1,"Näin sanoo Herra: pitäkäät oikeus, ja tehkäät vanhurskautta; sillä minun autuuteni on läsnä tulemassa, ja minun vanhurskauteni, että se ilmoitetaan.","Näin sanoo Herra: pitäkäät oikeus, ja tehkäät vanhurskautta; sillä minun autuuteni on läsnä tulemassa, ja minun vanhurskauteni, että se ilmoitetaan."],[56,2,"Autuas on se ihminen, joka sen tekee, ja se ihmisen lapsi, joka sen käsittää: että hän pitäis sabbatin, eikä sitä arkioksi tekisi, ja pidättäis kätensä, ettei hän mitään pahaa tekisi.","Autuas on se ihminen, joka sen tekee, ja se ihmisen lapsi, joka sen käsittää: että hän pitäis sabbatin, eikä sitä arkioksi tekisi, ja pidättäis kätensä, ettei hän mitään pahaa tekisi."],[56,3,"Ja muukalainen, joka Herraan on suostunut, ei pidä sanoman: Herra kaiketi eroittaa minun kansastansa; ja kuohittu ei pidä sanoman: katso, minä olen kuiva puu.","Ja muukalainen, joka Herraan on suostunut, ei pidä sanoman: Herra kaiketi eroittaa minun kansastansa; ja kuohittu ei pidä sanoman: katso, minä olen kuiva puu."],[56,4,"Sillä näin sanoo Herra kuohituille: jotka minun sabbatini pitävät, ja valitsevat mitä minulle kelpaa, ja lujasti pitävät minun liittoni:","Sillä näin sanoo Herra kuohituille: jotka minun sabbatini pitävät, ja valitsevat mitä minulle kelpaa, ja lujasti pitävät minun liittoni:"],[56,5,"Niin minä annan heille minun huoneessani ja muurissani paikan, ja paremman nimen kuin pojilla ja tyttärillä on; ijankaikkisen nimen minä heille annan, jota ei pidä hävitettämän.","Niin minä annan heille minun huoneessani ja muurissani paikan, ja paremman nimen kuin pojilla ja tyttärillä on; ijankaikkisen nimen minä heille annan, jota ei pidä hävitettämän."],[56,6,"Ja muukalaisten lapsille, jotka Herraan suostuneet ovat häntä palvelemaan ja Herran nimeä rakastamaan, ja hänen palveliansa olemaan: jokainen heistä, joka sabbatin pitää, ettei hän sitä arkioksi tekisi, vaan pitäis lujasti minun liittoni,","Ja muukalaisten lapsille, jotka Herraan suostuneet ovat häntä palvelemaan ja Herran nimeä rakastamaan, ja hänen palveliansa olemaan: jokainen heistä, joka sabbatin pitää, ettei hän sitä arkioksi tekisi, vaan pitäis lujasti minun liittoni,"],[56,7,"Ne minä vien pyhän vuoreni tykö, ja ilahutan heitä minun rukoushuoneessani; heidän uhrinsa ja polttouhrinsa pitää minulle otolliset oleman minun alttarillani; sillä minun huoneeni pitää kutsuttaman kaikkein kansain rukoushuoneeksi.","Ne minä vien pyhän vuoreni tykö, ja ilahutan heitä minun rukoushuoneessani; heidän uhrinsa ja polttouhrinsa pitää minulle otolliset oleman minun alttarillani; sillä minun huoneeni pitää kutsuttaman kaikkein kansain rukoushuoneeksi."],[56,8,"Herra, Herra, joka Israelin hyljätyt kokoo, sanoo: minä tahdon vielä enemmän hänen koottuinsa joukkoon koota.","Herra, Herra, joka Israelin hyljätyt kokoo, sanoo: minä tahdon vielä enemmän hänen koottuinsa joukkoon koota."],[56,9,"Kaikki pedot kedolla, tulkaat ja syökäät, ja kaikki pedot metsässä.","Kaikki pedot kedolla, tulkaat ja syökäät, ja kaikki pedot metsässä."],[56,10,"Kaikki heidän vartiansa ovat sokiat, eikä tiedä mitään, he ovat kaikki mykät koirat, jotka ei voi haukkua; he ovat laiskat, he makaavat ja unta rakastavat.","Kaikki heidän vartiansa ovat sokiat, eikä tiedä mitään, he ovat kaikki mykät koirat, jotka ei voi haukkua; he ovat laiskat, he makaavat ja unta rakastavat."],[56,11,"Mutta he ovat häpeemättömät väkevät koirat, jotka ei ikänä taida tulla ravituiksi. Ei paimenet itsekään tiedä mitään eli ymmärrä; jokainen ottaa vaarin omasta tiestänsä, kukin noudattaa ahneuttansa hänen tilassansa.","Mutta he ovat häpeemättömät väkevät koirat, jotka ei ikänä taida tulla ravituiksi. Ei paimenet itsekään tiedä mitään eli ymmärrä; jokainen ottaa vaarin omasta tiestänsä, kukin noudattaa ahneuttansa hänen tilassansa."],[56,12,"Tulkaat, ottakaamme viinaa ja juopukaamme, ja olkoon huomenna niinkuin tänäpänäkin, ja vielä paljo enempi.","Tulkaat, ottakaamme viinaa ja juopukaamme, ja olkoon huomenna niinkuin tänäpänäkin, ja vielä paljo enempi."],[57,1,"Vanhurskas hukkuu, ja ei ajattele kenkään sitä sydämessänsä; pyhät miehet temmataan pois, ja ei siitä kenkään pidä vaaria; sillä vanhurskaat otetaan pois onnettomuudesta,","Vanhurskas hukkuu, ja ei ajattele kenkään sitä sydämessänsä; pyhät miehet temmataan pois, ja ei siitä kenkään pidä vaaria; sillä vanhurskaat otetaan pois onnettomuudesta,"],[57,2,"Ja jotka toimellisesti vaeltaneet ovat, tulevat rauhaan, ja lepäävät kammioissansa.","Ja jotka toimellisesti vaeltaneet ovat, tulevat rauhaan, ja lepäävät kammioissansa."],[57,3,"Tulkaat tänne edes, te noitain lapset, te huorintekiäin ja porttoin siemenet.","Tulkaat tänne edes, te noitain lapset, te huorintekiäin ja porttoin siemenet."],[57,4,"Kenenkä kanssa te nyt tahdotte iloita hekumassa? Kenenkä päälle te nyt tahdotte suutanne irvistellä, ja kieltänne pistää? Ettekö te ole rikoksen lapset ja väärä siemen?","Kenenkä kanssa te nyt tahdotte iloita hekumassa? Kenenkä päälle te nyt tahdotte suutanne irvistellä, ja kieltänne pistää? Ettekö te ole rikoksen lapset ja väärä siemen?"],[57,5,"Te jotka olette hempeät epäjumaliin kaikkein viheriäisten puiden alla, ja teurastatte lapsia ojain tykönä vuorten alla.","Te jotka olette hempeät epäjumaliin kaikkein viheriäisten puiden alla, ja teurastatte lapsia ojain tykönä vuorten alla."],[57,6,"Sinun menos on sileiden kivien seassa, ojissa, ne ovat sinun osas; niille sinä vuodatat juomauhris, kuin sinä ruokauhria uhraat: pitäiskö minun siihen mielistymän?","Sinun menos on sileiden kivien seassa, ojissa, ne ovat sinun osas; niille sinä vuodatat juomauhris, kuin sinä ruokauhria uhraat: pitäiskö minun siihen mielistymän?"],[57,7,"Sinä teet vuotees korkialle jyrkälle vuorelle, ja menet myös itse sinne ylös uhria uhraamaan.","Sinä teet vuotees korkialle jyrkälle vuorelle, ja menet myös itse sinne ylös uhria uhraamaan."],[57,8,"Oven ja pihtipielen taa panet sinä muistos; sillä sinä vierität sinus pois minun tyköäni, menet ylös, ja levität vuotees, ja kiinnität itses heihin; sinä rakastat heidän vuodettansa, kussa ikänä sinä heidät näet.","Oven ja pihtipielen taa panet sinä muistos; sillä sinä vierität sinus pois minun tyköäni, menet ylös, ja levität vuotees, ja kiinnität itses heihin; sinä rakastat heidän vuodettansa, kussa ikänä sinä heidät näet."],[57,9,"Sinä menet kuninkaan tykö öljyllä, ja sinulla on moninaiset voiteet: ja lähetät sanas saattajat kauvas, ja olet alennettu hamaan helvettiin.","Sinä menet kuninkaan tykö öljyllä, ja sinulla on moninaiset voiteet: ja lähetät sanas saattajat kauvas, ja olet alennettu hamaan helvettiin."],[57,10,"Sinä vaivasit itsiäs monissa teissä, ja et sanonut: minä suutun; vaan ettäs löydät sinun kätes elämän, sentähden et sinä väsy.","Sinä vaivasit itsiäs monissa teissä, ja et sanonut: minä suutun; vaan ettäs löydät sinun kätes elämän, sentähden et sinä väsy."],[57,11,"Ketäs kartat ja pelkäät? ettäs valheessa olet, ja et muista minua, etkä johdata mielees; luuletkos minun ijäti olevan ääneti, ettes minua ensinkään pelkää?","Ketäs kartat ja pelkäät? ettäs valheessa olet, ja et muista minua, etkä johdata mielees; luuletkos minun ijäti olevan ääneti, ettes minua ensinkään pelkää?"],[57,12,"Minä ilmoitan sinun vanhurskautes, ja sinun tekos: ja ne ei sinua pidä hyödyttämän.","Minä ilmoitan sinun vanhurskautes, ja sinun tekos: ja ne ei sinua pidä hyödyttämän."],[57,13,"Kuin sinä huudat, niin auttakoon sinun joukkos sinua; mutta tuulen pitää heidät kaikki viemän pois, ja turhuuden pitää ne ottaman pois; mutta joka minuun uskaltaa, hänen pitää maan perimän ja omistaman minun pyhän vuoreni,","Kuin sinä huudat, niin auttakoon sinun joukkos sinua; mutta tuulen pitää heidät kaikki viemän pois, ja turhuuden pitää ne ottaman pois; mutta joka minuun uskaltaa, hänen pitää maan perimän ja omistaman minun pyhän vuoreni,"],[57,14,"Ja sanoman: tehkäät tietä, tehkää tietä, levittäkäät polku, sysätkäät loukkaukset minun kansani tieltä pois.","Ja sanoman: tehkäät tietä, tehkää tietä, levittäkäät polku, sysätkäät loukkaukset minun kansani tieltä pois."],[57,15,"Sillä näin sanoo korkia ja ylistetty, joka asuu ijankaikkisuudessa, ja jonka nimi on Pyhä: minä asun korkeudessa ja pyhyydessä, ja niiden tykönä, joilla särjetty ja nöyrä henki on, että minä virvoittaisin nöyryytetyn hengen, ja saattaisin särjetyn sydämen eläväiseksi.","Sillä näin sanoo korkia ja ylistetty, joka asuu ijankaikkisuudessa, ja jonka nimi on Pyhä: minä asun korkeudessa ja pyhyydessä, ja niiden tykönä, joilla särjetty ja nöyrä henki on, että minä virvoittaisin nöyryytetyn hengen, ja saattaisin särjetyn sydämen eläväiseksi."],[57,16,"Sillä en minä ijäti tahdo riidellä, enkä vihastua ijankaikkisesti; vaan minun kasvoistani on henki lähtevä, ja minä teen hengen.","Sillä en minä ijäti tahdo riidellä, enkä vihastua ijankaikkisesti; vaan minun kasvoistani on henki lähtevä, ja minä teen hengen."],[57,17,"Minä olin vihainen heidän ahneutensa vääryyden tähden, ja löin heitä, lymytin itseni ja närkästyin; silloin he menivät eksyksissä oman sydämensä tiellä.","Minä olin vihainen heidän ahneutensa vääryyden tähden, ja löin heitä, lymytin itseni ja närkästyin; silloin he menivät eksyksissä oman sydämensä tiellä."],[57,18,"Minä näin heidän tiensä, paransin heidät, ja johdatin heitä ja lohdutin niitä, jotka heitä murehtivat.","Minä näin heidän tiensä, paransin heidät, ja johdatin heitä ja lohdutin niitä, jotka heitä murehtivat."],[57,19,"Minä olen luonut huulten hedelmän: rauhan, rauhan sekä kaukaisille että läheisille, sanoo Herra, ja olen heitä parantanut.","Minä olen luonut huulten hedelmän: rauhan, rauhan sekä kaukaisille että läheisille, sanoo Herra, ja olen heitä parantanut."],[57,20,"Mutta jumalattomat ovat niinkuin lainehtiva meri, joka ei voi tyventyä; vaan hänen aaltonsa heittävät loan ja mudan.","Mutta jumalattomat ovat niinkuin lainehtiva meri, joka ei voi tyventyä; vaan hänen aaltonsa heittävät loan ja mudan."],[57,21,"Jumalattomilla ei ole rauhaa, sanoo minun Jumalani.","Jumalattomilla ei ole rauhaa, sanoo minun Jumalani."],[58,1,"Huuda rohkiasti, älä säästä, korota äänes niinkuin basuna, ja ilmoita minun kansalleni heidän ylitsekäymisensä, ja Jakobin huoneelle heidän syntinsä.","Huuda rohkiasti, älä säästä, korota äänes niinkuin basuna, ja ilmoita minun kansalleni heidän ylitsekäymisensä, ja Jakobin huoneelle heidän syntinsä."],[58,2,"Minua tosin he etsivät joka päivä, tahtovat tietää minun tietäni, niinkuin se kansa, joka jo vanhurskauden tehnyt on, ja ei ole heidän Jumalansa oikeutta hyljännyt. He kysyvät minulta oikiaa tuomiota, ja tahtovat lähestyä Jumalaa.","Minua tosin he etsivät joka päivä, tahtovat tietää minun tietäni, niinkuin se kansa, joka jo vanhurskauden tehnyt on, ja ei ole heidän Jumalansa oikeutta hyljännyt. He kysyvät minulta oikiaa tuomiota, ja tahtovat lähestyä Jumalaa."],[58,3,"Miksi me paastoamme, ja et sinä sitä katso? miksi me ruumistamme vaivaamme, ja et sinä sitä tahdo tietää? Katso, kuin te paastootte, niin te teette teidän tahtonne, ja vaaditte kaikkia teidän velvollisianne.","Miksi me paastoamme, ja et sinä sitä katso? miksi me ruumistamme vaivaamme, ja et sinä sitä tahdo tietää? Katso, kuin te paastootte, niin te teette teidän tahtonne, ja vaaditte kaikkia teidän velvollisianne."],[58,4,"Katso, te paastotte toraksi ja riidaksi, pieksätte rusikalla jumalattomasti. Älkäät paastotko niinkuin te nyt teette, että teidän parkunne kuuluu korkeuteen.","Katso, te paastotte toraksi ja riidaksi, pieksätte rusikalla jumalattomasti. Älkäät paastotko niinkuin te nyt teette, että teidän parkunne kuuluu korkeuteen."],[58,5,"Pitäiskö se oleman senkaltainen paasto, jonka minä valitsen: että ihminen ruumistansa päivällä vaivaa eli kallistaa päänsä niinkuin kaisla, taikka säkissä eli tuhassa makaa, senkö te paastoksi kutsutte, ja Herran otolliseksi päiväksi?","Pitäiskö se oleman senkaltainen paasto, jonka minä valitsen: että ihminen ruumistansa päivällä vaivaa eli kallistaa päänsä niinkuin kaisla, taikka säkissä eli tuhassa makaa, senkö te paastoksi kutsutte, ja Herran otolliseksi päiväksi?"],[58,6,"Mutta tämä on paasto, jonka minä valitsen: laske ne vallallensa, jotka vääryydellä sidotut ovat, päästä raskautetut irralle, laske vaivatut vapaaksi, ota pois kaikkinainen kuorma.","Mutta tämä on paasto, jonka minä valitsen: laske ne vallallensa, jotka vääryydellä sidotut ovat, päästä raskautetut irralle, laske vaivatut vapaaksi, ota pois kaikkinainen kuorma."],[58,7,"Taita isoovalle leipäs, vie raadolliset kulkiat huoneesees: kuin sinä näet alastoman, niin vaateta häntä, ja älä käännä itsiäs pois lihas tyköä.","Taita isoovalle leipäs, vie raadolliset kulkiat huoneesees: kuin sinä näet alastoman, niin vaateta häntä, ja älä käännä itsiäs pois lihas tyköä."],[58,8,"Silloin sinun valkeutes puhkee paistamaan niinkuin aamurusko, ja sinun parannukses on nopiasti kasvava; ja sinun vanhurskautes vaeltaa sinun edelläs. ja Herran kunnia on sinun korjaava.","Silloin sinun valkeutes puhkee paistamaan niinkuin aamurusko, ja sinun parannukses on nopiasti kasvava; ja sinun vanhurskautes vaeltaa sinun edelläs. ja Herran kunnia on sinun korjaava."],[58,9,"Silloin sinä rukoilet, ja Herra kuulee sinun rukoukses; ja koska sinä huudat, niin hän sanoo: katso, tässä minä olen. Ellet sinä ketään tykönäs raskauta, eli sormellas osoita, taikka pahasti puhu.","Silloin sinä rukoilet, ja Herra kuulee sinun rukoukses; ja koska sinä huudat, niin hän sanoo: katso, tässä minä olen. Ellet sinä ketään tykönäs raskauta, eli sormellas osoita, taikka pahasti puhu."],[58,10,"Jos avaat sydämes isoovaiselle, ja ravitset raadolliset sielut; niin sinun valkeutes on pimiässä koittava, ja sinun hämäräs on oleva niinkuin puolipäivä.","Jos avaat sydämes isoovaiselle, ja ravitset raadolliset sielut; niin sinun valkeutes on pimiässä koittava, ja sinun hämäräs on oleva niinkuin puolipäivä."],[58,11,"Ja Herra johdattaa aina sinua, ja ravitsee sielus poudalla, ja sinun luus vahvistaa; ja sinä olet oleva niinkuin kasvatettu yrttitarha ja niinkuin lähde, josta ei koskaan vesi puutu.","Ja Herra johdattaa aina sinua, ja ravitsee sielus poudalla, ja sinun luus vahvistaa; ja sinä olet oleva niinkuin kasvatettu yrttitarha ja niinkuin lähde, josta ei koskaan vesi puutu."],[58,12,"Ja se rakennetaan sinulta, joka kauvan on autiona ollut, ja sinä lasket perustuksen, joka pysyy ijankaikkisesti; ja sinä pitää kutsuttaman rauvenneen tukiaksi, ja teiden parantajaksi, että siinä saataisiin asua.","Ja se rakennetaan sinulta, joka kauvan on autiona ollut, ja sinä lasket perustuksen, joka pysyy ijankaikkisesti; ja sinä pitää kutsuttaman rauvenneen tukiaksi, ja teiden parantajaksi, että siinä saataisiin asua."],[58,13,"Jos sinä käännät jalkas sabbatista pois, niin ettes tee sinun tahtoas minun pyhäpäivänäni, niin se pitää iloiseksi sabbatiksi kutsuttaman, Herran kunnialliseksi pyhäksi; sillä niin sinä häntä ylistät, kuin et tee sinun teitäs, etkä niistä löydetä, jotka sinulle kelpaavat, eli mitä sinä puhut.","Jos sinä käännät jalkas sabbatista pois, niin ettes tee sinun tahtoas minun pyhäpäivänäni, niin se pitää iloiseksi sabbatiksi kutsuttaman, Herran kunnialliseksi pyhäksi; sillä niin sinä häntä ylistät, kuin et tee sinun teitäs, etkä niistä löydetä, jotka sinulle kelpaavat, eli mitä sinä puhut."],[58,14,"Silloin on sinulla ilo oleva Herrassa, ja minä ylennän sinun maan kukkulain päälle, ja tahdon sinua ruokkia Jakobin sinun isäs perimisestä; sillä Herran suu on sen puhunut.","Silloin on sinulla ilo oleva Herrassa, ja minä ylennän sinun maan kukkulain päälle, ja tahdon sinua ruokkia Jakobin sinun isäs perimisestä; sillä Herran suu on sen puhunut."],[59,1,"Katso, ei Herran käsi ole lyhennetty, niin ettei hän voi auttaa, ja ei hänen korvansa raskaat, ettei hän kuule;","Katso, ei Herran käsi ole lyhennetty, niin ettei hän voi auttaa, ja ei hänen korvansa raskaat, ettei hän kuule;"],[59,2,"Vaan teidän pahuutenne eroittaa teidät ja teidän Jumalanne toisen toisestansa, ja teidän syntinne kätkevät pois hänen kasvonsa teiltä, niin ettei teitä kuulla.","Vaan teidän pahuutenne eroittaa teidät ja teidän Jumalanne toisen toisestansa, ja teidän syntinne kätkevät pois hänen kasvonsa teiltä, niin ettei teitä kuulla."],[59,3,"Sillä teidän kätenne ovat saastutetut verellä, ja sormenne vääryydellä; teidän huulenne puhuvat valhetta, ja kielenne latelevat vääryyttä.","Sillä teidän kätenne ovat saastutetut verellä, ja sormenne vääryydellä; teidän huulenne puhuvat valhetta, ja kielenne latelevat vääryyttä."],[59,4,"Ei ole yhtään, joka saarnaa vanhurskautta eli tuomitsee uskollisesti. Turhuuteen luotetaan ja puhutaan kelpaamattomia; onnettomuudesta ovat he raskaat, ja synnyttävät tuskan.","Ei ole yhtään, joka saarnaa vanhurskautta eli tuomitsee uskollisesti. Turhuuteen luotetaan ja puhutaan kelpaamattomia; onnettomuudesta ovat he raskaat, ja synnyttävät tuskan."],[59,5,"He hautovat basiliskin munia, ja kutovat hämähäkin verkkoa: jos joku syö hänen muniansa, niin hänen täytyy kuolla, jos ne rikotaan, niin niistä tulee kyykärme.","He hautovat basiliskin munia, ja kutovat hämähäkin verkkoa: jos joku syö hänen muniansa, niin hänen täytyy kuolla, jos ne rikotaan, niin niistä tulee kyykärme."],[59,6,"Heidän hämähäkkinsä verkot ei kelpaa vaatteeksi, ja heidän tekonsa ei kelpaa peitteeksi; sillä heidän työnsä ovat väärät työt, ja heidän käsissänsä on väkivalta.","Heidän hämähäkkinsä verkot ei kelpaa vaatteeksi, ja heidän tekonsa ei kelpaa peitteeksi; sillä heidän työnsä ovat väärät työt, ja heidän käsissänsä on väkivalta."],[59,7,"Heidän jalkansa juoksevat pahaan ja ovat nopsat vuodattamaan viatonta verta; heidän ajatuksensa ovat väärät ajatukset, heidän teissänsä on hävitys ja vahinko.","Heidän jalkansa juoksevat pahaan ja ovat nopsat vuodattamaan viatonta verta; heidän ajatuksensa ovat väärät ajatukset, heidän teissänsä on hävitys ja vahinko."],[59,8,"Ei he tunne rauhan teitä, eikä ole oikeutta heidän käymisissänsä; heidän polkunsa ovat karsaat: joka niitä käy, ei hänellä ole ikänä rauhaa.","Ei he tunne rauhan teitä, eikä ole oikeutta heidän käymisissänsä; heidän polkunsa ovat karsaat: joka niitä käy, ei hänellä ole ikänä rauhaa."],[59,9,"Sentähden on meistä oikeus kaukana, ja vanhurskaus ei käsitä meitä; me odotimme valkeutta, katso, niin tulee pimeys: paistetta, ja katso, me vaellamme sumussa.","Sentähden on meistä oikeus kaukana, ja vanhurskaus ei käsitä meitä; me odotimme valkeutta, katso, niin tulee pimeys: paistetta, ja katso, me vaellamme sumussa."],[59,10,"Me haparoitsimme seiniä niinkuin sokiat, ja pitelimme niinkuin ne, joilla ei silmiä ole; me loukkaamme itsemme puolipäivänä niinkuin hämärissä, me olemme pimeydessä niinkuin kuolleet.","Me haparoitsimme seiniä niinkuin sokiat, ja pitelimme niinkuin ne, joilla ei silmiä ole; me loukkaamme itsemme puolipäivänä niinkuin hämärissä, me olemme pimeydessä niinkuin kuolleet."],[59,11,"Me myrisemme kaikki niinkuin karhut, ja vaikeroitsemme surkiasti niinkuin mettiset, sillä me odotamme oikeutta, ja ei sitä olekaan, autuutta, ja se on meistä kaukana.","Me myrisemme kaikki niinkuin karhut, ja vaikeroitsemme surkiasti niinkuin mettiset, sillä me odotamme oikeutta, ja ei sitä olekaan, autuutta, ja se on meistä kaukana."],[59,12,"Sillä meidän rikoksiamme on sinun edessäs aivan paljo, ja meidän syntimme todistavat meitä vastaan; sillä meidän rikoksemme on meitä läsnä, ja me tunnemme pahat tekomme.","Sillä meidän rikoksiamme on sinun edessäs aivan paljo, ja meidän syntimme todistavat meitä vastaan; sillä meidän rikoksemme on meitä läsnä, ja me tunnemme pahat tekomme."],[59,13,"Rikoksella ja valheella Herraa vastaan me luovumme meidän Jumalastamme, puhumaan vääryyttä ja tottelemattomuutta, ajatellaksemme ja ladellaksemme vääriä sanoja sydämestämme.","Rikoksella ja valheella Herraa vastaan me luovumme meidän Jumalastamme, puhumaan vääryyttä ja tottelemattomuutta, ajatellaksemme ja ladellaksemme vääriä sanoja sydämestämme."],[59,14,"Sentähden on myös oikeus palannut takaperin, ja vakuus on kauvas mennyt; sillä totuus putoo kaduille, ja vakuus ei taida tulla edes.","Sentähden on myös oikeus palannut takaperin, ja vakuus on kauvas mennyt; sillä totuus putoo kaduille, ja vakuus ei taida tulla edes."],[59,15,"Totuus on pois, ja joka luopuu pahasta, hänen pitää oleman jokaisen saaliina. Herra näkee sen, ja se on paha hänen silmäinsä edessä, ettei oikeutta ole.","Totuus on pois, ja joka luopuu pahasta, hänen pitää oleman jokaisen saaliina. Herra näkee sen, ja se on paha hänen silmäinsä edessä, ettei oikeutta ole."],[59,16,"Ja hän näkee, ettei yhtään miestä ole, ja ihmettelee, ettei kenkään pyydä sitä sovittaa: niin hänen käsivartensa vapahtaa hänen, ja hänen vanhurskautensa pitää hänen tallella.","Ja hän näkee, ettei yhtään miestä ole, ja ihmettelee, ettei kenkään pyydä sitä sovittaa: niin hänen käsivartensa vapahtaa hänen, ja hänen vanhurskautensa pitää hänen tallella."],[59,17,"Sillä hän pukee yllensä vanhurskauden niinkuin rautapaidan, ja panee autuuden rautalakin päähänsä; ja puettaa itsensä koston vaatteilla niinkuin puvulla, ja pukee yllensä kiivauden niinkuin hameen:","Sillä hän pukee yllensä vanhurskauden niinkuin rautapaidan, ja panee autuuden rautalakin päähänsä; ja puettaa itsensä koston vaatteilla niinkuin puvulla, ja pukee yllensä kiivauden niinkuin hameen:"],[59,18,"Niinkuin se, joka kostaa vihollisillensa heidän ansionsa jälkeen ja tahtoo maksaa vihamiehillensä julmuudella, ja luodoille tahtoo hän maksaa ansion jälkeen,","Niinkuin se, joka kostaa vihollisillensa heidän ansionsa jälkeen ja tahtoo maksaa vihamiehillensä julmuudella, ja luodoille tahtoo hän maksaa ansion jälkeen,"],[59,19,"Että Herran nimeä peljättäisiin lännestä, ja hänen kunniaansa idästä, kuin hän on tuleva niinkuin tydytetty virta, jonka Herran tuuli ajaa matkaan.","Että Herran nimeä peljättäisiin lännestä, ja hänen kunniaansa idästä, kuin hän on tuleva niinkuin tydytetty virta, jonka Herran tuuli ajaa matkaan."],[59,20,"Ja Zionille on tuleva vapahtaja, ja niille, jotka kääntyvät pois synneistä Jakobissa, sanoo Herra.","Ja Zionille on tuleva vapahtaja, ja niille, jotka kääntyvät pois synneistä Jakobissa, sanoo Herra."],[59,21,"Ja minä teen tämän liiton heidän kanssansa, sanoo Herra: minun henkeni, joka sinun päälläs on, ja minun sanani, jotka minä sinun suuhus pannut olen, ei pidä lähtemän sinun suustas, eikä sinun siemenes suusta, ja lastes lasten suusta, sanoo Herra, nyt niin ijankaikkiseen.","Ja minä teen tämän liiton heidän kanssansa, sanoo Herra: minun henkeni, joka sinun päälläs on, ja minun sanani, jotka minä sinun suuhus pannut olen, ei pidä lähtemän sinun suustas, eikä sinun siemenes suusta, ja lastes lasten suusta, sanoo Herra, nyt niin ijankaikkiseen."],[60,1,"Nouse, ole kirkas; sillä sinun valkeutes tulee, ja Herran kunnia koittaa sinun ylitses.","Nouse, ole kirkas; sillä sinun valkeutes tulee, ja Herran kunnia koittaa sinun ylitses."],[60,2,"Sillä katso, pimeys peittää maan, ja synkeys kansan; mutta Herra koittaa sinun ylitses, ja hänen kunniansa pitää sinun päälläs nähtämän.","Sillä katso, pimeys peittää maan, ja synkeys kansan; mutta Herra koittaa sinun ylitses, ja hänen kunniansa pitää sinun päälläs nähtämän."],[60,3,"Ja pakanat pitää vaeltaman sinun valkeudessas, ja kuninkaat sinun paisteessas, joka sinun ylitses koittaa.","Ja pakanat pitää vaeltaman sinun valkeudessas, ja kuninkaat sinun paisteessas, joka sinun ylitses koittaa."],[60,4,"Nosta silmäs, katso ympärilles, kaikki nämät kootut tulevat sinun tykös; sinun poikas tulevat kaukaa, ja sinun tyttäres kylkien vieressä kasvatetaan.","Nosta silmäs, katso ympärilles, kaikki nämät kootut tulevat sinun tykös; sinun poikas tulevat kaukaa, ja sinun tyttäres kylkien vieressä kasvatetaan."],[60,5,"Silloin sinä saat sen nähdä ja iloitset, sinun sydämes ihmettelee, ja levittää itsensä, kuin suuri paljous meren tykönä kääntyy sinun tykös, ja pakanain voima tulee sinulle.","Silloin sinä saat sen nähdä ja iloitset, sinun sydämes ihmettelee, ja levittää itsensä, kuin suuri paljous meren tykönä kääntyy sinun tykös, ja pakanain voima tulee sinulle."],[60,6,"Kamelein paljous on peittävä sinun, nopsat Midianin ja Ephan kamelit; ne kaikki tulevat Sabasta; kultaa ja pyhää savua he tuovat, ja he ilmoittavat Herran kiitoksen.","Kamelein paljous on peittävä sinun, nopsat Midianin ja Ephan kamelit; ne kaikki tulevat Sabasta; kultaa ja pyhää savua he tuovat, ja he ilmoittavat Herran kiitoksen."],[60,7,"Kaikki Kedarin laumat kokoontuvat sinun tykös, ja Nebajotin oinaat palvelevat sinua: ne pitää minun otolliselle alttarilleni uhrattaman, sillä minä tahdon minun kunniani huoneen kaunistaa.","Kaikki Kedarin laumat kokoontuvat sinun tykös, ja Nebajotin oinaat palvelevat sinua: ne pitää minun otolliselle alttarilleni uhrattaman, sillä minä tahdon minun kunniani huoneen kaunistaa."],[60,8,"Kutka ovat nuo, jotka lentävät niinkuin pilvet, ja niinkuin mettiset akkunoillensa?","Kutka ovat nuo, jotka lentävät niinkuin pilvet, ja niinkuin mettiset akkunoillensa?"],[60,9,"Sillä minua luodot odottavat, ja haahdet meressä ensimäisinä tuomaan sinun lapses tähän kaukaa; heidän hopiansa ja kultansa heidän kanssansa, Herran sinun Jumalas ja Israelin Pyhän nimeen, joka sinua kunnioitti.","Sillä minua luodot odottavat, ja haahdet meressä ensimäisinä tuomaan sinun lapses tähän kaukaa; heidän hopiansa ja kultansa heidän kanssansa, Herran sinun Jumalas ja Israelin Pyhän nimeen, joka sinua kunnioitti."],[60,10,"Muukalaisten lapset pitää sinun muuris rakentaman, ja heidän kuninkaansa pitää sinua palveleman; sillä vihassani löin minä sinua, ja armoissani minä armahdan sinua.","Muukalaisten lapset pitää sinun muuris rakentaman, ja heidän kuninkaansa pitää sinua palveleman; sillä vihassani löin minä sinua, ja armoissani minä armahdan sinua."],[60,11,"Ja sinun porttis pitää alati avoinna oleman, ja ei pidä päivällä eikä yöllä suljettaman, että pakanain voima tuotaisiin, ja heidän kuninkaansa saatettaisiin sinun tykös.","Ja sinun porttis pitää alati avoinna oleman, ja ei pidä päivällä eikä yöllä suljettaman, että pakanain voima tuotaisiin, ja heidän kuninkaansa saatettaisiin sinun tykös."],[60,12,"Sillä ne pakanat ja valtakunnat, jotka ei tahdo sinua palvella, pitää hukkuman, ja pakanat pitää peräti hukutettaman.","Sillä ne pakanat ja valtakunnat, jotka ei tahdo sinua palvella, pitää hukkuman, ja pakanat pitää peräti hukutettaman."],[60,13,"Libanonin kunnia pitää tuleman sinun tykös, honka, tammi ja buksipuu ynnä, kaunistamaan minun pyhää siaani; sillä minä tahdon jalkani sian kunnioittaa.","Libanonin kunnia pitää tuleman sinun tykös, honka, tammi ja buksipuu ynnä, kaunistamaan minun pyhää siaani; sillä minä tahdon jalkani sian kunnioittaa."],[60,14,"Heidän pitää myös kumaroissansa sinun tykös tuleman, jotka sinua sortaneet ovat, ja kaikki, jotka sinua pilkanneet ovat, pitää lankeeman sinun jalkais eteen, ja kutsuman sinun Herran kaupungiksi, Israelin Pyhän Zioniksi.","Heidän pitää myös kumaroissansa sinun tykös tuleman, jotka sinua sortaneet ovat, ja kaikki, jotka sinua pilkanneet ovat, pitää lankeeman sinun jalkais eteen, ja kutsuman sinun Herran kaupungiksi, Israelin Pyhän Zioniksi."],[60,15,"Ettäs olet hyljätty ja vihattu ollut, kussa ei kenkään vaeltanut, tahdon minä sinua ijankaikkiseksi korkeudeksi tehdä, ja iloksi suvusta sukuun;","Ettäs olet hyljätty ja vihattu ollut, kussa ei kenkään vaeltanut, tahdon minä sinua ijankaikkiseksi korkeudeksi tehdä, ja iloksi suvusta sukuun;"],[60,16,"Että sinun pitää pakanain rieskaa imemän, ja kuningasten nisät pitää sinua imettämän: ettäs tuntisit minun Herraksi sinun vapahtajakses, ja että minä, Jakobin väkevä, olen sinun lunastajas.","Että sinun pitää pakanain rieskaa imemän, ja kuningasten nisät pitää sinua imettämän: ettäs tuntisit minun Herraksi sinun vapahtajakses, ja että minä, Jakobin väkevä, olen sinun lunastajas."],[60,17,"Minä tahdon saattaa kultaa vasken siaan, ja hopiaa raudan siaan, ja vaskea puiden siaan ja rantaa kivien sijaan ja tahdon tehdä vaivas rauhaksi, ja työs vanhurskaudeksi.","Minä tahdon saattaa kultaa vasken siaan, ja hopiaa raudan siaan, ja vaskea puiden siaan ja rantaa kivien sijaan ja tahdon tehdä vaivas rauhaksi, ja työs vanhurskaudeksi."],[60,18,"Ei enään sinun maallas vääryyttä kuuluman pidä, ei vahinkoa, eikä kadotusta sinun äärissäs; vaan sinun muuris pitää autuudeksi ja sinun porttis kiitokseksi kutsuttaman.","Ei enään sinun maallas vääryyttä kuuluman pidä, ei vahinkoa, eikä kadotusta sinun äärissäs; vaan sinun muuris pitää autuudeksi ja sinun porttis kiitokseksi kutsuttaman."],[60,19,"Ei auringon pidä enään päivällä sinulle paistaman, eikä kuun valon sinua valaiseman; vaan Herra on sinun ijankaikkinen valkeutes, ja sinun Jumalas on sinun ylistykses.","Ei auringon pidä enään päivällä sinulle paistaman, eikä kuun valon sinua valaiseman; vaan Herra on sinun ijankaikkinen valkeutes, ja sinun Jumalas on sinun ylistykses."],[60,20,"Ei sinun aurinkos enään laske, eikä kuus kadota valoansa; sillä Herra on sinun ijankaikkinen valkeutes, ja sinun murhepäiväs loppuvat.","Ei sinun aurinkos enään laske, eikä kuus kadota valoansa; sillä Herra on sinun ijankaikkinen valkeutes, ja sinun murhepäiväs loppuvat."],[60,21,"Ja sinun kansas on kaikki vanhurskas oleva, ja maan piirin ijankaikkisesti omistava, niinkuin minun istutukseni vesat ja käsialani ovat minulle ylistykseksi.","Ja sinun kansas on kaikki vanhurskas oleva, ja maan piirin ijankaikkisesti omistava, niinkuin minun istutukseni vesat ja käsialani ovat minulle ylistykseksi."],[60,22,"Vähäinen pitää tuhanneksi tuleman, ja piskuinen väkeväksi kansaksi: minä Herra tahdon sen ajallansa toimittaa.","Vähäinen pitää tuhanneksi tuleman, ja piskuinen väkeväksi kansaksi: minä Herra tahdon sen ajallansa toimittaa."],[61,1,"Herran, Herran henki on minun päälläni, sentähden on Herra minua voidellut, saarnaamaan köyhille hyvää sanomaa; hän on minun lähettänyt parantamaan särjettyjä sydämiä: saarnaamaan vangeille lunastusta ja sidotuille pääsemistä;","Herran, Herran henki on minun päälläni, sentähden on Herra minua voidellut, saarnaamaan köyhille hyvää sanomaa; hän on minun lähettänyt parantamaan särjettyjä sydämiä: saarnaamaan vangeille lunastusta ja sidotuille pääsemistä;"],[61,2,"Saarnaamaan Herran otollista vuotta, ja meidän Jumalamme kostopäivää; lohduttamaan kaikkia murheellisia;","Saarnaamaan Herran otollista vuotta, ja meidän Jumalamme kostopäivää; lohduttamaan kaikkia murheellisia;"],[61,3,"Että minä saattaisin murheellisille Zionissa kaunistuksen tuhan edestä, ja iloöljyn murheen edestä, ja kauniit vaatteet murheellisen hengen edestä; että he vanhurskauden puuksi kutsuttaisiin, Herran istuttamisen ylistykseksi.","Että minä saattaisin murheellisille Zionissa kaunistuksen tuhan edestä, ja iloöljyn murheen edestä, ja kauniit vaatteet murheellisen hengen edestä; että he vanhurskauden puuksi kutsuttaisiin, Herran istuttamisen ylistykseksi."],[61,4,"Ja heidän pitää vanhat autiot paikat rakentaman, ja parantaman mitä muinen on hävitetty; heidän pitää autiot kaupungit uudistaman, jotka suvusta sukuun hävitettynä olivat.","Ja heidän pitää vanhat autiot paikat rakentaman, ja parantaman mitä muinen on hävitetty; heidän pitää autiot kaupungit uudistaman, jotka suvusta sukuun hävitettynä olivat."],[61,5,"Muukalaiset pitää seisoman ja teidän laumanne kaitseman; ja vierasten lapset pitää teidän peltomiehenne ja viinamäkenne miehet oleman.","Muukalaiset pitää seisoman ja teidän laumanne kaitseman; ja vierasten lapset pitää teidän peltomiehenne ja viinamäkenne miehet oleman."],[61,6,"Mutta teitä pitää Herran papiksi kutsuttaman, ja sanottaman: te olette meidän Jumalamme palveliat, ja teidän pitää pakanain hyvyyden syömän, ja heidän kunniastansa pitää teidän kerskaaman.","Mutta teitä pitää Herran papiksi kutsuttaman, ja sanottaman: te olette meidän Jumalamme palveliat, ja teidän pitää pakanain hyvyyden syömän, ja heidän kunniastansa pitää teidän kerskaaman."],[61,7,"Teidän häpiänne edestä pitää teidän kaksinkertaisesti saaman, ja häväistyksen edestä pitää heidän riemuitseman osassansa: sentähden pitää heidän kaksinkertaisesti maansa omistaman: heillä pitää ijankaikkinen riemu oleman.","Teidän häpiänne edestä pitää teidän kaksinkertaisesti saaman, ja häväistyksen edestä pitää heidän riemuitseman osassansa: sentähden pitää heidän kaksinkertaisesti maansa omistaman: heillä pitää ijankaikkinen riemu oleman."],[61,8,"Sillä minä olen Herra, joka oikeutta rakastan, ja vihaan ryövättyä polttouhria: ja tahdon saattaa, ettei heidän työnsä pidä turha oleman, ja teen ijankaikkisen liiton heidän kanssansa.","Sillä minä olen Herra, joka oikeutta rakastan, ja vihaan ryövättyä polttouhria: ja tahdon saattaa, ettei heidän työnsä pidä turha oleman, ja teen ijankaikkisen liiton heidän kanssansa."],[61,9,"Ja heidän siemenensä pitää pakanain seassa tunnettaman, ja heidän jälkeentulevaisensa kansain seassa; että jokainen, joka heidät näkee, pitää heidät tunteman, että he ovat siunattu siemen Herralta.","Ja heidän siemenensä pitää pakanain seassa tunnettaman, ja heidän jälkeentulevaisensa kansain seassa; että jokainen, joka heidät näkee, pitää heidät tunteman, että he ovat siunattu siemen Herralta."],[61,10,"Minä iloitsen suuresti Herrassa, ja minun sieluni riemuitsee minun Jumalassani; sillä hän puetti minun autuuden vaatteilla, ja verhoitti minun vanhurskauden hameella: niinkuin ylkä kaunistettu papillisella kaunistuksella, ja niinkuin morsian kaunistettu kaunistuksessansa.","Minä iloitsen suuresti Herrassa, ja minun sieluni riemuitsee minun Jumalassani; sillä hän puetti minun autuuden vaatteilla, ja verhoitti minun vanhurskauden hameella: niinkuin ylkä kaunistettu papillisella kaunistuksella, ja niinkuin morsian kaunistettu kaunistuksessansa."],[61,11,"Sillä niinkuin hedelmä kasvaa maasta, ja siemen yrttitarhassa putkahtaa, niin antaa Herra, Herra vanhurskauden ja kiitoksen käydä ylös kaikkein pakanain edessä.","Sillä niinkuin hedelmä kasvaa maasta, ja siemen yrttitarhassa putkahtaa, niin antaa Herra, Herra vanhurskauden ja kiitoksen käydä ylös kaikkein pakanain edessä."],[62,1,"Zionin tähden en minä vaikene, ja Jerusalemin tähden en minä lakkaa, siihenasti että hänen vanhurskautensa koittaa niinkuin paiste, ja hänen autuutensa palaa niinkuin tulisoitto.","Zionin tähden en minä vaikene, ja Jerusalemin tähden en minä lakkaa, siihenasti että hänen vanhurskautensa koittaa niinkuin paiste, ja hänen autuutensa palaa niinkuin tulisoitto."],[62,2,"Että pakanatkin näkisivät sinun vanhurskautes, ja kaikki kuninkaat sinun kunnias. Ja sinä nimitetään uudella nimellä, jonka Herran suu on nimittävä.","Että pakanatkin näkisivät sinun vanhurskautes, ja kaikki kuninkaat sinun kunnias. Ja sinä nimitetään uudella nimellä, jonka Herran suu on nimittävä."],[62,3,"Ja sinun pitää oleman kunnian kruunu Herran kädessä, ja kuninkaan hiippa sinun Jumalas kädessä.","Ja sinun pitää oleman kunnian kruunu Herran kädessä, ja kuninkaan hiippa sinun Jumalas kädessä."],[62,4,"Et sinä enään kutsuta hyljätyksi, eikä sinun maatas enää sanota hävitetyksi, vaan sinä kutsutaan: minun suosioni on hänessä, ja sinun maas asuttavaksi; sillä Herra on mielistynyt sinuun, ja sinun maallas asutaan.","Et sinä enään kutsuta hyljätyksi, eikä sinun maatas enää sanota hävitetyksi, vaan sinä kutsutaan: minun suosioni on hänessä, ja sinun maas asuttavaksi; sillä Herra on mielistynyt sinuun, ja sinun maallas asutaan."],[62,5,"Sillä niinkuin nuorukainen rakastaa neitsyttä, niin sinun lapses pitää sinua rakastaman; ja niinkuin ylkä iloitsee morsiamestansa, niin myös sinun Jumalas iloitsee sinusta.","Sillä niinkuin nuorukainen rakastaa neitsyttä, niin sinun lapses pitää sinua rakastaman; ja niinkuin ylkä iloitsee morsiamestansa, niin myös sinun Jumalas iloitsee sinusta."],[62,6,"Jerusalem, minä asetan vartiat muuris päälle, jotka ei ikänä päivällä eikä yöllä vaikene; ja jotka Herran muistatte, ei teidän pidä vaiti oleman.","Jerusalem, minä asetan vartiat muuris päälle, jotka ei ikänä päivällä eikä yöllä vaikene; ja jotka Herran muistatte, ei teidän pidä vaiti oleman."],[62,7,"Ja ei teidän pidä hänestä vaikeneman, siihenasti että hän sen vahvistaa, ja asettaa Jerusalemin maan päälle kiitokseksi.","Ja ei teidän pidä hänestä vaikeneman, siihenasti että hän sen vahvistaa, ja asettaa Jerusalemin maan päälle kiitokseksi."],[62,8,"Herra vannoo oikian kätensä kautta, ja voimansa käsivarren kautta: en minä tahdo enään antaa jyviäs vihollistes syödä, enkä viinaas, jonka tähden sinä työtä teit, muukalaisten juoda;","Herra vannoo oikian kätensä kautta, ja voimansa käsivarren kautta: en minä tahdo enään antaa jyviäs vihollistes syödä, enkä viinaas, jonka tähden sinä työtä teit, muukalaisten juoda;"],[62,9,"Vaan jotka sen kokoovat, syövät sitä ja kiittävät Herraa; ja jotka sitä kokoovat, juovat sitä minun pyhyyteni esihuoneissa.","Vaan jotka sen kokoovat, syövät sitä ja kiittävät Herraa; ja jotka sitä kokoovat, juovat sitä minun pyhyyteni esihuoneissa."],[62,10,"Menkäät, menkäät porttein kautta, peratkaat tietä kansalle: silittäkäät, silittäkäät polut, siirtäkäät kivet pois, ylentäkäät lippu kansain päälle.","Menkäät, menkäät porttein kautta, peratkaat tietä kansalle: silittäkäät, silittäkäät polut, siirtäkäät kivet pois, ylentäkäät lippu kansain päälle."],[62,11,"Katso, Herra antaa sen kuulua hamaan maailman ääriin asti: sanokaat Zionin tyttärelle: katso, sinun autuutes tulee, katso, hänen palkkansa on hänen myötänsä, ja hänen työnsä hänen edessänsä.","Katso, Herra antaa sen kuulua hamaan maailman ääriin asti: sanokaat Zionin tyttärelle: katso, sinun autuutes tulee, katso, hänen palkkansa on hänen myötänsä, ja hänen työnsä hänen edessänsä."],[62,12,"Ja he pitää kutsuttaman pyhäksi kansaksi, Herran lunastetuiksi; ja sinä kutsutaan etsityksi ja ei hyljätyksi kaupungiksi.","Ja he pitää kutsuttaman pyhäksi kansaksi, Herran lunastetuiksi; ja sinä kutsutaan etsityksi ja ei hyljätyksi kaupungiksi."],[63,1,"Kuka on se, joka tulee Edomista, punaisilla vaatteilla Botsrasta, joka niin on kaunistettu vaatteissansa, ja käy suuressa voimassansa? Minä joka puhun vanhurskautta, ja taidan kyllä auttaa.","Kuka on se, joka tulee Edomista, punaisilla vaatteilla Botsrasta, joka niin on kaunistettu vaatteissansa, ja käy suuressa voimassansa? Minä joka puhun vanhurskautta, ja taidan kyllä auttaa."],[63,2,"Miksi ovat siis vaattees niin punaiset, ja pukus niinkuin viinakuurnan sotkujan?","Miksi ovat siis vaattees niin punaiset, ja pukus niinkuin viinakuurnan sotkujan?"],[63,3,"Minä sotkun viinakuurnan yksinäni, ja ei yksikään kansasta minun kanssani. Minä tallaan heitä vihassani, ja sotkun heitä julmuudessani; siitä on heidän verensä priiskunut vaatteisiini, ja minä olen saastuttanut kaikki minun pukuni;","Minä sotkun viinakuurnan yksinäni, ja ei yksikään kansasta minun kanssani. Minä tallaan heitä vihassani, ja sotkun heitä julmuudessani; siitä on heidän verensä priiskunut vaatteisiini, ja minä olen saastuttanut kaikki minun pukuni;"],[63,4,"Sillä minä olen säätänyt itselleni kostopäivän, ja vuosi on tullut omiani pelastaa.","Sillä minä olen säätänyt itselleni kostopäivän, ja vuosi on tullut omiani pelastaa."],[63,5,"Sillä minä katsoin ympärilleni, ja ei ollut auttajaa, ja minä hämmästyin, ja ei kenkään holhonut minua; vaan minun käsivarteni vapahti minun, ja minun vihani holhoi minua.","Sillä minä katsoin ympärilleni, ja ei ollut auttajaa, ja minä hämmästyin, ja ei kenkään holhonut minua; vaan minun käsivarteni vapahti minun, ja minun vihani holhoi minua."],[63,6,"Ja minä olen tallannut kansat vihassani, ja tehnyt heitä juovuksiin minun julmuudessani; ja sysäsin heidän voittonsa maahan.","Ja minä olen tallannut kansat vihassani, ja tehnyt heitä juovuksiin minun julmuudessani; ja sysäsin heidän voittonsa maahan."],[63,7,"Minä tahdon Herran laupiutta muistaa, ja Herran kiitosta kaikista niistä, mitkä Herra meille tehnyt on, ja sitä suurta hyvyyttä Israelin huoneelle, jonka hän sille tehnyt on, suuren laupiutensa ja hyvyytensä kautta.","Minä tahdon Herran laupiutta muistaa, ja Herran kiitosta kaikista niistä, mitkä Herra meille tehnyt on, ja sitä suurta hyvyyttä Israelin huoneelle, jonka hän sille tehnyt on, suuren laupiutensa ja hyvyytensä kautta."],[63,8,"Sillä hän sanoo: he ovat tosin minun kansani, lapset, jotka ei valhetteliat ole; ja hän oli heidän vapahtajansa.","Sillä hän sanoo: he ovat tosin minun kansani, lapset, jotka ei valhetteliat ole; ja hän oli heidän vapahtajansa."],[63,9,"Kaikessa heidän ahdistuksessansa oli hänellä ahdistus, ja enkeli, joka hänen edessänsä on, autti heitä; rakkautensa ja armonsa tähden hän lunasti heitä, ja otti heitä ylös, ja kantoi heitä aina vanhasta tähän asti.","Kaikessa heidän ahdistuksessansa oli hänellä ahdistus, ja enkeli, joka hänen edessänsä on, autti heitä; rakkautensa ja armonsa tähden hän lunasti heitä, ja otti heitä ylös, ja kantoi heitä aina vanhasta tähän asti."],[63,10,"Mutta he olivat vastahakoiset, ja vihoittivat hänen Pyhän Henkensä; sentähden hän muuttui heidän viholliseksensa, ja soti heitä vastaan.","Mutta he olivat vastahakoiset, ja vihoittivat hänen Pyhän Henkensä; sentähden hän muuttui heidän viholliseksensa, ja soti heitä vastaan."],[63,11,"Ja hänen kansansa muisti taas entisiä Moseksen aikoja. Kussa siis nyt se on, joka heidät vei ulos merestä laumansa paimenen kanssa? Kussa on se, joka Pyhän Henkensä heidän sekaansa antoi;","Ja hänen kansansa muisti taas entisiä Moseksen aikoja. Kussa siis nyt se on, joka heidät vei ulos merestä laumansa paimenen kanssa? Kussa on se, joka Pyhän Henkensä heidän sekaansa antoi;"],[63,12,"Joka oikialla kädellänsä Moseksen vei, kunniallisella käsivarrellansa; joka vedet jakoi heidän edellänsä, tehdäksensä itsellensä ijankaikkista nimeä;","Joka oikialla kädellänsä Moseksen vei, kunniallisella käsivarrellansa; joka vedet jakoi heidän edellänsä, tehdäksensä itsellensä ijankaikkista nimeä;"],[63,13,"Joka heitä vei syvyyden kautta, niinkuin hevoset korvessa, ilman kompastumata.","Joka heitä vei syvyyden kautta, niinkuin hevoset korvessa, ilman kompastumata."],[63,14,"Niinkuin karjan, joka kedolle menee, saatti Herran Henki heidät lepoon, niin sinä myös kansas johdatit, tehdäkses itselles ijankaikkista nimeä.","Niinkuin karjan, joka kedolle menee, saatti Herran Henki heidät lepoon, niin sinä myös kansas johdatit, tehdäkses itselles ijankaikkista nimeä."],[63,15,"Niin katso nyt taivasta, ja katso tänne alas pyhästä ja kunniallisesta asuinsiastas. Kussa nyt on kiivautes ja voimas? sinun suuri sydämellinen laupiutes kovennetaan minua vastaan.","Niin katso nyt taivasta, ja katso tänne alas pyhästä ja kunniallisesta asuinsiastas. Kussa nyt on kiivautes ja voimas? sinun suuri sydämellinen laupiutes kovennetaan minua vastaan."],[63,16,"Sinä olet kuitenkin meidän Isämme; sillä ei Abraham meistä mitään tiedä, ja ei Israel meitä tunne; mutta sinä Herra olet meidän Isämme ja meidän Lunastajamme; ja se on ijäti sinun nimes.","Sinä olet kuitenkin meidän Isämme; sillä ei Abraham meistä mitään tiedä, ja ei Israel meitä tunne; mutta sinä Herra olet meidän Isämme ja meidän Lunastajamme; ja se on ijäti sinun nimes."],[63,17,"Miksis, Herra, sallit meidän eksyä sinun teiltäs, ja annoit sydämemme paatua, ettemme sinua peljänneet? Palaja palveliais tähden ja perimises sukukuntain tähden.","Miksis, Herra, sallit meidän eksyä sinun teiltäs, ja annoit sydämemme paatua, ettemme sinua peljänneet? Palaja palveliais tähden ja perimises sukukuntain tähden."],[63,18,"He omistavat lähes kaiken sinun pyhän kansas; meidän vihollisemme polkevat sinun pyhyytes alas.","He omistavat lähes kaiken sinun pyhän kansas; meidän vihollisemme polkevat sinun pyhyytes alas."],[63,19,"Me olemme juuri niinkuin ennenkin, kuin et sinä meitä hallinnut, ja emme olleetkaan sinun nimees nimitetyt.","Me olemme juuri niinkuin ennenkin, kuin et sinä meitä hallinnut, ja emme olleetkaan sinun nimees nimitetyt."],[64,1,"Jospa sinä taivaat halkaisisit, ja astuisit alas, että vuoret vuotaisivat sinun edessäs, niinkuin palava vesi kiehuu pois väkevällä tulella,","Jospa sinä taivaat halkaisisit, ja astuisit alas, että vuoret vuotaisivat sinun edessäs, niinkuin palava vesi kiehuu pois väkevällä tulella,"],[64,2,"Että sinun nimes tulis tiettäväksi sinun vihollisilles, ja että pakanat sinun edessäs vapisisivat.","Että sinun nimes tulis tiettäväksi sinun vihollisilles, ja että pakanat sinun edessäs vapisisivat."],[64,3,"Niiden ihmeitten tähden, jotka sinä teet, joita ei kenkään toivonut; koska sinä menit alas, ja vuoret edessäs sulaisivat.","Niiden ihmeitten tähden, jotka sinä teet, joita ei kenkään toivonut; koska sinä menit alas, ja vuoret edessäs sulaisivat."],[64,4,"Ja ei maailman alusta kuultu, eikä korville tullut ole, eli yksikään silmä nähnyt ole, paitsi sinua Jumala, mikä niille tapahtuu, jotka sinua odottavat.","Ja ei maailman alusta kuultu, eikä korville tullut ole, eli yksikään silmä nähnyt ole, paitsi sinua Jumala, mikä niille tapahtuu, jotka sinua odottavat."],[64,5,"Sinä kohtasit niitä iloisna, jotka tekivät vanhurskautta, ja sinua muistelivat sinun teilläs. Katso, sinä vihastuit, koska me syntiä teimme ja kauvan niissä viivyimme, mutta kuitenkin meitä autettiin.","Sinä kohtasit niitä iloisna, jotka tekivät vanhurskautta, ja sinua muistelivat sinun teilläs. Katso, sinä vihastuit, koska me syntiä teimme ja kauvan niissä viivyimme, mutta kuitenkin meitä autettiin."],[64,6,"Mutta me olemme kaikki saastaiset, ja kaikki meidän vanhurskautemme on niinkuin saastainen vaate; me olemme kaikki lakastuneet niinkuin lehdet, ja meidän syntimme viskoivat meitä niinkuin tuuli.","Mutta me olemme kaikki saastaiset, ja kaikki meidän vanhurskautemme on niinkuin saastainen vaate; me olemme kaikki lakastuneet niinkuin lehdet, ja meidän syntimme viskoivat meitä niinkuin tuuli."],[64,7,"Ja ei ole sitä, joka rukoilee sinun nimeäs, ja nousee sinuun kiinni tarttumaan; sillä sinä peität kasvos meiltä, ja annat meidät nääntyä suurissa synneissämme.","Ja ei ole sitä, joka rukoilee sinun nimeäs, ja nousee sinuun kiinni tarttumaan; sillä sinä peität kasvos meiltä, ja annat meidät nääntyä suurissa synneissämme."],[64,8,"Mutta nyt Herra, sinä olet meidän Isämme; me olemme savi, sinä olet meidän valajamme, ja me olemme kaikki sinun käsialas.","Mutta nyt Herra, sinä olet meidän Isämme; me olemme savi, sinä olet meidän valajamme, ja me olemme kaikki sinun käsialas."],[64,9,"Älä, Herra, niin kovin vihastu, ja älä ijäti ajattele syntiämme; katso sitä, että me olemme kaikki sinun kansas.","Älä, Herra, niin kovin vihastu, ja älä ijäti ajattele syntiämme; katso sitä, että me olemme kaikki sinun kansas."],[64,10,"Sinun pyhyytes kaupungit ovat hävitetyt, Zion on autioksi tehty ja Jerusalem on kylmillä.","Sinun pyhyytes kaupungit ovat hävitetyt, Zion on autioksi tehty ja Jerusalem on kylmillä."],[64,11,"Meidän pyhyytemme ja kunniamme huone, jossa meidän isämme sinua kunnioittivat, on tulella poltettu; ja kaikki meidän kauniimpamme ovat häväistyt.","Meidän pyhyytemme ja kunniamme huone, jossa meidän isämme sinua kunnioittivat, on tulella poltettu; ja kaikki meidän kauniimpamme ovat häväistyt."],[64,12,"Herra, maltatkos sinus näistä niin kovana pitää ja vaiti olla, ja lyödä meitä niin kovin alas.","Herra, maltatkos sinus näistä niin kovana pitää ja vaiti olla, ja lyödä meitä niin kovin alas."],[65,1,"Minä etsitään niiltä, jotka ei kysyneet minua; minä löytään niiltä, jotka ei minua etsineet; ja pakanoille, jotka ei rukoilleet minun nimeäni, sanon minä: tässä minä olen, tässä minä olen.","Minä etsitään niiltä, jotka ei kysyneet minua; minä löytään niiltä, jotka ei minua etsineet; ja pakanoille, jotka ei rukoilleet minun nimeäni, sanon minä: tässä minä olen, tässä minä olen."],[65,2,"Minä kokotan käteni koko päivän tottelemattomalle kansalle, joka vaeltaa ajatustensa jälkeen sitä tietä, joka ei hyvä ole;","Minä kokotan käteni koko päivän tottelemattomalle kansalle, joka vaeltaa ajatustensa jälkeen sitä tietä, joka ei hyvä ole;"],[65,3,"Sille kansalle, joka vihoittaa minun, on aina minun kasvoini edessä: uhraa yrttitarhoissa, suitsuttaa tulikivien päällä;","Sille kansalle, joka vihoittaa minun, on aina minun kasvoini edessä: uhraa yrttitarhoissa, suitsuttaa tulikivien päällä;"],[65,4,"Asuu hautain keskellä, on yötä luolissa, syö sian lihaa, ja heillä on kauhia liemi heidän padoissansa,","Asuu hautain keskellä, on yötä luolissa, syö sian lihaa, ja heillä on kauhia liemi heidän padoissansa,"],[65,5,"Ja sanovat: mene puolelles, ja älä satu minuun, sillä minä olen pyhempi sinua: näiden pitää oleman savun minun vihassani, ja tulen, joka palaa koko päivän.","Ja sanovat: mene puolelles, ja älä satu minuun, sillä minä olen pyhempi sinua: näiden pitää oleman savun minun vihassani, ja tulen, joka palaa koko päivän."],[65,6,"Katso, minun edessäni on kirjoitettu: en minä tahdo olla ääneti, vaan minä tahdon maksaa, ja maksaa heidän helmaansa,","Katso, minun edessäni on kirjoitettu: en minä tahdo olla ääneti, vaan minä tahdon maksaa, ja maksaa heidän helmaansa,"],[65,7,"Sekä teidän pahat tekonne, ja teidän isäinne pahat teot yhtenänsä, sanoo Herra: ne jotka vuorilla suitsuttaneet, ja minua kukkuloilla häväisseet ovat; minä tahdon jälleen mitata heidän entiset työnsä heidän helmaansa.","Sekä teidän pahat tekonne, ja teidän isäinne pahat teot yhtenänsä, sanoo Herra: ne jotka vuorilla suitsuttaneet, ja minua kukkuloilla häväisseet ovat; minä tahdon jälleen mitata heidän entiset työnsä heidän helmaansa."],[65,8,"Näin sanoo Herra: niinkuin viina löytään viinamarjoissa, ja sanotaan: älä sitä hävitä, sillä siinä on siunaus: juuri niin tahdon minä minun palveliani tähden tehdä, etten minä sitä kaikkea hävitä.","Näin sanoo Herra: niinkuin viina löytään viinamarjoissa, ja sanotaan: älä sitä hävitä, sillä siinä on siunaus: juuri niin tahdon minä minun palveliani tähden tehdä, etten minä sitä kaikkea hävitä."],[65,9,"Vaan johdatan Jakobista siemenen, ja Juudasta sen, joka minun vuorellani asuman pitää; sillä minun valittuni pitää sen omistaman, ja minun palveliani siinä asuman.","Vaan johdatan Jakobista siemenen, ja Juudasta sen, joka minun vuorellani asuman pitää; sillä minun valittuni pitää sen omistaman, ja minun palveliani siinä asuman."],[65,10,"Ja Saaronin pitää oleman laumain huoneen, ja Akorin laakson karjan pihaton, minun kansalleni, joka minua etsii.","Ja Saaronin pitää oleman laumain huoneen, ja Akorin laakson karjan pihaton, minun kansalleni, joka minua etsii."],[65,11,"Mutta te, jotka hylkäätte Herran, ja unohdatte minun pyhän vuoreni, ja nostatte Gadille pöydän ja panette juomauhria täyteen Menille:","Mutta te, jotka hylkäätte Herran, ja unohdatte minun pyhän vuoreni, ja nostatte Gadille pöydän ja panette juomauhria täyteen Menille:"],[65,12,"Olkaan, minä tahdon lukea teitä miekkaan, niin että teidän kaikkein pitää lankeeman teurastamiseen; sillä minä kutsuin, ja ette mitään vastanneet, minä puhuin, ja ette kuulleet, vaan teitte pahaa minun silmäini edessä, ja valitsitte mitä en minä tahtonut.","Olkaan, minä tahdon lukea teitä miekkaan, niin että teidän kaikkein pitää lankeeman teurastamiseen; sillä minä kutsuin, ja ette mitään vastanneet, minä puhuin, ja ette kuulleet, vaan teitte pahaa minun silmäini edessä, ja valitsitte mitä en minä tahtonut."],[65,13,"Sentähden sanoo Herra, Herra näin: katso, minun palveliani syövät, mutta teidän pitää isooman; katso, minun palveliani juovat, mutta teidän pitää janooman; katso, minun palveliani iloitsevat, mutta teidän pitää häpiään tuleman.","Sentähden sanoo Herra, Herra näin: katso, minun palveliani syövät, mutta teidän pitää isooman; katso, minun palveliani juovat, mutta teidän pitää janooman; katso, minun palveliani iloitsevat, mutta teidän pitää häpiään tuleman."],[65,14,"Katso, minun palveliani riemuitsevat hyvästä mielestä, mutta teidän pitää sydämen kivusta parkuman, ja hengen ahdistuksessa ulvoman.","Katso, minun palveliani riemuitsevat hyvästä mielestä, mutta teidän pitää sydämen kivusta parkuman, ja hengen ahdistuksessa ulvoman."],[65,15,"Ja teidän pitää jättämän teidän nimenne minun valituilleni valaksi; ja Herra Jumala on tappava sinun, mutta hänen palveliansa nimitetään toisella nimellä.","Ja teidän pitää jättämän teidän nimenne minun valituilleni valaksi; ja Herra Jumala on tappava sinun, mutta hänen palveliansa nimitetään toisella nimellä."],[65,16,"Että joka itsensä siunaa maan päällä, hän siunaa itsensä totisessa Jumalassa, ja joka vannoo maan päällä, se vannoo totisen Jumalan kautta; sillä entiset ahdistukset ovat unhotetut, ja ovat minun silmistäni peitetyt.","Että joka itsensä siunaa maan päällä, hän siunaa itsensä totisessa Jumalassa, ja joka vannoo maan päällä, se vannoo totisen Jumalan kautta; sillä entiset ahdistukset ovat unhotetut, ja ovat minun silmistäni peitetyt."],[65,17,"Sillä katso, minä luon uuden taivaan ja uuden maan, ja entisiä ei pidä muistettaman, eikä mieleen johdatettaman.","Sillä katso, minä luon uuden taivaan ja uuden maan, ja entisiä ei pidä muistettaman, eikä mieleen johdatettaman."],[65,18,"Vaan iloitkaat ja riemuitkaat ijankaikkisesti niissä, kuin minä luon; sillä katso, minä luon Jerusalemin iloksi ja hänen kansansa riemuksi.","Vaan iloitkaat ja riemuitkaat ijankaikkisesti niissä, kuin minä luon; sillä katso, minä luon Jerusalemin iloksi ja hänen kansansa riemuksi."],[65,19,"Ja minä tahdon iloita Jerusalemista ja riemuita minun kansastani; ja ei hänessä enään pidä kuultaman itkun ääntä eikä valituksen ääntä.","Ja minä tahdon iloita Jerusalemista ja riemuita minun kansastani; ja ei hänessä enään pidä kuultaman itkun ääntä eikä valituksen ääntä."],[65,20,"Ei siellä pidä enään lapsia oleman, jotka ei päiviinsä ulotu, eikä vanhoja, jotka ei vuosiansa täytä; sillä sadan vuotiset lapset pitää kuoleman, ja sadan ajastaikaiset syntiset pitää kirotut oleman.","Ei siellä pidä enään lapsia oleman, jotka ei päiviinsä ulotu, eikä vanhoja, jotka ei vuosiansa täytä; sillä sadan vuotiset lapset pitää kuoleman, ja sadan ajastaikaiset syntiset pitää kirotut oleman."],[65,21,"He rakentavat huoneita, ja niissä asuvat: he istuttavat viinapuita, ja niiden hedelmistä syövät.","He rakentavat huoneita, ja niissä asuvat: he istuttavat viinapuita, ja niiden hedelmistä syövät."],[65,22,"Ei heidän pidä muiden asua rakentaman, eikä istuttaman muiden syödä; sillä minun kansani päivät pitää oleman niinkuin puun päivät, ja heidän käsialansa pitää vanheneman minun valittuini tykönä.","Ei heidän pidä muiden asua rakentaman, eikä istuttaman muiden syödä; sillä minun kansani päivät pitää oleman niinkuin puun päivät, ja heidän käsialansa pitää vanheneman minun valittuini tykönä."],[65,23,"Ei heidän pidä hukkaan työtä tekemän, eikä turmeluksessa synnyttämän; sillä he ovat Herran siunattuin siemen, ja heidän jälkeentulevaisensa heidän kanssansa.","Ei heidän pidä hukkaan työtä tekemän, eikä turmeluksessa synnyttämän; sillä he ovat Herran siunattuin siemen, ja heidän jälkeentulevaisensa heidän kanssansa."],[65,24,"Ja tapahtuu, että ennenkuin he huutavat, tahdon minä vastata; koska he vielä puhuvat, tahdon minä kuulla.","Ja tapahtuu, että ennenkuin he huutavat, tahdon minä vastata; koska he vielä puhuvat, tahdon minä kuulla."],[65,25,"Susi ja lammas pitää ynnä laitumella käymän, jalopeura ja härkä yhdessä korsia syömän, ja kärmeet pitää maata syömän. Ei heidän pidä vahinkoa tekemän, eikä turmeleman koko minun pyhällä vuorellani, sanoo Herra.","Susi ja lammas pitää ynnä laitumella käymän, jalopeura ja härkä yhdessä korsia syömän, ja kärmeet pitää maata syömän. Ei heidän pidä vahinkoa tekemän, eikä turmeleman koko minun pyhällä vuorellani, sanoo Herra."],[66,1,"Näin sanoo Herra: taivas on minun istuimeni, ja maa minun jalkaini astinlauta. Mikä siis on se huone, jonka te minulle rakennatte, eli mikä on minun leposiani?","Näin sanoo Herra: taivas on minun istuimeni, ja maa minun jalkaini astinlauta. Mikä siis on se huone, jonka te minulle rakennatte, eli mikä on minun leposiani?"],[66,2,"Ja minun käteni on kaikki nämät tehnyt ja kaikki nämät ovat tehdyt, sanoo Herra; mutta minä katson sen puoleen, joka raadollinen ja särjetyllä hengellä on, ja joka vapisee minun sanani edessä.","Ja minun käteni on kaikki nämät tehnyt ja kaikki nämät ovat tehdyt, sanoo Herra; mutta minä katson sen puoleen, joka raadollinen ja särjetyllä hengellä on, ja joka vapisee minun sanani edessä."],[66,3,"Sillä joka härjän teurastaa, on niinkuin hän miehenkin tappais; joka lampaan uhraa, on niinkuin hän koiran niskat taittais; joka ruokauhria tuo, on niinkuin hän sian verta uhrais; joka pyhää savua muistelee, on niinkuin hän vääryyttä kiittäis: näitä he valitsevat teissänsä, ja heidän sielunsa mielistyy heidän kauhistuksiinsa.","Sillä joka härjän teurastaa, on niinkuin hän miehenkin tappais; joka lampaan uhraa, on niinkuin hän koiran niskat taittais; joka ruokauhria tuo, on niinkuin hän sian verta uhrais; joka pyhää savua muistelee, on niinkuin hän vääryyttä kiittäis: näitä he valitsevat teissänsä, ja heidän sielunsa mielistyy heidän kauhistuksiinsa."],[66,4,"Sentähden tahdon minä myös valita heidän pilkkansa, ja jota he pelkäävät, sen saatan minä heidän päällensä; sentähden että minä kutsuin, ja ei kenkään vastannut, minä puhuin, ja ei he kuulleet. Ja he tekivät pahaa minun silmäini edessä, ja valitsivat, jota en minä tahtonut.","Sentähden tahdon minä myös valita heidän pilkkansa, ja jota he pelkäävät, sen saatan minä heidän päällensä; sentähden että minä kutsuin, ja ei kenkään vastannut, minä puhuin, ja ei he kuulleet. Ja he tekivät pahaa minun silmäini edessä, ja valitsivat, jota en minä tahtonut."],[66,5,"Kuulkaat Herran sanaa te, jotka hänen sanaansa pelkäätte: teidän veljenne, jotka teitä vihasivat, ja eroittivat teidät heistänsä minun nimeni tähden, he sanovat: olkoon Herra ylistetty! vaan ilmaantukaan hän teidän iloonne; mutta heidän pitää häpiään tuleman.","Kuulkaat Herran sanaa te, jotka hänen sanaansa pelkäätte: teidän veljenne, jotka teitä vihasivat, ja eroittivat teidät heistänsä minun nimeni tähden, he sanovat: olkoon Herra ylistetty! vaan ilmaantukaan hän teidän iloonne; mutta heidän pitää häpiään tuleman."],[66,6,"Sillä metelin ääni (pitää kuuluman) kaupungista, ääni templistä, Herran ääni, joka vihollisensa kostaa ansion jälkeen.","Sillä metelin ääni (pitää kuuluman) kaupungista, ääni templistä, Herran ääni, joka vihollisensa kostaa ansion jälkeen."],[66,7,"Hän synnyttää ennenkuin hän saa kivun; hän synnyttää pojan ennenkuin hänen kipunsa tulee.","Hän synnyttää ennenkuin hän saa kivun; hän synnyttää pojan ennenkuin hänen kipunsa tulee."],[66,8,"Kuka on ikänä senkaltaista kuullut? kuka on ikänä senkaltaista nähnyt? Saaneeko koko maa yhtenä päivänä synnyttämisen kivun? syntyneekö kaikki kansa yhtä haavaa? kuitenkin on Zion, saatuansa synnyttämisen kivun, myös synnyttänyt.","Kuka on ikänä senkaltaista kuullut? kuka on ikänä senkaltaista nähnyt? Saaneeko koko maa yhtenä päivänä synnyttämisen kivun? syntyneekö kaikki kansa yhtä haavaa? kuitenkin on Zion, saatuansa synnyttämisen kivun, myös synnyttänyt."],[66,9,"Eikö minun, joka muut saatan synnyttämään, pitäisi itse myös synnyttämän? sanoo Herra; pitäiskö minun antaman muiden synnyttää, ja itse hedelmätöin oleman? sanoo sinun Jumalas.","Eikö minun, joka muut saatan synnyttämään, pitäisi itse myös synnyttämän? sanoo Herra; pitäiskö minun antaman muiden synnyttää, ja itse hedelmätöin oleman? sanoo sinun Jumalas."],[66,10,"Iloitkaat Jerusalemin kanssa, ja ihastukaat hänestä kaikki, jotka häntä rakastatte; iloitkaat suuresti hänen kanssansa kaikki te, jotka tähänasti olette hänen tähtensä murheelliset olleet.","Iloitkaat Jerusalemin kanssa, ja ihastukaat hänestä kaikki, jotka häntä rakastatte; iloitkaat suuresti hänen kanssansa kaikki te, jotka tähänasti olette hänen tähtensä murheelliset olleet."],[66,11,"Sillä teidän pitää imemän ja ravittaman hänen lohdutuksensa nisistä; teidän pitää lypsämän ja ilahuttaman teitänne hänen kunniansa kirkkaudesta.","Sillä teidän pitää imemän ja ravittaman hänen lohdutuksensa nisistä; teidän pitää lypsämän ja ilahuttaman teitänne hänen kunniansa kirkkaudesta."],[66,12,"Sillä näin sanoo Herra: katso minä levitän hänen tykönänsä rauhan niinkuin virran, ja pakanain kunnian niinkuin vuotavan ojan, jota te saatte imeä; ja teitä pitää sylissä kannettaman, ja polvien päällä ihanteleman.","Sillä näin sanoo Herra: katso minä levitän hänen tykönänsä rauhan niinkuin virran, ja pakanain kunnian niinkuin vuotavan ojan, jota te saatte imeä; ja teitä pitää sylissä kannettaman, ja polvien päällä ihanteleman."],[66,13,"Niinkuin äiti poikaansa lohduttaa, niin minä tahdon teitä lohduttaa, ja teidän pitää Jerusalemissa lohdutuksen saaman.","Niinkuin äiti poikaansa lohduttaa, niin minä tahdon teitä lohduttaa, ja teidän pitää Jerusalemissa lohdutuksen saaman."],[66,14,"Teidän pitää sen näkemän, ja teidän sydämenne pitää iloitseman, ja teidän luunne pitää vihoittaman niinkuin ruoho; niin tunnetaan Herran käsi hänen palvelioissansa, ja hänen vihollisissansa.","Teidän pitää sen näkemän, ja teidän sydämenne pitää iloitseman, ja teidän luunne pitää vihoittaman niinkuin ruoho; niin tunnetaan Herran käsi hänen palvelioissansa, ja hänen vihollisissansa."],[66,15,"Sillä katso, Herra tulee tulella, ja hänen rattaansa ovat niinkuin tuulispää; että hän kostais vihansa hirmuisuudessa, ja rangaistuksen tulen liekissä.","Sillä katso, Herra tulee tulella, ja hänen rattaansa ovat niinkuin tuulispää; että hän kostais vihansa hirmuisuudessa, ja rangaistuksen tulen liekissä."],[66,16,"Sillä Herra on tuomitseva tulella ja miekallansa kaiken lihan; ja Herralta tapetuita pitää paljo oleman.","Sillä Herra on tuomitseva tulella ja miekallansa kaiken lihan; ja Herralta tapetuita pitää paljo oleman."],[66,17,"Jotka heitänsä pyhittävät ja puhdistavat yrttitarhoissa, yksi täällä, toinen siellä, ja syövät sian lihaa, kauhistuksia ja hiiriä: kaikki nämät pitää lopetettaman yhtä haavaa, sanoo Herra.","Jotka heitänsä pyhittävät ja puhdistavat yrttitarhoissa, yksi täällä, toinen siellä, ja syövät sian lihaa, kauhistuksia ja hiiriä: kaikki nämät pitää lopetettaman yhtä haavaa, sanoo Herra."],[66,18,"Sillä minä tahdon tulla ja koota heidän ajatuksensa ja tekonsa, ynnä kaikkein pakanain ja kielten kanssa, että he tulisivat ja näkisivät minun kunniani.","Sillä minä tahdon tulla ja koota heidän ajatuksensa ja tekonsa, ynnä kaikkein pakanain ja kielten kanssa, että he tulisivat ja näkisivät minun kunniani."],[66,19,"Ja minä asetan merkin heidän sekaansa, ja muutamat niistä, kuin pelastetut ovat, lähetän minä pakanoille meren tykö, joutsimiehen puoleen, Puliin ja Ludiin, Tubaliin ja Javaan päin, ja niihin kaukaisiin saariin, joissa ei tähänasti mitään ole minusta kuultu, ja ei ole minun kunniaani nähneet: ja heidän pitää minun kunniani pakanain seassa ilmoittaman.","Ja minä asetan merkin heidän sekaansa, ja muutamat niistä, kuin pelastetut ovat, lähetän minä pakanoille meren tykö, joutsimiehen puoleen, Puliin ja Ludiin, Tubaliin ja Javaan päin, ja niihin kaukaisiin saariin, joissa ei tähänasti mitään ole minusta kuultu, ja ei ole minun kunniaani nähneet: ja heidän pitää minun kunniani pakanain seassa ilmoittaman."],[66,20,"Ja tuoman ulos kaikki teidän veljenne kaikista pakanoista, Herralle ruokauhriksi, hevosilla ja rattailla, paareilla, muuleilla ja liukkailla juhdilla Jerusalemiin minun pyhän vuoreni puoleen, sanoo Herra: niinkuin Israelinkin lapset tuovat ruokauhrin puhtaassa astiassa Herran huoneeseen.","Ja tuoman ulos kaikki teidän veljenne kaikista pakanoista, Herralle ruokauhriksi, hevosilla ja rattailla, paareilla, muuleilla ja liukkailla juhdilla Jerusalemiin minun pyhän vuoreni puoleen, sanoo Herra: niinkuin Israelinkin lapset tuovat ruokauhrin puhtaassa astiassa Herran huoneeseen."],[66,21,"Ja minä tahdon niistä ottaa papit ja Leviläiset, sanoo Herra.","Ja minä tahdon niistä ottaa papit ja Leviläiset, sanoo Herra."],[66,22,"Sillä niinkuin uudet taivaat ja uusi maa, jotka minä teen, ovat minun edessäni, sanoo Herra, juuri niin pitää teidän siemenenne ja nimenne pysymän.","Sillä niinkuin uudet taivaat ja uusi maa, jotka minä teen, ovat minun edessäni, sanoo Herra, juuri niin pitää teidän siemenenne ja nimenne pysymän."],[66,23,"Ja kaikki liha pitää yhdestä kuukaudesta niin toiseen, ja yhdestä sabbatista niin toiseen, tuleman kumartamaan minun eteeni, sanoo Herra:","Ja kaikki liha pitää yhdestä kuukaudesta niin toiseen, ja yhdestä sabbatista niin toiseen, tuleman kumartamaan minun eteeni, sanoo Herra:"],[66,24,"Ja heidän pitää menemän ulos, ja katseleman niiden ihmisten raatoja, jotka minua vastaan väärin tekivät; sillä ei heidän matonsa pidä kuoleman, eikä heidän tulensa sammuman, ja heidän pitää kaikelle lihalle kauhistukseksi oleman.","Ja heidän pitää menemän ulos, ja katseleman niiden ihmisten raatoja, jotka minua vastaan väärin tekivät; sillä ei heidän matonsa pidä kuoleman, eikä heidän tulensa sammuman, ja heidän pitää kaikelle lihalle kauhistukseksi oleman."]]}};